import { ComplexButton } from '../../../gui/buttons/ComplexButton'

export class AddCoinsButton extends ComplexButton {
	private white: Phaser.Image

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'boosters_shop', 'Button_Add_Coins0000')

		this.addWhite()
	}

	private addWhite(): void {
		this.white = this.game.add.image(0, 0, 'boosters_shop', 'Button_Add_Coins_White0000', this)
		this.white.anchor.set(0.5, 0.5)
		this.white.scale.set(0.995)
		this.white.centerX = this.back.centerX
		this.white.centerY = this.back.centerY
		this.white.visible = false
	}

	public highlight(): void {
		let duration = 330

		this.white.alpha = 0
		this.white.visible = true
		this.game.tweens.removeFrom(this.white)
		this.game.add
			.tween(this.white)
			.to({ alpha: 0.66 }, duration, Phaser.Easing.Sinusoidal.InOut, true, 0, 0, true)
			.onComplete.addOnce(() => {
				this.white.visible = false
			})

		let targetScale = 1.1
		this.scale.set(1)
		this.game.tweens.removeFrom(this.scale)
		this.game.add
			.tween(this.scale)
			.to({ x: targetScale, y: targetScale }, duration, Phaser.Easing.Sinusoidal.InOut, true, 0, 0, true)
	}
}
