import { Config } from '../Config'

export class GameBackground extends Phaser.Image {
	constructor(game: Phaser.Game, texture: string = 'interface', frame: string = 'white_rect0000') {
		super(game, 0, 0, texture, frame)

		this.game.world.add(this)
		this.tint = 0xfff3e0
	}

	public resize(): void {
		let k: number = 1.25
		this.width = Config.GAME_WIDTH * k
		this.height = Config.GAME_HEIGHT * k

		this.centerX = Config.HALF_GAME_WIDTH
		this.centerY = Config.HALF_GAME_HEIGHT
	}

	public destroy(): void {
		super.destroy(true)
	}
}
