import { FontWeight, GameFonts } from '../../../GameFonts'

export class TutorialTopPanel extends Phaser.Group {
	private back: Phaser.Image
	private title: Phaser.Text
	private subtitle: Phaser.BitmapText
	private tutorialLines: string[]
	private currentLine: number = 0

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'tutorial_text')

		this.tutorialLines = this.game.texts.texts.tutorial
		this.addBack()
		this.addTitle()
		this.addSubtitle()
		this.alignTexts()

		this.game.add.tween(this.subtitle).to({ alpha: 0.33 }, 400, Phaser.Easing.Sinusoidal.InOut, true, 0, -1, true)
	}

	private addBack(): void {
		this.back = this.game.add.image(0, 0, 'interface', 'Tutorial_Back0000', this)
	}

	private addTitle(): void {
		let content = this.tutorialLines[0]
		let style = {
			font: GameFonts.DEFAULT,
			fontWeight: FontWeight.BOLD,
			fontSize: 32,
			fill: '#ffffff',
			align: 'center',
		}

		this.title = this.game.add.text(0, 0, content, style, this)
		this.title.wordWrap = true
		this.title.wordWrapWidth = this.back.width * 0.85
		this.title.lineSpacing = -10
		this.title.align = 'center'
		this.title.anchor.set(0.5, 0)
		this.title.name = 'title'
	}

	private addSubtitle(): void {
		let content: string = this.game.texts.texts.tutorial_hint

		this.subtitle = this.game.add.bitmapText(0, 0, GameFonts.BARIOL_BOLD_BMP, content, 28, this)
		this.subtitle.anchor.set(0.5, 0)
		this.subtitle.centerX = this.title.centerX
		this.subtitle.top = this.title.bottom + 5
		this.subtitle.name = 'subtitle'
	}

	public showNextLine(): void {
		this.setTextLine(++this.currentLine)
		this.tweenText()
	}

	private setTextLine(lineNum: number): void {
		this.currentLine = Phaser.Math.clamp(lineNum, 0, this.tutorialLines.length - 1)

		let text = this.tutorialLines[this.currentLine]
		let maxHeight = this.back.height
		this.title.setText(text, true)
		this.title.scale.set(1)
		this.title.scale.set(Math.min(1, maxHeight / this.title.height))
		this.title.centerY = this.back.centerY
	}

	private tweenText(): void {
		this.game.tweens.removeFrom(this.title)
		this.game.tweens.removeFrom(this.title.scale)

		let originalScale = this.title.scale.x
		this.title.alpha = 0
		this.title.scale.set(originalScale * 0.8)
		this.game.add.tween(this.title).to({ alpha: 1 }, 200, Phaser.Easing.Cubic.Out, true)
		this.game.add.tween(this.title.scale).to(
			{
				x: originalScale,
				y: originalScale,
			},
			360,
			Phaser.Easing.Back.Out,
			true
		)
	}

	public hide(): void {
		this.game.add.tween(this).to({ alpha: 0, y: '-66' }, 100, Phaser.Easing.Cubic.In, true)
	}

	public show(): void {
		this.alpha = 0
		this.game.add.tween(this).to({ alpha: 1 }, 660, Phaser.Easing.Linear.None, true, 100)
	}

	public resize(height: number): void {
		this.back.height = height

		this.alignTexts()
	}

	private alignTexts() {
		this.subtitle.centerX = this.back.centerX
		this.subtitle.bottom = this.back.bottom - 20

		if (this.subtitle.visible) {
			this.title.bottom = this.subtitle.top - 5
		} else {
			let maxHeight: number = this.back.height * 0.7
			this.title.scale.set(1)
			if (this.title.height > maxHeight) {
				this.title.scale.set(maxHeight / this.title.height)
			}

			this.title.centerY = this.back.centerY
		}

		this.title.centerX = this.back.centerX
	}

	public hideSubtitle(): void {
		this.game.tweens.removeFrom(this.subtitle)
		this.subtitle.visible = false
	}

	public get isLastLine(): boolean {
		return this.currentLine === this.tutorialLines.length - 1
	}

	public destroy(): void {
		this.hideSubtitle()

		super.destroy(true, false)

		this.tutorialLines = null
	}
}
