import { Cell } from '../grid/Cell'
import { Grid } from './../grid/Grid'
import { CellState } from './CellState'

export class GridState {
	public cellStates: CellState[]

	constructor(cellStates: CellState[]) {
		this.cellStates = cellStates
	}

	public static fromGrid(grid: Grid): GridState {
		let cellStates: CellState[] = grid.cells.map((cell: Cell) => {
			let itemType: number = cell.isFree() ? 0 : cell.item.itemType
			let cellState: CellState = new CellState(cell.row, cell.column, itemType)

			return cellState
		})

		return new GridState(cellStates)
	}

	public static fromString(data: string): GridState {
		let parsedData: any[]
		try {
			parsedData = JSON.parse(data)
		} catch (error) {
			const parseError = error as Error
			console.warn("Can't parse saved GridState", parseError.name, parseError.message)
			return null
		}

		let cellStates: CellState[] = parsedData.map((data) => {
			return new CellState(data.row, data.column, data.itemType)
		})

		return new GridState(cellStates)
	}

	public toString(): string {
		let data = this.cellStates.map((cellState: CellState) => {
			return {
				row: cellState.row,
				column: cellState.column,
				itemType: cellState.itemType,
			}
		})

		return JSON.stringify(data)
	}

	public destroy(): void {
		this.cellStates = null
	}
}
