import { snakeCase } from 'es-toolkit/compat'
import { FontWeight, GameFonts } from './../../../../GameFonts'
import { ComplexButton } from './../../../../gui/buttons/ComplexButton'
import PhaserTextStyle = Phaser.PhaserTextStyle

export class GameOverButton extends ComplexButton {
	protected white: Phaser.Image

	constructor(_game: Phaser.Game, parent: Phaser.Group, textContent: string) {
		super(_game, parent, 'interface', 'Game_Over_Button_Back0000')

		this.back.name = 'game_over_button_' + snakeCase(textContent)
		this.back.scale.set(1.1, 1)

		this.addCustomText(textContent)
		this.addWhite()
	}

	private addCustomText(textContent: string) {
		let style: PhaserTextStyle = {
			font: GameFonts.NUNITO_CSS,
			fontSize: 25,
			fontWeight: FontWeight.BOLD,
			fill: '#ffffff',
			align: 'center',
		}

		this.addText(textContent, style)
		this.text.lineSpacing = -8
		this.text.y += 2
	}

	private addWhite(): void {
		this.white = this.game.add.image(0, 0, 'interface', 'Game_Over_Button_White0000', this)
		this.white.centerX = this.back.centerX
		this.white.centerY = this.back.centerY
		this.white.visible = false
	}

	public enable(): void {
		this.enabled = true
		this.alpha = 1
	}

	public disable(): void {
		this.enabled = false
		this.alpha = 0.66
	}

	public highlight(): void {
		this.game.tweens.removeFrom(this.white)

		this.white.visible = true
		this.white.alpha = 0
		this.game.add
			.tween(this.white)
			.to({ alpha: 0.33 }, 100, Phaser.Easing.Sinusoidal.InOut, true, 0, 6, true)
			.onComplete.addOnce(() => {
				this.white.visible = false
			})
	}
}
