import * as Sentry from '@sentry/browser'
import { Logger } from 'tslog'
import { merge } from 'es-toolkit/compat'
import { BaseError } from '../errors/BaseError'
import { Main } from '../Main'
import { TypedEventEmitter } from '../robowhale/TypedEventEmitter'
import { Env } from '../startup/Env'
import { platformTag } from '../startup/Platform'
import { UrlParams } from '../url-params/UrlParams'

type Events = {
	error: (error: Sentry.Event, hint: Sentry.EventHint) => void
}

export interface SentryServiceOptions {
	game: Main
	logger: Logger<{}>
}

export class SentryService extends TypedEventEmitter<Events> {
	public logger: Logger<{}>
	private game: Main
	private dropAllEvents = false

	constructor(options: SentryServiceOptions) {
		super()

		this.logger = options.logger

		this.game = options.game

		const isDisabled = UrlParams.get('sentry') === '0'
		if (isDisabled) {
			this.logger.info('disabled')
		}

		const config = window.game.config

		Sentry.init({
			dsn: config.sentry.dsn,
			debug: UrlParams.getBool('sentryDebug'),
			enabled: !isDisabled,
			tunnel: 'https://stun.robowhale.ru/tunnel',
			environment: config.env,
			release: this.getRelease(config),
			beforeBreadcrumb: this.beforeBreadcrumb.bind(this),
			beforeSend: this.beforeSend.bind(this),
			normalizeDepth: 4,
			maxBreadcrumbs: config.env === Env.PROD ? 500 : 3000,
			// errors from the ignored list do not get to `beforeSend` method
			ignoreErrors: [
				'Can not find auth window opener', // yandex auth error
				'Cancel last request', // gamepush error
			],
		})

		// добавляем event processor, чтобы данные из BaseError.sentryContext добавлялись в Сентри ивенты
		Sentry.addEventProcessor((event, hint) => {
			const exception = hint.originalException
			if (exception instanceof BaseError && typeof exception.sentryContext !== 'undefined') {
				const context =
					typeof exception.sentryContext === 'function'
						? exception.sentryContext(event, hint)
						: exception.sentryContext

				merge(event, context)
			}

			return event
		})

		Sentry.setTag('platform', platformTag(config.platform))

		Sentry.setTag('release.build', config.build_version)

		Sentry.setTag('device.RAM', this.getDeviceMemory())

		this.trackPageUnload()
		this.trackSessionDuration()
	}

	private getRelease(config: IGameConfig): string {
		if (config.env === Env.PROD) {
			return `${config.platform}-${config.build_version}`
		}

		return `${config.env}-${config.build_version}`
	}

	private beforeBreadcrumb(breadcrumb: Sentry.Breadcrumb): Sentry.Breadcrumb | null {
		return breadcrumb
	}

	private beforeSend(event: Sentry.Event, hint: Sentry.EventHint): Sentry.Event | null {
		if (event.level === 'error' || event.level === 'fatal') {
			this.emit('error', event, hint)
		}

		if (this.dropAllEvents) {
			return null
		}

		const error = hint.originalException
		if (error instanceof BaseError && error.isFatal) {
			// we will report this game-breaking fatal error to Sentry but all the following errors will be dropped
			this.dropAllEvents = true
		}

		return event
	}

	private getDeviceMemory(): string {
		const valueInGb = navigator['deviceMemory']
		if (!valueInGb || typeof valueInGb !== 'number') {
			return 'unknown'
		}

		return `${valueInGb * 1024} MB`
	}

	private trackPageUnload(): void {
		Sentry.setTag('page.status', 'active')

		window.addEventListener('beforeunload', () => {
			this.game.logs?.info(`page - 'beforeunload' event`)
			Sentry.setTag('page.status', 'beforeUnload')
		})

		window.addEventListener('unload', () => {
			this.game.logs?.info(`page - 'unload' event`)
			Sentry.setTag('page.status', 'unloaded')
		})
	}

	private trackSessionDuration(): void {
		setInterval(() => {
			if (!this.game.gameStartedAt) {
				return
			}

			const msSinceStart = Date.now() - this.game.gameStartedAt
			const minutesSinceStart = Math.floor(msSinceStart / 1000 / 60)
			Sentry.setTag('game.duration', Phaser.Math.snapToFloor(minutesSinceStart, 5) + ' minutes')
		}, 5_000)
	}

	/**
	 * Alias for `Sentry.captureException`.
	 */
	public sendError(...args: Parameters<(typeof Sentry)['captureException']>) {
		return Sentry.captureException(...args)
	}

	/**
	 * Alias for `Sentry.captureMessage`.
	 */
	public sendMessage(...args: Parameters<(typeof Sentry)['captureMessage']>) {
		return Sentry.captureMessage(...args)
	}

	public setContext(...args: Parameters<(typeof Sentry)['setContext']>) {
		return Sentry.setContext(...args)
	}

	public setTag(...args: Parameters<(typeof Sentry)['setTag']>) {
		return Sentry.setTag(...args)
	}

	public setTags(...args: Parameters<(typeof Sentry)['setTags']>) {
		return Sentry.setTags(...args)
	}

	public setUser(...args: Parameters<(typeof Sentry)['setUser']>) {
		return Sentry.setUser(...args)
	}

	public addBreadcrumb(...args: Parameters<(typeof Sentry)['addBreadcrumb']>) {
		return Sentry.addBreadcrumb(...args)
	}
}
