import { Config } from '../../Config'
import { DrawUtil } from './DrawUtil'

export class FPSMeter extends Phaser.Group {
	private bg: Phaser.Image
	private text: Phaser.Text
	private timer: number = 0
	private readonly updateInterval: number = 100

	constructor(game: Phaser.Game, parent?: Phaser.Group) {
		super(game, parent || game.stage, 'fps_meter')

		this.initBackground()
		this.initText()
		this.onResize()

		this.game.state.onStateChange.add(this.addPointerCallback, this)
		this.game.scale.onSizeChange.add(this.onResize, this)
		this.game.time.advancedTiming = true
	}

	private addPointerCallback(): void {
		if (this.game.input.onDown.has(this.onInputDown, this) === false) {
			this.game.input.onDown.add(this.onInputDown, this)
		}
	}

	private onInputDown(pointer: Phaser.Pointer) {
		let bounds: Phaser.Rectangle = this.getBounds(this.parent) as any
		let isPointerOver: boolean = bounds.contains(pointer.x, pointer.y)
		if (isPointerOver) {
			this.toggleVisibility()
		}
	}

	public toggleVisibility() {
		if (this.alive) {
			this.kill()
		} else {
			this.revive()
		}
	}

	private initBackground(): void {
		let texture: Phaser.BitmapData = DrawUtil.createRectTexture(this.game, 164, 26)
		this.bg = this.game.add.image(0, 0, texture, null, this)
	}

	private initText(): void {
		let style = { font: '18px Consolas', fill: '#FFFFFF', align: 'left' }
		this.text = this.game.add.text(6, 4, '0 fps', style, this)
		// this.text.lineSpacing = -5;
	}

	public update(): void {
		this.timer += this.game.time.elapsed
		if (this.timer >= this.updateInterval) {
			this.timer -= this.updateInterval
			this.updateStats()
		}
	}

	private updateStats(): void {
		let fps: string = `FPS: ${this.game.time.fps}`
		let drawCalls: string = `DC: ${this.getDrawCallsNum()}`
		let result: string = `${fps} | ${drawCalls}`
		this.text.setText(result)
	}

	private getDrawCallsNum(): number {
		if (this.game.renderType === Phaser.CANVAS) {
			return 0
		}

		let num: number = this.game.renderer.renderSession['drawCount']
		let meterDrawCalls: number = 2
		return num - meterDrawCalls
	}

	public onResize(): void {
		this.top = Config.GAME_HEIGHT - this.bg.height
		this.left = 0
	}

	public destroy(): void {
		this.game.time.advancedTiming = false

		super.destroy(true, false)
	}
}
