import { Config } from '../../Config'
import { FontWeight, GameFonts } from '../../GameFonts'
import { SimpleButton } from '../buttons/SimpleButton'
import { Checkbox } from '../Checkbox'

export class ComplexPopup extends Phaser.Group {
	protected backdrop: Phaser.Image
	protected window: Phaser.Group
	private windowBack: Phaser.Image
	private titleBack: Phaser.Image
	public title: Phaser.Text
	public mainText: Phaser.Text
	public content: Phaser.Image
	public noButton: SimpleButton
	public yesButton: SimpleButton
	public checkbox: Checkbox
	public onShow: Phaser.Signal
	public onHide: Phaser.Signal
	public onRewardedAdComplete: Phaser.Signal
	private hiding: boolean = false

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'popup')

		this.onShow = new Phaser.Signal()
		this.onHide = new Phaser.Signal()
		this.onRewardedAdComplete = new Phaser.Signal()

		this.addBackdrop()
		this.addWindow()
		this.addTitle()
		this.addMainText()
		this.addContent()
		this.addButtons()
		this.addCheckbox()
		this.alignContent()

		this.kill()
	}

	private addBackdrop(): void {
		this.backdrop = this.game.add.image(0, 0, 'interface', 'white_rect0000', this)
		this.backdrop.anchor.set(0.5, 0.5)
		this.backdrop.alpha = 0.5
		this.backdrop.tint = 0x1a237e
		this.backdrop.inputEnabled = true
	}

	private addWindow(): void {
		this.window = this.game.add.group(this, 'container')

		this.windowBack = this.game.add.image(0, 0, 'interface', 'Popup_Back0000', this.window)
		this.windowBack.anchor.set(0.5, 0.5)
	}

	private addTitle(): void {
		this.titleBack = this.game.add.image(0, 0, 'interface', 'Popup_Title_Back0000', this.window)
		this.titleBack.centerX = this.windowBack.centerX
		this.titleBack.top = this.windowBack.top + 40

		let style = {
			font: GameFonts.DEFAULT,
			fontWeight: FontWeight.BOLD,
			fontSize: 44,
			fill: '#ffffff',
			align: 'center',
		}

		this.title = this.game.add.text(0, 0, 'Title', style, this.window)
		this.title.anchor.set(0.5, 0.5)
		this.title.centerX = this.titleBack.centerX
		this.title.centerY = this.titleBack.centerY
	}

	private addMainText(): void {
		let content = 'Some multiline\ncontent?!?!'
		let style = {
			font: GameFonts.DEFAULT,
			fontWeight: FontWeight.NORMAL,
			fontSize: 30,
			fill: '#F89932',
			align: 'center',
		}

		this.mainText = this.game.add.text(0, 0, content, style, this.window)
		this.mainText.anchor.set(0.5, 0.5)
		this.mainText.lineSpacing = -8
		this.mainText.wordWrap = true
		this.mainText.wordWrapWidth = this.windowBack.width * 0.9
		this.mainText.x = this.windowBack.centerX
		this.mainText.top = this.windowBack.top + 130
	}

	private addContent(): void {
		this.content = this.game.add.image(0, 0, 'interface', 'Headstart_Popup_Content0000', this.window)
		this.content.anchor.set(0.5, 0.5)
		this.content.centerX = this.windowBack.centerX
		this.content.top = this.mainText.bottom + 10
	}

	private addButtons(): void {
		let dx: number = 90
		let buttonY: number = this.windowBack.top + 410

		this.noButton = new SimpleButton(this.game, 0, 0, 'interface', 'Button_No0000', this.window)
		this.noButton.x = this.windowBack.centerX - dx
		this.noButton.y = buttonY
		this.noButton.callback.addOnce(this.hide, this)

		this.yesButton = new SimpleButton(this.game, 0, 0, 'interface', 'Button_Yes0000', this.window)
		this.yesButton.x = this.windowBack.centerX + dx
		this.yesButton.y = buttonY
		// this.yesButton.callback.addOnce(this.hide, this);
	}

	private addCheckbox(): void {
		let title: string = this.game.texts.texts['dont_ask_cb']
		this.checkbox = new Checkbox(this.game, this.window, title, {
			textureKey: 'interface',
			onFrame: 'Checkbox0001',
			offFrame: 'Checkbox0000',
		})

		this.checkbox.checked = this.game.save.getValue('headstart_popup_disabled')
		this.checkbox.centerX = this.windowBack.centerX
		this.checkbox.centerY = this.yesButton.bottom + (this.windowBack.bottom - this.yesButton.bottom) / 2
		this.checkbox.label.tint = 0xff9933
	}

	public alignContent() {
		let top: number = this.mainText.bottom
		let bottom: number = this.noButton.top
		let height: number = bottom - top

		this.content.centerX = this.windowBack.centerX
		this.content.centerY = top + height / 2
	}

	public show(): void {
		this.parent.bringToTop(this)

		this.revive()

		this.showBackdrop()
		this.showWindow(250)
	}

	private showBackdrop() {
		this.backdrop.alpha = 0
		this.game.add.tween(this.backdrop).to({ alpha: 0.66 }, 500, Phaser.Easing.Cubic.Out, true)
	}

	private showWindow(delay: number) {
		this.alignWindow()
		this.game.add.tween(this.window).from({ alpha: 0 }, 200, Phaser.Easing.Cubic.Out, true, delay)
		this.game.add.tween(this.window).from({ y: '+60' }, 600, Phaser.Easing.Back.Out, true, delay)

		this.window.scale.set(0.8)
		let scaleTween: Phaser.Tween = this.game.add.tween(this.window.scale).to(
			{
				x: 1,
				y: 1,
			},
			400,
			Phaser.Easing.Back.Out,
			true,
			delay
		)
		scaleTween.onStart.addOnce(() => {
			this.game.sound.play('popup', 0.33)
		})
		scaleTween.onComplete.addOnce(() => {
			this.animateYesButton()
		})
	}

	private animateYesButton(): void {
		let scale = 1.15
		this.game.add.tween(this.yesButton.scale).to(
			{
				x: scale,
				y: scale,
			},
			440,
			Phaser.Easing.Sinusoidal.InOut,
			true,
			0,
			-1,
			true
		)
	}

	public hide(): void {
		if (this.hiding) {
			return
		}

		this.hiding = true
		this.disableInput()

		this.game.add
			.tween(this)
			.to({ alpha: 0 }, 150, Phaser.Easing.Cubic.Out, true)
			.onComplete.addOnce(() => {
				this.onHideComplete()
			})
	}

	private disableInput() {
		;[this.noButton, this.yesButton].forEach((button) => {
			button.enabled = false
		})
		this.checkbox.ignoreChildInput = true
	}

	private onHideComplete(): void {
		this.onHide.dispatch()
		this.visible = false
		this.pendingDestroy = true
	}

	public resize(): void {
		this.resizeBackground()
		this.alignWindow()
	}

	private resizeBackground() {
		this.backdrop.width = Config.GAME_WIDTH * 1.2
		this.backdrop.height = Config.GAME_HEIGHT * 1.2
		this.backdrop.centerX = Config.HALF_GAME_WIDTH
		this.backdrop.centerY = Config.HALF_GAME_HEIGHT
	}

	private alignWindow() {
		this.window.centerX = Config.HALF_GAME_WIDTH
		this.window.centerY = Config.HALF_GAME_HEIGHT
	}

	protected showRewardedVideo(placement: string): void {
		this.game.ads.showRewarded(placement).then((result) => {
			if (result.success === true) {
				this.onRewardedAdCompleteCallback()
			} else {
				// this.onRewardedAdFail()
			}
		})
	}

	private onRewardedAdCompleteCallback(): void {
		this.onRewardedAdComplete.dispatch(this)
		this.hide()
	}

	private onRewardedAdFail(): void {
		this.game.toast.showRewardedVideoWarning()
		this.hide()
	}

	public destroy(): void {
		this.game.tweens.removeFrom(this.yesButton.scale)

		super.destroy(true, false)

		this.onShow.dispose()
		this.onShow = null
		this.onHide.dispose()
		this.onHide = null
		this.onRewardedAdComplete.dispose()
		this.onRewardedAdComplete = null
	}
}
