import { match } from 'ts-pattern'
import { IVisibilityProvider, VisibilityState } from './IVisibilityProvider'

export class WebVisibilityProvider implements IVisibilityProvider {
	public readonly name = 'web'

	public getState(): VisibilityState {
		return match(document.visibilityState as string)
			.with('visible', () => 'visible' as const)
			.otherwise(() => 'hidden' as const)
	}

	public addChangeListener(listener: (event: Event) => void): () => void {
		document.addEventListener('visibilitychange', listener)
		return () => document.removeEventListener('visibilitychange', listener)
	}
}
