import { Config } from '../../../../Config'
import { SimpleButton } from '../../../../gui/buttons/SimpleButton'
import { GameBackground } from '../../../../objects/GameBackground'
import { Item } from '../../items/Item'
import { LevelStats } from '../../LevelStats'
import { FinalItem } from './FinalItem'
import { VictoryTopPanel } from './VictoryPanel'

export class GameCompleteScreen extends Phaser.Group {
	private levelStats: LevelStats
	private bg: GameBackground
	private victoryPanel: VictoryTopPanel
	private centralItemBack: Phaser.Image
	private centralItem: FinalItem
	private crown: Phaser.Image
	private shareButton: SimpleButton
	private friendsButton: SimpleButton
	private continueButton: SimpleButton
	private menuButton: SimpleButton
	private bottomButtons: SimpleButton[]
	private buttonsGroup: Phaser.Group
	private whiteOverlay: Phaser.Image
	private escKey: Phaser.Key

	public onBackFadeInComplete: Phaser.Signal
	public onHideStarted: Phaser.Signal
	public onHideComplete: Phaser.Signal

	constructor(_game: Phaser.Game, parent: Phaser.Group, levelStats: LevelStats) {
		super(_game, parent, 'game_complete')

		this.levelStats = levelStats

		this.onBackFadeInComplete = new Phaser.Signal()
		this.onHideStarted = new Phaser.Signal()
		this.onHideComplete = new Phaser.Signal()

		this.escKey = this.game.input.keyboard.addKey(Phaser.Keyboard.ESC)

		this.sendGameCompleteEvent()
		this.addBackground()
		this.addVictoryPanel()
		this.addCentralItem()
		this.addCrown()
		this.addShareButton()
		this.addButtons()
		this.addWhiteOverlay()

		this.bringToTop(this.victoryPanel)
	}

	private sendGameCompleteEvent(): void {}

	private addBackground(): void {
		this.bg = new GameBackground(this.game)
		this.add(this.bg)
	}

	private addVictoryPanel(): void {
		this.victoryPanel = new VictoryTopPanel(this.game, this)
	}

	private addCentralItem(): void {
		this.centralItemBack = this.game.add.image(0, 0, 'interface', 'Cental_Item_Back0000', this)
		this.centralItemBack.anchor.set(0.5, 0.5)
		// this.centralItemBack.tint = 0xFFFAD0;
		this.centralItemBack.alpha = 0.8

		this.centralItem = new FinalItem(this.game, this)
	}

	private addCrown(): void {
		this.crown = this.game.add.image(0, 0, 'interface', 'Crown0000', this)
		this.crown.anchor.set(0.5, 1)
	}

	private addShareButton(): void {
		this.shareButton = new SimpleButton(this.game, 0, 0, 'interface', 'Button_Share0000', this)
		this.shareButton.events.onInputUp.add(this.onShareButtonClick, this)
	}

	private onShareButtonClick(): void {
		let highscore: number = this.game.save.getValue('best_item')
		let text: string = this.game.texts.texts['share_highscore'].replace('#', highscore.toString())
		// let image: string = this.getShareImage()

		this.game.share.share(text).catch((error) => {
			console.warn(error)
		})
	}

	private getShareImage(): string {
		let image: Phaser.Image = this.game.make.image(0, 0, 'main_menu', 'Item_130000')
		let dataURL: string = this.game.make.bitmapData(image.width, image.height).drawFull(image).canvas.toDataURL()

		// utils.NetUtil.openWindowWithImage(dataURL);

		return dataURL
	}

	private addButtons(): void {
		let buttonFrames: string[] = ['Button_Rate0000', 'Button_Continue0000', 'Button_Home0000']
		this.bottomButtons = buttonFrames.map((texture: string) => {
			return new SimpleButton(this.game, 0, 0, 'interface', texture, this)
		})
		;[this.friendsButton, this.continueButton, this.menuButton] = this.bottomButtons
		this.friendsButton.callback.add(this.onFriendsButtonClick, this)
		this.continueButton.callback.addOnce(this.hide, this)
		this.menuButton.callback.addOnce(this.onMenuButtonClick, this)

		this.buttonsGroup = this.game.add.group(this, 'bottomButtons')
		this.buttonsGroup.addMultiple(this.bottomButtons, true)
		this.buttonsGroup.align(this.bottomButtons.length, 1, 150, 155, Phaser.CENTER)
	}

	private onFriendsButtonClick(): void {}

	private onMenuButtonClick(): void {
		this.game.changeState('BoostersShop')
	}

	private addWhiteOverlay(): void {
		this.whiteOverlay = this.game.add.image(0, 0, 'interface', 'white_rect0000', this)
		this.whiteOverlay.visible = false
	}

	public show(originalItem: Item): void {
		this.setVisibility()
		this.showBackground()
		this.showFinalItem(originalItem)
	}

	private setVisibility(): void {
		this.visible = true

		this.bg.visible = false
		this.victoryPanel.visible = false
		this.centralItemBack.visible = false
		this.crown.visible = false
		this.shareButton.visible = false
		this.bottomButtons.forEach((button) => {
			button.visible = false
		})
	}

	private showBackground(): void {
		this.bg.visible = true
		this.bg.alpha = 0

		this.game.add
			.tween(this.bg)
			.to({ alpha: 1 }, 2800, Phaser.Easing.Linear.None, true)
			.onComplete.addOnce(() => {
				this.onBackFadeInComplete.dispatch()
			})
	}

	private showFinalItem(item: Item): void {
		let worldItemPosition: PIXI.Point = item.parent.toGlobal(item.position)
		this.centralItem.x = worldItemPosition.x
		this.centralItem.y = worldItemPosition.y
		this.centralItem.onAnimationComplete.addOnce(this.show2, this)
		this.centralItem.show()
	}

	private show2(): void {
		this.escKey.onDown.addOnce(this.hide, this)

		this.showCentralItemBack(330)
		this.showCrown(660)
		this.showWhiteOverlay(1700)
		this.victoryPanel.show(2700)
		this.showButtons(3500)

		this.game.time.events.add(1000, this.shakeShareButton, this)
	}

	private showCentralItemBack(initialDelay: number): void {
		this.centralItemBack.visible = true
		this.centralItemBack.scale.set(0)
		this.centralItemBack.angle = -20

		this.game.add.tween(this.centralItemBack.scale).to(
			{
				x: 1,
				y: 1,
			},
			400,
			Phaser.Easing.Back.Out,
			true,
			initialDelay
		)
		this.game.add.tween(this.centralItemBack).to({ angle: 0 }, 1000, Phaser.Easing.Cubic.Out, true, initialDelay)
	}

	private showCrown(initialDelay: number): void {
		let crownOffsetY: number = 50 * Config.ASSETS_SCALE

		this.crown.scale.set(2)
		this.crown.visible = true
		this.crown.alpha = 0
		this.crown.y -= crownOffsetY

		this.game.add.tween(this.crown).to(
			{
				alpha: 1,
				y: this.crown.y + crownOffsetY,
			},
			1500,
			Phaser.Easing.Cubic.Out,
			true,
			initialDelay
		)
		this.game.add.tween(this.crown.scale).to({ x: 1, y: 1 }, 1500, Phaser.Easing.Cubic.Out, true, initialDelay)
	}

	private showWhiteOverlay(initialDelay: number): void {
		this.game.time.events.add(
			initialDelay,
			() => {
				this.game.sound.play('game_complete_2', 0.66)
			},
			this
		)

		this.whiteOverlay.visible = true
		this.whiteOverlay.alpha = 0
		this.game.add
			.tween(this.whiteOverlay)
			.to({ alpha: 1 }, 66, Phaser.Easing.Cubic.Out, true, initialDelay)
			.onComplete.addOnce(() => {
				this.game.add
					.tween(this.whiteOverlay)
					.to({ alpha: 0 }, 1000, Phaser.Easing.Exponential.In, true)
					.onComplete.addOnce(() => {
						this.whiteOverlay.visible = false
					})
			})
	}

	private showButtons(initialDelay: number): void {
		;[this.shareButton, ...this.bottomButtons].forEach((button, index) => {
			button.visible = true

			let delay: number = initialDelay + index * 100
			this.game.add.tween(button.scale).from({ x: 0.5, y: 0.5 }, 330, Phaser.Easing.Back.Out, true, delay)
			this.game.add.tween(button).from({ y: '+40' }, 330, Phaser.Easing.Back.Out, true, delay)
			this.game.add.tween(button).from({ alpha: 0 }, 150, Phaser.Easing.Cubic.Out, true, delay)
		})
	}

	private shakeShareButton(): void {
		this.game.time.events.loop(4000, this.doShakeShareButton, this)
	}

	private doShakeShareButton(): void {
		this.game.tweens.removeFrom(this.shareButton)
		this.game.tweens.removeFrom(this.shareButton.scale)

		this.shareButton.scale.set(1)
		this.game.add.tween(this.shareButton.scale).to(
			{
				x: 1.1,
				y: 1.1,
			},
			450,
			Phaser.Easing.Sinusoidal.InOut,
			true,
			0,
			0,
			true
		)

		let deltaAngle: number = 3
		this.game.add
			.tween(this.shareButton)
			.to({ angle: deltaAngle }, 100, Phaser.Easing.Linear.None, true)
			.onComplete.addOnce(() => {
				this.game.add
					.tween(this.shareButton)
					.to({ angle: -deltaAngle }, 100, Phaser.Easing.Sinusoidal.InOut, true, 0, 3, true)
					.onComplete.addOnce(() => {
						this.game.add.tween(this.shareButton).to({ angle: 0 }, 100, Phaser.Easing.Linear.None, true)
					})
			})
	}

	private hide(e: Event = null): void {
		this.escKey.onDown.remove(this.hide, this)

		let hideTween: Phaser.Tween = this.game.add.tween(this).to({ alpha: 0 }, 330, Phaser.Easing.Cubic.Out, true)

		hideTween.onStart.addOnce(() => {
			this.onHideStarted.dispatch()
		})

		hideTween.onComplete.addOnce(() => {
			this.onHideCompleteCallback()
		})
	}

	private onHideCompleteCallback(): void {
		this.onHideComplete.dispatch()
		this.visible = false
		this.pendingDestroy = true
	}

	public resize(): void {
		this.bg.resize()

		this.resizeWhiteOverlay()

		this.victoryPanel.centerX = Config.HALF_GAME_WIDTH
		this.victoryPanel.top = Config.GAME_HEIGHT * 0.07

		this.centralItemBack.x = Config.HALF_GAME_WIDTH
		this.centralItemBack.y = Config.GAME_HEIGHT * 0.48

		this.centralItem.x = Config.HALF_GAME_WIDTH
		this.centralItem.y = this.centralItemBack.y + 4 * Config.ASSETS_SCALE
		this.centralItem.saveInitialPosition(this.centralItem.x, this.centralItem.y)

		this.crown.x = this.centralItem.x
		this.crown.y = this.centralItem.top + 17

		this.shareButton.x = Config.HALF_GAME_WIDTH
		this.shareButton.y = this.centralItemBack.bottom - 10

		this.alignBottomButtons()
	}

	private resizeWhiteOverlay() {
		this.whiteOverlay.width = Config.GAME_WIDTH * 1.25
		this.whiteOverlay.height = Config.GAME_HEIGHT * 1.25
		this.whiteOverlay.centerX = Config.HALF_GAME_WIDTH
		this.whiteOverlay.centerY = Config.HALF_GAME_HEIGHT
	}

	private alignBottomButtons() {
		let top: number = this.shareButton.bottom
		let bottom: number = Config.GAME_HEIGHT
		let height: number = bottom - top

		this.buttonsGroup.centerX = Config.HALF_GAME_WIDTH
		this.buttonsGroup.centerY = top + height / 2
	}

	public destroy(): void {
		this.game.time.events.removeBy(this.shakeShareButton, this)
		this.game.time.events.removeBy(this.doShakeShareButton, this)

		this.escKey.onDown.remove(this.hide, this)
		this.escKey = null

		super.destroy(true, false)

		this.disposeSignals()
	}

	private disposeSignals() {
		this.onBackFadeInComplete.dispose()
		this.onBackFadeInComplete = null
		this.onHideStarted.dispose()
		this.onHideStarted = null
		this.onHideComplete.dispose()
		this.onHideComplete = null
	}
}
