import { times } from 'es-toolkit/compat'
import { FontWeight, GameFonts } from '../../../GameFonts'
import { Item } from '../items/Item'
import PhaserTextStyle = Phaser.PhaserTextStyle
export class HighscoreToast extends Phaser.Group {
	private titleLines: string[]
	private back: Phaser.Image
	private shadow: Phaser.Image
	private title: Phaser.Text
	private subtitle: Phaser.Text
	private ripples: Phaser.Image[]
	public originalY: number

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'highscore_toast')

		this.titleLines = this.game.texts.texts['highscore_titles']
		this.addBack()
		this.addShadow()
		this.addTitle()
		this.addSubtitle()
		this.addRipples()
	}

	private addBack(): void {
		this.back = this.game.add.image(0, 0, 'interface', 'Highscore_Back0000', this)
		this.back.anchor.set(0.5, 0.5)
		this.back.tint = 0xea3139
	}

	private addShadow(): void {
		this.shadow = this.game.add.image(0, 0, 'interface', 'Highscore_Back0000', this)
		this.shadow.alpha = 0.2
		this.shadow.tint = this.back.tint
		this.shadow.centerX = this.back.centerX
		this.shadow.bottom = this.back.bottom + 8
	}

	private addTitle(): void {
		let content: string = this.game.rnd.pick(this.titleLines)
		let style: PhaserTextStyle = {
			font: GameFonts.DEFAULT,
			fontWeight: FontWeight.BOLD,
			fontSize: 40,
			fill: '#ffffff',
			align: 'center',
		}

		this.title = this.game.add.text(0, 0, content, style, this)
		this.title.anchor.set(0.5, 0.5)
		this.title.centerX = this.back.centerX
		this.title.y = this.back.top + 32
	}

	private addSubtitle(): void {
		let content: string = this.game.texts.texts.highscore_subtitle
		let style: PhaserTextStyle = {
			font: GameFonts.DEFAULT,
			fontWeight: FontWeight.BOLD,
			fontSize: 22,
			fill: '#ffffff',
			align: 'center',
		}

		this.subtitle = this.game.add.text(0, 0, content, style, this)
		this.subtitle.anchor.set(0.5, 0.5)
		this.subtitle.centerX = this.back.centerX
		this.subtitle.y = this.back.y + 24
	}

	private addRipples(): void {
		this.ripples = times(3, (num: number) => {
			let white: Phaser.Image = this.game.add.image(0, 0, 'interface', 'Highscore_Back0000', this)
			white.anchor.set(0.5, 0.5)
			white.visible = false
			this.sendToBack(white)

			return white
		})
	}

	public updateContent(item: Item): void {
		this.updateTitle(item.itemType)
		this.updateSubtitle(item.itemType)
		this.back.tint = Item.getBackColor(item.itemType)
		this.shadow.tint = Item.getBackColor(item.itemType)
	}

	private updateTitle(itemType: number): void {
		let newTextLine =
			itemType === 12 ? this.game.texts.texts.highscore_title_12 : this.game.rnd.pick(this.titleLines)

		this.title.setText(newTextLine)
		this.adjustTitleSize()
	}

	private adjustTitleSize() {
		let maxWidth: number = this.back.width * 0.82

		this.title.scale.set(1)
		this.title.scale.set(Math.min(1, maxWidth / this.title.width))
	}

	private updateSubtitle(itemType: number): void {
		this.subtitle.text = this.game.texts.texts.highscore_subtitle.replace('#', itemType.toString())
		// this.subtitle.scale.set(this.title.scale.x)
	}

	public show(): void {
		this.revive()

		this.game.tweens.removeFrom(this)
		this.game.tweens.removeFrom(this.scale)

		this.scale.set(1.3)
		this.alpha = 0

		this.game.add.tween(this.scale).to({ x: 1, y: 1 }, 800, Phaser.Easing.Bounce.Out, true)
		this.game.add.tween(this).to({ alpha: 1 }, 300, Phaser.Easing.Linear.None, true)
		this.game.add.tween(this).to({ y: '-14' }, 900, Phaser.Easing.Sinusoidal.InOut, true, 0, -1, true)

		this.showRipples()

		this.game.time.events.removeBy(this.hide, this)
		this.game.time.events.add(3000, this.hide, this)
	}

	private showRipples(): void {
		this.ripples.forEach((ripple, index) => {
			ripple.visible = true
			ripple.alpha = 0.66
			ripple.scale.set(1)

			this.game.tweens.removeFrom(ripple)
			this.game.tweens.removeFrom(ripple.scale)

			let delay: number = 220 + 200 * index
			let targetScale = 1.2
			this.game.add.tween(ripple).to({ alpha: 0 }, 500, Phaser.Easing.Linear.None, true, delay)
			this.game.add.tween(ripple.scale).to(
				{
					x: targetScale,
					y: targetScale,
				},
				500,
				Phaser.Easing.Linear.None,
				true,
				delay
			)
		})
	}

	private hide(): void {
		this.game.tweens.removeFrom(this)
		this.game.tweens.removeFrom(this.scale)

		this.game.add.tween(this.scale).to({ x: 0.66, y: 0.66 }, 330, Phaser.Easing.Back.In, true)
		this.game.add
			.tween(this)
			.to({ alpha: 0 }, 130, Phaser.Easing.Cubic.Out, true, 200)
			.onComplete.addOnce(() => {
				this.visible = false
				this.exists = false
			})
	}

	public destroy(): void {
		this.game.time.events.removeBy(this.hide, this)

		super.destroy(true, false)
	}
}
