import { GameFonts } from './../../../GameFonts';
import { AddCoinsButton } from './AddCoinsButton'

export class ShopCoinsLabel extends Phaser.Group {
	public coinsNum: number = 0
	private back: Phaser.Image
	public coinIcon: Phaser.Image
	public textInitialX: number = 0
	public text: Phaser.BitmapText
	public getCoinsButton: AddCoinsButton

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'coins_label')

		this.addBack()
		this.addCoinIcon()
		this.addGetCoinsButton()
		this.addText()
	}

	private addBack(): void {
		this.back = this.game.add.image(0, 0, 'boosters_shop', 'Coins_Label_Back0000', this)
		this.back.anchor.set(0.5, 0.5)
		this.back.scale.x = 0.9
	}

	private addCoinIcon(): void {
		this.coinIcon = this.game.add.image(0, 0, 'boosters_shop', 'Coins_Label_Coin0000', this)
		this.coinIcon.anchor.set(0.5, 0.5)
		this.coinIcon.left = this.back.left + 18
		this.coinIcon.centerY = this.back.centerY
	}

	private addGetCoinsButton() {
		this.getCoinsButton = new AddCoinsButton(this.game, this)
		this.getCoinsButton.right = this.back.right
		this.getCoinsButton.centerY = this.back.centerY
		this.getCoinsButton.visible = false
	}

	private addText(): void {
		this.text = this.game.add.bitmapText(0, 0, GameFonts.BOOSTERS_SHOP_BARIOL_BOLD, '0000', 42, this)
		this.text.anchor.set(1, 0.5)
		this.text.x = this.back.right - 20
		this.text.centerY = this.coinIcon.centerY + 1

		this.textInitialX = this.text.x
	}

	public updateCount(newCoinsNum: number, tweenX: boolean = false, tweenNumber: boolean = true): void {
		if (this.coinsNum !== newCoinsNum) {
			this.game.tweens.removeFrom(this)
			this.text.setText(newCoinsNum.toString())

			if (tweenX) {
				this.text.x = this.textInitialX

				this.game.tweens.removeFrom(this.text)
				this.game.add.tween(this.text).to({ x: '-10' }, 220, Phaser.Easing.Sinusoidal.InOut, true, 0, 0, true)
			}

			if (tweenNumber) {
				let tween = this.game.add.tween(this).to({ coinsNum: newCoinsNum }, 1333, Phaser.Easing.Exponential.Out)
				tween.onStart.addOnce(() => {
					this.game.audio.playSound('score_count_2', 0.44)
				})
				tween.onComplete.addOnce(() => {
					this.game.add
						.tween(this.text.scale)
						.to({ x: 1.2, y: 1.2 }, 216, Phaser.Easing.Sinusoidal.InOut, true, 0, 0, true)
				})
				tween.onUpdateCallback(() => {
					this.text.setText(this.coinsNum.toFixed(0))
				})
				tween.start()
			} else {
				this.coinsNum = newCoinsNum
			}
		}
	}

	public shake(): void {
		this.game.tweens.removeFrom(this.text)

		this.text.x = this.textInitialX
		this.game.add.tween(this.text).to({ x: '-10' }, 80, Phaser.Easing.Sinusoidal.InOut, true, 0, 3, true)
	}

	public destroy(): void {
		super.destroy(true, false)
	}
}
