import { GameOverButton } from './GameOverButton'

export class GameOverVideoButton extends GameOverButton {
	get wasUsed(): boolean {
		return this._wasUsed
	}

	private videoIcon: Phaser.Image
	private _wasUsed: boolean = false

	constructor(_game: Phaser.Game, parent: Phaser.Group, textContent: string) {
		super(_game, parent, textContent)

		this.addVideoIcon()
		this.alignText()
	}

	private addVideoIcon(): void {
		this.videoIcon = this.game.add.image(0, 0, 'interface', 'Video_Icon0000', this)
		this.videoIcon.anchor.set(0.5, 0.5)
		this.videoIcon.centerX = this.back.left + this.back.width * 0.23
		this.videoIcon.centerY = this.back.centerY
	}

	private alignText(): void {
		let left: number = this.videoIcon.right
		let right: number = this.back.right
		let width: number = right - left

		let maxWidth: number = width * 0.8
		this.text.scale.set(1)
		this.text.scale.set(Math.min(1, maxWidth / this.text.width))
		this.text.centerX = left + width / 2
	}

	public markAsUsed(): void {
		this._wasUsed = true
		this.disable()
	}
}
