type ObjectKeys<T extends object> = (keyof T)[]

export function getObjectKeys<T extends object>(obj: T): ObjectKeys<T> {
	return Object.keys(obj) as ObjectKeys<T>
}

type ObjectKeysWithoutFunctions<T extends object> = Exclude<
	keyof T,
	{ [K in keyof T]: T[K] extends Function ? K : never }[keyof T]
>[]

/**
 * Get the keys of an object without the functions.
 *
 * @example
 * const a = {
 * 	foo: () => {},
 * 	bar: 1,
 * 	baz: 'baz',
 * }
 * const b = getObjectKeysWithoutFunctions(a)
 * console.log(b) // ['bar', 'baz']
 */
export function getObjectKeysWithoutFunctions<T extends object>(obj: T): ObjectKeysWithoutFunctions<T> {
	return getObjectKeys(obj).filter((key) => typeof obj[key] !== 'function') as ObjectKeysWithoutFunctions<T>
}
