export class ComplexButton extends Phaser.Group {
    public get enabled(): boolean {
        return this._enabled
    }

    public set enabled(value: boolean) {
        this._enabled = value
        this.back.input.enabled = this._enabled
    }

    public back: Phaser.Image
    private _enabled: boolean = true
    private _callbackOn: 'pointerdown' | 'pointerup' = 'pointerdown'
    private _callback: Phaser.Signal
    private callbackDelay: number = 0
    private originalScale: Phaser.Point
    public bmpText: Phaser.BitmapText
    public text: Phaser.Text
    public icon: Phaser.Image
    public userData: any
    public soundKey: string = 'tap'

    constructor(_game: Phaser.Game, parent?: Phaser.Group, imageKey?: string, imageFrame?: string) {
        super(_game, parent)

        this.userData = {}
        this.name = 'button_' + imageKey + ', ' + imageFrame
        this._callback = new Phaser.Signal()
        this.addBack(imageKey, imageFrame)
    }

    private addBack(imageKey: string, imageFrame: string): void {
        this.back = this.game.add.image(0, 0, imageKey, imageFrame, this)
        this.back.anchor.set(0.5, 0.5)
        this.back.inputEnabled = true
        this.back.events.onInputDown.add(this.onInputDown, this)
        this.back.events.onInputUp.add(this.onInputUp, this)
        this.back.name = imageFrame

        if (this.game.device.desktop) {
            this.back.input.useHandCursor = true
        }
    }

    private onInputDown(): void {
        if (this.game.cache.checkSoundKey(this.soundKey)) {
            this.game.sound.play(this.soundKey)
        }

        if (this._callbackOn === 'pointerdown') {
            this.executeCallback()
        }

        this.originalScale = this.scale.clone()
        this.game.tweens.removeFrom(this.scale)
        this.game.add.tween(this.scale).to(
            {
                x: this.scale.x * 0.9,
                y: this.scale.y * 0.9,
            },
            100,
            Phaser.Easing.Cubic.Out,
            true
        )
    }

    private onInputUp(back: Phaser.Image, pointer: Phaser.Pointer): void {
        if (this._callbackOn === 'pointerup') {
            this.executeCallback()
        }

        this.game.tweens.removeFrom(this.scale)
        this.game.add.tween(this.scale).to(
            {
                x: this.originalScale.x,
                y: this.originalScale.y,
            },
            150,
            Phaser.Easing.Cubic.Out,
            true
        )
    }

    private executeCallback(): void {
        if (this.callbackDelay > 0) {
            this.game.time.events.add(this.callbackDelay, this._callback.dispatch, this._callback, this)
        } else {
            this._callback.dispatch(this)
        }
    }

    public addIcon(texture: string, frame: string, position: number = Phaser.CENTER): void {
        this.icon = this.game.add.image(0, 0, texture, frame, this)
        this.icon.anchor.set(0.5, 0.5)
        this.icon.alignIn(this.back, position)
    }

    public addBmpText(
        content: string,
        font: string,
        fontSize: number,
        offsetX: number = 0,
        offsetY: number = 0
    ): Phaser.BitmapText {
        this.bmpText = this.game.add.bitmapText(0, 0, font, content, fontSize, this)
        this.bmpText.align = 'center'
        this.bmpText.anchor.set(0.5, 0.5)
        this.bmpText.centerX = this.back.centerX + offsetX
        this.bmpText.centerY = this.back.centerY + offsetY

        return this.bmpText
    }

    public addText(content: string, style: Phaser.PhaserTextStyle): Phaser.Text {
        this.text = this.game.add.text(0, 0, content, style, this)
        this.text.anchor.set(0.5, 0.5)
        this.text.alignIn(this.back, Phaser.CENTER)

        return this.text
    }

    public destroy(): void {
        super.destroy(true, false)

        this._callback.dispose()
        this._callback = null

        this.userData = null
    }

    public setCallbackOn(callbackOn: 'pointerdown' | 'pointerup'): void {
        this._callbackOn = callbackOn
    }

    public get callback(): Phaser.Signal {
        return this._callback
    }

    /*public get inputEnabled():boolean {
        return this._inputEnabled;
    }
    
    public set inputEnabled(value:boolean) {
        this._inputEnabled = value;
        this.back.input.enabled = this._inputEnabled;
    }*/
}
