import { Config } from '../../../Config'
import { GameFonts } from '../../../GameFonts'
import { ComplexButton } from '../../../gui/buttons/ComplexButton'

export class ShareButton extends ComplexButton {
	protected readonly bottomOffset: number = 55
	protected shadow: Phaser.Image
	protected hint: Phaser.BitmapText
	protected hashtag: Phaser.Image
	protected white: Phaser.Image
	public shareMessage: string = ''
	private _shareBitmapData: Phaser.BitmapData

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'game_over', 'Share_Button_Back0000')

		this.addHint()
		this.addShadow()
		this.addWhite()
	}

	private addShadow(): void {
		let shadowOffset: number = 8 * Config.ASSETS_SCALE

		this.shadow = this.game.add.image(0, 0, 'game_over', 'Share_Shadow0000', this)
		this.shadow.centerX = this.back.centerX
		this.shadow.bottom = this.back.bottom + shadowOffset
		this.shadow.tint = 0
		this.shadow.alpha = 0.08
		this.sendToBack(this.shadow)
	}

	private addWhite(): void {
		this.white = this.game.add.image(0, 0, 'game_over', 'Share_Button_Back0000', this)
		this.white.visible = false
	}

	protected addTextContent(): void {}

	private addHint(): void {
		let content: string = this.game.texts.texts['share_tap']
		this.hint = this.game.add.bitmapText(0, 0, GameFonts.GAME_OVER_BARIOL_BOLD, content, 30, this)
		this.hint.anchor.set(0.5, 0.5)
		this.hint.centerX = this.back.centerX
		this.hint.centerY = this.back.bottom - 26
	}

	protected addHashtag(): void {
		this.hashtag = this.game.add.image(0, 0, 'game_over', 'Hashtag0000', this)
		this.hashtag.anchor.set(0.5, 0.5)
		this.hashtag.centerX = this.back.centerX
		this.hashtag.centerY = this.back.top + 194
		this.hashtag.alpha = 0.85
		this.hashtag.visible = false
	}

	public destroy(): void {
		super.destroy()

		if (this._shareBitmapData) {
			this._shareBitmapData.destroy()
			this._shareBitmapData = null
		}
	}
}
