import { SimpleButton } from "../../../gui/buttons/SimpleButton"
import { ToggleButton } from "../../../gui/buttons/ToggleButton"
import { LevelCoinsLabel } from "./LevelCoinsLabel"
import { LevelGUI } from "./LevelGUI"

export class LevelTopPanel extends Phaser.Group {
    private back: Phaser.Image
    public coinsLabel: LevelCoinsLabel
    public boostersButton: ToggleButton
    public pauseButton: SimpleButton
    private buttons: SimpleButton[]

    constructor(_game: Phaser.Game, parent: Phaser.Group) {
        super(_game, parent, 'top_panel')

        this.addBack()
        this.addCoinsLabel()
        this.addPauseButton()
        this.addBoostersButton()

        this.buttons = [this.boostersButton, this.pauseButton]
    }

    private addBack() {
        this.back = this.game.add.image(0, 0, 'interface', 'Panel_Back0000', this)
        this.back.tint = LevelGUI.NORMAL_COLOR
    }

    private addCoinsLabel() {
        let coinsNum: number = this.game.save.getCoins()

        this.coinsLabel = new LevelCoinsLabel(this.game, this)
        this.coinsLabel.updateContent(coinsNum, true)
    }

    private addBoostersButton() {
        this.boostersButton = new ToggleButton(
            this.game,
            0,
            0,
            'interface',
            'Boosters_Button_Show0000',
            'Boosters_Button_Hide0000'
        )
        this.add(this.boostersButton)
    }

    private addPauseButton() {
        this.pauseButton = new SimpleButton(this.game, 0, 0, 'interface', 'Button_Pause0000')
        this.add(this.pauseButton)
    }

    public resize(width: number, height: number, contentWidth: number): void {
        this.back.width = width
        this.back.height = height

        this.alignContent(width, contentWidth)
    }

    private alignContent(width: number, contentWidth: number) {
        let sidePadding: number = (width - contentWidth) / 2

        this.coinsLabel.resize(this.back.height)
        this.coinsLabel.left = this.back.left + sidePadding
        this.coinsLabel.centerY = this.back.centerY

        this.pauseButton.right = this.back.right - sidePadding
        this.pauseButton.centerY = this.back.centerY + 4

        this.boostersButton.x = this.pauseButton.x - 90
        this.boostersButton.centerY = this.pauseButton.centerY
    }

    public hideForTutorial(): void {
        // this.coinsLabel.visible = false;
        this.coinsLabel.alpha = 0
        this.buttons.forEach((button) => {
            button.visible = false
        })
    }

    public showAfterTutorial(): void {
        // this.coinsLabel.visible = true;
        this.coinsLabel.alpha = 1
        this.buttons.forEach((button) => {
            button.visible = true
        })
    }

    public enableButtons(): void {
        this.buttons.forEach((button) => {
            button.enabled = true
            button.alpha = 1
        })
    }

    public disableButtons(): void {
        this.buttons.forEach((button) => {
            button.enabled = false
            button.alpha = LevelGUI.DISABLED_BUTTON_ALPHA
        })
    }

    public enableInput() {
        this.buttons.forEach((button) => {
            button.enabled = true
        })
    }

    public disableInput() {
        this.buttons.forEach((button) => {
            button.enabled = false
        })
    }

    public onBoosterHintShow() {
        this.coinsLabel.visible = false
        this.buttons.forEach((button) => {
            button.visible = false
        })
    }

    public onBoosterHintHide(): void {
        this.coinsLabel.visible = true
        this.buttons.forEach((button) => {
            button.visible = true
        })
    }

    public destroy(): void {
        super.destroy(true, false)
    }
}
