import { BrowserSyncApiEndpoint } from './BrowserSyncApiEndpoint'

export const BrowserSyncService = {
	isAvailable(): boolean {
		return typeof window['___browserSync___'] !== 'undefined'
	},

	getUrl(apiEndpoint: BrowserSyncApiEndpoint): string {
		return `${location.protocol}//${location.host}/${apiEndpoint}`
	},

	saveScreenshot(blob: Blob, gameState?: string, language?: string): Promise<{ filename: string }> {
		if (this.isAvailable() === false) {
			throw new Error('BrowserSync is not available!')
		}

		const params = new URLSearchParams()
		if (gameState) {
			params.append('state', gameState)
		}
		if (language) {
			params.append('lang', language)
		}

		let url = this.getUrl('screenshot')
		if (params.toString()) {
			url += `?${params.toString()}`
		}

		return fetch(url, {
			method: 'POST',
			body: blob,
		}).then(async (response) => {
			if (!response.ok) {
				const text = await response.text().catch(() => '')
				throw new Error(`Screenshot upload failed (${response.status}): ${text}`)
			}
			return response.json()
		})
	},
}
