import { Config } from '../../../Config'
import { SimpleButton } from '../../../gui/buttons/SimpleButton'
import { ToggleButtonState } from '../../../gui/buttons/ToggleButton'
import { BoosterType } from '../boosters/BoosterType'
import { Grid } from '../grid/Grid'
import { Item } from '../items/Item'
import { Level } from '../Level'
import { Tutorial } from '../tutorial/Tutorial'
import { HeadstartPopup } from './../../../gui/popups/HeadstartPopup'
import { Booster } from './../boosters/Booster'
import { BoosterHint } from './boostersPanel/BoosterHint'
import { BoostersPanel } from './boostersPanel/BoostersPanel'
import { FreeBoostersPopover } from './freeBoosters/FreeBoostersPopover'
import { GameOverGUI } from './gameOver/GameOverGUI'
import { HighscoreToast } from './HighscoreToast'
import { LevelCoinsLabel } from './LevelCoinsLabel'
import { LevelTopPanel } from './LevelTopPanel'
import { PauseScreen } from './pauseScreen/PauseScreen'

export class LevelGUI extends Phaser.Group {
	public static NORMAL_COLOR: number = 0xffb751
	public static GAME_OVER_COLOR: number = 0xe57373
	public static DISABLED_BUTTON_ALPHA: number = 0.7
	public static PANEL_HEIGHT: number = 110

	private level: Level
	private grid: Grid
	public topPanel: LevelTopPanel
	public freeBoostersPopover: FreeBoostersPopover
	public boostersPanel: BoostersPanel
	private highscoreToast: HighscoreToast
	private boosterHint: BoosterHint
	public pauseScreen: PauseScreen
	public gameOver: GameOverGUI
	private restartOverlay: Phaser.Image
	public headstartPopup: HeadstartPopup

	public onUndoSelected: Phaser.Signal
	public onBoosterSelected: Phaser.Signal
	public onBoosterCancelled: Phaser.Signal

	constructor(_game: Phaser.Game, parent: Phaser.Group, level: Level) {
		super(_game, parent, 'level_gui')

		this.level = level
		this.grid = this.level.grid

		this.onUndoSelected = new Phaser.Signal()
		this.onBoosterSelected = new Phaser.Signal()
		this.onBoosterCancelled = new Phaser.Signal()

		this.addTopPanel()
		this.addFreeBoostersPopover()
		this.addBoostersPanel()
		this.addHighscoreToast()
		this.addGameOver()
		this.addBoosterHint()
		this.addPauseScreen()
		this.addRestartOverlay()
	}

	private addTopPanel(): void {
		this.topPanel = new LevelTopPanel(this.game, this)

		if (this.game.ads.provider.name === 'noop') {
			this.topPanel.boostersButton.kill()
		} else {
			this.topPanel.boostersButton.callback.add(this.toggleFreeBoosters, this)
		}
	}

	public toggleFreeBoosters(): void {
		if (this.freeBoostersPopover.visible) {
			this.hideFreeBoostersPopover()
		} else {
			this.showFreeBoostersPopover()
		}
	}

	public hideFreeBoostersPopover() {
		this.level.pointerEnabled = true

		this.pauseButton.enabled = true
		this.pauseButton.alpha = 1
		this.boostersPanel.enableInput()

		this.freeBoostersPopover.hide()
	}

	private showFreeBoostersPopover() {
		this.level.pointerEnabled = false
		this.level.pointerDown = false

		this.pauseButton.enabled = false
		this.pauseButton.alpha = LevelGUI.DISABLED_BUTTON_ALPHA
		this.boostersPanel.disableInput()

		this.freeBoostersPopover.x = this.topPanel.boostersButton.x
		this.freeBoostersPopover.y = this.topPanel.boostersButton.bottom - 4
		this.freeBoostersPopover.show()
	}

	private addFreeBoostersPopover(): void {
		this.freeBoostersPopover = new FreeBoostersPopover(this.game, this)
		this.freeBoostersPopover.onBoosterRewarded.add(this.onFreeBoosterEarned, this)
		this.freeBoostersPopover.kill()
	}

	private onFreeBoosterEarned(boosterType: BoosterType, boostersNum: number): void {
		let booster: Booster = this.game.boosters.getBooster(boosterType)
		if (!booster) {
			return
		}

		booster.num += boostersNum
		this.boostersPanel.getButton(boosterType).highlight()
		this.boostersPanel.updateData()
		this.hideFreeBoostersPopover()
		this.topPanel.boostersButton.buttonState = ToggleButtonState.STATE_1
		this.game.sound.play('booster_selected', 0.5)
		this.level.saveGameStateInStore()
	}

	private addBoostersPanel(): void {
		this.boostersPanel = new BoostersPanel(this.game, this)
		this.boostersPanel.onBoosterSelected.add(this.onBoosterSelectedCallback, this)
		this.boostersPanel.onBoosterCanceled.add(this.onBoosterCancelledCallback, this)
		this.boostersPanel.updateData()
	}

	private onBoosterSelectedCallback(boosterType: BoosterType): void {
		let booster: Booster = this.game.boosters.getBooster(boosterType)
		if (boosterType === BoosterType.UNDO) {
			this.boostersPanel.deselectAllButtons()
			this.onUndoSelected.dispatch()
			return
		}

		this.boostersPanel.disableInput()
		this.boostersPanel.getButton(boosterType).select()
		this.boostersPanel.getButton(boosterType).ignoreChildInput = false

		this.topPanel.disableInput()

		this.boosterHint.onCancel.addOnce(this.onBoosterCancelledCallback, this)
		this.boosterHint.top = 0
		this.boosterHint.updateContent(booster.hint)
		this.boosterHint.show()

		if (this.gameOver.visible) {
			this.gameOver.onBoosterSelected(this.boosterHint)
		}

		this.onBoosterSelected.dispatch(boosterType)
	}

	private onBoosterCancelledCallback(boosterType: BoosterType): void {
		this.boostersPanel.deselectAllButtons()
		this.boostersPanel.enableInput()

		if (this.gameOver) {
			this.boosterHint.hideInstant()
		} else {
			this.boosterHint.hide()
		}

		this.topPanel.enableInput()

		if (this.gameOver.visible) {
			this.gameOver.onBoosterCancelled()
		}

		this.onBoosterCancelled.dispatch()
	}

	public onBoosterComplete(): void {
		this.boosterHint.hide()

		this.boostersPanel.enableInput()
		this.boostersPanel.deselectAllButtons()
		this.boostersPanel.updateData()

		this.topPanel.onBoosterHintHide()
		this.topPanel.enableInput()

		if (this.gameOver.visible) {
			this.gameOver.hide()
			this.boostersPanel.setNormalColors()
			this.topPanel.enableButtons()
		}
	}

	private addHighscoreToast(): void {
		this.highscoreToast = new HighscoreToast(this.game, this)
		this.highscoreToast.kill()
	}

	private addGameOver(): void {
		this.gameOver = new GameOverGUI(this.game, this)
		this.gameOver.kill()
	}

	private addBoosterHint(): void {
		this.boosterHint = new BoosterHint(this.game, this)
	}

	private addPauseScreen(): void {
		this.pauseScreen = new PauseScreen(this.game, this)
		this.pauseScreen.kill()
	}

	private addRestartOverlay(): void {
		this.restartOverlay = this.game.add.image(0, 0, 'interface', 'white_rect0000', this)
		this.restartOverlay.anchor.set(0.5, 0.5)
		this.restartOverlay.visible = false
		this.restartOverlay.name = 'restart_overlay'
	}

	public addHeadstartPopup(): HeadstartPopup {
		this.headstartPopup = new HeadstartPopup(this.game, this)

		return this.headstartPopup
	}

	public addTutorial(): Tutorial {
		let tutorial: Tutorial = new Tutorial(this.game, this, this.level)
		tutorial.initAllowedItems()
		tutorial.parent.bringToTop(tutorial)

		return tutorial
	}

	public showRestartOverlay(): void {
		this.restartOverlay.bringToTop()
		this.restartOverlay.visible = true
		this.restartOverlay.alpha = 1
		this.game.add
			.tween(this.restartOverlay)
			.to({ alpha: 0 }, 500, Phaser.Easing.Cubic.In, true, 100)
			.onComplete.addOnce(() => {
				this.restartOverlay.visible = false
			})
	}

	public onPause(moves: number): void {
		this.game.time.events.add(100, this.pauseScreen.show, this.pauseScreen, moves)

		this.game.add
			.tween(this.topPanel)
			.to({ alpha: 0 }, 200, Phaser.Easing.Cubic.Out, true)
			.onComplete.addOnce(() => {
				this.topPanel.visible = false
			})

		this.game.add
			.tween(this.boostersPanel)
			.to({ alpha: 0 }, 200, Phaser.Easing.Cubic.Out, true)
			.onComplete.addOnce(() => {
				this.boostersPanel.visible = false
			})

		this.highscoreToast.visible = false
	}

	public onResume(): void {
		this.pauseScreen.hide()

		this.topPanel.visible = true
		this.game.tweens.removeFrom(this.topPanel)
		this.game.add.tween(this.topPanel).from({ y: '-40' }, 200, Phaser.Easing.Cubic.Out, true)
		this.game.add.tween(this.topPanel).to({ alpha: 1 }, 200, Phaser.Easing.Cubic.Out, true)

		this.boostersPanel.visible = true
		this.game.tweens.removeFrom(this.boostersPanel)
		this.game.add.tween(this.boostersPanel).from({ y: '+40' }, 200, Phaser.Easing.Cubic.Out, true)
		this.game.add.tween(this.boostersPanel).to({ alpha: 1 }, 200, Phaser.Easing.Cubic.Out, true)
	}

	public onRestore(): void {
		this.showRestartOverlay()

		if (this.gameOver.visible) {
			this.gameOver.hide()
			this.boostersPanel.setNormalColors()
			this.topPanel.enableButtons()
		}
	}

	public onGameOver(): void {
		if (this.gameOver.visible !== false) {
			return
		}

		this.game.sound.play('no_moves_1', 0.66)
		this.topPanel.disableInput()
		this.boostersPanel.enableInput()
		this.boostersPanel.setGameOverColors()
		this.gameOver.top = 0
		this.gameOver.show()

		// if (this.gameOverTutorial) {
		// 	this.gameOver.disableInput()
		// 	this.boostersPanel.disableInput()
		//
		// 	this.gameOverTutorial.onComplete.addOnce(this.onGameOverTutorialComplete, this)
		// 	this.gameOverTutorial.show(this.gameOver)
		// }
	}

	private onGameOverTutorialComplete(): void {
		this.gameOver.enableInput()
		this.boostersPanel.enableInput()
	}

	public onContinueAfterGameOver(): void {
		this.topPanel.enableInput()
		this.topPanel.enableButtons()

		this.boostersPanel.setNormalColors()

		this.gameOver.hide()
	}

	public show(delay: number): void {
		let offsetY: number = 60 * Config.ASSETS_SCALE
		let duration = 400

		this.game.add.tween(this.topPanel).from(
			{
				y: `-${offsetY}`,
				alpha: 0,
			},
			duration,
			Phaser.Easing.Cubic.Out,
			true,
			delay
		)

		this.game.add.tween(this.boostersPanel).from(
			{
				y: `+${offsetY}`,
				alpha: 0,
			},
			duration,
			Phaser.Easing.Cubic.Out,
			true,
			delay
		)
	}

	public showHighscoreToast(item: Item): void {
		this.highscoreToast.x = Config.HALF_GAME_WIDTH
		this.highscoreToast.y = this.boostersPanel.y
		this.highscoreToast.updateContent(item)
		this.highscoreToast.show()
	}

	// adjust panel heights
	public initialResize(): void {
		this.topPanel.resize(Config.GAME_WIDTH, LevelGUI.PANEL_HEIGHT, Config.GAME_WIDTH * 0.85)
		this.topPanel.top = 0
		this.topPanel.centerX = Config.HALF_GAME_WIDTH

		this.boostersPanel.resize(LevelGUI.PANEL_HEIGHT)
		this.boostersPanel.centerX = Config.HALF_GAME_WIDTH
		this.boostersPanel.bottom = Config.GAME_HEIGHT

		this.highscoreToast.centerX = Config.HALF_GAME_WIDTH
		this.highscoreToast.y = this.boostersPanel.top
		this.highscoreToast.originalY = this.highscoreToast.y

		this.gameOver.resize(Config.GAME_WIDTH)
		this.gameOver.top = 0
		this.gameOver.centerX = Config.HALF_GAME_WIDTH

		if (this.headstartPopup) {
			this.headstartPopup.resize()
		}

		this.pauseScreen.resize()
		this.resizeRestartOverlay()
	}

	private resizeRestartOverlay() {
		this.restartOverlay.width = Config.GAME_WIDTH * 1.2
		this.restartOverlay.height = Config.GAME_HEIGHT * 1.2
		this.restartOverlay.centerX = Config.HALF_GAME_WIDTH
		this.restartOverlay.centerY = Config.HALF_GAME_HEIGHT
	}

	// adjust sizes which depends on grid size and position
	public finalResize(): void {
		let contentWidth: number = Math.max(Config.GAME_WIDTH * 0.8, this.level.grid.width)
		this.topPanel.resize(Config.GAME_WIDTH, LevelGUI.PANEL_HEIGHT, contentWidth)
		this.topPanel.top = 0
		this.topPanel.centerX = Config.HALF_GAME_WIDTH

		this.freeBoostersPopover.centerX = this.topPanel.boostersButton.centerX
		this.freeBoostersPopover.top = this.topPanel.boostersButton.bottom + 6

		if (this.level.tutorial) {
			this.level.tutorial.resize(LevelGUI.PANEL_HEIGHT)
			this.level.tutorial.centerX = this.topPanel.centerX
			this.level.tutorial.centerY = this.topPanel.centerY
		}

		this.boosterHint.resize(contentWidth, LevelGUI.PANEL_HEIGHT)
		this.boosterHint.centerX = this.topPanel.centerX
		this.boosterHint.centerY = this.topPanel.centerY
	}

	public destroy(): void {
		super.destroy(true, false)

		this.disposeSignals()

		this.level = null
	}

	private disposeSignals() {
		this.onBoosterSelected.dispose()
		this.onBoosterSelected = null
		this.onBoosterCancelled.dispose()
		this.onBoosterCancelled = null
		this.onUndoSelected.dispose()
		this.onUndoSelected = null
	}

	public get coinsLabel(): LevelCoinsLabel {
		return this.topPanel.coinsLabel
	}

	public get pauseButton(): SimpleButton {
		return this.topPanel.pauseButton
	}
}
