export class Boot extends Phaser.State {
	public async init() {
		this.initAnalytics()

		this.game.avif = await this.checkAvifSupport()

		// with this particular game the compressed pngs are smaller when webps so we can just skip webp entirely
		// this.game.webp = this.checkWebpSupport()

		this.patchImagesLoading()
	}

	private initAnalytics(): void {
		this.game.analytics = new GameAnalyticsWrapper({
			game: this.game,
			logger: this.game.logs.getOrCreate('analytics'),
		})
	}

	private checkAvifSupport(): Promise<boolean> {
		let disableAvif = NetUtil.getParamBool('noAvif')
		if (disableAvif) {
			return Promise.resolve(false)
		}

		let isDevBuild = window.game.config.build_type === 'dev'
		if (isDevBuild) {
			return Promise.resolve(false)
		}

		return new Promise<boolean>((resolve) => {
			let callback = () => (image.height === 2 ? resolve(true) : resolve(false))
			let image = new Image()
			image.onload = callback
			image.onerror = callback
			image.src =
				'data:image/avif;base64,'
		})
	}

	private checkWebpSupport() {
		let disableWebP = NetUtil.getParamBool('noWebp')
		if (disableWebP) {
			return false
		}

		let isDevBuild = window.game.config.build_type === 'dev'
		if (isDevBuild) {
			return false
		}

		return this.checkWebP()
	}

	private checkWebP() {
		let match = navigator.userAgent.match(/(Edge|Firefox)\/(\d+)\.(\d*)/)
		if (match && match[1] === 'Firefox' && +match[2] >= 65) {
			return true
		}

		// https://web.archive.org/web/20190626051700/https://developer.microsoft.com/en-us/microsoft-edge/platform/issues/19618851/
		if (match && match[1] === 'Edge' && +match[2] === 18 && +match[3] === 17763) {
			return false
		}

		let canvas = Phaser.CanvasPool.create(document.body)
		let supported = canvas.toDataURL ? canvas.toDataURL('image/webp').indexOf('data:image/webp') == 0 : false

		Phaser.CanvasPool.remove(canvas)

		return supported
	}

	private patchImagesLoading() {
		if (!this.game.avif && !this.game.webp) {
			return
		}

		let newFormat = this.game.avif ? '.avif' : '.webp'
		let formatsToReplace = ['.png', '.jpg']

		let original = Phaser.Loader.prototype.addToFileList
		Phaser.Loader.prototype.addToFileList = function (type, key, url, properties, overwrite, extension) {
			let format = formatsToReplace.find((_format) => url.includes(_format))
			if (format) {
				url = url.replace(format, newFormat)
			}

			original.call(this, type, key, url, properties, overwrite, extension)

			return this
		}
	}

	public preload() {}

	public async create() {
		this.initGameController()

		this.addPlugins()
		this.setupScale()
		this.addFPSMeter()
		this.detectModernDevice()
		this.fixAndroidDoubleClickBug()
		this.decoratePage()

		this.game.input.maxPointers = 1

		await this.initGamePush()

		await Promise.all([this.loadWebFonts(), this.initPlatform()])

		this.initVisibilityService()

		await this.initTimeService()

		await this.initSaveService()

		this.initAudio()

		this.initAdsService()

		if (this.game.platform.type === 'yandex') {
			this.showInterstitialAdOnBoot()
		}

		if (this.game.platform.isBannerAdSupported()) {
			this.showBannerAdOnBoot()
		}

		this.initLeaderboards()

		this.game.state.start('Preloader', true, false)
	}

	private addPlugins(): void {
		this.game.stateTransitionPlugin = this.game.add.plugin(new StateTransition(this.game)) as StateTransition
		this.game.kineticScrolling = this.game.plugins.add(Phaser.Plugin.KineticScrolling)

		// this.game.plugins.add(PhaserNineSlice.Plugin)
		// this.game.plugins.add(PhaserCachebuster.CacheBuster)

		if (Phaser.Plugin.SceneGraph) {
			this.game.plugins.add(Phaser.Plugin.SceneGraph, { quiet: true })
		}
	}

	private setupScale(): void {
		this.game.scaler = new GameScaler({
			game: this.game,
			scaleMode: isDesktop() ? 'desktop' : 'mobile',
		})
	}

	private decoratePage(): void {
		if (this.game.scaler.scaleMode === 'mobile') {
			document.querySelectorAll('.sidebar').forEach((sidebar) => {
				sidebar.remove()
			})
			return
		}

		let removeSidebars: boolean = NetUtil.getParamBool('noSidebars')
		if (removeSidebars === false) {
			const imageFormat = this.getDefaultImageFormat()

			// this.addSidebars(this.game.canvas, imageFormat)

			const imageUrl = getCacheBustedUrl(`assets/graphics/page_background.${imageFormat}`)
			this.game.canvas.parentElement.style.backgroundImage = `url('${imageUrl}')`
			this.game.canvas.style.boxShadow = '0px 0px 5px 5px rgba(0, 0, 0, 0.07)'
			this.game.scale.refresh()
		} else {
			this.game.scale.pageAlignHorizontally = true
			this.game.scale.pageAlignVertically = true
			this.game.scale.align(true, true)
		}
	}

	private getDefaultImageFormat() {
		if (this.game.avif) {
			return 'avif'
		} else if (this.game.webp) {
			return 'webp'
		} else {
			return 'png'
		}
	}

	private addSidebars(canvas: HTMLCanvasElement, imageFormat: string) {
		let leftImageUrl = getCacheBustedUrl(`assets/graphics/page_sidebar_left.${imageFormat}`)
		let leftSidebar = document.createElement('div')
		leftSidebar.className = 'sidebar'
		leftSidebar.style.backgroundImage = `url('${leftImageUrl}')`
		canvas.parentNode.insertBefore(leftSidebar, canvas)

		let rightImageUrl = getCacheBustedUrl(`assets/graphics/page_sidebar_right.${imageFormat}`)
		let rightSidebar = document.createElement('div')
		rightSidebar.className = 'sidebar'
		rightSidebar.style.backgroundImage = `url('${rightImageUrl}')`
		canvas.parentNode.insertBefore(rightSidebar, canvas.nextSibling)
	}

	private addFPSMeter(): void {
		let showStats: boolean = NetUtil.getParamBool('stats')
		if (showStats) {
			this.stage.addChild(new FPSMeter(this.game))
		}
	}

	private detectModernDevice(): void {
		Main.modernDevice = this.game.renderType === Phaser.WEBGL || this.game.renderType === Phaser.WEBGL_MULTI
	}

	private fixAndroidDoubleClickBug() {
		if (this.game.device.touch && this.game.device.android) {
			this.game.input.mouse.enabled = false
			this.game.input.mouse.stop()
		}
	}

	private loadWebFonts(): Promise<any> {
		return new Promise<any>((resolve, reject) => {
			// @ts-expect-error
			WebFont.load({
				custom: {
					families: ['Nunito:n4,n7'],
					urls: [getCacheBustedUrl('css/fonts.css')],
				},
				inactive: reject, // @ts-ignore
				active: resolve, // @ts-ignore
			})
		})
	}

	private async initGamePush() {
		if (!window.game.config.gamePush?.enabled) {
			this.game.gamePush = null
			return
		}

		this.game.gamePush = new GamePushService({
			logger: this.game.logs.getOrCreate('game-push'),
			projectId: '20712',
			publicToken: 'umL4Uqy3nWsUzpEHKi8uxY02RereaOpM',
		})

		this.game.gamePush.once('multi-session', () => {
			throw new MultiSessionError()
		})

		await this.game.gamePush.init()

		if (window.game.config.env !== Env.PROD) {
			this.game.gamePush.player.set('role', 'admin')
		}
	}

	private async initPlatform() {
		const platformType = window.game.config.platform

		this.game.platform = this.createPlatform(platformType)
		this.game.platform.on('player-logged-in', this.onPlayerLoggedIn.bind(this))
		this.game.platform.on('player-logged-out', this.onPlayerLoggedOut.bind(this))

		await this.game.platform.init()
	}

	private createPlatform(type: Platform): BasePlatform {
		const options: BasePlatformOptions = {
			game: this.game,
			logger: this.game.logs.getOrCreate('platform'),
			sentry: this.game.sentry,
		}

		return match(type)
			.with('dummy', () => new DummyPlatform(options))
			.with('yandex', () => new YaPlatform(options))
			.with('vk', () => new VkPlatform(options))
			.with('playgama', () => new PlaygamaPlatform(options))
			.with('viverse', () => new ViversePlatform(options))
			.exhaustive()
	}

	private onPlayerLoggedIn(id: string): void {}

	private onPlayerLoggedOut(): void {}

	private initVisibilityService(): void {
		this.game.visibility = new VisibilityService({
			logger: this.game.logs.getOrCreate('visibility'),
			provider: this.game.platform.getVisibilityProvider(),
		})

		this.game.visibility.on('page-visible', () => this.game.multiTabTracker.throwIfSessionExpired())
	}

	private async initTimeService() {
		const logger = this.game.logs.getOrCreate('time')

		const serverTimeGetter = this.getServerTimeGetter()

		const [serverTimeError, serverTime] = await until(() => serverTimeGetter())

		if (serverTimeError) {
			logger.warn(`failed to get server time (${getErrorLog(serverTimeError)})`)
		}

		this.game.timeSvc = new TimeService({
			logger,
			debugStorage: this.game.debugStorage,
			visibility: this.game.visibility,
			serverTimeGetter: serverTimeGetter,
			startTime: {
				local: Date.now(),
				server: serverTime ?? Date.now(),
			},
		})
	}

	private getServerTimeGetter() {
		if (this.game.platform instanceof YaPlatform) {
			return async () => (this.game.platform as YaPlatform).sdk.serverTime()
		}

		if (this.game.platform instanceof PlaygamaPlatform) {
			return async () => (this.game.platform as PlaygamaPlatform).getServerTime()
		}

		if (window.game.config.env === 'local') {
			return async () => {
				return Date.now()
			}
		}

		if (!this.game.gamePush) {
			return async () => {
				return Date.now()
			}
		}

		return async () => {
			return this.game.gamePush!.serverTime
		}
	}

	private async initSaveService() {
		const localStorage = await this.createLocalStorage(this.game.platform)

		const remoteStorage = await this.createRemoteStorage(this.game.platform)

		const stateService = new StateService({
			logger: this.game.logs.getOrCreate('state'),
			debugStorage: this.game.debugStorage,
			remoteStorage: remoteStorage,
			localStorage: localStorage,
			sentry: this.game.sentry,
		})

		const initialState = await stateService.init()

		this.game.save = new SaveService({
			logger: this.game.logs.getOrCreate('save'),
			initialState: initialState,
			debugStorage: this.game.debugStorage,
			remoteStorage: remoteStorage,
			remoteSaveIntervalMs: this.getRemoteSaveIntervalMs(),
			localStorage: localStorage,
			sentry: this.game.sentry,
			multiTabTracker: this.game.multiTabTracker,
			time: this.game.timeSvc,
		})

		await this.game.save.init()
	}

	private getRemoteSaveIntervalMs(): number {
		return match(this.game.platform.type)
			.with('dummy', () => toMs({ minutes: 1 }))
			.with('yandex', () => toMs({ seconds: 4 }))
			.with('vk', () => toMs({ seconds: 4 }))
			.with('playgama', () => toMs({ seconds: 4 }))
			.with('viverse', () => toMs({ minutes: 1 }))
			.exhaustive()
	}

	private async createLocalStorage(platform: BasePlatform): Promise<BaseStorage> {
		const storageLogger = this.game.logs.getOrCreate('storage')
		const logger = storageLogger.getSubLogger({ name: ':local' })
		const createDefaultStorage = () =>
			new LocalStorage({
				logger: logger,
				sentry: this.game.sentry,
				useEncryption: window.game.config.env !== 'local',
			})

		if (platform instanceof PlaygamaPlatform) {
			const storageType: PlaygamaStorageType = 'local_storage'
			const storage = await platform.getStorageForType(storageType)
			if (!storage) {
				logger.warn(`${storageType} storage is not available, using fallback local storage`)
				return createDefaultStorage()
			}

			return new PlaygamaRemoteStorage({
				logger: logger,
				sentry: this.game.sentry,
				storage: storage,
				storageType: 'local_storage',
			})
		}

		if (platform instanceof YaPlatform) {
			// redefine window.localStorage to use yandex safe storage
			// https://yandex.ru/dev/games/doc/ru/sdk/sdk-player#progress-loss
			const [safeStorageError, safeStorage] = await until(() => platform.getStorage())
			if (safeStorageError) {
				logger.warn(`failed to get safe storage (${getErrorLog(safeStorageError)})`)
				// TODO save: send GA or Sentry event
			} else {
				Object.defineProperty(window, 'localStorage', { get: () => safeStorage })
				logger.info('Yandex safe storage is working')
			}
		}

		return createDefaultStorage()
	}

	private async createRemoteStorage(platform: BasePlatform): Promise<BaseStorage> {
		const storageLogger = this.game.logs.getOrCreate('storage')

		return match(platform)
			.with(P.instanceOf(DummyPlatform), (dummyPlatform: DummyPlatform) => {
				return new DummyStorage({
					logger: storageLogger.getSubLogger({ name: ':remote' }),
					sentry: this.game.sentry,
				})
			})
			.with(P.instanceOf(PlaygamaPlatform), async (playgama: PlaygamaPlatform) => {
				/* const logger = storageLogger.getSubLogger({ name: ':playgama' })
				
				return new DummyStorage({
					logger: logger,
					sentry: this.game.sentry,
				}) */

				const logger = storageLogger.getSubLogger({ name: ':playgama' })

				const storageType: PlaygamaStorageType = 'platform_internal'
				const storage = await playgama.getStorageForType(storageType)

				if (!storage) {
					logger.warn(`${storageType} storage is not available, using fallback remote storage`)

					return new DummyStorage({
						logger: logger,
						sentry: this.game.sentry,
					})
				}

				return new PlaygamaRemoteStorage({
					logger: logger,
					sentry: this.game.sentry,
					storage: storage,
				})
			})
			.with(P.instanceOf(YaPlatform), async (yandex: YaPlatform) => {
				const logger = storageLogger.getSubLogger({ name: ':yandex' })
				const [playerError, player] = await until(() => yandex.sdk.getPlayer({ signed: false }))

				if (playerError) {
					logger.warn(`failed to get player (${getErrorLog(playerError)})`)
					// TODO save: send GA or Sentry event
				}

				return new YandexRemoteStorage({
					logger: logger,
					sentry: this.game.sentry,
					player: player,
				})
			})
			.with(P.instanceOf(VkPlatform), async (vk: VkPlatform) => {
				if (!vk.bridge) {
					throw new Error('VK Bridge is not initialized, remote saves are disabled')
				}

				return new VkRemoteStorage({
					logger: storageLogger.getSubLogger({ name: ':vk' }),
					sentry: this.game.sentry,
					bridge: vk.bridge,
				})
			})
			.exhaustive()
	}

	private initAudio(): void {
		this.game.audio = new GameAudio({
			game: this.game,
			save: this.game.save,
		})

		// this.game.audio.trackFocusChange()
		this.game.audio.loadMute()
	}

	private initAdsService(): void {
		this.game.ads = new AdsService({
			game: this.game,
			provider: this.createAdsProvider(this.game.platform),
			visibility: this.game.visibility,
			logger: this.game.logs.getOrCreate('ads'),
			cooldownMs: {
				interstitial: 10_000,
				rewarded: 10_000,
			},
		})

		this.game.ads.on('before-ad-start', this.onBeforeAdStart.bind(this))
		this.game.ads.on('after-ad-finish', this.onAfterAdFinished.bind(this))
	}

	private createAdsProvider(platform: BasePlatform): IAdsProvider {
		return match(platform.type)
			.with('dummy', () => new FakeAdsProvider(this.game))
			.with('yandex', () => new YaAdsProvider(platform as YaPlatform))
			.with('vk', () => new VkAdsProvider(platform as VkPlatform))
			.with('playgama', () => new PlaygamaAdsProvider(platform as PlaygamaPlatform))
			.with('viverse', () => new NoopAdsProvider())
			.exhaustive()
	}

	private onBeforeAdStart(timeoutAt: number, adType: AdType): void {
		const showDelayMs = adType === 'rewarded' ? 0 : 500

		this.game.globalScene?.waitingScreen?.show({
			showDelayMs: showDelayMs,
			reason: 'show-ad',
			text: this.game.texts.texts.ads_loading,
		})
	}

	private onAfterAdFinished(adType: AdType, result: AdBasicResult): void {
		this.game.globalScene?.waitingScreen?.hide()

		if (adType === 'rewarded' && result.success === false) {
			const code = result.error.code
			if (code === AdErrorCode.ADBLOCKED) {
				this.showAdblockWarning()
			} else if (code === AdErrorCode.CALL_LIMIT) {
				this.showAdCallLimitWarning()
			} else if (code === AdErrorCode.NO_FILL || code === AdErrorCode.GENERIC) {
				this.showAdGenericError()
			}
		}
	}

	private showAdblockWarning(): void {
		this.game.globalScene?.alertScreen?.show({
			title: this.game.texts.texts.ad_error_title,
			message: this.game.texts.texts.ad_error_adblock,
		})
	}

	private showAdCallLimitWarning(): void {
		this.game.globalScene?.alertScreen?.show({
			title: this.game.texts.texts.ad_cooldown_title,
			message: this.game.texts.texts.ad_cooldown_text,
		})
	}

	private showAdGenericError(): void {
		this.game.globalScene?.alertScreen?.show({
			title: this.game.texts.texts.ad_error_title,
			message: this.game.texts.texts.ad_error_generic,
		})
	}

	private showInterstitialAdOnBoot() {
		this.game.ads.preloaderAdComplete = deferred<void>()

		this.game.ads.showInterstitial('Preloader').finally(() => {
			this.game.ads.preloaderAdComplete.resolve()
		})
	}

	private showBannerAdOnBoot() {
		this.game.ads.bannerAdComplete = deferred<void>()

		this.game.platform.showBannerAd().finally(() => {
			this.game.ads.bannerAdComplete.resolve()
		})
	}

	private initLeaderboards(): void {
		if (!this.game.gamePush) {
			this.game.leaderboards = null
			return
		}

		this.game.leaderboards = new LeaderboardsService({
			game: this.game as Main,
			save: this.game.save,
			logger: this.game.logs.getOrCreate('leaderboards'),
			gamePush: this.game.gamePush,
			time: this.game.timeSvc,
			leaderboardId: 22858,
			submitScoreThreshold: 8,
		})
	}

	private initGameController(): void {
		if (!UrlParams.getBool('ctl')) {
			return
		}

		window.ctl = new GameController(this.game)
		this.game.logs.info('GameController initialized')
	}
}
