import { timeout } from '../../robowhale/utils/async/timeout'
import { LeaderboardTab } from '../LeaderboardTab'
import {
	BaseLeaderboardProvider,
	BaseLeaderboardProviderOptions,
	LeaderboardFetchOptions,
} from './BaseLeaderboardProvider'
import { LeaderboardData, LeaderboardEntry } from './LeaderboardData'

export interface FakeLeaderboardProviderOptions extends BaseLeaderboardProviderOptions {
	fetchOptions?: { [tab in LeaderboardTab]?: FakeLeaderboardFetchOptions }
}

export interface FakeLeaderboardFetchOptions {
	playerRank: number
	topEntriesCount?: number
	topPlayersScores?: { min: number; max: number }
	aroundPlayerCount?: number
	aroundPlayerPosition?: 'start' | 'middle' | 'end'
	aroundPlayerScores?: { min: number; max: number }
}

export class FakeLeaderboardProvider extends BaseLeaderboardProvider {
	private fetchOptions: { [tab in LeaderboardTab]?: FakeLeaderboardFetchOptions }

	constructor(options: FakeLeaderboardProviderOptions) {
		super(options)
		this.fetchOptions = options.fetchOptions || {}
	}

	public getPlayerId(): string {
		return 'currentUser'
	}

	public async fetch(options: LeaderboardFetchOptions): Promise<LeaderboardData> {
		const fakeOptions = options as unknown as FakeLeaderboardFetchOptions
		const tab = options.tab || 'all-time'

		// Get tab-specific options if they exist
		const tabOptions = (this.fetchOptions[tab] || {}) as FakeLeaderboardFetchOptions

		// Merge options with priority: fakeOptions > tabOptions > defaults
		const playerRank = fakeOptions.playerRank !== undefined ? fakeOptions.playerRank : tabOptions.playerRank || 50
		const topPlayersScores = fakeOptions.topPlayersScores ||
			tabOptions.topPlayersScores || { min: 1000, max: 10000 }
		const aroundPlayerScores = fakeOptions.aroundPlayerScores ||
			tabOptions.aroundPlayerScores || { min: 500, max: 2000 }
		const aroundPlayerPosition = fakeOptions.aroundPlayerPosition || tabOptions.aroundPlayerPosition || 'middle'
		const topEntriesCount = fakeOptions.topEntriesCount || tabOptions.topEntriesCount || 10
		const aroundPlayerCount = fakeOptions.aroundPlayerCount || tabOptions.aroundPlayerCount || 5
		const playerId = options.playerId

		// Generate top entries - don't include player if rank is -1
		const shouldIncludePlayerInTop = playerRank !== -1
		const topEntries = this.generateTopEntries(
			topEntriesCount,
			topPlayersScores,
			tab,
			shouldIncludePlayerInTop ? playerId : undefined,
			shouldIncludePlayerInTop ? playerRank : undefined
		)

		// Check if player is in top entries
		const playerInTopEntries = topEntries.some((entry) => entry.userId === playerId)

		// Only generate around player entries if:
		// 1. Player is not in top entries
		// 2. Player rank is not -1 (which means player is not in leaderboard at all)
		let aroundPlayerEntries: LeaderboardEntry[] = []

		if (!playerInTopEntries && playerRank !== -1) {
			// Generate around player entries
			aroundPlayerEntries = this.generateAroundPlayerEntries(
				playerId,
				playerRank,
				aroundPlayerCount,
				aroundPlayerScores,
				tab,
				aroundPlayerPosition
			)
		}

		// generate fake data
		const data = {
			topEntries,
			aroundPlayerEntries,
			playerId,
		}

		// Simulate network delay
		await timeout(500)

		return data
	}

	/**
	 * Generate top leaderboard entries with fake data
	 * @param count Number of entries to generate
	 * @param scoreRange Score range for the entries
	 * @param tab Leaderboard tab
	 * @param playerId Player ID to use if player is in top entries
	 * @param playerRank Player's rank to check if they should be in top entries
	 */
	private generateTopEntries(
		count: number,
		scoreRange: { min: number; max: number },
		tab: LeaderboardTab,
		playerId?: string,
		playerRank?: number
	): LeaderboardEntry[] {
		const entries: LeaderboardEntry[] = []

		// Generate entries with decreasing scores
		for (let i = 0; i < count; i++) {
			const rank = i + 1

			// Check if this entry should be the player
			const isPlayer = playerId && playerRank && rank === playerRank && rank <= count

			// Calculate a score that decreases as rank increases
			// Higher ranks (1, 2, 3) get scores closer to max
			// Lower ranks get scores closer to min
			const rankFactor = 1 - i / count
			const score = Math.floor(scoreRange.min + (scoreRange.max - scoreRange.min) * rankFactor)

			entries.push({
				userId: isPlayer ? playerId : `user-${rank}`,
				timestamp: this.getTimestampForTab(tab),
				rank,
				avatarUrl: isPlayer ? `https://randomuser.me/api/portraits/men/1.jpg` : this.getRandomAvatarUrl(rank),
				username: isPlayer ? 'You' : this.getRandomUsername(),
				score,
			})
		}

		return entries
	}

	/**
	 * Generate entries around the player's position
	 */
	private generateAroundPlayerEntries(
		playerId: string,
		playerRank: number,
		count: number,
		scoreRange: { min: number; max: number },
		tab: LeaderboardTab,
		position: 'start' | 'middle' | 'end' = 'middle'
	): LeaderboardEntry[] {
		const entries: LeaderboardEntry[] = []

		// Calculate how many entries to generate above and below the player based on position
		let aboveCount = 0
		let belowCount = 0

		switch (position) {
			case 'start':
				// Player at the start - more entries below
				aboveCount = 0
				belowCount = count - 1 // -1 for the player entry
				break
			case 'end':
				// Player at the end - more entries above
				aboveCount = count - 1 // -1 for the player entry
				belowCount = 0
				break
			case 'middle':
			default:
				// Player in the middle - balanced entries above and below
				aboveCount = Math.floor((count - 1) / 2)
				belowCount = count - 1 - aboveCount
				break
		}

		// Ensure we don't try to generate entries with negative ranks
		aboveCount = Math.min(aboveCount, playerRank - 1)

		// If we couldn't generate all the above entries (because player rank is too low),
		// add more below entries to compensate
		if (aboveCount < Math.floor((count - 1) / 2) && position === 'middle') {
			belowCount = count - 1 - aboveCount
		}

		// Generate entries above the player
		for (let i = 0; i < aboveCount; i++) {
			const rank = playerRank - (aboveCount - i)
			const rankFactor = 1 - (rank - 1) / (playerRank + belowCount)
			const score = Math.floor(scoreRange.min + (scoreRange.max - scoreRange.min) * rankFactor)

			entries.push({
				userId: `user-near-${rank}`,
				timestamp: this.getTimestampForTab(tab),
				rank,
				avatarUrl: this.getRandomAvatarUrl(rank),
				username: this.getRandomUsername(),
				score,
			})
		}

		// Add the player entry
		const playerRankFactor = 1 - (playerRank - 1) / (playerRank + belowCount)
		const playerScore = Math.floor(scoreRange.min + (scoreRange.max - scoreRange.min) * playerRankFactor)

		entries.push({
			userId: playerId,
			timestamp: this.getTimestampForTab(tab),
			rank: playerRank,
			avatarUrl: `https://randomuser.me/api/portraits/men/1.jpg`,
			username: 'You',
			score: playerScore,
		})

		// Generate entries below the player
		for (let i = 0; i < belowCount; i++) {
			const rank = playerRank + i + 1
			const rankFactor = 1 - (rank - 1) / (playerRank + belowCount)
			const score = Math.floor(scoreRange.min + (scoreRange.max - scoreRange.min) * rankFactor)

			entries.push({
				userId: `user-near-${rank}`,
				timestamp: this.getTimestampForTab(tab),
				rank,
				avatarUrl: this.getRandomAvatarUrl(rank),
				username: this.getRandomUsername(),
				score,
			})
		}

		return entries
	}

	/**
	 * Get a timestamp appropriate for the given leaderboard tab
	 */
	private getTimestampForTab(tab: LeaderboardTab): number {
		const now = Date.now()

		switch (tab) {
			case 'all-time':
				// Random timestamp within the last year
				return now - Math.floor(Math.random() * 365 * 24 * 60 * 60 * 1000)
			case 'monthly':
				// Random timestamp within the last month
				return now - Math.floor(Math.random() * 30 * 24 * 60 * 60 * 1000)
			case 'weekly':
				// Random timestamp within the last week
				return now - Math.floor(Math.random() * 7 * 24 * 60 * 60 * 1000)
			default:
				return now
		}
	}

	/**
	 * Generate a random username
	 */
	private getRandomUsername(): string {
		const firstNames = [
			'Alex',
			'Jordan',
			'Taylor',
			'Morgan',
			'Casey',
			'Riley',
			'Avery',
			'Quinn',
			'Skyler',
			'Reese',
			'Parker',
			'Blake',
			'Dakota',
			'Harper',
			'Emerson',
		]

		const lastNames = [
			'Smith',
			'Johnson',
			'Williams',
			'Jones',
			'Brown',
			'Davis',
			'Miller',
			'Wilson',
			'Moore',
			'Taylor',
			'Anderson',
			'Thomas',
			'Jackson',
			'White',
		]

		const longUsernamePrefixes = [
			'SuperAwesome',
			'UltimatePro',
			'MegaChampion',
			'LegendaryGamer',
			'UnstoppablePlayer',
			'ExtraordinaryMaster',
			'InvincibleWarrior',
			'UnbeatableHero',
			'FantasticWizard',
			'MagnificentStrategist',
		]

		const longUsernameSuffixes = [
			'OfTheUniverse',
			'FromOuterSpace',
			'WithSuperPowers',
			'TheUndefeated',
			'MasterOfDisaster',
			'WhoNeverLoses',
			'WithInfiniteSkills',
			'TheAllKnowing',
			'WithAThousandVictories',
			'TheIncredible',
		]

		// 15% chance to generate a really long username
		const generateLongUsername = Math.random() < 0.15

		if (generateLongUsername) {
			const prefix = longUsernamePrefixes[Math.floor(Math.random() * longUsernamePrefixes.length)]
			const firstName = firstNames[Math.floor(Math.random() * firstNames.length)]
			const lastName = lastNames[Math.floor(Math.random() * lastNames.length)]
			const suffix = longUsernameSuffixes[Math.floor(Math.random() * longUsernameSuffixes.length)]

			// 50% chance to add numbers to the long username
			const addNumbers = Math.random() < 0.5
			const numbers = addNumbers
				? Math.floor(Math.random() * 9999)
						.toString()
						.padStart(4, '0')
				: ''

			return `${prefix}${firstName}${lastName}${suffix}${numbers}`
		}

		const firstName = firstNames[Math.floor(Math.random() * firstNames.length)]
		const lastName = lastNames[Math.floor(Math.random() * lastNames.length)]

		// Sometimes add a number to the username
		const addNumber = Math.random() > 0.7
		const number = addNumber ? Math.floor(Math.random() * 100) : null

		return addNumber ? `${firstName}${lastName}${number}` : `${firstName}${lastName}`
	}

	/**
	 * Generate a random avatar URL based on a seed value
	 * @param seed A number used to determine the avatar gender and ID
	 * @returns A URL to a random avatar image
	 */
	private getRandomAvatarUrl(seed: number): string {
		// Determine gender based on whether seed is even or odd
		const gender = seed % 2 === 0 ? 'men' : 'women'

		// Use modulo to keep the avatar ID within the available range (1-70)
		const avatarId = (seed % 70) + 1

		return `https://randomuser.me/api/portraits/${gender}/${avatarId}.jpg`
	}
}
