import { Config } from '../../../../Config'
import { FontWeight, GameFonts } from '../../../../GameFonts'
import { PanelStars } from './../../../../gui/PanelStars'
export class VictoryTopPanel extends Phaser.Group {
	private back: Phaser.Image
	private title: Phaser.Text
	private leftStars: PanelStars
	private rightStars: PanelStars

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'victory_panel')

		this.addBack()
		this.addTitle()
		this.addStars()

		this.bringToTop(this.title)
	}

	private addBack(): void {
		this.back = this.game.add.image(0, 0, 'interface', 'Victory_Back0000', this)
	}

	private addTitle(): void {
		let content: string = this.game.texts.texts.victory
		let style: Phaser.PhaserTextStyle = {
			font: GameFonts.DEFAULT,
			fontWeight: FontWeight.BOLD,
			fontSize: 60,
			fill: '#ffffff',
			align: 'center',
		}

		this.title = this.game.add.text(0, 0, content, style, this)
		this.title.anchor.set(0.5, 0.5)
		this.title.centerX = this.back.centerX
		this.title.centerY = this.back.centerY + 3
	}

	private addStars(): void {
		let titleMargin: number = 26
		let key: string = 'interface'
		let frame: string = 'Little_Star0000'

		this.leftStars = new PanelStars(this.game, this, key, frame)
		this.leftStars.right = this.title.left - titleMargin
		this.leftStars.centerY = this.title.centerY

		this.rightStars = new PanelStars(this.game, this, key, frame)
		this.rightStars.scale.x = -1
		this.rightStars.left = this.title.right + titleMargin
		this.rightStars.centerY = this.title.centerY
	}

	public show(delay: number): void {
		this.visible = true

		this.showMain(delay)
		this.showStars(delay)
	}

	private showMain(delay: number): void {
		let yOffset: number = 40 * Config.ASSETS_SCALE

		this.y -= yOffset
		this.alpha = 0

		this.game.add.tween(this).to({ alpha: 1 }, 100, Phaser.Easing.Linear.None, true, delay)
		this.game.add.tween(this).to({ y: this.y + yOffset }, 330, Phaser.Easing.Back.Out, true, delay)
	}

	private showStars(initialDelay: number): void {
		let delay: number = initialDelay + 0.1

		this.leftStars.show(delay)
		this.rightStars.show(delay)
	}
}
