import { SavedGameState } from './SaveGameState'

export class UndoHandler {
	public maxSaveNum: number = 3
	private gameStates: SavedGameState[]

	constructor() {
		this.gameStates = []
	}

	public save(gameState: SavedGameState): void {
		this.gameStates.push(gameState)

		if (this.gameStates.length > this.maxSaveNum) {
			let oldestSave: SavedGameState = this.gameStates.shift()
			oldestSave.destroy()
			oldestSave = null
		}
	}

	public getSave(offset: number = 0): SavedGameState {
		let index: number = offset < 0 ? this.gameStates.length + offset : offset
		if (index >= 0) {
			return this.gameStates[index]
		} else {
			return null
		}
	}

	public getEarliestSave(): SavedGameState {
		if (this.gameStates.length > 0) {
			return this.gameStates[0]
		} else {
			return null
		}
	}

	public popLatestSave(): SavedGameState {
		if (this.gameStates.length > 0) {
			return this.gameStates.pop()
		} else {
			return null
		}
	}

	public removeLatestSave(): void {
		if (this.gameStates.length > 0) {
			let lastSave: SavedGameState = this.gameStates.pop()
			lastSave.destroy()
			lastSave = null
		}
	}

	public savedStatesNum(): number {
		return this.gameStates.length
	}

	public clearSavesAfter(save: SavedGameState): void {
		let index: number = this.gameStates.indexOf(save)
		if (index > -1) {
			let l: number = this.gameStates.length
			for (let i: number = index; i < l; i++) {
				this.gameStates[i].destroy()
			}

			this.gameStates.length = index
		}
	}

	public clearAllSaves(): void {
		this.gameStates.forEach((gameState: SavedGameState) => {
			gameState.destroy()
		})

		this.gameStates.length = 0
	}

	public destroy(): void {
		this.clearAllSaves()
		this.gameStates = null
	}
}
