import { until } from '@open-draft/until'
import { err, ok } from 'neverthrow'
import type { Player, SDK } from 'ysdk'
import { tryit } from '../../robowhale/functions/tryit'
import { Result } from '../../robowhale/Result'
import { deferred } from '../../robowhale/utils/async/deferred'
import { getErrorLog } from '../../robowhale/utils/error/utils'
import { Platform } from '../../startup/Platform'
import { UrlParams } from '../../url-params/UrlParams'
import { BasePlatform, BasePlatformOptions } from '../BasePlatform'

/**
 * https://yandex.com/dev/games/doc/en/sdk/sdk-about
 */
export class YaPlatform extends BasePlatform {
	public readonly type: Platform = 'yandex'
	private _sdk: SDK | undefined
	private _player: Player | undefined

	constructor(options: BasePlatformOptions) {
		super(options)
	}

	async init(): Promise<void> {
		const preloader = window.preloader.platform

		if (!preloader || preloader.type !== this.type) {
			throw new Error('Platform preloader is not initialized')
		}

		this._sdk = (await preloader.loadAndInit()) as SDK

		// TODO add retries
		this._player = await this._sdk.getPlayer({})
		this._logger.info(`player ${this._player.isAuthorized() ? 'logged in' : 'logged out'}`)
		this._logger.info(`player (id: ${this._player.getUniqueID()})`)

		if (this._player.isAuthorized()) {
			this.emit('player-logged-in', this._player.getUniqueID())
		}

		this._ready = true

		this._logger.info('ready')

		this.setSentryData()
	}

	private setSentryData(): void {
		this._sentry.setTags({
			'ya.deviceType': this._sdk.deviceInfo.type,
			'ya.language': this._sdk.environment.i18n.lang,
			'ya.tld': this._sdk.environment.i18n.tld,
			'ya.guest': !this._player.isAuthorized(),
		})

		this._sentry.setContext('yandex', {
			payload: this._sdk.environment.payload,
		})

		this._sentry.setUser({
			id: this._player.getUniqueID(),
		})
	}

	/**
	 * @link https://yandex.com/dev/games/doc/en/sdk/sdk-environment#i18n-structure
	 */
	async getLanguage(): Promise<string | undefined> {
		return this._sdk.environment.i18n.lang
	}

	/**
	 * @link https://yandex.com/dev/games/doc/en/sdk/sdk-game-events#ysdkfeaturesloadingapiready
	 */
	async gameReady(): Promise<void> {
		return this._sdk.features.LoadingAPI.ready()
	}

	override async hasAdblock(): Promise<boolean> {
		return false
	}

	loadRewardedAd(): Promise<any> {
		throw new Error('Method not implemented.')
	}

	async showRewardedAd(): Promise<Result> {
		const isAdblockEnabled = await this.hasAdblock()
		if (isAdblockEnabled) {
			return Result.Error('adblock-enabled')
		}

		const complete = deferred<Result>()

		this._sdk.adv.showRewardedVideo({
			callbacks: {
				onOpen: () => {
					this._logger.info(`rewarded ad - opened`)
				},
				onClose: () => {
					this._logger.info(`rewarded ad - closed`)
					complete.resolve(Result.Error('ad-closed'))
				},
				onRewarded: () => {
					this._logger.info(`rewarded ad - completed`)
					complete.resolve(Result.Ok())
				},
				onError: (error: string | Error) => {
					const errorLog = getErrorLog(error)
					this._logger.info(`rewarded ad - failed (${errorLog})`)
					complete.resolve(Result.Error(errorLog))
				},
			},
		})

		return complete
	}

	async showInterstitialAd(): Promise<Result> {
		const isAdblockEnabled = await this.hasAdblock()
		if (isAdblockEnabled) {
			return Result.Error('adblock-enabled')
		}

		const complete = deferred<Result>()

		this._sdk.adv.showFullscreenAdv({
			callbacks: {
				onOpen: () => {
					this._logger.info(`interstitial ad - opened`)
				},
				onClose: (wasShown: boolean) => {
					complete.resolve(wasShown ? Result.Ok() : Result.Error('ad-not-shown'))
					this._logger.info(`interstitial ad - closed (wasShown: ${wasShown})`)
				},
				onError: (error: string | Error) => {
					const errorLog = getErrorLog(error)
					this._logger.error(`interstitial ad - failed (${errorLog})`)
					complete.resolve(Result.Error(errorLog))
				},
				onOffline: () => {
					this._logger.info(`interstitial ad - failed (offline)`)
					complete.resolve(Result.Error('offline'))
				},
			},
		})

		return complete
	}

	public isBannerAdSupported(): boolean {
		if (UrlParams.get('bannerAds') === '0') {
			return false
		}

		return true
	}

	public async showBannerAd() {
		const { error, data } = await until(() => this._sdk.adv.showBannerAdv())

		if (error) {
			const log = getErrorLog(error)
			this._logger.warn(`banner ad show - failed (${log})`)
			return err(log)
		}

		if (data.reason) {
			this._logger.warn(`banner ad show - failed (${data.reason})`)
			return err(data.reason)
		}

		return ok()
	}

	public async hideBannerAd() {
		const [error] = tryit(() => this._sdk.adv.hideBannerAdv())

		if (error) {
			const log = getErrorLog(error)
			this._logger.warn(`banner ad hide - failed (${log})`)
			return err(log)
		}

		return ok()
	}

	public getStorage() {
		return this._sdk.getStorage()
	}

	public get sdk(): SDK | undefined {
		return this._sdk
	}

	public get player(): Player | undefined {
		return this._player
	}

	/**
	 * @note even logged out player will have unique id (guest id)
	 */
	public get playerId(): string | undefined {
		return this._player?.getUniqueID()
	}

	public get isLoggedIn(): boolean {
		return this._player?.isAuthorized() ?? false
	}

	public isFullscreenSupported(): boolean {
		return this._sdk?.screen?.fullscreen !== undefined
	}

	public isFullscreen(): boolean {
		return this._sdk?.screen?.fullscreen?.status === 'on'
	}

	public async requestFullscreen(): Promise<void> {
		return this._sdk?.screen?.fullscreen?.request()
	}

	public async exitFullscreen(): Promise<void> {
		return this._sdk?.screen?.fullscreen?.exit()
	}
}
