import { FontWeight, GameFonts } from '../../../GameFonts'
import { ToggleButton } from '../../../gui/buttons/ToggleButton'
import { BoosterCountLabel } from './BoosterCountLabel'
import { CardBuyButton } from './CardBuyButton'
import { ShopCardConfig } from './ShopCardConfig'

import PhaserTextStyle = Phaser.PhaserTextStyle

export class ShopCard extends Phaser.Group {
	private _config: ShopCardConfig
	protected back: Phaser.Image
	public readonly shadowOffset: number = 6
	private shadow: Phaser.Image
	private whiteStripe: Phaser.Image
	private icon: Phaser.Image
	private title: Phaser.Text
	private description: Phaser.Text
	private countLabel: BoosterCountLabel
	public buyButton: CardBuyButton
	private infoButton: ToggleButton
	private mainContent: PIXI.DisplayObject[]
	private white: Phaser.Image

	constructor(_game: Phaser.Game, parent: Phaser.Group, config: ShopCardConfig) {
		super(_game, parent, 'item_card_' + config)

		this._config = config

		this.addShadow()
		this.addBack()
		this.addWhiteStripe()
		this.addIcon()
		this.addTitle()
		this.addCountLabel()
		this.addBuyButton()
		this.addDescription()
		this.addInfoButton()
		this.addWhite()
		this.initMainContent()
	}

	private addShadow(): void {
		this.shadow = this.game.add.image(0, this.shadowOffset, 'boosters_shop', 'Card_Shadow0000', this)
		this.shadow.anchor.set(0.5, 0.5)
	}

	private addBack(): void {
		this.back = this.game.add.image(0, 0, 'boosters_shop', 'Card_Back0000', this)
		this.back.anchor.set(0.5, 0.5)
		this.back.tint = 0x35afdb
	}

	private addWhiteStripe(): void {
		this.whiteStripe = this.game.add.image(0, 0, 'boosters_shop', 'White_Stripe0000', this)
		this.whiteStripe.left = this.back.left
		this.whiteStripe.top = this.back.top + 35
	}

	private addIcon(): void {
		let imageKey: string = 'Booster_' + this._config.booster.type + '0000'

		this.icon = this.game.add.image(0, 0, 'boosters_shop', imageKey, this)
		this.icon.anchor.set(0.5, 0.5)
		this.icon.x = this.back.left + 77
		this.icon.centerY = this.whiteStripe.centerY
	}

	private addTitle(): void {
		let content: string = this._config.booster.title
		let style: PhaserTextStyle = {
			font: GameFonts.DEFAULT,
			fontWeight: FontWeight.BOLD,
			fontSize: 36,
			fill: '#ffffff',
			align: 'left',
		}

		this.title = this.game.add.text(0, 0, content, style, this)
		this.title.lineSpacing = -14
		this.title.anchor.set(0, 0.5)
		this.title.x = this.back.left + 136
		this.title.y = this.whiteStripe.centerY
	}

	private addCountLabel(): void {
		let count: number = this._config.booster.num

		this.countLabel = new BoosterCountLabel(this.game, this)
		this.countLabel.setBackgroundColor(this.back.tint)
		this.countLabel.x = this.back.left + 390
		this.countLabel.y = this.whiteStripe.centerY
		this.countLabel.updateContent(count, false)
	}

	private addBuyButton(): void {
		let price: number = this._config.booster.price

		this.buyButton = new CardBuyButton(this.game, this)
		this.buyButton.centerX = this.back.centerX
		this.buyButton.y = this.back.top + 146
		this.buyButton.updatePrice(price)
		this.buyButton.card = this
		this.buyButton.name = 'buy_button_' + this._config.booster.title
		this.buyButton.back.name = 'buy_button_' + this._config.booster.title
	}

	private addDescription(): void {
		let content: string = this._config.booster.description
		let style: Phaser.PhaserTextStyle = {
			font: GameFonts.DEFAULT,
			fontWeight: FontWeight.BOLD,
			fontSize: 33,
			fill: '#ffffff',
			align: 'center',
		}

		this.description = this.game.add.text(0, 0, content, style, this)
		this.description.anchor.set(0.5, 0.5)
		this.description.lineSpacing = -10
		this.description.wordWrap = true
		this.description.wordWrapWidth = this.back.width * 0.75
		this.description.setShadow(0, 2, 'rgba(0,0,0,0.2)', 0, false, true)
		this.description.centerX = this.back.centerX
		this.description.centerY = this.back.centerY
		this.description.visible = false
	}

	private addInfoButton(): void {
		this.infoButton = new ToggleButton(this.game, 0, 0, 'boosters_shop', 'Button_Info0000', 'Button_Info0001')
		this.infoButton.right = this.back.right
		this.infoButton.bottom = this.back.bottom
		this.infoButton.areTweensEnabled = false
		this.infoButton.callback.add(this.onInfoButtonClick, this)
		this.add(this.infoButton)
	}

	public updateContent(): void {
		if (this.countLabel) {
			this.countLabel.updateContent(this.config.booster.num)
		}
	}

	public get config(): ShopCardConfig {
		return this._config
	}

	private onInfoButtonClick(event: Event): void {
		if (this.description.visible) {
			this.hideDescription()
			this.showMainContent(100)
		} else {
			this.hideMainContent()
			this.showDescription(100)
		}
	}

	private hideDescription() {
		this.game.tweens.removeFrom(this.description)
		this.game.add
			.tween(this.description)
			.to({ alpha: 0 }, 150, Phaser.Easing.Cubic.Out, true)
			.onComplete.addOnce(() => {
				this.description.visible = false
			})
	}

	private showMainContent(delay: number): void {
		this.mainContent.forEach((child, index) => {
			child.visible = true
			child.alpha = 0
			this.game.tweens.removeFrom(child)
			this.game.add.tween(child).to({ alpha: 1 }, 200, Phaser.Easing.Cubic.Out, true, delay)
		})

		this.buyButton.enabled = true
	}

	private hideMainContent(): void {
		this.mainContent.forEach((child, index) => {
			this.game.tweens.removeFrom(child)
			this.game.add.tween(child).to({ alpha: 0 }, 150, Phaser.Easing.Cubic.Out, true)
		})

		this.buyButton.enabled = false
	}

	private showDescription(delay: number) {
		this.description.visible = true
		this.description.alpha = 0

		this.game.tweens.removeFrom(this.description)
		this.game.add.tween(this.description).to({ alpha: 1 }, 200, Phaser.Easing.Cubic.Out, true, delay)
	}

	private initMainContent(): void {
		this.mainContent = [this.whiteStripe, this.icon, this.title, this.countLabel, this.buyButton]
	}

	private addWhite(): void {
		this.white = this.game.add.image(0, 0, 'boosters_shop', 'Card_Back0000', this)
		this.white.centerX = this.back.centerX
		this.white.centerY = this.back.centerY
		this.white.visible = false
	}

	public highlight(): void {
		this.white.visible = true
		this.white.alpha = 0

		this.game.tweens.removeFrom(this.white)
		this.game.add
			.tween(this.white)
			.to({ alpha: 0.66 }, 300, Phaser.Easing.Sinusoidal.InOut, true, 0, 0, true)
			.onComplete.addOnce(() => {
				this.white.visible = false
			})
	}

	public resetHighlight() {
		this.game.tweens.removeFrom(this.white)
		this.white.visible = false
	}

	public animateBuyButton(): void {
		this.stopAnimateBuyButton()

		this.game.add.tween(this.buyButton.scale).to(
			{
				x: 1.1,
				y: 1.1,
			},
			500,
			Phaser.Easing.Sinusoidal.InOut,
			true,
			0,
			-1,
			true
		)
	}

	public stopAnimateBuyButton(): void {
		this.game.tweens.removeFrom(this.buyButton.scale)
		this.buyButton.scale.set(1)
	}

	public getHeight(): number {
		return this.back.height
	}

	public destroy(): void {
		this.game.tweens.removeFrom(this.buyButton.scale)
		this.mainContent = null

		super.destroy(true, false)
	}
}
