import { times } from 'es-toolkit/compat'
import { Cell } from './Cell'

export class Grid extends Phaser.Group {
	public static ROWS: number = 5
	public static COLUMNS: number = 4

	private _rows: number = 0
	private _columns: number = 0
	public cells: Cell[]
	private cellsVisible: boolean = false

	constructor(_game: Phaser.Game, parent: Phaser.Group, rows: number, columns: number) {
		super(_game, parent || _game.world, `grid_[${columns}, ${rows}]`)

		this._rows = rows
		this._columns = columns
		this.createCells()
		// this.alignCells();
	}

	private createCells() {
		let cellsNum: number = this._rows * this._columns
		this.cells = times(cellsNum, (cellIndex: number) => {
			let row: number = Math.floor(cellIndex / this._columns)
			let column: number = cellIndex - row * this._columns
			let cell = new Cell(this.game, row, column)
			cell.alpha = 0
			cell.left = column * Cell.WIDTH
			cell.top = row * Cell.HEIGHT

			this.add(cell)

			return cell
		})
	}

	private alignCells(): void {
		console.log(this.children)
		this.align(10, this._rows, 100, 100, Phaser.CENTER)
	}

	public toggleVisibility(): void {
		this.cellsVisible = !this.cellsVisible
		this.cells.forEach((cell) => {
			cell.alpha = this.cellsVisible ? 0.66 : 0
		})
	}

	public getCellAt(row: number, column: number): Cell {
		let l: number = this.cells.length
		for (let i: number = 0; i < l; i++) {
			let cell: Cell = this.cells[i]
			if (cell.row === row && cell.column === column) {
				return cell
			}
		}

		return null
	}

	public getFreeCell(): Cell {
		for (let i: number = 0; i < this.cells.length; i++) {
			let cell: Cell = this.cells[i]
			if (cell.isFree()) return cell
		}

		return null
	}

	public getFreeCellsNum(): number {
		let freeCellsNum: number = 0

		this.cells.forEach((cell: Cell) => {
			if (cell.isFree()) freeCellsNum++
		})

		return freeCellsNum
	}

	public getCellUnderPoint(worldX: number, worldY: number): Cell {
		let localPosition = this.toLocal(new PIXI.Point(worldX, worldY), this.game.world)
		let row: number = Math.floor(localPosition.y / Cell.WIDTH)
		let column: number = Math.floor(localPosition.x / Cell.HEIGHT)

		return this.getCellAt(row, column)
	}

	public topRowIsEmpty(): boolean {
		for (let i: number = 0; i < this._columns; i++) {
			let cell: Cell = this.getCellAt(0, i)
			if (cell.isFree() === false) return false
		}

		return true
	}

	public getWidth(): number {
		let left: number = this.cells[0].x
		let right: number = this.cells[this.cells.length - 1].x + this.cells[this.cells.length - 1].width

		return right - left
	}

	public getHeight(): number {
		let top: number = this.cells[0].y
		let bottom: number = this.cells[this.cells.length - 1].y + this.cells[this.cells.length - 1].height

		return bottom - top
	}

	public logState() {
		var output: String = this.game.time.now.toString() + ' GRID:\n'
		for (let i: number = 0; i < this._rows; i++) {
			for (let j: number = 0; j < this._columns; j++) {
				let cell: Cell = this.getCellAt(i, j)
				if (cell.isFree()) {
					output += '-  '
				} else {
					output += cell.item.itemType + '  '
				}
			}
			output += '\n'
		}

		console.log(output)
	}

	public destroy(): void {
		super.destroy(true, false)

		this.cells = null
	}

	public get rows(): number {
		return this._rows
	}

	public get columns(): number {
		return this._columns
	}
}
