import { FontWeight, GameFonts } from '../GameFonts'

export interface CheckboxInitProps {
	textureKey: string
	onFrame: string
	offFrame: string
}
export class Checkbox extends Phaser.Group {
	get checked(): boolean {
		return this._checked
	}

	set checked(value: boolean) {
		this._checked = value

		this._checked ? this.setChecked() : this.setUnchecked()
	}

	private props: CheckboxInitProps
	private check: Phaser.Image
	public label: Phaser.Text
	private _checked: boolean = true
	public onChange: Phaser.Signal

	constructor(_game: Phaser.Game, parent: Phaser.Group, text: string, props: CheckboxInitProps) {
		super(_game, parent, 'checkbox')

		this.onChange = new Phaser.Signal()

		this.props = props

		this.addCheck()
		this.addLabel(text)

		this.onChildInputDown.add(this.onClick, this)
	}

	private addCheck() {
		this.check = this.game.add.image(0, 0, this.props.textureKey, this.props.onFrame, this)
		this.check.anchor.set(0.5, 0.5)
		this.check.inputEnabled = true
		this.check.input.useHandCursor = true
	}

	private addLabel(labelContent: string) {
		let style: Phaser.PhaserTextStyle = {
			font: GameFonts.DEFAULT,
			fontWeight: FontWeight.NORMAL,
			fontSize: 32,
			fill: '#ffffff',
			align: 'left',
		}

		this.label = this.game.add.text(0, 0, labelContent, style, this)
		this.label.anchor.set(0, 0.5)
		this.label.x = this.check.right + 8
		this.label.centerY = this.check.centerY + 1
		this.label.data.originalX = this.label.x
		this.label.inputEnabled = true
		this.label.input.useHandCursor = true
		this.label.hitArea = new Phaser.Rectangle(0, -this.label.height / 2, this.label.width, this.label.height)
		// this.label.hitArea = this.label.getBounds(this.game.world);
	}

	public onClick(): void {
		if (this._checked) {
			this.setUnchecked()
		} else {
			this.setChecked()
		}
	}

	private setChecked() {
		this._checked = true
		this.check.frameName = this.props.onFrame
		this.playTweens()
		this.playClickSound()
		this.onChange.dispatch(this)
	}

	private setUnchecked() {
		this._checked = false
		this.check.frameName = this.props.offFrame
		this.playTweens()
		this.playClickSound()
		this.onChange.dispatch(this)
	}

	private playClickSound(): void {
		this.game.audio.playClickSound(0.5)
	}

	private playTweens(): void {
		// this.game.tweens.removeFrom(this.check.scale);
		// this.check.scale.set(1);
		// let scale = 1.1;
		// this.game.add.tween(this.check.scale).to({x: scale, y: scale}, 200, Phaser.Easing.Sinusoidal.InOut, true, 0, 0, true);

		this.game.tweens.removeFrom(this.label)
		this.label.x = this.label.data.originalX
		this.game.add.tween(this.label).to({ x: '+8' }, 150, Phaser.Easing.Sinusoidal.InOut, true, 0, 0, true)
	}

	public destroy(): void {
		super.destroy(true, false)

		this.onChange.dispose()
		this.onChange = null
	}
}
