import { PlaygamaPlatform } from '../../platform/playgama/PlaygamaPlatform'
import { Result } from '../../robowhale/Result'
import { AdBasicResult, AdErrorCode } from '../AdsService'
import { IAdsProvider } from './IAdsProvider'

/**
 * @link https://wiki.playgama.com/playgama/sdk/engines/core-plain-js/advertising
 */
export class PlaygamaAdsProvider implements IAdsProvider {
	readonly name = 'playgama'

	private platform: PlaygamaPlatform

	constructor(platform: PlaygamaPlatform) {
		this.platform = platform
	}

	public async loadRewarded(): Promise<AdBasicResult> {
		if (!this.platform.ready) {
			return Result.Error({
				code: AdErrorCode.GENERIC,
				message: 'Playgama platform is not ready',
			})
		}

		const loaded = await this.platform.loadRewardedAd()
		if (loaded.success === true) {
			return Result.Ok()
		}

		return Result.Error({
			code: this.getErrorCode(loaded.error),
			message: loaded.error || 'platform load error',
		})
	}

	public async showRewarded(): Promise<AdBasicResult> {
		if (!this.platform.ready) {
			return Result.Error({
				code: AdErrorCode.GENERIC,
				message: 'Playgama platform is not ready',
			})
		}

		const shown = await this.platform.showRewardedAd()
		if (shown.success === true) {
			return Result.Ok()
		}

		return Result.Error({
			code: this.getErrorCode(shown.error),
			message: shown.error || 'platform show error',
		})
	}

	public async showInterstitial(): Promise<AdBasicResult> {
		if (!this.platform.ready) {
			return Result.Error({
				code: AdErrorCode.GENERIC,
				message: 'Playgama platform is not ready',
			})
		}

		const shown = await this.platform.showInterstitialAd()
		if (shown.success === true) {
			return Result.Ok()
		}

		return Result.Error({
			code: this.getErrorCode(shown.error),
			message: shown.error || 'platform show error',
		})
	}

	private getErrorCode(error?: string): AdErrorCode {
		const message = (error ?? '').toLowerCase()

		if (message.includes('no fill') || message.includes('no-fill') || message.includes('no inventory')) {
			return AdErrorCode.NO_FILL
		}

		if (message.includes('limit') || message.includes('cooldown') || message.includes('delay') || message.includes('often')) {
			return AdErrorCode.CALL_LIMIT
		}

		if (message.includes('adblock') || message.includes('block')) {
			return AdErrorCode.ADBLOCKED
		}

		if (message.includes('skip') || message.includes('closed') || message.includes('close')) {
			return AdErrorCode.SKIP
		}

		return AdErrorCode.GENERIC
	}
}
