import { DropStrategy } from './DropStrategy'
import { Cell } from './grid/Cell'
import { Grid } from './grid/Grid'
import { Item } from './items/Item'

export class ItemsAligner {
	private game: Phaser.Game
	private grid: Grid
	private items: Item[]
	private dropStrategy: DropStrategy
	private freeCells: Cell[]
	public onAddItem: Phaser.Signal
	public onAlignComplete: Phaser.Signal

	constructor(_game: Phaser.Game, grid: Grid) {
		this.game = _game
		this.grid = grid
		this.dropStrategy = new DropStrategy(this.game, this.grid)
		this.freeCells = []

		this.onAddItem = new Phaser.Signal()
		this.onAlignComplete = new Phaser.Signal()
	}

	public alignAndRefill(items: Item[]): void {
		this.items = items

		this.dropItems()
	}

	public dropItems(): void {
		this.dropStrategy.onDropComplete.add(this.refillGrid, this)
		this.dropStrategy.dropItems(this.items)
	}

	private sortItemsForMoveUp(item1: Item, item2: Item): number {
		var cell1: Cell = item1.cell
		var cell2: Cell = item2.cell

		if (cell1.row === cell2.row) return cell2.column - cell1.column
		else return cell1.row - cell2.row
	}

	private refillGrid(): void {
		var cellsToRefill: Cell[] = this.getCellsToRefill()
		cellsToRefill.sort(this.sortCellsBottomUp)

		if (cellsToRefill.length > 0) {
			this.doRefillGrid(cellsToRefill)
		}

		this.freeCells.length = 0
		this.onComplete()
	}

	private getCellsToRefill(): Cell[] {
		this.freeCells.length = 0

		var cells: Cell[] = this.grid.cells
		var l: number = cells.length
		for (var i: number = 0; i < l; i++) {
			var cell: Cell = cells[i]
			if (cell.isFree()) {
				this.freeCells.push(cell)
			}
		}

		return this.freeCells
	}

	private sortCellsBottomUp(cell1: Cell, cell2: Cell): number {
		if (cell1.row === cell2.row) return cell2.column - cell1.column
		else return cell2.row - cell1.row
	}

	private doRefillGrid(cells: Cell[]): void {
		var delay: number = 0
		var l: number = cells.length
		for (var i: number = 0; i < l; i++) {
			this.onAddItem.dispatch(cells[i], delay)

			delay += 33
		}
	}

	private onComplete(): void {
		this.onAlignComplete.dispatch()
	}

	public destroy(): void {
		this.grid = null
		this.items = null

		this.freeCells.length = 0
		this.freeCells = null

		this.dropStrategy.destroy()
		this.dropStrategy = null
	}
}
