import { attempt } from 'es-toolkit'
import { err, ok } from 'neverthrow'
import { tryit } from '../robowhale/functions/tryit'
import { getErrorLog } from '../robowhale/utils/error/utils'
import { BaseStorage, BaseStorageOptions, StorageLoadResult, StorageSaveResult } from './BaseStorage'

export interface LocalStorageOptions extends BaseStorageOptions {
	useEncryption: boolean
}

export class LocalStorage extends BaseStorage {
	private readonly KEYS = {
		STATE: 'state',
	} as const

	private readonly useEncryption: boolean

	constructor(options: LocalStorageOptions) {
		super(options)

		this.useEncryption = options.useEncryption
	}

	public async loadState(): Promise<StorageLoadResult> {
		const [loadError, stateStr] = tryit(() => localStorage.getItem(this.KEYS.STATE))
		if (loadError) {
			return err({ code: 'load_error', message: getErrorLog(loadError) })
		}

		if (!stateStr) {
			return ok({})
		}

		const [decryptError, decryptedStateStr] = tryit(() => (this.useEncryption ? ncr.decrypt(stateStr) : stateStr))
		if (decryptError) {
			return err({ code: 'decrypt_error', message: getErrorLog(decryptError) })
		}

		const [parseError, state] = tryit(() => JSON.parse(decryptedStateStr))
		if (parseError) {
			return err({ code: 'parse_error', message: getErrorLog(parseError) })
		}

		const isObject = typeof state === 'object' && state !== null
		if (!isObject) {
			return err({ code: 'invalid_state', message: 'state is not an object' })
		}

		return ok(state)
	}

	public async saveState(state: Record<string, unknown>): Promise<StorageSaveResult> {
		if (!this._savesEnabled) {
			return err({ code: 'saves_disabled', message: 'saves are disabled' })
		}

		const stateStr = JSON.stringify(state)

		const encryptedStateStr = this.useEncryption ? ncr.encrypt(stateStr) : stateStr

		const [error] = tryit(() => localStorage.setItem(this.KEYS.STATE, encryptedStateStr))

		if (error) {
			return err({ code: 'save_error', message: getErrorLog(error) })
		}

		return ok({})
	}

	public async clearState(): Promise<StorageSaveResult> {
		const [error] = attempt(() => localStorage.removeItem(this.KEYS.STATE))

		if (error) {
			return err({ code: 'clear_error', message: getErrorLog(error) })
		}

		return ok({})
	}
}
