import { Config } from '../../../../Config'
import { GameFonts } from '../../../../GameFonts'
import { SimpleButton } from '../../../../gui/buttons/SimpleButton'
import { ToggleButton, ToggleButtonState } from '../../../../gui/buttons/ToggleButton'
import { Checkbox, CheckboxInitProps } from '../../../../gui/Checkbox'
import { toReadableDateString } from '../../../../robowhale/utils/date/readable-date-string'
import { Level } from '../../Level'
import { ExitConfirmPopup } from './ExitConfirmPopup'

export class PauseScreen extends Phaser.Group {
	private level: Level
	private background: Phaser.Image
	private mainGroup: Phaser.Group
	public resumeButton: SimpleButton
	private middleButtons: Phaser.Group
	public homeButton: SimpleButton
	public restartButton: SimpleButton
	private soundButton: ToggleButton
	private checkboxes: Phaser.Group
	private headstartCheckbox: Checkbox
	private doubleCoinsCheckbox: Checkbox
	private buildInfo: Phaser.BitmapText
	private confirmExitPopup: ExitConfirmPopup
	public onShow: Phaser.Signal
	public onHide: Phaser.Signal

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'pause_screen')

		this.onShow = new Phaser.Signal()
		this.onHide = new Phaser.Signal()

		this.level = this.game.state.getCurrentState() as Level

		this.addBackground()
		this.addMainGroup()
		this.addResumeButton()
		this.addMiddleButtons()
		this.addCheckboxes()
		this.updateCheckboxes()
		this.addBuildInfo()
		this.addConfirmExitPopup()
	}

	private addBackground() {
		this.background = this.game.add.image(0, 0, 'interface', 'white_rect0000', this)
		this.background.inputEnabled = true
		this.background.tint = 0xfff3e0
		this.background.anchor.set(0.5, 0.5)
		this.background.name = 'pause_screen_back'
	}

	private addMainGroup() {
		this.mainGroup = this.game.add.group(this, 'main_group')
	}

	private addResumeButton() {
		this.resumeButton = new SimpleButton(this.game, 0, 0, 'interface', 'Button_Resume0000', this.mainGroup)
	}

	private addMiddleButtons() {
		this.homeButton = new SimpleButton(this.game, 0, 0, 'interface', 'Button_Home0000')
		this.homeButton.callback.add(this.onHomeButtonClick, this)

		this.restartButton = new SimpleButton(this.game, 0, 0, 'interface', 'Button_Restart0000')
		this.restartButton.callback.add(this.onRestartButtonClick, this)

		this.soundButton = new ToggleButton(this.game, 0, 0, 'interface', 'Button_Sound_On0000', 'Button_Sound_Off0000')
		this.soundButton.callback.add(this.onSoundButtonClick, this)
		this.updateSoundButtonState()

		this.middleButtons = this.game.add.group(this.mainGroup, 'middle_buttons')
		this.middleButtons.addMultiple([this.homeButton, this.restartButton, this.soundButton], true)
		this.middleButtons.align(3, 1, 150, 100, Phaser.CENTER)
	}

	private onHomeButtonClick() {
		if (this.showConfirmExitPopup()) {
			let title = this.game.texts.texts.quit_popup_title
			let subtitle = this.game.texts.texts.progress_lost_warinig
			this.confirmExitPopup.updateContent(title, subtitle)
			this.confirmExitPopup.yesButton.setCallbackOn('pointerup')
			this.confirmExitPopup.yesButton.callback.addOnce(this.switchToBoosterShop, this)
			this.confirmExitPopup.show()
		} else {
			this.switchToBoosterShop()
		}
	}

	private switchToBoosterShop(): void {
		this.game.ads.showInterstitial('PauseScreen:Quit').finally(() => {
			this.game.changeState('BoostersShop')
		})
	}

	private onRestartButtonClick() {
		let showPopup = this.showConfirmExitPopup() === false
		if (showPopup) {
			this.restartLevel()
			return
		}

		let title = this.game.texts.texts.restart_popup_title
		let subtitle = this.game.texts.texts.progress_lost_warinig
		this.confirmExitPopup.updateContent(title, subtitle)
		this.confirmExitPopup.yesButton.setCallbackOn('pointerup')
		this.confirmExitPopup.yesButton.callback.addOnce(this.restartLevel, this)
		this.confirmExitPopup.show()
	}

	private restartLevel(): void {
		this.game.ads.showInterstitial('PauseScreen:Restart').finally(() => {
			this.game.changeState('Level')
		})
	}

	public showConfirmExitPopup(): boolean {
		return this.level.levelStats.moves > 3
	}

	private onSoundButtonClick() {
		this.game.audio.soundMute = !this.game.audio.soundMute
	}

	private addCheckboxes() {
		let props: CheckboxInitProps = {
			textureKey: 'interface',
			onFrame: 'Checkbox0001',
			offFrame: 'Checkbox0000',
		}

		let headstartText: string = this.game.texts.texts['headstart_popup_cb']
		this.headstartCheckbox = new Checkbox(this.game, this, headstartText, props)
		this.headstartCheckbox.onChange.add(this.onHeadstartCbChanged, this)
		this.headstartCheckbox.label.tint = 0xff9933
		this.headstartCheckbox.name = 'headstart_checkbox'
		this.headstartCheckbox.kill()

		let doubleCoinsText: string = this.game.texts.texts['coinsx2_popup_cb']
		this.doubleCoinsCheckbox = new Checkbox(this.game, this, doubleCoinsText, props)
		this.doubleCoinsCheckbox.onChange.add(this.onDoubleCoinsCbChanged, this)
		this.doubleCoinsCheckbox.label.tint = 0xff9933
		this.doubleCoinsCheckbox.name = 'double_coins_checkbox'
		this.doubleCoinsCheckbox.kill()

		let cbsArray = [this.headstartCheckbox, this.doubleCoinsCheckbox]
		this.checkboxes = this.game.add.group(this.mainGroup, 'checkboxes')
		this.checkboxes.addMultiple(cbsArray, true)
		this.checkboxes.align(1, cbsArray.length, Config.GAME_WIDTH, 80, Phaser.LEFT_CENTER)
	}

	private onHeadstartCbChanged(checkbox: Checkbox): void {
		this.game.save.setValue('headstart_popup_disabled', !checkbox.checked, {
			origin: 'pause_screen/headstart_checkbox',
		})
	}

	private onDoubleCoinsCbChanged(checkbox: Checkbox): void {
		this.game.save.setValue('coinsx2_popup_disabled', !checkbox.checked, {
			origin: 'pause_screen/double_coins_checkbox',
		})
	}

	public resize(): void {
		this.resizeBackground()

		this.resumeButton.centerX = Config.HALF_GAME_WIDTH
		this.resumeButton.top = 0

		this.middleButtons.centerX = Config.HALF_GAME_WIDTH
		this.middleButtons.top = this.resumeButton.bottom + 40

		this.checkboxes.centerX = Config.HALF_GAME_WIDTH
		this.checkboxes.top = this.middleButtons.bottom + 45

		this.mainGroup.centerX = Config.HALF_GAME_WIDTH
		this.mainGroup.centerY = Config.HALF_GAME_HEIGHT

		this.buildInfo.centerX = Config.HALF_GAME_WIDTH
		this.buildInfo.bottom = Config.GAME_HEIGHT - 20

		this.confirmExitPopup.resize()
	}

	private resizeBackground() {
		this.background.width = Config.GAME_WIDTH * 1.25
		this.background.height = Config.GAME_HEIGHT * 1.25
		this.background.centerX = Config.HALF_GAME_WIDTH
		this.background.centerY = Config.HALF_GAME_HEIGHT
	}

	public show(): void {
		this.revive()
		this.updateCheckboxes()
		this.updateSoundButtonState()

		this.onShow.dispatch(this)

		this.game.tweens.removeFrom(this)

		this.alpha = 1

		this.background.alpha = 0
		this.game.add.tween(this.background).to({ alpha: 1 }, 100, Phaser.Easing.Cubic.Out, true)
		;[this.resumeButton, ...this.middleButtons.children].forEach((child, index: number) => {
			this.game.add.tween(child).from({ alpha: 0, y: '+20' }, 150, Phaser.Easing.Cubic.Out, true, index * 66)
		})
		;[this.headstartCheckbox, this.doubleCoinsCheckbox].forEach((cb, index) => {
			this.game.add.tween(cb).from(
				{
					x: '+20',
					alpha: 0,
				},
				150,
				Phaser.Easing.Cubic.Out,
				true,
				100 + index * 66
			)
		})
	}

	private updateSoundButtonState() {
		this.soundButton.buttonState = this.game.sound.mute ? ToggleButtonState.STATE_2 : ToggleButtonState.STATE_1
	}

	private updateCheckboxes() {
		this.headstartCheckbox.checked = this.game.save.getValue('headstart_popup_disabled') === false
		this.doubleCoinsCheckbox.checked = this.game.save.getValue('coinsx2_popup_disabled') === false
	}

	private addBuildInfo() {
		let buildVersion: string = window.game.config.build_version.toString()
		let buildDate: string = toReadableDateString(window.game.config.build_time)
		let content: string = `Build #${buildVersion}\n${buildDate}`

		this.buildInfo = this.game.add.bitmapText(0, 0, GameFonts.BARIOL_REGULAR_BMP, content, 30, this)
		this.buildInfo.align = 'center'
		this.buildInfo.anchor.set(0.5, 1)
		this.buildInfo.tint = 0xff9933
		this.buildInfo.alpha = 0
		this.buildInfo.inputEnabled = true
		this.buildInfo.hitArea = this.buildInfo.getBounds(this)
		this.buildInfo.events.onInputDown.add(() => {
			this.buildInfo.alpha = this.buildInfo.alpha === 0 ? 1 : 0
		})
	}

	private addConfirmExitPopup() {
		this.confirmExitPopup = new ExitConfirmPopup(this.game, this)
		this.confirmExitPopup.kill()
	}

	public hide(): void {
		this.game.tweens.removeFrom(this)

		this.game.add
			.tween(this)
			.to({ alpha: 0 }, 100, Phaser.Easing.Cubic.Out, true)
			.onComplete.addOnce(() => {
				this.onHide.dispatch(this)

				this.visible = false
				this.exists = false
			})
	}

	public destroy(): void {
		super.destroy(true, false)
	}
}
