export class FinalItem extends Phaser.Group {
    private originalWidth: number
    private image: Phaser.Image
    private white: Phaser.Image
    private initialPos: Phaser.Point
    public onAnimationComplete: Phaser.Signal

    constructor(_game: Phaser.Game, parent: Phaser.Group) {
        super(_game, parent, 'final_item')

        this.onAnimationComplete = new Phaser.Signal()

        this.addImage()
        this.addWhite()
    }

    private addImage(): void {
        this.image = this.game.add.image(0, 0, 'interface', 'Tile0000', this)
        this.image.anchor.set(0.5, 0.5)

        this.originalWidth = this.image.width
    }

    private addWhite(): void {
        this.white = this.game.add.image(0, 0, 'interface', 'Tile_White0000', this)
        this.white.anchor.set(0.5, 0.5)
        this.white.visible = false
    }

    public saveInitialPosition(x: number, y: number): void {
        this.initialPos = new Phaser.Point(x, y)
    }

    public show(): void {
        let targetScale: number = 116 / this.originalWidth

        this.visible = true
        this.scale.set(0)

        this.game.add
            .tween(this.scale)
            .to({ x: targetScale, y: targetScale }, 400, Phaser.Easing.Back.Out, true)
            .onComplete.addOnce(() => {
                this.game.add
                    .tween(this.scale)
                    .to({ x: 0.8, y: 0.8 }, 300, Phaser.Easing.Sinusoidal.InOut, true, 0, 2, true)
                    .onComplete.addOnce(() => {
                        this.game.add
                            .tween(this.scale)
                            .to({ x: 1, y: 1 }, 500, Phaser.Easing.Back.Out, true, 33)
                            .onComplete.addOnce(() => {
                                this.show3()
                            })
                    })
            })

        this.showWhite()
    }

    private showWhite(): void {
        this.white.visible = true
        this.white.alpha = 0.1

        this.game.add
            .tween(this.white)
            .to({ alpha: 0.66 }, 100, Phaser.Easing.Cubic.Out, true)
            .onComplete.addOnce(this.hideWhite, this)
    }

    private hideWhite() {
        this.game.add
            .tween(this.white)
            .to({ alpha: 0 }, 1500, Phaser.Easing.Cubic.In, true)
            .onComplete.addOnce(() => {
                this.white.visible = false
            })
    }

    private show2(): void {
        this.game.add.tween(this).to({ angle: -5 }, 100, Phaser.Easing.Sinusoidal.InOut, true, 0, 8, true)
        this.game.add
            .tween(this.scale)
            .to({ x: 1, y: 1 }, 1600, Phaser.Easing.Linear.None, true)
            .onComplete.addOnce(() => {
                this.show3()
            })
    }

    private show3(): void {
        let distance: number = this.position.distance(this.initialPos)
        let duration: number = Phaser.Math.clamp(distance, 500, 1500)
        this.game.add
            .tween(this)
            .to({ x: this.initialPos.x, y: this.initialPos.y, angle: 0 }, duration, Phaser.Easing.Back.InOut, true)
            .onComplete.addOnce(() => {
                this.onAnimationComplete.dispatch(this)
            })
    }

    public destroy(): void {
        super.destroy(true, false)

        this.onAnimationComplete.dispose()
        this.onAnimationComplete = null
    }
}
