import { maxBy } from 'es-toolkit/compat'
import { Item } from "./items/Item"

export class ItemsGenerator {
    private itemRnd: Phaser.RandomDataGenerator
    private allowedItemTypes: number[]
    private difficulty: number

    constructor(difficulty: number) {
        this.itemRnd = new Phaser.RandomDataGenerator()
        this.difficulty = difficulty
        this.setNewSeed()

        //for (i:number = 1; i < 15; i++) {
        //    trace("Difficulty for", i, "= " + this.getDifficulty(i));
        //}
    }

    public setAllowedItemTypes(itemTypes: number[]): void {
        this.allowedItemTypes = itemTypes
    }

    public getNewItemType(): number {
        let randomIndex: number = this.itemRnd.integerInRange(0, this.allowedItemTypes.length - 1)

        return this.allowedItemTypes[randomIndex]
    }

    public updateAllowedItemTypes(activeItems: Item[]): void {
        let bestItem: number = this.getBestItemType(activeItems)
        let worstItem: number = this.getWorstItemType(bestItem)

        let itemTypes: number[] = []
        if (bestItem < 3) {
            itemTypes.push(1, 2)
        } else {
            if ((bestItem + 1) % 13 === 0) {
                bestItem-- // do not generate 13, 26, 39 and so on
            }

            for (let i: number = worstItem; i < bestItem; i++) {
                itemTypes.push(i)
            }
        }

        this.setChances(itemTypes)
    }

    public getBestItemType(items: Item[]): number {
        return maxBy(items, 'itemType').itemType
    }

    public getWorstItemType(bestType: number): number {
        return Math.max(1, bestType - 6)
    }

    private setChances(itemTypes: number[]): void {
        this.allowedItemTypes.length = 0

        let bestType: number = itemTypes[itemTypes.length - 1]
        let difficulty: number = this.getDifficulty(bestType) // [0.5..1.99] lower - easier
        let typesNum: number = itemTypes.length
        for (let i: number = 0; i < itemTypes.length; i++) {
            let itemType: number = itemTypes[i]
            let chances: number = 0
            if (typesNum > 1) {
                chances = (100 - this.allowedItemTypes.length) / typesNum
                chances = Math.floor(chances * difficulty)
            } else {
                chances = 100 - this.allowedItemTypes.length
            }

            for (let j: number = 0; j < chances; j++) {
                this.allowedItemTypes.push(itemType)
            }

            typesNum--
        }

        console.assert(this.allowedItemTypes.length === 100)
    }

    private getDifficulty(bestType: number): number {
        return this.difficulty
    }

    private setNewSeed(): void {
        let seeds = [Date.now()]
        //seeds = [0];
        this.itemRnd.sow(seeds)
    }

    public getSeed(): string {
        return this.itemRnd.state()
    }

    public setSeed(seed: string): void {
        this.itemRnd.state(seed)
    }

    public destroy(): void {
        this.itemRnd = null
        this.allowedItemTypes = null
    }
}
