import { z } from 'zod'

const zson = <T extends z.ZodType>(schema: T) => {
	return z.preprocess((value: string | null) => {
		if (value === null) {
			return null
		}

		try {
			return JSON.parse(value)
		} catch {
			return null
		}
	}, schema).nullable()
}

export const SCHEMA = z.object({
	/**
	 * Unique identifier for the current game session.
	 */
	sessionId: zson(z.number()),

	/**
	 * Offset in minutes to be added to the local time.
	 */
	localTimeOffsetMinutes: zson(z.number()),

	/**
	 * Offset in minutes to be added to the server time.
	 */
	serverTimeOffsetMinutes: zson(z.number()),

	/**
	 * Custom display refresh rate in Hz.
	 */
	displayRefreshRateHz: zson(z.number().positive()),

	/**
	 * Whether to log time when the page is visible.
	 */
	logTimeOnPageVisible: zson(z.boolean()),

	/**
	 * Whether to disable the multi-tab check.
	 */
	disableMultiTabCheck: zson(z.boolean()),

	/**
	 * When true, next boot must clear both localStorage and remoteStorage before loading any state.
	 * Written by reset to defer clearing until the next page load.
	 * Cleared by StateService.init() before any load calls to avoid repeated wipes.
	 */
	pendingProfileClear: zson(z.boolean()),
})

export type Schema = z.infer<typeof SCHEMA>
