import { FontWeight, GameFonts } from '../../../GameFonts'
import { SimpleButton } from '../../../gui/buttons/SimpleButton'
import { GameTexts } from '../../../texts/GameTexts'
import { LanguageUtil } from '../../../texts/LanguageUtil'
import { ToggleButton, ToggleButtonState } from './../../../gui/buttons/ToggleButton'
import { LanguageButton } from './LanguageButton'

export class SettingsContent extends Phaser.Group {
	private back: Phaser.Image
	private title: Phaser.Text
	private buttonsContainer: Phaser.Group
	private buttons: (SimpleButton | LanguageButton | ToggleButton)[]
	public soundButton: ToggleButton
	public languageButton: LanguageButton

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'settings_content')

		this.addBack()
		this.addTitle()
		this.addButtons()

		this.buttons = [this.soundButton, this.languageButton]
	}

	private addBack(): void {
		this.back = this.game.add.image(0, 0, 'main_menu', 'Settings_GUI_Back0000', this)
		this.back.alpha = 0
	}

	private addTitle(): void {
		let content: string = this.getTitleContent()
		let style: Phaser.PhaserTextStyle = {
			font: GameFonts.DEFAULT,
			fontWeight: FontWeight.BOLD,
			fontSize: 46,
			fill: '#F29000',
			align: 'center',
		}

		this.title = this.game.add.text(0, 0, content, style, this)
		this.title.anchor.set(0.5, 0.5)
		this.title.centerX = this.back.centerX
		this.title.centerY = this.back.top + 56
	}

	private getTitleContent(): string {
		return this.game.texts.texts.settings
	}

	private addButtons(): void {
		this.buttonsContainer = this.game.add.group(this, 'buttons')
		this.addSoundButton()
		this.addLanguageButton()

		this.alignButtons()
	}

	private addSoundButton() {
		this.soundButton = new ToggleButton(
			this.game,
			0,
			0,
			'main_menu',
			'Button_Sound_On0000',
			'Button_Sound_Off0000',
			this.buttonsContainer
		)
		this.soundButton.buttonState = this.game.sound.mute ? ToggleButtonState.STATE_2 : ToggleButtonState.STATE_1
		this.soundButton.callback.add(this.onSoundButtonClick, this)
	}

	private onSoundButtonClick(): void {
		this.game.audio.soundMute = !this.game.audio.soundMute
	}

	private addLanguageButton() {
		let language = LanguageUtil.getLanguageTitle(this.game.texts.language)
		this.languageButton = new LanguageButton(this.game, this.buttonsContainer)
		this.languageButton.centerX = this.soundButton.centerX
		this.languageButton.top = this.soundButton.bottom + 30
		this.languageButton.leftArrow.events.onInputDown.add(() => this.updateLanguage(-1))
		this.languageButton.rightArrow.events.onInputDown.add(() => this.updateLanguage(1))
		this.languageButton.updateText(language)
	}

	private updateLanguage(direction: number): void {
		this.game.audio.playSound('tap')

		let texts: GameTexts = this.game.texts
		let currentLanguage: string = texts.language
		let languages: string[] = texts.allLanguages

		let currentIndex: number = languages.indexOf(currentLanguage)
		let newIndex: number = Phaser.Math.wrap(currentIndex + direction, 0, languages.length)
		let newLanguage: string = languages[newIndex]
		this.game.save.setValue('language', newLanguage, { origin: 'settings/language_change' })
		this.game.texts.setLanguage(newLanguage)
		this.languageButton.updateText(LanguageUtil.getLanguageTitle(newLanguage))
	}

	private alignButtons() {
		let top: number = this.title.bottom
		let bottom: number = this.back.bottom
		let height: number = bottom - top

		this.buttonsContainer.centerX = this.back.centerX
		this.buttonsContainer.centerY = top + height / 2
	}

	public show(delay: number): void {
		this.visible = true
		this.exists = true

		this.buttons.forEach((button) => {
			button.enabled = true
		})

		this.alpha = 0
		this.game.add.tween(this).to({ alpha: 1 }, 250, Phaser.Easing.Cubic.Out, true, delay)
	}

	public hide(): void {
		this.buttons.forEach((button) => {
			button.enabled = false
		})

		this.game.tweens.removeFrom(this)
		this.game.add
			.tween(this)
			.to({ alpha: 0 }, 120, Phaser.Easing.Cubic.Out, true)
			.onComplete.addOnce(() => {
				this.exists = false
				this.visible = false
			})
	}

	public destroy(): void {
		super.destroy(true, false)

		this.buttons = null
	}

	public onLanguageChange() {
		this.title.text = this.getTitleContent()
	}
}
