import { Config } from '../../../Config'
import { FontWeight, GameFonts } from '../../../GameFonts'
import { SimpleButton } from '../../../gui/buttons/SimpleButton'

export class AlertPopup extends Phaser.Group {
    private back: Phaser.Image
    private title: Phaser.Text
    private message: Phaser.Text
    public okButton: SimpleButton

    constructor(_game: Phaser.Game, parent: Phaser.Group) {
        super(_game, parent, 'alert_popup')

        this.addBack()
        this.addTitle()
        this.addMessage()
        this.addOkButton()
    }

    private addBack(): void {
        this.back = this.game.add.image(0, 0, 'main_menu', 'Settings_GUI_Back0000', this)
        this.back.inputEnabled = true
        this.back.name = 'alert_popup'
    }

    private addTitle(): void {
        let style = {
            font: GameFonts.DEFAULT,
            fontWeight: FontWeight.BOLD,
            fontSize: 40,
            fill: '#FF9933',
            align: 'center',
        }

        this.title = this.game.add.text(0, 0, 'Alert', style, this)
        this.title.anchor.set(0.5, 0)
        this.title.centerX = this.back.centerX
        this.title.top = this.back.top + 30
        this.title.wordWrap = true
        this.title.wordWrapWidth = this.back.width * 0.85
        this.title.lineSpacing = -8
    }

    private addMessage(): void {
        let style = {
            font: GameFonts.DEFAULT,
            fontWeight: FontWeight.NORMAL,
            fontSize: 28,
            fill: '#FF9933',
            align: 'center',
        }

        this.message = this.game.add.text(0, 0, 'Alert message', style, this)
        this.message.anchor.set(0.5, 0.5)
        this.message.wordWrap = true
        this.message.wordWrapWidth = this.back.width * 0.85
        this.message.lineSpacing = -8
        this.message.centerX = this.back.centerX
        this.message.centerY = this.back.centerY
    }

    private addOkButton(): void {
        this.okButton = new SimpleButton(this.game, 0, 0, 'interface', 'Button_Yes0000', this)
        this.okButton.centerX = this.back.centerX
        this.okButton.bottom = this.back.bottom - 30
        this.okButton.name = 'alert_ok_button'
    }

    public updateContent(titleText: string, messageText: string): void {
        this.title.text = titleText
        this.message.text = messageText
    }

    public show(initialDelay: number = 0): void {
        this.visible = true
        this.exists = true

        this.game.tweens.removeFrom(this)
        this.game.add.tween(this).from({ alpha: 0 }, 150, Phaser.Easing.Cubic.Out, true, initialDelay)
        this.game.add.tween(this).from({ y: '+50' }, 350, Phaser.Easing.Back.Out, true, initialDelay)
    }

    public hide(): void {
        this.game.tweens.removeFrom(this)
        this.game.add
            .tween(this)
            .to({ alpha: 0, y: '+40' }, 160, Phaser.Easing.Cubic.In, true)
            .onComplete.addOnce(() => {
                this.visible = false
                this.exists = false
            })
    }

    public getWidth(): number {
        return this.back.width
    }

    public getHeight(): number {
        return this.back.height
    }

    public destroy(): void {
        super.destroy(true, false)
    }
} 