import { until } from 'until-async'
import { getCacheBustedUrl } from '../../CacheBuster'
import { loadScript } from '../../robowhale/net/load-script'

export const WA_STYLESHEET_ID = 'webawesome-styles'

let isLoaderStarted = false
let runtimePromise: Promise<HTMLScriptElement> | null = null

/**
 * Ensures WebAwesome runtime (JS and CSS) is loaded and started.
 */
export async function ensureWebAwesomeRuntime(): Promise<void> {
	// Compute URLs (relative paths are fine because they'll be resolved relative to index.html)
	const runtimeUrlStr = getCacheBustedUrl('js/webawesome.js')
	const runtimeUrl = new URL(runtimeUrlStr, window.location.href).href
	const cssUrl = getCacheBustedUrl('css/webawesome.css')

	// Ensure stylesheet is injected
	ensureStyles(cssUrl)

	// Ensure JS runtime bundle is imported (it registers needed components)
	const [error] = await until(() => getRuntime(runtimeUrl))
	if (!error) {
		isLoaderStarted = true
	}
}

/**
 * Injects the WebAwesome stylesheet if it hasn't been injected yet.
 */
function ensureStyles(cssUrl: string): void {
	if (document.getElementById(WA_STYLESHEET_ID)) {
		return
	}

	const link = document.createElement('link')
	link.id = WA_STYLESHEET_ID
	link.rel = 'stylesheet'
	link.href = cssUrl
	document.head.appendChild(link)
	// console.log(`[WebAwesome] Stylesheet injected: ${cssUrl}`);
}

/**
 * Dynamically imports the WebAwesome loader module.
 */
async function getRuntime(runtimeUrl: string): Promise<HTMLScriptElement> {
	if (runtimePromise) {
		return runtimePromise
	}

	runtimePromise = loadScript(runtimeUrl)
	return runtimePromise
}
