import { BoosterType } from './BoosterType'
import { IBoostersConfig } from './IBoostersConfig'

interface BoosterTexts {
	title: string
	description: string
	hint: string
	warning: string
}

export class Booster {
	private game: Phaser.Game
	private _type: BoosterType
	private _title: string
	private _description: string
	private _hint: string
	private basePrice: number
	private _price: number
	private _num: number
	private _maxNum: number
	public warning: string
	public onChange: Phaser.Signal

	constructor(_game: Phaser.Game, type: BoosterType) {
		this.game = _game

		this._type = type

		this.onChange = new Phaser.Signal()

		this.updateTexts()
		this.initValuesFromConfig()
		this._num = this.game.save.getValue(this._type)
		this._price = this.calculatePrice()
	}

	public updateTexts() {
		let texts: BoosterTexts = this.game.texts.texts['boosters'][this._type.toString()]

		this._title = texts.title
		this._description = texts.description
		this._hint = texts.hint
		this.warning = texts.warning
	}

	private initValuesFromConfig() {
		let config = (this.game.cache.getJSON('boosters') as IBoostersConfig)[this._type]

		this._maxNum = config.max
		this.basePrice = config.price
	}

	private calculatePrice(): number {
		/*let price:number = this.basePrice;
        for (let i:number = 0; i < this._num; i++) {
            price *= 1.25;
        }
        return Math.floor(price);*/
		return this.basePrice
	}

	public get description(): string {
		return this._description
	}

	public get title(): string {
		return this._title
	}

	public get type(): BoosterType {
		return this._type
	}

	public get price(): number {
		return this._price
	}

	public get num(): number {
		return this._num
	}

	public set num(value: number) {
		if (value >= 0 && value <= this._maxNum) {
			let prevValue: number = this._num
			let newValue: number = value

			this._num = value
			this._price = this.calculatePrice()
			this.game.save.setValue(this._type, value, { origin: 'boosters/update_count' })

			this.onChange.dispatch(this, prevValue, newValue)
		}

		if (value > this._maxNum) {
			console.warn(`Booster ${this._type} :: Max num is reached! [max = ${this._maxNum}, newValue = ${value}]`)
		}
	}

	public get hint(): string {
		return this._hint
	}

	public get maxNum(): number {
		return this._maxNum
	}
}
