export class Finger extends Phaser.Image {
    public static OFFSET: Phaser.Point = new Phaser.Point(26, 50)

    private path: Phaser.Point[]
    private currentPoint: Phaser.Point
    private delayedCall: Phaser.TimerEvent

    constructor(_game: Phaser.Game) {
        super(_game, 0, 0, 'interface', 'Finger0000')

        this.visible = false
    }

    public showTap(): void {
        this.visible = true

        this.game.tweens.removeFrom(this)

        this.rotation = 0
        this.alpha = 0
        this.scale.set(1)

        this.game.add
            .tween(this)
            .to({ alpha: 1 }, 250, Phaser.Easing.Cubic.Out, true)
            .onComplete.addOnce(() => {
                this.showTap2()
            })
    }

    private showTap2(): void {
        let duration: number = 400
        this.game.add.tween(this.scale).to({ x: 0.8, y: 0.8 }, duration, Phaser.Easing.Cubic.Out, true)
        this.game.add.tween(this).to({ angle: -17 }, duration, Phaser.Easing.Cubic.Out, true)

        this.delayedCall = this.game.time.events.add(900, this.hideTap, this)
    }

    private hideTap(): void {
        this.game.add.tween(this.scale).to({ x: 1, y: 1 }, 750, Phaser.Easing.Cubic.Out, true)
        this.game.add.tween(this).to({ angle: 0 }, 750, Phaser.Easing.Cubic.Out, true)

        this.game.add
            .tween(this)
            .to({ alpha: 0 }, 250, Phaser.Easing.Cubic.Out, true, 500)
            .onComplete.addOnce(() => {
                this.hideTap2()
            })
    }

    private hideTap2(): void {
        this.delayedCall = this.game.time.events.add(660, this.showTap, this)
    }

    public pointAt(x: number, y: number): void {
        this.removeTimers()

        this.removeTweens()

        this.frameName = 'Finger_20000'
        this.angle = 0
        this.scale.set(1)

        this.anchor.set(0.5, 1)
        this.visible = true

        this.alpha = 0
        this.x = x
        this.y = y
        this.game.add.tween(this).to({ alpha: 1 }, 200, Phaser.Easing.Cubic.Out, true)
        this.game.add.tween(this).to({ y: '-66' }, 500, Phaser.Easing.Cubic.InOut, true, 0, -1, true)
    }

    private removeTweens() {
        if (this.game) {
            this.game.tweens.removeFrom(this)
            this.game.tweens.removeFrom(this.scale)
        }
    }

    public followPath(path: Phaser.Point[]): void {
        this.path = path

        this.visible = true
        this.show()
    }

    private show(): void {
        this.removeTweens()

        this.currentPoint = this.path[0]
        this.x = this.currentPoint.x
        this.y = this.currentPoint.y
        this.alpha = 0
        this.rotation = 0
        this.scale.set(1)

        this.game.add
            .tween(this)
            .to({ alpha: 1 }, 250, Phaser.Easing.Cubic.Out, true)
            .onComplete.addOnce(() => {
                this.show2()
            })
    }

    private show2(): void {
        let duration = 400
        this.game.add.tween(this.scale).to({ x: 0.8, y: 0.8 }, duration, Phaser.Easing.Cubic.Out, true)
        this.game.add.tween(this).to({ angle: -17 }, duration, Phaser.Easing.Cubic.Out, true)

        this.delayedCall = this.game.time.events.add(600, this.moveToNextPoint, this)
    }

    private moveToNextPoint(): void {
        let nextPoint: Phaser.Point = this.getNextPoint()
        let distance: number = this.currentPoint.distance(nextPoint)
        let duration: number = distance * 3.3

        this.currentPoint = nextPoint

        this.game.add
            .tween(this)
            .to({ x: nextPoint.x, y: nextPoint.y }, duration, Phaser.Easing.Linear.None, true)
            .onComplete.addOnce(() => {
                this.onMoveComplete()
            })
    }

    private getNextPoint(): Phaser.Point {
        let currentIndex: number = this.path.indexOf(this.currentPoint)
        let nextIndex: number = currentIndex === this.path.length - 1 ? 0 : currentIndex + 1

        return this.path[nextIndex]
    }

    private onMoveComplete(): void {
        if (this.currentPoint === this.path[this.path.length - 1]) {
            this.hide()
        } else {
            this.moveToNextPoint()
        }
    }

    private hide(): void {
        this.game.add
            .tween(this)
            .to({ alpha: 0 }, 250, Phaser.Easing.Cubic.Out, true, 500)
            .onComplete.addOnce(() => {
                this.hide2()
            })
    }

    private hide2(): void {
        this.game.time.events.add(666, this.show, this)
    }

    public stopAndHide(): void {
        this.removeTweens()
        this.removeTimers()
        this.visible = false
    }

    public removeTimers(): void {
        if (this.delayedCall) {
            this.game.time.events.remove(this.delayedCall)
            this.delayedCall = null
        }
    }

    public destroy(): void {
        this.stopAndHide()
        this.removeTimers()

        super.destroy(true)

        this.path = null
        this.currentPoint = null
    }
}
