import { Config } from '../Config'
import { FontWeight, GameFonts } from '../GameFonts'
import { DrawUtil } from './../robowhale/utils/DrawUtil'

export class Toast extends Phaser.Group {
	private back: Phaser.Image
	public text: Phaser.Text

	constructor(_game: Phaser.Game, parent: Phaser.Group | Phaser.Stage) {
		super(_game, parent, 'toast')

		this.addBack()
		this.addText()
		this.resizeBack(500, 120)

		this.game.state.onStateChange.add(this.hide, this)
	}

	private addBack() {
		let texture: Phaser.BitmapData = DrawUtil.createRectTexture(this.game, 200, 100)

		this.back = this.game.add.image(0, 0, texture, null, this)
		this.back.anchor.set(0.5, 0.5)
		this.back.alpha = 0.8
	}

	private addText() {
		let content = 'Toast'
		let style: Phaser.PhaserTextStyle = {
			font: GameFonts.DEFAULT,
			fontWeight: FontWeight.NORMAL,
			fontSize: 32,
			fill: '#ffffff',
			align: 'center',
		}

		this.text = this.game.add.text(0, 0, content, style, this)
		this.text.align = 'center'
		this.text.wordWrap = true
		this.text.wordWrapWidth = this.back.width * 0.85
		this.text.lineSpacing = -5
		this.text.anchor.set(0.5, 0.5)
	}

	private alignText() {
		let maxHeight: number = this.back.height * 0.8

		this.text.scale.set(1)
		if (this.text.height > maxHeight) {
			this.text.scale.set(maxHeight / this.text.height)
		}

		this.text.centerX = this.back.centerX
		this.text.centerY = this.back.centerY
	}

	public resizeBack(width: number, height: number): void {
		this.back.width = width
		this.back.height = height

		this.text.wordWrapWidth = this.back.width * 0.85
		this.alignText()
	}

	public updateText(content: string): void {
		this.text.setText(content)
		this.alignText()
	}

	public show(message: string, showDelay: number = 0, hideDelay: number = 3000): void {
		this.visible = true
		this.exists = true

		this.updateText(message)

		this.alpha = 1
		this.scale.set(1)
		this.centerX = Config.HALF_GAME_WIDTH
		this.centerY = Config.GAME_HEIGHT * 0.9

		this.game.tweens.removeFrom(this)
		this.game.tweens.removeFrom(this.scale)
		this.game.add.tween(this).from({ alpha: 0, y: '+10' }, 230, Phaser.Easing.Cubic.Out, true, showDelay)

		this.game.time.events.removeBy(this.hide, this)
		this.game.time.events.add(hideDelay, this.hide, this)
	}

	private hide() {
		this.game.time.events.removeBy(this.hide, this)

		this.game.tweens.removeFrom(this)
		this.game.add
			.tween(this)
			.to({ alpha: 0 }, 150, Phaser.Easing.Cubic.Out, true)
			.onComplete.addOnce(() => {
				this.visible = false
				this.exists = false
			})
	}

	public showRewardedVideoWarning(): void {
		let message: string = this.game.texts.texts.videos_warning
		this.show(message, 0, 2500)
	}

	public showShareMessage(coins: number = 0): void {
		let message: string = this.game.texts.texts['share_complete']
		if (coins > 0) {
			message += '\n' + this.game.texts.texts['coins_reward'].replace('#', coins.toString())
		}

		this.show(message, 0, 3000)
	}

	public showShareWarningMessage() {
		let message: string = 'Sharing is not available in your browser'
		this.show(message, 0, 2500)
	}

	public destroy(): void {
		super.destroy(true, false)
	}
}
