import { Item } from '../items/Item'

export class Cell extends Phaser.Image {
	public static WIDTH: number = 130
	public static HEIGHT: number = 130

	public item: Item = null
	private _column: number
	private _row: number

	constructor(game: Phaser.Game, row: number, column: number) {
		super(game, 0, 0, 'interface', 'white_rect0000')

		this._row = row
		this._column = column
		this.name = `cell {${this.column}, ${this.row}}`

		this.width = Cell.WIDTH
		this.height = Cell.HEIGHT

		this.tint = 0x2bb6f6
	}

	public isFree(): boolean {
		return this.item === null
	}

	public toString(): string {
		return 'Cell {row: ' + this._row + ', column: ' + this._column + '}'
	}

	// @ts-ignore
	public get centerX(): number {
		return this.x + this.width * 0.5
	}

	// @ts-ignore
	public get centerY(): number {
		return this.y + this.height * 0.5
	}

	public get column(): number {
		return this._column
	}

	public get row(): number {
		return this._row
	}
}
