export class ChainLink extends Phaser.Image {
    constructor(_game: Phaser.Game) {
        super(_game, 0, 0, 'interface', 'Item_Link0000')

        this.anchor.set(0.5, 0.5)
        this.exists = false
        this.visible = false
    }

    public show(): void {
        this.visible = true
        this.exists = true

        this.game.tweens.removeFrom(this.scale)
        this.scale.set(0, 1)
        this.game.add.tween(this.scale).to({ x: 1, y: 1 }, 330, Phaser.Easing.Back.Out, true)
    }

    public hide(): void {
        this.exists = false
        this.visible = false
    }
}
