import { until } from '@open-draft/until'
import { Config } from '../../Config'
import { SimpleButton } from '../../gui/buttons/SimpleButton'
import { ToggleButton, ToggleButtonState } from '../../gui/buttons/ToggleButton'
import { Main } from '../../Main'
import { GameBackground } from '../../objects/GameBackground'
import { LevelStats } from '../level/LevelStats'
import { CoinsSpreadFX } from './../../objects/CoinsSpreadFX'
import { BestItemCircle } from './circles/BestItemCircle'
import { CoinsCircle } from './circles/CoinsCircle'
import { StatCircle } from './circles/StatCircle'
import { GameOverTopPanel } from './GameOverTopPanel'
import { LeaderboardRankLabel } from './LeaderboardRankLabel'
import { ItemShareButton } from './share/ItemShareButton'
import { ShopLabel } from './ShopLabel'
import { getErrorLog } from '../../robowhale/utils/error/utils'
import { err, ok } from 'neverthrow'

export interface IGameOverInitData {
	levelStats: LevelStats
	skipStartAnimation: boolean
}

export class GameOver extends Phaser.State {
	private skipStartAnimation: boolean = false
	private levelStats: LevelStats
	private background: GameBackground
	private topPanel: GameOverTopPanel
	private circles: StatCircle[]
	private coinsCircle: CoinsCircle
	private bestItemCircle: BestItemCircle
	private timeCircle: StatCircle
	private doubleCoinsButton: SimpleButton
	private shareButton: ItemShareButton
	private restartButton: SimpleButton
	private boostersShopButton: SimpleButton
	private soundButton: ToggleButton
	private shopLabel: ShopLabel
	private rankLabel: LeaderboardRankLabel
	private buttons: SimpleButton[]
	private bottomButtons: Phaser.Group
	private coinsSpreadFX: CoinsSpreadFX

	public init(data: IGameOverInitData): void {
		this.levelStats = data.levelStats
		this.skipStartAnimation = data.skipStartAnimation
	}

	public create(): void {
		this.updateAchievements()
		this.addBackground()
		this.addTopPanel()
		this.addCircles()
		this.addShareButton()
		this.addBottomButtons()
		this.addShopLabel()
		this.addRankLabel()
		this.addCoinsFX()

		this.addKeyCallbacks()

		this.resize()

		if (this.skipStartAnimation === false) {
			this.show()
		}
	}

	private updateAchievements(): void {
		this.game.save.changeNum('games_played', 1, { origin: 'game_over/update_achievements' })
	}

	private addBackground() {
		this.background = new GameBackground(this.game, 'game_over', 'white_rect0000')
	}

	private addTopPanel(): void {
		this.topPanel = new GameOverTopPanel(this.game, this.world)
	}

	private addCircles(): void {
		let coins: number = this.game.save.getCoins()
		this.coinsCircle = new CoinsCircle(this.game, this.world, 'game_over', 'Circle0000', 0xff9800, coins.toString())
		this.coinsCircle.originalScale = this.coinsCircle.scale.clone()
		this.coinsCircle.addIcon('game_over', 'Icon_Coin0000')
		this.coinsCircle.setCoinsNum(coins)

		let itemType: number = this.levelStats.bestItemTypeAtEnd
		this.bestItemCircle = new BestItemCircle(
			this.game,
			this.world,
			'game_over',
			'Circle0000',
			0xff9800,
			itemType.toString(),
			itemType
		)
		this.bestItemCircle.scale.set(1.25)
		if (this.levelStats.isHighscore) {
			this.bestItemCircle.addIcon('game_over', 'Icon_Crown0000')
		}

		let timeContent: string = this.getTimeCircleContent()
		this.timeCircle = new StatCircle(this.game, this.world, 'game_over', 'Circle0000', 0xff9800, timeContent)
		this.timeCircle.addIcon('game_over', 'Icon_Time0000')

		this.circles = [this.coinsCircle, this.bestItemCircle, this.timeCircle]
	}

	private getTimeCircleContent(): string {
		let minutes: number = Math.floor(this.levelStats.timeInSeconds / 60)
		let minutesStr: string = minutes < 10 ? '0' + minutes : minutes.toString()
		let seconds: number = this.levelStats.timeInSeconds % 60
		let secondsStr: string = seconds < 10 ? '0' + seconds : seconds.toString()

		return minutesStr + ':' + secondsStr
	}

	private addDoubleCoinsButton(): void {
		this.doubleCoinsButton = new SimpleButton(this.game, 0, 0, 'game_over', 'Button_Double_Coins0000')
		this.doubleCoinsButton.setCallbackOn('pointerup')
		this.doubleCoinsButton.callback.addOnce(this.showRewardedVideo, this, 0, 'double_coins_button')
	}

	private showRewardedVideo(uiOrigin: string) {
		this.game.ads.showRewarded('GameOver:DoubleCoinsButton').then((result) => {
			if (result.success === true) {
				this.doubleEarnedCoins()
			}
		})
	}

	private addShareButton(): void {
		let shareMessageTemplate: string = this.game.texts.texts.share_highscore
		let shareMessage: string = shareMessageTemplate.replace('#', this.levelStats.bestItemTypeAtEnd.toString())

		this.shareButton = new ItemShareButton(this.game, this.world, this.levelStats.bestItemTypeAtEnd)
		this.shareButton.shareMessage = shareMessage
		this.shareButton.x = Config.HALF_GAME_WIDTH
		this.shareButton.y = Config.GAME_HEIGHT * 0.59
		this.shareButton.back.events.onInputUp.add(this.shareHighscore, this)

		if (this.levelStats.isHighscore) {
			this.shareButton.showHighscore()
		}

		this.shareButton.kill()
	}

	private async shareHighscore() {
		let highscore: number = this.game.save.getValue('best_item')
		let text: string = this.game.texts.texts['share_highscore'].replace('#', highscore.toString())
		// let image: string = this.getShareImage()

		this.game.share.share(text).catch((error) => {
			console.warn(error)
		})
	}

	private getShareImage(): string {
		let image: Phaser.Image = this.game.make.image(0, 0, 'main_menu', 'Item_130000')
		let dataURL: string = this.game.make.bitmapData(image.width, image.height).drawFull(image).canvas.toDataURL()

		// utils.NetUtil.openWindowWithImage(dataURL);

		return dataURL
	}

	private addBottomButtons(): void {
		let dx: number = 146 * Config.ASSETS_SCALE
		let y: number = Config.GAME_HEIGHT * 0.87

		this.restartButton = new SimpleButton(this.game, 0, 0, 'game_over', 'Button_Restart0000')
		this.restartButton.x = Config.HALF_GAME_WIDTH - dx
		this.restartButton.setCallbackOn('pointerup')
		this.restartButton.callback.addOnce(this.onRestartButtonClick, this)

		this.boostersShopButton = new SimpleButton(this.game, 0, 0, 'game_over', 'Button_Shop0000')
		this.boostersShopButton.x = Config.HALF_GAME_WIDTH
		this.boostersShopButton.callback.addOnce(this.gotoBoostersShop, this)

		this.soundButton = new ToggleButton(this.game, 0, 0, 'main_menu', 'Button_Sound_On0000', 'Button_Sound_Off0000')
		this.soundButton.buttonState = this.game.sound.mute ? ToggleButtonState.STATE_2 : ToggleButtonState.STATE_1
		this.soundButton.x = Config.HALF_GAME_WIDTH + dx
		this.soundButton.callback.add(this.onSoundButtonClick, this)

		this.buttons = [this.restartButton, this.boostersShopButton, this.soundButton]
		this.bottomButtons = this.game.add.group(this.world, 'bottom_buttons')
		this.bottomButtons.addMultiple(this.buttons, true)
		this.bottomButtons.align(this.buttons.length, 1, 146, 140, Phaser.CENTER)
	}

	private async onRestartButtonClick() {
		await this.addGameShortcut()

		this.game.ads.showInterstitial('GameOver:RestartButton').finally(() => {
			this.gotoLevel()
		})
	}

	private gotoLevel(): void {
		this.game.changeState('Level')
	}

	private async gotoBoostersShop() {
		await this.addGameShortcut()

		this.game.changeState('BoostersShop')
	}

	private onSoundButtonClick(): void {
		this.game.audio.soundMute = !this.game.audio.soundMute
	}

	private async addGameShortcut() {
		const result = await this.doAddGameShortcut()

		if (result.isErr()) {
			this.game.logs.warn(`failed to add game shortcut (${result.error})`)
			return false
		}

		this.game.logs.info(`game shortcut added`)

		this.game.analytics.sendDesignEvent('Platform:GameShortcut:Added')

		return true
	}

	private async doAddGameShortcut() {
		if (!this.game.gamePush) {
			return err(`gamePush is not available`)
		}

		if (!this.game.gamePush.sdk.app.canAddShortcut) {
			return err(`not supported on this platform`)
		}

		const { error, data } = await until(() => this.game.gamePush!.sdk.app.addShortcut())
		
		if (error) {
			return err(getErrorLog(error))
		}

		if (!data) {
			return err(`player declined to add game shortcut`)
		}

		return ok()
	}

	private addShopLabel(): void {
		let offset: number = 48 * Config.ASSETS_SCALE

		this.shopLabel = new ShopLabel(this.game)
		this.shopLabel.x = this.boostersShopButton.x + offset
		this.shopLabel.y = this.boostersShopButton.y - offset
		this.bottomButtons.add(this.shopLabel)
	}

	private addRankLabel() {
		this.rankLabel = new LeaderboardRankLabel(this.game, this.bottomButtons)
		this.rankLabel.centerX = this.soundButton.centerX
		this.rankLabel.top = this.soundButton.bottom + 4
		this.rankLabel.kill()
	}

	private addCoinsFX(): void {
		this.coinsSpreadFX = new CoinsSpreadFX(this.game, this.world, 30)
	}

	private doubleEarnedCoins(): void {
		if (this.doubleCoinsButton) {
			this.doubleCoinsButton.visible = false
		}

		this.game.save.changeNum('Coins', this.levelStats.coins, { origin: 'game_over/double_earned_coins' })

		if (this.shopLabel.visible === false && this.game.boosters.canBuyAnyBooster()) {
			this.shopLabel.show(0)
		}

		this.showCoinsFX()
	}

	private showCoinsFX(): void {
		let dispatchPoint: Phaser.Point = new Phaser.Point(Config.HALF_GAME_WIDTH, Config.HALF_GAME_HEIGHT)
		let collectPoint: Phaser.Point = this.coinsCircle.parent.toGlobal(this.coinsCircle.position).toPhaser()

		this.coinsSpreadFX.onCoinsCollectedSignal.addOnce(() => {
			this.coinsCircle.updateCoins(this.game.save.getCoins(), 0)
			this.coinsSpreadFX.pendingDestroy = true
		}, this)

		this.coinsSpreadFX.show(dispatchPoint, collectPoint)
	}

	private addKeyCallbacks() {
		this.game.input.keyboard.addKey(Phaser.Keyboard.ESC).onDown.add(this.onEscPressed, this)

		if (Main.development) {
			this.game.input.keyboard.addKey(Phaser.Keyboard.R).onDown.add(this.restart, this)
		}
	}

	public restart(): void {
		this.game.changeState('GameOver', {
			levelStats: this.levelStats,
			skipStartAnimation: false,
		} as IGameOverInitData)
	}

	private onEscPressed(): void {
		this.game.changeState('BoostersShop')
	}

	public resize(): void {
		this.background.resize()

		this.topPanel.resize()
		this.topPanel.centerX = Config.HALF_GAME_WIDTH
		this.topPanel.top = 0

		this.alignBottomButtons()
		this.alignTopCircles()
		this.alignBestItemCircle()
		this.alignShareButton()

		if (this.coinsSpreadFX) {
			this.coinsSpreadFX.resize()
		}
	}

	private alignBottomButtons() {
		this.bottomButtons.centerX = Config.HALF_GAME_WIDTH
		this.bottomButtons.centerY = Config.GAME_HEIGHT * 0.88
	}

	private alignTopCircles() {
		let offsetX: number = Config.GAME_WIDTH * 0.27
		let y: number = Config.GAME_HEIGHT * 0.3

		this.coinsCircle.x = Config.HALF_GAME_WIDTH - offsetX
		this.coinsCircle.centerY = y

		this.timeCircle.x = Config.HALF_GAME_WIDTH + offsetX
		this.timeCircle.centerY = y
	}

	private alignBestItemCircle() {
		let top: number = this.timeCircle.bottom
		let bottom: number = this.bottomButtons.top
		let height: number = bottom - top

		this.bestItemCircle.x = Config.HALF_GAME_WIDTH
		this.bestItemCircle.y = top + height / 2
	}

	private alignDoubleCoinsButton() {
		this.doubleCoinsButton.centerX = this.coinsCircle.centerX
		this.doubleCoinsButton.centerY = this.coinsCircle.bottom - 12
	}

	private alignShareButton() {
		let top: number = this.bestItemCircle.bottom
		let bottom: number = this.bottomButtons.top
		let height: number = bottom - top

		let maxHeight: number = height * 0.9
		if (this.shareButton.height > maxHeight) {
			this.shareButton.scale.set(maxHeight / this.shareButton.height)
		}

		this.shareButton.x = Config.HALF_GAME_WIDTH
		this.shareButton.y = top + height / 2 - 6
	}

	public show(): void {
		this.topPanel.show(100)
		this.showCircles(330)
		this.showShareButton(700)
		this.showButtons(1100)
	}

	private showCircles(initialDelay: number): void {
		this.circles.forEach((child, index) => {
			let delay: number = initialDelay + index * 120
			this.game.add.tween(child).from({ alpha: 0 }, 200, Phaser.Easing.Cubic.Out, true, delay)
			this.game.add.tween(child).from({ y: '+40' }, 750, Phaser.Easing.Cubic.Out, true, delay)
		})

		if (this.doubleCoinsButton) {
			let delay: number = initialDelay + 480
			this.game.add.tween(this.doubleCoinsButton).from({ alpha: 0 }, 150, Phaser.Easing.Cubic.Out, true, delay)
			this.game.add
				.tween(this.doubleCoinsButton.scale)
				.from(
					{
						x: 0.8,
						y: 0.8,
					},
					400,
					Phaser.Easing.Back.Out,
					true,
					delay
				)
				.onComplete.addOnce(() => {
					this.animateDoubleCoinsButton()
				})
		}
	}

	private animateDoubleCoinsButton(): void {
		if (this.doubleCoinsButton && this.doubleCoinsButton.visible) {
			this.game.time.events.loop(3000, () => {
				this.game.add.tween(this.doubleCoinsButton.scale).to(
					{
						x: 1.1,
						y: 1.1,
					},
					300,
					Phaser.Easing.Sinusoidal.InOut,
					true,
					0,
					2,
					true
				)
			})
		}
	}

	private showShareButton(delay: number) {
		this.game.add.tween(this.shareButton).from({ alpha: 0 }, 200, Phaser.Easing.Cubic.Out, true, delay)
		this.game.add.tween(this.shareButton).from({ y: '+40' }, 750, Phaser.Easing.Cubic.Out, true, delay)
		// .onComplete.addOnce(() => {
		// 	this.shareButton.animate(500);
		// });
	}

	private showButtons(initialDelay: number): void {
		this.buttons.forEach((button, index) => {
			let delay: number = initialDelay + index * 100
			this.game.add.tween(button).from({ alpha: 0, y: '+20' }, 300, Phaser.Easing.Cubic.Out, true, delay)
		})

		this.showShopLabel(initialDelay + 500)

		this.game.time.events.add(initialDelay, this.loadLeaderboardRank, this)
	}

	public showShopLabel(delay: number): void {
		if (this.game.boosters.canBuyAnyBooster()) {
			this.shopLabel.show(delay)
		}
	}

	private loadLeaderboardRank() {
		this.rankLabel.loadPlayerRank()
	}

	public shutdown(): void {
		this.circles = null
		this.buttons = null
	}
}
