import { Config } from "../../../../Config"
import { GameFonts, FontWeight } from "../../../../GameFonts"
import { SimpleButton } from "../../../../gui/buttons/SimpleButton"

export class ExitConfirmPopup extends Phaser.Group {
    private backdrop: Phaser.Image
    private window: Phaser.Group
    private windowBack: Phaser.Image
    private title: Phaser.Text
    private subtitle: Phaser.Text
    private noButton: SimpleButton
    public yesButton: SimpleButton
    private buttons: SimpleButton[]

    constructor(_game: Phaser.Game, parent: Phaser.Group) {
        super(_game, parent, 'exit_confirm_screen')

        this.addBackdrop()
        this.addBack()
        this.addTitle()
        this.addSubtitle()
        this.addButtons()

        this.alignSubtitle()
    }

    private addBackdrop(): void {
        this.backdrop = this.game.add.image(0, 0, 'interface', 'white_rect0000', this)
        this.backdrop.tint = 0x1a237e
        this.backdrop.alpha = 0.5
        this.backdrop.inputEnabled = true
    }

    private addBack(): void {
        this.window = this.game.add.group(this, 'popup')

        this.windowBack = this.game.add.image(0, 0, 'interface', 'Modal_Back0000', this.window)
        this.windowBack.anchor.set(0.5, 0.5)
    }

    private addTitle(): void {
        let content = this.game.texts.texts.quit_popup_title
        let style = {
            font: GameFonts.DEFAULT,
            fontWeight: FontWeight.BOLD,
            fontSize: 40,
            fill: '#FF9933',
            align: 'center',
        }

        this.title = this.game.add.text(0, 0, content, style, this.window)
        this.title.anchor.set(0.5, 0.5)
        this.title.centerX = this.windowBack.centerX
        this.title.top = this.windowBack.top + 25
    }

    private addSubtitle(): void {
        let content = this.game.texts.texts.progress_lost_warinig
        let style = {
            font: GameFonts.DEFAULT,
            fontWeight: FontWeight.NORMAL,
            fontSize: 28,
            fill: '#FF9933',
            align: 'center',
        }

        this.subtitle = this.game.add.text(0, 0, content, style, this.window)
        this.subtitle.anchor.set(0.5, 0.5)
        this.subtitle.wordWrap = true
        this.subtitle.wordWrapWidth = this.windowBack.width * 0.85
        this.subtitle.lineSpacing = -8
        this.subtitle.centerX = this.windowBack.centerX
    }

    private addButtons(): void {
        let dx: number = 90 * Config.ASSETS_SCALE
        let y: number = 160 * Config.ASSETS_SCALE

        this.noButton = new SimpleButton(this.game, 0, 0, 'interface', 'Button_No0000', this.window)
        this.noButton.x = this.windowBack.centerX - dx
        this.noButton.top = this.windowBack.top + y
        this.noButton.callback.add(this.onNoButtonClick, this)

        this.yesButton = new SimpleButton(this.game, 0, 0, 'interface', 'Button_Yes0000', this.window)
        this.yesButton.x = this.windowBack.centerX + dx
        this.yesButton.top = this.windowBack.top + y
        // this.yesButton.callback.addOnce(this.onYesButtonClick, this);

        this.buttons = [this.noButton, this.yesButton]
    }

    private alignButtons() {
        let top: number = this.subtitle.bottom
        let bottom: number = this.windowBack.bottom
        let height: number = bottom - top

        this.buttons.forEach((button, index) => {
            button.y = top + height / 2
        })
    }

    private alignSubtitle() {
        let top = this.title.bottom - 12
        let bottom = this.yesButton.top
        let height = bottom - top

        this.subtitle.y = top + height / 2
    }

    private onNoButtonClick() {
        this.disableButtons()
        this.hide()
    }

    private onYesButtonClick() {
        this.disableButtons()
        this.game.changeState('BoostersShop')
    }

    private enableButtons(): void {
        this.buttons.forEach((button) => {
            button.enabled = true
        })
    }

    private disableButtons(): void {
        this.buttons.forEach((button) => {
            button.enabled = false
        })
    }

    public updateContent(titleContent: string, subtitleContent: string): void {
        this.title.text = titleContent
        this.subtitle.text = subtitleContent
    }

    public show(): void {
        this.visible = true
        this.exists = true

        this.enableButtons()

        this.alpha = 1

        this.game.add.tween(this.backdrop).from({ alpha: 0 }, 150, Phaser.Easing.Cubic.Out, true)

        let delay: number = 0
        this.game.add.tween(this.window).from({ alpha: 0 }, 200, Phaser.Easing.Cubic.Out, true, delay)
        this.game.add.tween(this.window.scale).from({ x: 0.8, y: 0.8 }, 400, Phaser.Easing.Back.Out, true, delay)

        /*[this.title, this.subtitle, ...this.buttons].forEach((child, index) => {
            let delay_2:number = 100 + index * 50;
            this.game.add.tween(child).from({alpha: 0}, 100, Phaser.Easing.Cubic.Out, true, delay_2);
            this.game.add.tween(child.scale).from({x: 0.8, y: 0.8}, 400, Phaser.Easing.Back.Out, true, delay_2);
        });*/
    }

    public hide(): void {
        this.yesButton.callback.removeAll()

        this.game.add
            .tween(this)
            .to({ alpha: 0 }, 150, Phaser.Easing.Cubic.Out, true)
            .onComplete.addOnce(() => {
                this.visible = false
                this.exists = false
            })
    }

    public resize(): void {
        this.resizeBackdrop()
        this.alignWindow()
    }

    private resizeBackdrop() {
        this.backdrop.width = Config.GAME_WIDTH * 1.2
        this.backdrop.height = Config.GAME_HEIGHT * 1.2
        this.backdrop.centerX = Config.HALF_GAME_WIDTH
        this.backdrop.centerY = Config.HALF_GAME_HEIGHT
    }

    private alignWindow() {
        this.window.centerX = Config.HALF_GAME_WIDTH
        this.window.centerY = Config.HALF_GAME_HEIGHT
    }

    public destroy(): void {
        super.destroy(true, false)
    }
}
