export const DEFAULT_STATE = {
	/**
	 * Selected UI language code (e.g. `en`, `ru`).
	 * @default ''
	 */
	language: '',

	/**
	 * Whether sound effects are muted via settings or focus handling.
	 * @default false
	 */
	sound_muted: false,

	/**
	 * Whether background music is muted via settings.
	 * @default false
	 */
	music_muted: false,

	/**
	 * Serialized in-progress level state for resuming gameplay.
	 * @default ''
	 */
	saved_game_state: '',

	/**
	 * Tutorial completion flag used to skip onboarding next time.
	 * @default false
	 */
	Tutorial: false,

	/**
	 * Whether the Game Over tutorial overlay was already completed.
	 * @default false
	 */
	game_over_tutorial_complete: false,

	/**
	 * Soft currency balance saved between sessions.
	 * @default 0
	 */
	Coins: 0,

	/**
	 * Highest item tier achieved across all runs (used for UI gating).
	 * @default 2
	 */
	best_item: 2,

	/**
	 * Highest score already submitted to leaderboards to avoid duplicates.
	 * @default 0
	 */
	best_submitted_item: 0,

	/**
	 * Whether the headstart rewarded-ad popup is disabled by the player.
	 * @default false
	 */
	headstart_popup_disabled: false,

	/**
	 * Whether the double-coins popup is disabled by the player.
	 * @default false
	 */
	coinsx2_popup_disabled: false,

	/**
	 * Total number of shuffle actions performed (achievement/stat tracking).
	 * @default 0
	 */
	shuffle_times: 0,

	/**
	 * Number of finished games (incremented on Game Over).
	 * @default 0
	 */
	games_played: 0,

	/**
	 * Flag that the free-coins rewarded ad was claimed/disabled in the shop.
	 * @default false
	 */
	free_coins_enabled: false,

	/**
	 * Stored count of Magnet boosters available to the player.
	 * @default 0
	 */
	Magnet: 0,

	/**
	 * Stored count of Remove boosters available to the player.
	 * @default 0
	 */
	Remove: 0,

	/**
	 * Stored count of Sort boosters available to the player.
	 * @default 0
	 */
	Sort: 0,

	/**
	 * Stored count of Undo boosters available to the player.
	 * @default 0
	 */
	Undo: 0,

	/**
	 * Stored count of Upgrade boosters available to the player.
	 * @default 0
	 */
	Upgrade: 0,

	/**
	 * Server timestamp (ms) of the last successful save for conflict resolution.
	 * @default 0
	 */
	savedAt: 0,

	/**
	 * Server timestamp (readable date) of the last successful save for conflict resolution.
	 */
	savedAtStr: '',
} /* satisfies { [key in GameStoreKey | BoosterType]: any } */

export type GameState = typeof DEFAULT_STATE

export type GameStateKey = keyof GameState

export type GameStateNumberKey = {
	[key in GameStateKey]: GameState[key] extends number ? key : never
}[GameStateKey]

export type GameStateBooleanKey = {
	[key in GameStateKey]: GameState[key] extends boolean ? key : never
}[GameStateKey]

export type GameStateStringKey = {
	[key in GameStateKey]: GameState[key] extends string ? key : never
}[GameStateKey]

export type GameStateValue<TKey extends GameStateKey> = GameState[TKey]
