import { Config } from '../../Config'
import { SimpleButton } from './../../gui/buttons/SimpleButton'
import { ToggleButton, ToggleButtonState } from './../../gui/buttons/ToggleButton'
import { GameBackground } from './../../objects/GameBackground'
import { CreditsScreen } from './credits/CreditsScreen'
import { GameLogo } from './GameLogo'
import { MainMenuCircles } from './MainMenuCircles'
import { SettingsScreen } from './settings/SettingsScreen'

export class MainMenu extends Phaser.State {
	private skipStartAnimation: boolean
	private background: GameBackground
	private gameLogo: GameLogo
	private playButton: SimpleButton
	private soundButton: ToggleButton
	private creditsButton: SimpleButton
	private settingsButton: SimpleButton
	private buttons: SimpleButton[]
	private buttonsGroup: Phaser.Group
	private circles: MainMenuCircles
	private settingsScreen: SettingsScreen
	private creditsScreen: CreditsScreen

	public init(skipStartAnimation: boolean = false): void {
		this.skipStartAnimation = skipStartAnimation
	}

	public create(): void {
		this.addBackground()
		this.addTitle()
		this.addButtons()
		this.addCircles()
		this.addSettingsScreen()
		this.addCreditsScreen()

		this.addKeyboardCallbacks()

		this.resize()

		if (this.skipStartAnimation === false) {
			this.show()
		}

		this.game.texts.onLanguageChange.add(this.onLanguageChange, this)
	}

	private onLanguageChange(): void {
		this.settingsScreen.window.content.onLanguageChange()
		this.creditsScreen.window.content.onLanguageChange()
		this.circles.onLanguageChange()
	}

	private addBackground() {
		this.background = new GameBackground(this.game, 'main_menu', 'white_rect_large0000')
	}

	private addTitle(): void {
		this.gameLogo = new GameLogo(this.game, this.world)
	}

	private addButtons(): void {
		this.playButton = new SimpleButton(this.game, 0, 0, 'main_menu', 'Button_Play_20000')
		this.playButton.setCallbackOn('pointerup')
		this.playButton.callback.addOnce(this.onPlayButtonClick, this)

		let playButtonBottomMargin: number = 21

		this.soundButton = new ToggleButton(this.game, 0, 0, 'main_menu', 'Button_Sound_On0000', 'Button_Sound_Off0000')
		this.soundButton.buttonState = this.game.sound.mute ? ToggleButtonState.STATE_2 : ToggleButtonState.STATE_1
		this.soundButton.top = this.playButton.bottom + playButtonBottomMargin
		this.soundButton.left = this.playButton.left
		this.soundButton.callback.add(this.onSoundButtonClick, this)

		this.creditsButton = new SimpleButton(this.game, 0, 0, 'main_menu', 'Button_Credits0000')
		this.creditsButton.top = this.playButton.bottom + playButtonBottomMargin
		this.creditsButton.centerX = this.playButton.centerX
		this.creditsButton.callback.add(this.onCreditsButtonClick, this)

		this.settingsButton = new SimpleButton(this.game, 0, 0, 'main_menu', 'Button_Settings0000')
		this.settingsButton.right = this.playButton.right
		this.settingsButton.top = this.playButton.bottom + playButtonBottomMargin
		this.settingsButton.callback.add(this.onSettingsButtonClick, this)

		this.buttons = [this.playButton, this.soundButton, this.creditsButton, this.settingsButton]
		this.buttonsGroup = this.game.add.group(this.world, 'buttons')
		this.buttonsGroup.addMultiple(this.buttons, true)
	}

	private onPlayButtonClick(): void {
		if (this.game.boosters.canBuyAnyBooster()) {
			this.game.changeState('BoostersShop')
		} else {
			this.game.ads.showInterstitial('MainMenu:PlayButton').finally(() => {
				this.game.changeState('Level')
			})
		}
	}

	private onSoundButtonClick(): void {
		this.game.audio.soundMute = !this.game.audio.soundMute
	}

	private onCreditsButtonClick(): void {
		this.creditsScreen.show()
	}

	private onSettingsButtonClick(): void {
		this.settingsScreen.show()
	}

	private addCircles(): void {
		this.circles = new MainMenuCircles(this.game, this.world)
	}

	private addSettingsScreen(): void {
		this.settingsScreen = new SettingsScreen(this.game, this.world)
		this.settingsScreen.kill()
	}

	private addCreditsScreen() {
		this.creditsScreen = new CreditsScreen(this.game, this.world)
		this.creditsScreen.kill()
	}

	private addKeyboardCallbacks() {
		this.game.input.keyboard.addKey(Phaser.Keyboard.ESC).onDown.add(this.onEscPressed, this)
		this.game.input.keyboard.addKey(Phaser.Keyboard.ENTER).onDown.add(this.onPlayButtonClick, this)

		const isAdmin = this.game.gamePush?.playerRole === 'admin' || window.game.config.env === 'local'
		if (isAdmin) {
			this.game.input.keyboard.addKey(Phaser.Keyboard.T).onDown.add(this.showTestToast, this)
			this.game.input.keyboard.addKey(Phaser.Keyboard.SPACEBAR).onDown.add(this.onPlayButtonClick, this)
			this.game.input.keyboard.addKey(Phaser.Keyboard.R).onDown.add(this.restart, this)
			this.game.input.keyboard.addKey(Phaser.Keyboard.X).onDown.add(this.sendSentryEvent, this)

		}
	}

	private showTestToast() {
		this.game.toast.show("Some multiline unbelievibly long content. That's just insane, folks!", 0, 4000)
	}

	private sendSentryEvent(key: Phaser.Key) {
		if (key.shiftKey) {
			const event = this.game.sentry.sendMessage(`Test Message ${Date.now()}`)
			this.game.sentry.logger.info(`message sent`, event)
		} else {
			throw new Error('Test error')
		}
	}

	private onEscPressed(): void {
		if (this.settingsScreen.visible) {
			this.settingsScreen.hide()
			return
		}

		if (this.creditsScreen.visible) {
			this.creditsScreen.hide()
			return
		}
	}

	private restart() {
		this.game.changeState('MainMenu')
	}

	public resize(): void {
		this.background.resize()

		this.buttonsGroup.centerX = Config.HALF_GAME_WIDTH
		this.buttonsGroup.centerY = Config.HALF_GAME_HEIGHT

		this.alignLogo()

		this.alignCircles()

		this.settingsScreen.resize()
		this.creditsScreen.resize()
	}

	private alignLogo() {
		let top: number = 0
		let bottom: number = this.buttonsGroup.top
		let height: number = bottom - top

		this.gameLogo.centerX = Config.HALF_GAME_WIDTH
		this.gameLogo.centerY = top + height / 2
		this.gameLogo.originalY = this.gameLogo.y
	}

	private alignCircles() {
		let top: number = this.buttonsGroup.bottom
		let bottom: number = Config.GAME_HEIGHT
		let height: number = bottom - top

		this.circles.centerX = Config.HALF_GAME_WIDTH
		this.circles.centerY = top + height / 2 - 20
	}

	private show(): void {
		this.gameLogo.show(200)
		this.showButtons(500)
		this.circles.show(600)

		this.game.time.events.add(2200, this.animatePlayButton, this)
	}

	private showButtons(initialDelay: number): void {
		this.buttons.forEach((button, index) => {
			let delay: number = initialDelay + index * 100
			this.game.add.tween(button.scale).from({ x: 0.66, y: 0.66 }, 400, Phaser.Easing.Back.Out, true, delay)
			this.game.add.tween(button).from({ alpha: 0 }, 200, Phaser.Easing.Quadratic.Out, true, delay)
		})
	}

	private animatePlayButton(): void {
		let targetScale = 1.07
		this.game.add
			.tween(this.playButton.scale)
			.to(
				{
					x: targetScale,
					y: targetScale,
				},
				300,
				Phaser.Easing.Sinusoidal.InOut,
				true,
				0,
				2,
				true
			)
			.onComplete.addOnce(() => {
				this.game.time.events.add(3000, this.animatePlayButton, this)
			})
	}

	public shutdown(): void {
		this.buttons = null
		this.game.texts.onLanguageChange.remove(this.onLanguageChange, this)
	}
}
