export class ShopLabel extends Phaser.Image {
    private delayedCall: Phaser.TimerEvent

    constructor(_game: Phaser.Game) {
        super(_game, 0, 0, 'game_over', 'Buy_Label0000')

        this.anchor.set(0.5, 0.5)
        this.visible = false
    }

    public show(delay: number = 0): void {
        this.visible = true

        this.alpha = 1
        this.scale.set(1)
        this.game.add.tween(this).from({ alpha: 0 }, 200, Phaser.Easing.Cubic.Out, true, delay)
        this.game.add
            .tween(this.scale)
            .from({ x: 0.8, y: 0.8 }, 400, Phaser.Easing.Back.Out, true, delay)
            .onComplete.addOnce(() => {
                this.startShake()
            })
    }

    private startShake(): void {
        let deltaAngle: number = 6

        this.game.add
            .tween(this)
            .to({ angle: -deltaAngle }, 50, Phaser.Easing.Linear.None, true)
            .onComplete.addOnce(() => {
                this.doShake()
            })
    }

    private doShake(): void {
        this.game.add
            .tween(this.scale)
            .to({ x: 1.33, y: 1.33 }, 250, Phaser.Easing.Sinusoidal.InOut, true, 0, 1, true)

        this.game.add
            .tween(this)
            .to({ angle: Math.abs(this.angle) }, 100, Phaser.Easing.Sinusoidal.InOut, true, 0, 3, true)
            .onComplete.addOnce(() => {
                this.onShakeComplete()
            })
    }

    private onShakeComplete(): void {
        this.game.add.tween(this).to({ angle: 0 }, 50, Phaser.Easing.Linear.None, true)

        this.delayedCall = this.game.time.events.add(2000, this.startShake, this)
    }

    public destroy(): void {
        this.game.tweens.removeFrom(this)
        this.game.tweens.removeFrom(this.scale)

        if (this.delayedCall) {
            this.game.time.events.remove(this.delayedCall)
        }

        super.destroy(true)
    }
}
