import { Item } from "./Item"

export class ItemRippleFX extends Phaser.Group {
    private circles: Phaser.Image[]
    private item: Item

    constructor(_game: Phaser.Game, parent: Phaser.Group) {
        super(_game, parent)

        this.addCirles()

        this.visible = false
        this.exists = false
    }

    private addCirles(): void {
        this.circles = this.createMultiple(3, 'interface', 'Item_White0000')
        this.circles.forEach((circle) => {
            circle.anchor.set(0.5, 0.5)
        })
    }

    public show(item: Item): void {
        this.item = item

        this.visible = true
        this.exists = true

        let color: number = Item.getBackColor(item.itemType)
        this.circles.forEach((circle, index) => {
            this.game.tweens.removeFrom(circle)
            this.game.tweens.removeFrom(circle.scale)

            let delay: number = 100 + index * 200
            let scale: number = 1.6
            let duration: number = 660

            circle.tint = color

            this.game.add
                .tween(circle.scale)
                .to({ x: scale, y: scale }, duration, Phaser.Easing.Linear.None, true, delay)
            this.game.add
                .tween(circle)
                .to({ alpha: 0 }, duration, Phaser.Easing.Linear.None, true, delay)
                .onComplete.addOnce(this.onTweenComplete, this, 0, index)
        })
    }

    private onTweenComplete(index: number): void {
        if (index === this.circles.length - 1) {
            this.visible = false
        }
    }

    public update(): void {
        if (this.visible && this.item) {
            this.x = this.item.x
            this.y = this.item.y
        }
    }

    public destroy(): void {
        super.destroy(true, false)

        this.circles = null
        this.item = null
    }
}
