import type { ErrorData } from '@vkontakte/vk-bridge'
import { match } from 'ts-pattern'
import { getErrorLog } from '../../robowhale/utils/error/utils'

/**
 * Gets a readable error log from a VK Bridge error, which can be an Error instance,
 * a structured VK error object, or other types.
 *
 * @param error The error to stringify.
 * @returns A formatted error message.
 */
export function getVkBridgeSendErrorLog(error: unknown): string {
	if (error instanceof Error) {
		return getErrorLog(error)
	}

	if (isVkBridgeErrorData(error)) {
		return stringifyVkBridgeErrorData(error)
	}

	if (typeof error === 'string') {
		return error
	}

	if (typeof error === 'number' || typeof error === 'boolean' || typeof error === 'bigint') {
		return String(error)
	}

	if (error && typeof error === 'object' && 'message' in error && typeof error.message === 'string') {
		return error.message
	}

	return 'unknown'
}

/**
 * Checks if the given value matches the VK Bridge ErrorData structure.
 *
 * @param value The value to check.
 */
export function isVkBridgeErrorData(value: unknown): value is ErrorData {
	if (!value || typeof value !== 'object') {
		return false
	}

	if (!('error_type' in value) || !('error_data' in value)) {
		return false
	}

	const errorData = value as ErrorData
	return typeof errorData.error_type === 'string'
}

/**
 * Formats a VK Bridge ErrorData object into a readable string.
 *
 * @param error The VK Bridge error data.
 */
export function stringifyVkBridgeErrorData(error: ErrorData): string {
	const requestIdPart = error.request_id !== undefined ? ` request_id=${String(error.request_id)}` : ''

	const errorLog = match(error)
		.with({ error_type: 'client_error' }, ({ error_data: data }) => {
			const codePart = typeof data.error_code === 'number' ? ` code=${data.error_code}` : ''
			const reasonPart = typeof data.error_reason === 'string' ? ` reason=${data.error_reason}` : ''
			const descriptionPart = typeof data.error_description === 'string' ? ` description=${data.error_description}` : ''
			return `client_error${codePart}${reasonPart}${descriptionPart}`
		})
		.with({ error_type: 'api_error' }, ({ error_data: data }) => {
			const codePart = typeof data.error_code === 'number' ? ` code=${data.error_code}` : ''
			const messagePart = typeof data.error_msg === 'string' ? ` message=${data.error_msg}` : ''
			const paramsPart = Array.isArray(data.request_params) ? ` request_params=${data.request_params.map(String).join(',')}` : ''
			return `api_error${codePart}${messagePart}${paramsPart}`
		})
		.with({ error_type: 'auth_error' }, ({ error_data: data }) => {
			const codePart = typeof data.error_code === 'number' ? ` code=${data.error_code}` : ''
			const reasonPart = typeof data.error_reason === 'string' ? ` reason=${data.error_reason}` : ''
			const descriptionPart = Array.isArray(data.error_description) ? ` description=${data.error_description.map(String).join(',')}` : ''
			return `auth_error${codePart}${reasonPart}${descriptionPart}`
		})
		.exhaustive()

	return `vk_bridge ${errorLog}${requestIdPart}`.trim()
}
