import type { ReceiveData, ShowBannerAdRequest, VKBridge } from '@vkontakte/vk-bridge'
import {
	BannerAdAlign,
	BannerAdHeightType,
	BannerAdLayoutType,
	BannerAdLocation,
	BannerAdOrientation,
	EAdsFormats,
} from '@vkontakte/vk-bridge'
import { err, Result as NeverThrowResult, ok } from 'neverthrow'
import { until } from 'until-async'
import { Result } from '../../robowhale/Result'
import { Platform } from '../../startup/Platform'
import { IVisibilityProvider } from '../../visibility/IVisibilityProvider'
import { VkVisibilityProvider } from '../../visibility/VkVisibilityProvider'
import { BasePlatform, BasePlatformOptions } from '../BasePlatform'
import { getVkBridgeSendErrorLog } from './VkBridgeErrorUtils'

/**
 * @link https://dev.vk.com/ru/games/bridge
 */
export class VkPlatform extends BasePlatform {
	public readonly type: Platform = 'vk'

	private _bridge: VKBridge | undefined
	private _language: string | undefined
	private _userId: number | undefined
	private _clientPlatform: string | undefined
	private _isVkMobileClient: boolean = false
	private _isBannerAdSupported: boolean = false
	private _bannerShowDeferred: Promise<NeverThrowResult<void, string>> | undefined

	constructor(options: BasePlatformOptions) {
		super(options)
	}

	async init(): Promise<void> {
		const preloader = window.preloader.platform

		if (!preloader || preloader.type !== this.type) {
			throw new Error('Platform preloader is not initialized')
		}

		this._bridge = (await preloader.loadAndInit()) as VKBridge

		await Promise.all([this.setUserInfo(), this.initVkMobileDetection(), this.detectBannerSupport()])

		this._ready = true

		this._logger.info('ready')

		this.setSentryData()
	}

	private async detectBannerSupport(): Promise<void> {
		const bridge = this._bridge
		if (!bridge) {
			return
		}

		const [error, isSupported] = await until(() => bridge.supportsAsync('VKWebAppShowBannerAd'))

		if (error) {
			this._logger.warn(`failed to check banner ad support (${getVkBridgeSendErrorLog(error)})`)
			this._isBannerAdSupported = false
			return
		}

		this._isBannerAdSupported = isSupported
	}

	private async setUserInfo() {
		const bridge = this._bridge
		if (!bridge) {
			return
		}

		const [userInfoError, userInfoData] = await until(() => bridge.send('VKWebAppGetUserInfo'))
		if (userInfoError) {
			this._logger.warn(`failed to fetch VK user info (${getVkBridgeSendErrorLog(userInfoError)})`)
		} else {
			this._userId = userInfoData.id
		}

		const [launchParamsError, launchParamsData] = await until(() => bridge.send('VKWebAppGetLaunchParams'))
		if (launchParamsError) {
			this._logger.warn(`failed to fetch VK launch params (${getVkBridgeSendErrorLog(launchParamsError)})`)
		} else {
			this._language = launchParamsData.vk_language
		}
	}

	private async initVkMobileDetection(): Promise<void> {
		const bridge = this._bridge
		if (!bridge) {
			return
		}

		const [error, data] = await until(() => bridge.send('VKWebAppGetClientVersion'))

		if (error) {
			this._logger.warn(`failed to fetch VK client version (${getVkBridgeSendErrorLog(error)})`)
			return
		}

		this._clientPlatform = data.platform
		this._isVkMobileClient = data.platform === 'android' || data.platform === 'ios'
	}

	private setSentryData(): void {
		if (!this._bridge) {
			return
		}

		if (this._userId) {
			this._sentry.setUser({ id: String(this._userId) })
		}

		this._sentry.setTags({
			'vk.language': this._language,
			'vk.platform': this._clientPlatform,
			'vk.is_mobile_client': this._isVkMobileClient,
		})
	}

	async getLanguage(): Promise<string | undefined> {
		return this._language
	}

	async gameReady(): Promise<void> {
		return Promise.resolve()
	}

	async loadRewardedAd(): Promise<NeverThrowResult<void, string>> {
		return this.checkNativeAds('reward')
	}

	async showRewardedAd(): Promise<Result> {
		return this.showNativeAd('reward')
	}

	async showInterstitialAd(): Promise<Result> {
		return this.showNativeAd('interstitial')
	}

	public isBannerAdSupported(): boolean {
		return this._isBannerAdSupported
	}

	/**
	 * Shows banner advertisement.
	 *
	 * @link https://dev.vk.com/ru/bridge/VKWebAppShowBannerAd
	 * @returns Promise with NeverThrowResult: ok on success, err with reason otherwise.
	 */
	public async showBannerAd(): Promise<NeverThrowResult<void, string>> {
		if (!this._bridge) {
			return err('VK Bridge is not initialized')
		}

		if (!this._isBannerAdSupported) {
			return err('banner ad is not supported')
		}

		if (this._bannerShowDeferred) {
			return this._bannerShowDeferred
		}

		this._bannerShowDeferred = this.performShowBannerAd()
		return this._bannerShowDeferred
	}

	private async performShowBannerAd(): Promise<NeverThrowResult<void, string>> {
		const bridge = this._bridge
		if (!bridge) {
			this._bannerShowDeferred = undefined
			return err('VK Bridge is not initialized')
		}

		const isVisible = await this.isBannerAdVisible()
		if (isVisible) {
			return ok(undefined)
		}

		const options: ShowBannerAdRequest = this._isVkMobileClient
			? {
					banner_location: BannerAdLocation.BOTTOM,
					layout_type: BannerAdLayoutType.RESIZE,
					height_type: BannerAdHeightType.REGULAR,
					can_close: false,
				}
			: {
					banner_location: BannerAdLocation.BOTTOM,
					layout_type: BannerAdLayoutType.RESIZE,
					banner_align: BannerAdAlign.RIGHT,
					orientation: BannerAdOrientation.VERTICAL,
					can_close: false,
				}

		this._logger.info(`showing banner ad`, options)

		const [showError, showData] = await until(() => bridge.send('VKWebAppShowBannerAd', options))

		if (showError) {
			const errorLog = getVkBridgeSendErrorLog(showError)
			this._logger.warn(`banner ad show failed (${errorLog})`)
			this._bannerShowDeferred = undefined
			return err(errorLog)
		}

		if (showData?.result === true) {
			return ok(undefined)
		}

		const reason = 'unknown'
		this._logger.warn(`banner ad show failed (${reason})`)
		this._bannerShowDeferred = undefined
		return err(reason)
	}

	/**
	 * Checks if banner advertisement is currently visible in the game.
	 *
	 * @link https://dev.vk.com/ru/bridge/VKWebAppCheckBannerAd
	 * @returns Promise with boolean: true if banner is visible, false otherwise.
	 */
	public async isBannerAdVisible(): Promise<boolean> {
		const bridge = this._bridge
		if (!bridge) {
			return false
		}

		const [error, data] = await until(() => bridge.send('VKWebAppCheckBannerAd'))

		if (error) {
			this._logger.warn(`banner ad check failed (${getVkBridgeSendErrorLog(error)})`)
			return false
		}

		return data?.result === true
	}

	/**
	 * Hides banner advertisement.
	 *
	 * @link https://dev.vk.com/ru/bridge/VKWebAppHideBannerAd
	 * @returns Promise with NeverThrowResult: ok on success, err with reason otherwise.
	 */
	public async hideBannerAd(): Promise<NeverThrowResult<void, string>> {
		const bridge = this._bridge
		if (!bridge) {
			return err('VK Bridge is not initialized')
		}

		const [error, data] = await until(() => bridge.send('VKWebAppHideBannerAd'))

		if (error) {
			const errorLog = getVkBridgeSendErrorLog(error)
			this._logger.warn(`banner ad hide failed (${errorLog})`)
			return err(errorLog)
		}

		if (data?.result === true) {
			return ok(undefined)
		}

		return err('unknown')
	}

	/** Returns the initialized VK Bridge instance, if available. */
	public get bridge(): VKBridge | undefined {
		return this._bridge
	}

	public get userId(): number | undefined {
		return this._userId
	}

	public override getVisibilityProvider(): IVisibilityProvider | undefined {
		if (this._bridge && this._isVkMobileClient) {
			return new VkVisibilityProvider({ bridge: this._bridge })
		}

		return undefined
	}

	/**
	 * Shows a native advertisement.
	 * Native ads are available only in the VK mobile app on iOS and Android.
	 *
	 * @link https://dev.vk.com/ru/bridge/VKWebAppShowNativeAds
	 * @param format - Advertisement format: 'reward' for rewarded video, 'interstitial' for interstitial.
	 * @returns Promise with Result: Ok on success, Error with reason on failure.
	 */
	private async showNativeAd(format: 'reward' | 'interstitial'): Promise<Result> {
		const bridge = this._bridge
		if (!bridge) {
			return Result.Error('VK Bridge is not initialized')
		}

		const adFormat = format === 'reward' ? EAdsFormats.REWARD : EAdsFormats.INTERSTITIAL
		const [error, data] = await until(() => bridge.send('VKWebAppShowNativeAds', { ad_format: adFormat }))

		if (error) {
			const errorLog = getVkBridgeSendErrorLog(error)
			this._logger.warn(`native ad show failed (${errorLog})`)
			return Result.Error(errorLog)
		}

		if (data?.result === true) {
			return Result.Ok()
		}

		const reason = this.stringifyNativeAdsError(data)
		this._logger.warn(`native ad show failed (${reason})`)
		return Result.Error(reason)
	}

	/**
	 * Checks if native advertisement materials are available for the user.
	 * It is recommended to call this before attempting to show an ad.
	 *
	 * @link https://dev.vk.com/ru/bridge/VKWebAppCheckNativeAds
	 * @param format - Advertisement format: 'reward' for rewarded video, 'interstitial' for interstitial.
	 * @returns Promise with NeverThrowResult: ok if ads are available, err with reason otherwise.
	 */
	public async checkNativeAds(format: 'reward' | 'interstitial'): Promise<NeverThrowResult<void, string>> {
		const bridge = this._bridge
		if (!bridge) {
			return err('VK Bridge is not initialized')
		}

		const adFormat = format === 'reward' ? EAdsFormats.REWARD : EAdsFormats.INTERSTITIAL
		const [error, data] = await until(() => bridge.send('VKWebAppCheckNativeAds', { ad_format: adFormat }))

		if (error) {
			const errorLog = getVkBridgeSendErrorLog(error)
			this._logger.warn(`native ad check failed (${errorLog})`)
			return err(errorLog)
		}

		if (data?.result === true) {
			return ok(undefined)
		}

		const reason = this.stringifyNativeAdsError(data)
		this._logger.warn(`native ad check failed (${reason})`)
		return err(reason)
	}

	private stringifyNativeAdsError(
		response: ReceiveData<'VKWebAppShowNativeAds'> | ReceiveData<'VKWebAppCheckNativeAds'> | undefined
	): string {
		if (!response) {
			return 'unknown'
		}

		// Handle error responses - check if response has error fields
		if (
			'error_data' in response &&
			response.error_data &&
			typeof response.error_data === 'object' &&
			'error_reason' in response.error_data
		) {
			return String(response.error_data.error_reason)
		}

		if ('error_type' in response && response.error_type) {
			return String(response.error_type)
		}

		if ('reason' in response && response.reason) {
			return String(response.reason)
		}

		return 'unknown'
	}

	public isFullscreenSupported(): boolean {
		return false
	}

	public isFullscreen(): boolean {
		return false
	}

	public async requestFullscreen(): Promise<void> {
		return Promise.resolve()
	}

	public async exitFullscreen(): Promise<void> {
		return Promise.resolve()
	}
}
