import { Config } from '../../../Config'
import { GameFonts } from '../../../GameFonts'
import { Cell } from '../grid/Cell'

export class Item extends Phaser.Group {
	public static RADIUS: number = 55 * Config.ASSETS_SCALE
	public static RADIUS_SQUARED: number = Item.RADIUS * Item.RADIUS
	public static CONTACT_RADIUS: number = 190 * Config.ASSETS_SCALE
	public static CONTACT_RADIUS_SQUARED: number = Item.CONTACT_RADIUS * Item.CONTACT_RADIUS

	public static BACK_COLORS: number[] = [
		0xf56990, 0x4fc3f7, 0x9ad546, 0xa698c9, 0x80c8bd, 0xec535a, 0xd98c4d, 0xdfb600, 0x66bb6a,
	]

	public static TEXT_COLORS: number[] = [
		0xb04b67, 0x398bb0, 0x6e9832, 0x786e91, 0x5c8f87, 0xa9393e, 0x9c6538, 0x9c8000, 0x4a874d,
	]

	public onCollectComplete: Phaser.Signal
	public onRemoveBoosterComplete: Phaser.Signal
	private _itemType: number = 0
	private back: Phaser.Image
	private text: Phaser.BitmapText
	private white: Phaser.Image
	private border: Phaser.Image
	private _title: string
	public dropCell: Cell = null
	public cell: Cell
	public z: number = 0
	public wiggleTween: Phaser.Tween
	public floatTween: Phaser.Tween
	public alignTween: Phaser.Tween

	constructor(_game: Phaser.Game, parent?: Phaser.Group) {
		super(_game, parent, 'item')

		this.onCollectComplete = new Phaser.Signal()
		this.onRemoveBoosterComplete = new Phaser.Signal()

		this.addBack()
		this.addTextfield()
		this.addWhite()
		this.addBorder()

		this.visible = false
		this.exists = false
	}

	private addBack(): void {
		this.back = this.game.add.image(0, 0, 'interface', 'Item_White0000', this)
		this.back.anchor.set(0.5, 0.5)
	}

	private addTextfield(): void {
		this.text = this.game.add.bitmapText(0, 0, GameFonts.BARIOL_BOLD_BMP, '0', 45, this)
		this.text.anchor.set(0.5, 0.5)
	}

	private addWhite(): void {
		this.white = this.game.add.image(0, 0, 'interface', 'Item_White0000', this)
		this.white.anchor.set(0.5, 0.5)
		this.white.visible = false
	}

	private addBorder(): void {
		this.border = this.game.add.image(0, 0, 'interface', 'Item_Shine0000', this)
		this.border.anchor.set(0.5, 0.5)
		this.border.visible = false
	}

	public setItemType(itemType: number): void {
		this._itemType = itemType

		this._title = 'Item ' + this._itemType.toString()
		this.name = this._title

		this.back.tint = Item.getBackColor(this._itemType)
		this.border.tint = this.back.tint
		this.text.tint = Item.getTextColor(this._itemType)
		this.text.setText(this._itemType)
	}

	public static getBackColor(itemType: number): number {
		let index: number = Phaser.Math.wrap(itemType - 1, 0, Item.BACK_COLORS.length - 1)

		return Item.BACK_COLORS[index]
	}

	public static getTextColor(itemType: number): number {
		let index: number = Phaser.Math.wrap(itemType - 1, 0, Item.TEXT_COLORS.length - 1)

		return Item.TEXT_COLORS[index]
	}

	public onSelected(): void {
		this.showBorderOnSelect()

		this.game.add.tween(this.scale).to(
			{
				x: 1.1,
				y: 1.1,
			},
			200,
			Phaser.Easing.Sinusoidal.InOut,
			true,
			0,
			0,
			true
		)

		let dy: number = 7 * this.game.rnd.sign()
		this.wiggleTween = this.game.add
			.tween(this)
			.to({ y: this.y + dy }, 500, Phaser.Easing.Sinusoidal.InOut, true, 0, -1, true)
	}

	private showBorderOnSelect() {
		this.game.tweens.removeFrom(this.border)
		this.game.tweens.removeFrom(this.border.scale)

		this.border.visible = true
		this.border.alpha = 1
		this.border.scale.set(0.9)
		this.game.add.tween(this.border).to({ alpha: 0 }, 1000, Phaser.Easing.Exponential.Out, true)
		this.game.add
			.tween(this.border.scale)
			.to({ x: 1.2, y: 1.2 }, 1000, Phaser.Easing.Exponential.Out, true)
			.onComplete.addOnce(() => {
				this.border.visible = false
			})
	}

	public onDeselected(): void {
		this.game.tweens.removeFrom(this, false)
		this.game.tweens.removeFrom(this.scale)

		this.stopWiggleTween()
		this.hideBorder()

		this.scale.set(1)
		this.alignToCellCenterSmooth()
	}

	private hideBorder() {
		this.game.tweens.removeFrom(this.border)
		this.game.tweens.removeFrom(this.border.scale)
		this.border.visible = false
	}

	private stopWiggleTween() {
		if (this.wiggleTween) {
			this.game.tweens.remove(this.wiggleTween)
			this.wiggleTween.stop(false)
			this.wiggleTween = null
		}
	}

	public onConverted(scale: number = 1.2): void {
		this.game.tweens.removeFrom(this.white)
		this.game.tweens.removeFrom(this.white.scale)
		this.white.visible = true
		this.white.alpha = 0.7
		this.white.scale.set(1)
		this.game.add
			.tween(this.white)
			.to({ alpha: 0 }, 400, Phaser.Easing.Cubic.In, true)
			.onComplete.addOnce(() => {
				this.white.visible = false
			})

		this.angle = -20
		this.game.add.tween(this).to({ angle: 0 }, 400, Phaser.Easing.Back.Out, true)
		this.game.add
			.tween(this.scale)
			.to({ x: scale, y: scale }, 400, Phaser.Easing.Back.Out, true)
			.onComplete.addOnce(() => {
				this.game.add.tween(this.scale).to({ x: 1, y: 1 }, 300, Phaser.Easing.Back.Out, true)
			})
	}

	public applyRemoveBooster(): void {
		this.border.visible = false
		this.white.visible = false

		this.game.add.tween(this).to({ y: '+13' }, 500, Phaser.Easing.Back.InOut, true)
		this.game.add
			.tween(this.scale)
			.to({ x: 0.77, y: 0.77 }, 160, Phaser.Easing.Cubic.Out, true)
			.onComplete.addOnce(() => {
				this.onRemove2()
			})
	}

	private onRemove2(): void {
		let duration = 330
		this.game.add.tween(this.scale).to({ x: 2, y: 2 }, duration, Phaser.Easing.Cubic.In, true)
		this.game.add
			.tween(this)
			.to({ alpha: 0 }, duration, Phaser.Easing.Cubic.In, true)
			.onComplete.addOnce(() => {
				this.onRemoveBoosterComplete.dispatch(this)
			})
	}

	public showOnGrid(instant: boolean, delay: number): void {
		if (instant === false) {
			this.game.add.tween(this).from({ y: '-40', alpha: 0 }, 300, Phaser.Easing.Cubic.Out, true, delay)
		}
	}

	public collect(destinationX: number, destinationY: number): void {
		this.parent.bringToTop(this)
		this.onDeselected()

		let duration = this.getCollectTweenDuration(this._itemType)
		this.game.add
			.tween(this)
			.to({ x: destinationX, y: destinationY }, 200, Phaser.Easing.Back.In, true)
			.onComplete.addOnce(() => {
				this.onCollectComplete.dispatch(this, this._itemType)
				this.onAddToPool()
			})
	}

	private getCollectTweenDuration(itemType: number) {
		let minDuration = 150
		let duration = Phaser.Math.mapLinear(itemType, 1, 13, 250, minDuration)
		return Math.max(duration, minDuration)
	}

	public linkCell(cell: Cell): void {
		let cellIsFree: boolean = cell.isFree()
		if (cellIsFree === false) {
			console.assert(false, `Cell [${cell.column}, ${cell.row}] is busy! item = ${cell.item.itemType}`)
		}

		if (this.cell) {
			this.clearCell()
		}

		this.cell = cell
		this.cell.item = this
	}

	public clearCell(): void {
		if (this.cell) {
			this.cell.item = null
			this.cell = null
		}
	}

	public removeFromGrid(): void {
		this.clearCell()
		this.onAddToPool()
	}

	public dropToCell(targetCell: Cell, delay: number = 0): Phaser.Tween {
		let tweenX: number = targetCell.column * Cell.WIDTH + Cell.WIDTH * 0.5
		let tweenY: number = targetCell.row * Cell.HEIGHT + Cell.HEIGHT * 0.5
		let distance: number = Phaser.Math.distance(this.x, this.y, tweenX, tweenY)
		let tweenDuration: number = distance * 1.01

		return this.game.add.tween(this).to(
			{
				x: tweenX,
				y: tweenY,
			},
			tweenDuration,
			Phaser.Easing.Quadratic.Out,
			true,
			delay
		)
	}

	public onAddToPool(): void {
		this.visible = false
		this.exists = false

		this.game.tweens.removeFrom([this, this.scale, this.white, this.white.scale, this.border, this.border.scale])
	}

	public onRemoveFromPool(): void {
		this.visible = true
		this.exists = true

		this.alpha = 1
		this.scale.set(1)
		this.rotation = 0

		this.border.visible = false
		this.white.visible = false
	}

	public alignToCellCenterSmooth(duration: number = 150): void {
		if (this.cell) {
			this.stopAlignTween()
			this.game.tweens.removeFrom(this)
			this.alignTween = this.game.add.tween(this).to(
				{
					x: this.cell.centerX,
					y: this.cell.centerY,
				},
				duration,
				Phaser.Easing.Cubic.Out,
				true
			)
		}
	}

	public stopAlignTween(): void {
		if (this.alignTween) {
			this.alignTween.stop()
			this.alignTween = null
		}
	}

	public alignToCellCenterInstant(): void {
		if (this.cell) {
			this.x = this.cell.centerX
			this.y = this.cell.centerY
		}
	}

	public upgrade(newItemType: number = 0, delay: number = 0): void {
		if (newItemType === 0) {
			newItemType = this._itemType + 1
		}

		this._itemType = newItemType

		this.game.add.tween(this).to({ alpha: 0 }, 330, Phaser.Easing.Cubic.Out, true, delay)
		this.game.add
			.tween(this.scale)
			.to({ x: 0.2, y: 0.2 }, 330, Phaser.Easing.Back.In, true, delay)
			.onComplete.addOnce(() => {
				this.upgrade2(newItemType)
			})
	}

	private upgrade2(newType: number): void {
		this.setItemType(newType)

		this.white.visible = true
		this.white.alpha = 0
		this.game.add
			.tween(this.white)
			.to({ alpha: 0.55 }, 200, Phaser.Easing.Cubic.Out, true)
			.onComplete.addOnce(() => {
				this.hideWhite()
			})

		this.game.add.tween(this).to({ alpha: 1 }, 200, Phaser.Easing.Cubic.Out, true)
		this.game.add.tween(this.scale).to({ x: 1, y: 1 }, 440, Phaser.Easing.Back.Out, true)
	}

	private hideWhite(): void {
		this.game.add.tween(this.white).to({ alpha: 0 }, 660, Phaser.Easing.Cubic.Out, true)
	}

	public destroy(): void {
		this.clearCell()

		super.destroy(true, false)
	}

	public get title(): string {
		return this._title
	}

	public get itemType(): number {
		return this._itemType
	}

	public animateAsMagnet(): void {
		this.game.tweens.removeFrom(this.scale)
		this.game.add
			.tween(this.scale)
			.to({ x: 1.25, y: 1.25 }, 300, Phaser.Easing.Cubic.Out, true)
			.onComplete.addOnce(() => {
				this.game.add.tween(this.scale).to(
					{
						x: 1.1,
						y: 1.1,
					},
					300,
					Phaser.Easing.Sinusoidal.InOut,
					true,
					0,
					-1,
					true
				)
			})

		this.white.visible = true
		this.white.alpha = 0
		this.game.add.tween(this.white).to({ alpha: 0.33 }, 233, Phaser.Easing.Sinusoidal.InOut, true, 0, -1, true)
	}

	public stopMagnetAnimation(): void {
		this.game.tweens.removeFrom(this.scale)
		this.game.tweens.removeFrom(this.white)
	}
}
