import { SimpleButton } from '../../../gui/buttons/SimpleButton'
import { ToggleButton, ToggleButtonState } from '../../../gui/buttons/ToggleButton'
import { ShopCoinsLabel } from './ShopCoinsLabel'

export class BoostersShopTopPanel extends Phaser.Group {
	private back: Phaser.Image
	public backButton: SimpleButton
	public soundButton: ToggleButton
	public coinsLabel: ShopCoinsLabel

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'top_panel')

		this.addBack()
		this.addBackButton()
		this.addSoundButton()
		this.addCoinsCounter()
	}

	private addBack(): void {
		this.back = this.game.add.image(0, 0, 'boosters_shop', 'Top_Panel_Back0000', this)
		this.back.inputEnabled = true
	}

	private addBackButton() {
		this.backButton = new SimpleButton(this.game, 0, 0, 'boosters_shop', 'Button_Main_Menu0000', this)
	}

	private addSoundButton() {
		this.soundButton = new ToggleButton(
			this.game,
			0,
			0,
			'interface',
			'Button_Sound_On0000',
			'Button_Sound_Off0000',
			this
		)
		this.soundButton.scale.set(0.7)
		this.soundButton.areTweensEnabled = false
		this.soundButton.buttonState = this.game.sound.mute ? ToggleButtonState.STATE_2 : ToggleButtonState.STATE_1
		this.soundButton.callback.add(this.onSoundButtonClick, this)
	}

	private onSoundButtonClick() {
		this.game.audio.soundMute = !this.game.audio.soundMute
	}

	private addCoinsCounter(): void {
		let coinsNum: number = this.game.save.getCoins()

		this.coinsLabel = new ShopCoinsLabel(this.game, this)
		this.coinsLabel.updateCount(coinsNum, false, false)
	}

	public show(initialDelay: number): void {
		this.game.add.tween(this).from({ y: '-60', alpha: 0 }, 400, Phaser.Easing.Cubic.Out, true, initialDelay)
	}

	public resize(width: number): void {
		this.back.width = width

		this.alignButtons()
		this.alignCoinsLabel()
	}

	private alignButtons() {
		let sideMargin: number = 20
		let buttonsY: number = this.back.centerY + 2

		this.backButton.left = this.back.left + sideMargin
		this.backButton.centerY = buttonsY

		this.soundButton.right = this.back.right - sideMargin - 12
		this.soundButton.centerY = buttonsY
	}

	private alignCoinsLabel() {
		this.coinsLabel.centerX = this.back.centerX
		this.coinsLabel.centerY = this.back.centerY
	}

	public destroy(): void {
		super.destroy(true, false)
	}
}
