import { Logger } from 'tslog'
import { MultiTabError } from './errors/MultiTabError'
import { SafeLocalStorage } from './robowhale/storage/SafeLocalStorage'
import { toReadableDateString } from './robowhale/utils/date/readable-date-string'
import { getErrorLog } from './robowhale/utils/error/utils'

export interface MultiTabTrackerOptions {
	sessionStartedAt: number
	logger: Logger<unknown>
	debugStorage: SafeLocalStorage
}

export class MultiTabTracker {
	private logger: Logger<unknown>
	private debugStorage: SafeLocalStorage
	private sessionId: number

	constructor(options: MultiTabTrackerOptions) {
		this.logger = options.logger
		this.debugStorage = options.debugStorage
		this.sessionId = options.sessionStartedAt
		this.saveSessionId(this.sessionId)
	}

	private saveSessionId(sessionId: number) {
		const result = this.debugStorage.set('sessionId', sessionId)

		if (result.isErr()) {
			this.logger.warn(`error on session id save (${getErrorLog(result.error)})`)
		} else {
			this.logger.info(`session id '${sessionId}' was saved`)
		}

		return result
	}

	/**
	 * Returns current session id from localStorage.
	 * If there is no session id, it returns undefined.
	 */
	public getCurrentSessionId(): number | undefined {
		const result = this.debugStorage.get('sessionId')

		if (result.isErr()) {
			this.logger.warn(`error on session id fetch (${result.error.message})`)
			return undefined
		}

		if (!result.value) {
			return undefined
		}

		const data = result.value
		if (Number.isInteger(data) === false || data <= 0) {
			return undefined
		}

		return data
	}

	/**
	 * @throws MultiTabError
	 */
	public throwIfSessionExpired(): void {
		if (!this.hasSessionExpired()) {
			return
		}

		const currentSid = this.sessionId
		const currentSidStr = toReadableDateString(currentSid, 'ms')
		const newerSid = this.getCurrentSessionId()
		const newerSidStr = toReadableDateString(newerSid, 'ms')
		this.logger.warn(`current session: ${currentSidStr}, newer session: ${newerSidStr}`)
		throw new MultiTabError(currentSid, newerSid)
	}

	/**
	 * Returns true if current session id (that was fetched from localStorage) is different from the saved session id (that was set on game start).
	 * This means that game was run in another tab and this new game instance is a new session that should be continued.
	 * Current session should be stopped.
	 */
	public hasSessionExpired(): boolean {
		const currentSessionId = this.getCurrentSessionId()
		return currentSessionId !== this.sessionId
	}
}
