﻿import { Config } from './Config'
import { ErrorsHandlerService } from './ErrorsHandlerService'
import { GameAnalyticsWrapper } from './GameAnalyticsWrapper'
import { GameAudio } from './GameAudio'
import { GameFonts } from './GameFonts'
import { Toast } from './gui/Toast'
import { LogsManager } from './logs/LogsManager'
import { MultiTabTracker } from './MultiTabTracker'
import { StateTransition } from './plugins/StateTransition'
import { PhaserExtensions } from './robowhale/PhaserExtensions'
import { PIXIExtensions } from './robowhale/PIXIExtensions'
import { Polyfills } from './robowhale/Polyfills'
import { SafeLocalStorage } from './robowhale/storage/SafeLocalStorage'
import { NetUtil } from './robowhale/utils/NetUtil'
import { SentryService } from './sentry/SentryService'
import { BoostersShop } from './states/boostersShop/BoostersShop'
import { Boot } from './states/Boot'
import { GameOver } from './states/gameOver/GameOver'
import { BoostersManager } from './states/level/boosters/BoostersManager'
import { Level } from './states/level/Level'
import { MainMenu } from './states/mainMenu/MainMenu'
import { WebPreloader } from './states/preloader/WebPreloader'
import { GameTexts } from './texts/GameTexts'
import { LanguageUtil } from './texts/LanguageUtil'
import { UrlParams } from './url-params/UrlParams'
import { WebShare } from './WebShare'
import IGameConfig = Phaser.IGameConfig

export class Main extends Phaser.Game {
	public static modernDevice: boolean = false
	public static development: boolean = false

	public stateTransitionPlugin: StateTransition
	public texts: GameTexts
	public fonts: GameFonts
	public audio: GameAudio
	public boosters: BoostersManager
	public isLocalhost: boolean
	public toast: Toast
	public analytics: GameAnalyticsWrapper

	constructor() {
		Polyfills.extend()
		PIXIExtensions.extend()
		PhaserExtensions.extend()

		super({
			width: Config.SOURCE_GAME_WIDTH,
			height: Config.SOURCE_GAME_HEIGHT,
			renderer: Main.getRendererType(),
			transparent: false,
			antialias: true,
			preserveDrawingBuffer: NetUtil.getParamBool('dev'),
			enableDebug: NetUtil.getParamBool('debug'),
			failIfMajorPerformanceCaveat: true,
			disableVisibilityChange: true,
			clearBeforeRender: false,
			mouseWheel: true,
			forceSingleUpdate: false,
			parent: document.getElementById('canvas-container'),
		} as IGameConfig)

		this.detectDevMode()
		this.detectLocalhost()

		this.avif = false
		this.webp = false

		this.gameStartedAt = Date.now()

		const minLogLevel = LogsManager.parseLogLevel(UrlParams.get('minLogLevel'))
		this.logs = new LogsManager({
			minLogLevel: minLogLevel,
		})

		const defaultLanguage = LanguageUtil.convertLanguageCodeToGameLanguage(navigator.language)
		const texts = window.game.texts[defaultLanguage]
		this.errorsHandler = new ErrorsHandlerService({
			logger: this.logs.getOrCreate('errors-handler'),
			game: this,
			texts: texts as unknown as texts.En,
		})

		this.sentry = new SentryService({
			logger: this.logs.getOrCreate('sentry'),
			game: this,
		})
		this.sentry.on('error', (error, hint) => this.errorsHandler.handle(error, hint))

		this.debugStorage = new SafeLocalStorage({
			logger: this.logs.getOrCreate('local-storage'),
		})

		this.multiTabTracker = new MultiTabTracker({
			logger: this.logs.getOrCreate('multi-tab-tracker'),
			debugStorage: this.debugStorage,
			sessionStartedAt: Date.now(),
		})

		this.fonts = new GameFonts(this)

		this.share = new WebShare(this)

		this.addStates()
		this.disableContextMenu()
	}

	private disableContextMenu() {
		const container = document.getElementById('canvas-container')
		if (container) {
			container.addEventListener('contextmenu', (e) => e.preventDefault())
		}
	}

	private static getRendererType(): number {
		let forceCanvas = NetUtil.getParamBool('canvas')
		if (forceCanvas) {
			return Phaser.CANVAS
		}

		return Phaser.AUTO
	}

	private detectDevMode() {
		Main.development = NetUtil.getParamBool('dev')
		if (Main.development) {
			console.info('Developer mode is ON')
		}
	}

	private detectLocalhost() {
		let localhosts: string[] = ['localhost', '192.168']
		this.isLocalhost = localhosts.some((localAddress: string) => {
			return location.hostname.indexOf(localAddress) > -1
		})
	}

	private addStates() {
		this.state.add('Boot', Boot, true)
		this.state.add('Preloader', WebPreloader, false)
		this.state.add('MainMenu', MainMenu, false)
		this.state.add('BoostersShop', BoostersShop, false)
		this.state.add('Level', Level, false)
		this.state.add('GameOver', GameOver, false)

		// this.state.add('Test', TestState, false);
	}

	public changeState(newState: string, arg?: any): void {
		this.stateTransitionPlugin.changeState(newState, arg)
	}

	public getRendererString(): string {
		if (this.renderer) {
			return this.renderer.type === Phaser.WEBGL ? 'webgl' : 'canvas'
		}

		return 'no-renderer'
	}
}
