import { Config } from '../../Config'
import { Main } from '../../Main'
import { CoinsSpreadFX } from '../../objects/CoinsSpreadFX'
import { GameBackground } from '../../objects/GameBackground'
import { Booster } from '../level/boosters/Booster'
import { BoostersShopBottomPanel } from './bottomPanel/BoostersShopBottomPanel'
import { CardBuyButton } from './itemCards/CardBuyButton'
import { ShopCard } from './itemCards/ShopCard'
import { ShopCardConfig } from './itemCards/ShopCardConfig'
import { ScrollbarHandle } from './scroll/ScrollbarHandle'
import { BoostersShopTopPanel } from './topPanel/BoostersShopTopPanel'

export class BoostersShop extends Phaser.State {
	private background: GameBackground
	private topPanel: BoostersShopTopPanel
	public cardsContainer: Phaser.Group
	private cards: ShopCard[]
	public cardsBounds: Phaser.Rectangle
	public scroll: ScrollbarHandle
	private bottomPanel: BoostersShopBottomPanel
	private coinsSpreadFX: CoinsSpreadFX

	public create(): void {
		this.addBackground()
		this.addTopPanel()
		this.addCards()
		this.addScroll()
		this.addBottomPanel()
		this.addCoinsSpreadFx()

		this.addKineticScroll()
		this.addKeyboardCallbacks()

		this.resize()

		this.world.setChildIndex(this.cardsContainer, 1)

		this.show()
	}

	private addBackground() {
		this.background = new GameBackground(this.game, 'boosters_shop', 'Bottom_Panel_Back0000')
		this.background.tint = 0xffffff
		this.background.fixedToCamera = true
	}

	private addTopPanel(): void {
		this.topPanel = new BoostersShopTopPanel(this.game, this.world)
		this.topPanel.backButton.callback.addOnce(this.gotoMainMenu, this)
		this.topPanel.fixedToCamera = true
	}

	private gotoMainMenu(): void {
		this.game.changeState('MainMenu')
	}

	private onShareButtonClick(): void {
		let highscore: number = this.game.save.getValue('best_item')
		let text: string = this.game.texts.texts['share_message']
		// let image: string = this.getShareImage()

		this.game.share.share(text).catch((error) => {})
	}

	private getShareImage(): string {
		let image: Phaser.Image = this.game.make.image(0, 0, 'main_menu', 'Item_130000')
		let dataURL: string = this.game.make.bitmapData(image.width, image.height).drawFull(image).canvas.toDataURL()

		// utils.NetUtil.openWindowWithImage(dataURL);

		return dataURL
	}

	private onShareComplete(): void {
		this.highlightBuyButtons()
	}

	private addCards(): void {
		let cardConfigs: ShopCardConfig[] = this.game.boosters.boosters
			.sort(this.sortBoostersByPrice)
			.map((booster: Booster) => {
				let config: ShopCardConfig = new ShopCardConfig()
				config.booster = booster

				return config
			})

		this.cards = cardConfigs.map((config: ShopCardConfig) => {
			return new ShopCard(this.game, this.world, config)
		})

		this.cardsContainer = this.game.add.group(this.world, 'cards')
		this.cardsContainer.addMultiple(this.cards, true)
		this.cardsContainer.align(1, this.cards.length, this.cards[0].width, 226, Phaser.BOTTOM_CENTER)
		this.cardsContainer.forEach((card) => {
			card.buyButton.callback.add(this.onBuyButtonClick, this)
		}, this)

		this.cardsBounds = new Phaser.Rectangle(0, 0, Config.GAME_WIDTH, Config.GAME_HEIGHT)
	}

	private sortBoostersByPrice(booster_1: Booster, booster_2: Booster): number {
		let delta: number = booster_1.price - booster_2.price
		return Phaser.Math.sign(delta)
	}

	private onBuyButtonClick(buyButton: CardBuyButton): void {
		let card: ShopCard = buyButton.card
		let booster: Booster = card.config.booster
		let coins: number = this.game.save.getCoins()

		if (coins >= booster.price) {
			if (booster.num < booster.maxNum) {
				this.game.sound.play('purchase', 1.0)

				coins -= booster.price
				this.game.save.changeNum('Coins', -booster.price, { origin: 'boosters_shop/purchase' })

				this.topPanel.coinsLabel.updateCount(coins, true, false)
				booster.num++
				card.updateContent()
				card.highlight()

				this.highlightBuyButtons()
			} else {
				let content: string = this.game.texts.texts['booster_maxed_warning']
				this.game.toast.show(content)
			}
		} else {
			this.game.sound.play('muted_error', 0.66)

			this.topPanel.coinsLabel.shake()
		}
	}

	private addScroll(): void {
		this.scroll = new ScrollbarHandle(this.game, 'boosters_shop', 'Scroll0000')
		this.scroll.x = Config.GAME_WIDTH - 20 * Config.ASSETS_SCALE
		this.scroll.fixedToCamera = true
		this.world.add(this.scroll)
	}

	private addBottomPanel(): void {
		this.bottomPanel = new BoostersShopBottomPanel(this.game, this.world)
		this.bottomPanel.freeCoinsButton.visible = false
		this.bottomPanel.playButton.setCallbackOn('pointerup')
		this.bottomPanel.playButton.callback.addOnce(this.onPlayButtonClick, this)
		this.bottomPanel.fixedToCamera = true
	}

	private showRewardedVideo(): void {
		this.game.ads.showRewarded('BoostersShop:1000_coins').then((result) => {
			if (result.success === true) {
				this.giveFreeCoins()
				this.bottomPanel.freeCoinsButton.disable()
				this.game.save.setValue('free_coins_enabled', true, {
					origin: 'boosters_shop/free_coins_disabled',
					destination: 'local-and-remote',
				})
			}
		})
	}

	private giveFreeCoins(): void {
		let coinsNum: number = 1000

		this.game.save.changeNum('Coins', coinsNum, { origin: 'boosters_shop/free_coins' })

		let emitPoint: Phaser.Point = this.getCoinsFxEmitPoint()
		let coinsCollectPoint: Phaser.Point = this.getCoinsFxCollectPoint()
		this.coinsSpreadFX.show(emitPoint, coinsCollectPoint, 1330)
		this.coinsSpreadFX.onCoinsCollectedSignal.addOnce(() => {
			let targetScale = 1.07
			this.game.add.tween(this.topPanel.coinsLabel.scale).to(
				{
					x: targetScale,
					y: targetScale,
				},
				230,
				Phaser.Easing.Sinusoidal.InOut,
				true,
				0,
				0,
				true
			)

			this.updateCoinsLabel()
			this.highlightBuyButtons()
		})
	}

	private getCoinsFxEmitPoint(): Phaser.Point {
		return new Phaser.Point(Config.HALF_GAME_WIDTH, Config.HALF_GAME_HEIGHT)
	}

	private getCoinsFxCollectPoint(): Phaser.Point {
		let coinsLabel = this.topPanel.coinsLabel
		let coinPosition: Phaser.Point = coinsLabel.toGlobal(coinsLabel.coinIcon.position).toPhaser()

		return coinPosition
	}

	private updateCoinsLabel(): void {
		let coins: number = this.game.save.getCoins()

		this.topPanel.coinsLabel.updateCount(coins)
	}

	private onPlayButtonClick(): void {
		this.game.ads.showInterstitial('BoostersShop:PlayButton').finally(() => {
			this.gotoLevel()
		})
	}

	private gotoLevel(): void {
		this.game.changeState('Level')
	}

	private addCoinsSpreadFx(): void {
		this.coinsSpreadFX = new CoinsSpreadFX(this.game, this.world, 30)
		this.coinsSpreadFX.background.loadTexture('boosters_shop', 'white_rect_large0000')
		this.coinsSpreadFX.setCoinTexture('boosters_shop', 'Coins_Label_Coin0000')
		this.coinsSpreadFX.fixedToCamera = true
	}

	private addKineticScroll() {
		this.game.kineticScrolling.configure({
			kineticMovement: true,
			timeConstantScroll: 325, //really mimic iOS
			horizontalScroll: false,
			verticalScroll: true,
			horizontalWheel: false,
			verticalWheel: true,
			deltaWheel: 25,
		})

		this.game.kineticScrolling.start()

		this.game.input.mouseWheel.callback = () => {
			let scrolling = this.game.kineticScrolling
			let delta = this.game.input.mouseWheel.delta * 120 / scrolling.settings.deltaWheel
			scrolling.autoScrollY = false
			scrolling.velocityWheelY += delta
		}
	}

	private addKeyboardCallbacks() {
		this.game.input.keyboard.addKey(Phaser.Keyboard.ESC).onDown.add(this.gotoMainMenu, this)

		const isAdmin = this.game.gamePush?.playerRole === 'admin' || window.game.config.env === 'local'
		if (isAdmin) {
			this.game.input.keyboard.addKey(Phaser.Keyboard.R).onDown.add(this.restart, this)
			this.game.input.keyboard.addKey(Phaser.Keyboard.SPACEBAR).onDown.add(this.gotoLevel, this)
			this.game.input.keyboard.addKey(Phaser.Keyboard.EQUALS).onDown.add(() => {
				this.changeCoins(1000)
			})
			this.game.input.keyboard.addKey(Phaser.Keyboard.UNDERSCORE).onDown.add(() => {
				this.changeCoins(-1000)
			})

			this.game.input.keyboard.addKey(Phaser.Keyboard.OPEN_BRACKET).onDown.add(this.giveFreeCoins, this)
		}
	}

	private restart() {
		this.game.changeState('BoostersShop')
	}

	private changeCoins(delta: number) {
		let coins: number = 0
		
		if (delta > 0) {
			this.game.save.changeNum('Coins', delta, { origin: 'boosters_shop/add_coins' })
			coins = this.game.save.getCoins()
		} else {
			this.game.save.changeNum('Coins', delta, { origin: 'boosters_shop/remove_coins' })
			coins = this.game.save.getCoins()
		}

		this.topPanel.coinsLabel.updateCount(coins, true, false)
		this.highlightBuyButtons()
	}

	public resize(): void {
		this.background.resize()

		this.alignTopPanel()
		this.alignBottomPanel()
		this.alignCards()
		this.alignScroll()

		this.game.world.setBounds(
			0,
			0,
			Config.GAME_WIDTH,
			this.cardsContainer.height + this.bottomPanel.getHeight() + this.topPanel.height + 50
		)

		this.coinsSpreadFX.resize()
	}

	private alignTopPanel() {
		this.topPanel.resize(Config.GAME_WIDTH)
		this.topPanel.centerX = Config.HALF_GAME_WIDTH
		this.topPanel.top = 0
	}

	private alignBottomPanel() {
		this.bottomPanel.resize(Config.GAME_WIDTH)
		this.bottomPanel.centerX = Config.HALF_GAME_WIDTH
		this.bottomPanel.cameraOffset.y = Config.GAME_HEIGHT - this.bottomPanel.getHeight()
	}

	private alignCards(): void {
		this.cardsBounds.x = 0
		this.cardsBounds.width = Config.GAME_WIDTH
		this.cardsBounds.y = this.topPanel.bottom
		this.cardsBounds.height = this.bottomPanel.top - this.topPanel.bottom

		this.cardsContainer.centerX = this.cardsBounds.centerX
		this.cardsContainer.y = this.cardsBounds.top
	}

	private alignScroll(): void {
		let offset: number = this.scroll.height / 2 + 10
		let top: number = this.cardsBounds.top + offset
		let bottom: number = this.cardsBounds.bottom - offset
		this.scroll.setLimits(top, bottom)
		this.scroll.right = this.cardsBounds.right - 8
	}

	private show(): void {
		this.topPanel.show(100)
		this.bottomPanel.show(100)
		// this.showCards(250)
		this.showScroll(250)

		this.highlightBuyButtons()
	}

	private showCards(initialDelay: number): void {
		this.cardsContainer.y = this.bottomPanel.y - this.cardsContainer.height - 70 * Config.ASSETS_SCALE
		let dy: number = Math.abs(this.cardsContainer.y - this.cardsBounds.top)
		let duration: number = (dy / 1000) * 2600
		let scrollTween: Phaser.Tween = this.game.add
			.tween(this.cardsContainer)
			.to({ y: this.cardsBounds.top }, duration, Phaser.Easing.Cubic.Out, true, initialDelay)
		scrollTween.onUpdateCallback(() => {
			// this.scrollHandler.updateScrollbar()
		})

		this.game.add.tween(this.cardsContainer).from({ alpha: 0 }, 330, Phaser.Easing.Cubic.Out, true, initialDelay)
	}

	private showScroll(initialDelay: number): void {
		this.game.add.tween(this.scroll).from({ alpha: 1 }, 330, Phaser.Easing.Cubic.Out, true, initialDelay)
	}

	private highlightBuyButtons(): void {
		let coins: number = this.game.save.getCoins()

		this.cards.forEach((card: ShopCard) => {
			if (card.config.booster.price <= coins) {
				card.animateBuyButton()
			} else {
				card.stopAnimateBuyButton()
			}
		})
	}

	public update(game: Phaser.Game): void {
		super.update(game)

		this.updateScrollPosition()
	}

	private updateScrollPosition() {
		let offset: number = this.scroll.height / 2 + 10
		let top: number = this.topPanel.height + offset
		let bottom = Config.GAME_HEIGHT - this.bottomPanel.getHeight() - offset
		let height = bottom - top

		let scrollTop: number = 0
		let scrollBottom: number = this.game.world.bounds.height - this.game.camera.height
		let scrollHeight: number = scrollBottom - scrollTop
		let percent: number = this.game.camera.y / scrollHeight

		this.scroll.cameraOffset.y = top + height * percent
	}

	public shutdown(): void {
		this.game.kineticScrolling.stop()
		this.game.input.mouseWheel.callback = null
		this.game.camera.reset()
		this.game.world.setBounds(0, 0, Config.GAME_WIDTH, Config.GAME_HEIGHT)
	}
}
