import { cloneDeep } from 'es-toolkit'
import { ok } from 'neverthrow'
import { Logger } from 'tslog'
import { until } from 'until-async'
import { MultiTabTracker } from '../MultiTabTracker'
import { SafeLocalStorage } from '../robowhale/storage/SafeLocalStorage'
import { TypedEventEmitter } from '../robowhale/TypedEventEmitter'
import { Deferred, deferred } from '../robowhale/utils/async/deferred'
import { toReadableDateString } from '../robowhale/utils/date/readable-date-string'
import { getErrorLog } from '../robowhale/utils/error/utils'
import { SentryService } from '../sentry/SentryService'
import { BaseStorage, StorageSaveResult } from '../storage/BaseStorage'
import { TimeService } from '../time/TimeService'
import { prettyMs } from '../vendors/to-milliseconds'
import { GameState, GameStateKey, GameStateNumberKey, GameStateValue } from './GameState'

export interface SaveServiceOptions {
	logger: Logger<{}>
	initialState: GameState
	debugStorage: SafeLocalStorage
	remoteStorage: BaseStorage
	remoteSaveIntervalMs: number
	localStorage: BaseStorage
	sentry: SentryService
	multiTabTracker: MultiTabTracker
	time: TimeService
}

export interface SaveRequestOptions {
	/**
	 * The place where the save request comes from.
	 * E.g. 'game-over', 'shop-purchase', 'settings', etc.
	 */
	origin: string

	/**
	 * The destination of the save request.
	 * @default 'default'
	 */
	destination?: 'local-only' | 'local-and-remote' | 'default'

	/**
	 * Whether the save request is a background save request.
	 * @note background save requests are not guaranteed to be saved. Also they don't trigger waiting and error screens.
	 * @default false
	 */
	isBackground?: boolean
}

interface SaveRequest extends SaveRequestOptions {
	id: number
	startedAt: number
	completedAt: number
}

export class SaveService extends TypedEventEmitter<{}> {
	private options: SaveServiceOptions
	private logger: Logger<{}>
	private _state: GameState
	private _localStorage: BaseStorage
	private _remoteStorage: BaseStorage
	private requestsCounter = 0
	private currentSave = deferred<boolean>()
	private remoteSaveCompleteAt: number = 0
	private saveQueue: Promise<void> = Promise.resolve()

	constructor(options: SaveServiceOptions) {
		super()

		this.options = options
		this.logger = options.logger
		this._state = options.initialState
		this._localStorage = options.localStorage
		this._remoteStorage = options.remoteStorage
		this.currentSave.resolve(true)

		this.logger.info(`remote saves interval: ${prettyMs(this.options.remoteSaveIntervalMs)}`)
	}

	public async init() {
		return Promise.resolve()
	}

	/**
	 * Updates a state key and immediately saves.
	 */
	public setValue<K extends GameStateKey, V extends GameStateValue<K>>(
		key: K,
		value: V,
		_options: SaveRequestOptions
	): Promise<boolean> {
		const oldValue = this._state[key]

		if (oldValue === value) {
			return Promise.resolve(true)
		}

		this._state[key] = value

		const options: Required<SaveRequestOptions> = Object.assign(
			{
				origin: 'unknown',
				destination: 'default',
				isBackground: false,
			} satisfies SaveRequestOptions,
			_options
		)

		return this.run(options)
	}

	public changeNum<K extends GameStateNumberKey>(
		key: K,
		delta: number,
		_options: SaveRequestOptions
	): Promise<boolean> {
		const newValue = this._state[key] + delta

		return this.setValue(key, newValue, _options)
	}

	public async reset(): Promise<void> {
		await this.currentSave

		const setResult = this.options.debugStorage.set('pendingProfileClear', true)
		if (setResult.isErr()) {
			this.logger.warn(`failed to set pendingProfileClear (${setResult.error.message})`)
			return
		}

		this.logger.info('reset requested; pendingProfileClear set')

		const shouldReload = typeof window.confirm !== 'undefined' && window.confirm('Reload now to clear saved data?')
		if (!shouldReload) {
			return
		}

		window.location.reload()
	}

	public getValue<K extends GameStateKey, V extends GameStateValue<K>>(key: K): V {
		return this._state[key] as V
	}

	public getCoins(): number {
		return this.getValue('Coins')
	}

	/**
	 * Performs a save cycle: waits for an active save to finish, writes locally, optionally writes remotely,
	 * then resolves the shared deferred with success status. Remote save runs when destination is
	 * `local-and-remote` or when the configured interval elapsed for the default destination.
	 *
	 * @returns Promise resolving to `true` when at least one target succeeds, `false` otherwise.
	 */
	public async run(options: SaveRequestOptions): Promise<boolean> {
		const saveDeferred = deferred<boolean>()
		this.currentSave = saveDeferred

		const request: SaveRequest = {
			id: this.requestsCounter++,
			startedAt: Date.now(),
			completedAt: -1,
			...options,
		}

		this.saveQueue = this.saveQueue
			.then(async () => this.performSave({ request, saveDeferred }))
			.catch((error) => {
				this.logger.error(`save queue crashed (${getErrorLog(error)})`)
			})

		return saveDeferred
	}

	private async performSave(options: { request: SaveRequest; saveDeferred: Deferred<boolean> }): Promise<void> {
		const { request, saveDeferred } = options

		const prefix = this.logPrefix(request)

		const [error, isOk] = await until(async () => {
			this.logger.debug(`${prefix} - start`)

			this.checkMultiTab()

			await this.ensureServerTimeIsUpdated()

			this.beforeSave(request)

			request.startedAt = Date.now()

			const stateSnapshot: GameState = cloneDeep(this._state)

			const localSaveResult = await this.saveLocally(stateSnapshot)

			if (localSaveResult.isErr()) {
				this.logger.warn(`${prefix} - local save failed (${localSaveResult.error.message})`)
			}

			const remoteSaveRequired = this.isRemoteSaveRequired(request)
			const remoteSaveResult = remoteSaveRequired ? await this.saveRemotely(stateSnapshot) : ok({})

			if (remoteSaveResult.isErr()) {
				this.logger.warn(`${prefix} - remote save failed (${remoteSaveResult.error.message})`)
			}

			request.completedAt = Date.now()

			this.afterSave(request, localSaveResult, remoteSaveResult, remoteSaveRequired)

			return localSaveResult.isOk() || remoteSaveResult.isOk()
		})

		if (error) {
			request.completedAt = Date.now()
			const durationMs = request.completedAt - request.startedAt
			this.logger.error(`${prefix} - save crashed (${getErrorLog(error)})`)
			this.logger.debug(`${prefix} - end [${durationMs}ms]`)
			saveDeferred.resolve(false)
			return
		}

		saveDeferred.resolve(isOk)
	}

	private checkMultiTab() {
		const skipCheck = this.options.debugStorage.get('disableMultiTabCheck').unwrapOr(false)
		if (skipCheck) {
			return
		}

		this.options.multiTabTracker.throwIfSessionExpired()
	}

	private async ensureServerTimeIsUpdated() {
		const [error] = await until(() => this.options.time.updateServerTimeIfStale(3_000))
		if (error) {
			this.logger.error(`failed to update server time (${getErrorLog(error)})`)
		}
	}

	private beforeSave(request: SaveRequest) {
		const now = this.options.time.server
		this._state.savedAt = now
		this._state.savedAtStr = toReadableDateString(now, 'ms')
	}

	private isRemoteSaveRequired(request: SaveRequest): boolean {
		if (request.destination === 'local-and-remote') {
			return true
		}

		if (request.destination === 'local-only') {
			return false
		}

		if (request.destination === 'default') {
			const msSinceLastSave = Date.now() - this.remoteSaveCompleteAt
			return msSinceLastSave >= this.options.remoteSaveIntervalMs
		}

		return false
	}

	private async saveLocally(state: GameState): Promise<StorageSaveResult> {
		return this._localStorage.saveState(state)
	}

	private async saveRemotely(state: GameState): Promise<StorageSaveResult> {
		const result = await this._remoteStorage.saveState(state)

		if (result.isOk()) {
			this.remoteSaveCompleteAt = Date.now()
		}

		return result
	}

	private afterSave(
		request: SaveRequest,
		localSaveResult: StorageSaveResult,
		remoteSaveResult: StorageSaveResult,
		remoteSaveRequired: boolean
	) {
		const prefix = this.logPrefix(request)
		const durationMs = request.completedAt - request.startedAt

		let log = `${prefix} - local ${localSaveResult.isOk() ? '✔️' : '❌'}`
		if (remoteSaveRequired) {
			log += `, remote ${remoteSaveResult.isOk() ? '✔️' : '❌'}`
		}
		this.logger.debug(log)

		this.logger.debug(`${prefix} - end [${durationMs}ms]`)
	}

	private logPrefix(request: SaveRequest): string {
		return `${request.origin}#${request.id}`
	}

	public get remoteStorage(): BaseStorage {
		return this._remoteStorage
	}

	public get localStorage(): BaseStorage {
		return this._localStorage
	}
}
