import { GameFonts } from "../../../../GameFonts"

export class BoosterNumLabel extends Phaser.Group {
    public static NORMAL_COLOR: number = 0xff6f00
    public static GAME_OVER_COLOR: number = 0xb75d5d

    // public back:PhaserNineSlice.NineSlice;
    public back: Phaser.Image
    private text: Phaser.BitmapText

    constructor(_game: Phaser.Game, parent: Phaser.Group) {
        super(_game, parent, 'booster_num_label')

        this.addBack()
        this.addText()
    }

    private addBack() {
        // this.back = this.game.add.nineSlice(0, 0, "interface", "Booster_Label_Double0000", 40, 34, {top: 11}, this);
        this.back = this.game.add.image(0, 0, 'interface', 'Booster_Label_Double0000', this)
        this.back.anchor.set(0.5, 0.5)
        this.back.tint = BoosterNumLabel.NORMAL_COLOR
    }

    private addText() {
        let content: string = '0'

        this.text = this.game.add.bitmapText(0, 0, GameFonts.BARIOL_BOLD_BMP, content, 28, this)
        this.text.anchor.set(0.5, 0.5)
        this.text.y = 1
    }

    public updateContent(num: number): void {
        this.text.setText(num)
        this.back.width = this.getBackWidth()
        // this.back.resize(this.getBackWidth(), this.back.height);
    }

    private getBackWidth() {
        let minWidth: number = 32
        let width: number = this.text.width + 7 * 2

        return Math.max(minWidth, width)
    }

    public destroy(): void {
        super.destroy(true, false)
    }
}
