import { GamePushService, getMonthLeaderboardVariant, getWeekLeaderboardVariant } from '../../gamePush/GamePushService'
import { LeaderboardTab } from '../LeaderboardTab'
import {
	BaseLeaderboardProvider,
	BaseLeaderboardProviderOptions,
	LeaderboardFetchOptions,
} from './BaseLeaderboardProvider'
import { LeaderboardData, LeaderboardEntry } from './LeaderboardData'

export interface GamepushLeaderboardProviderOptions extends BaseLeaderboardProviderOptions {
	gamepush: GamePushService
	leaderboardId: number
}

export class GamepushLeaderboardProvider extends BaseLeaderboardProvider {
	private leaderboardId: number
	private gamepush: GamePushService

	constructor(options: GamepushLeaderboardProviderOptions) {
		super(options)

		this.gamepush = options.gamepush
		this.leaderboardId = options.leaderboardId
	}

	public getPlayerId(): string {
		return this.gamepush.sdk.player.id.toString()
	}

	public async fetch(options: LeaderboardFetchOptions): Promise<LeaderboardData> {
		const leaderboard = await this.gamepush.sdk.leaderboard.fetchScoped({
			id: this.leaderboardId,
			variant: this.getVariant(options.tab),
			includeFields: ['time'],
			withMe: 'first',
			showNearest: options.aroundPlayerCount || 5,
			limit: options.topEntriesCount || 10,
		})

		// Convert top players to LeaderboardEntry format
		const topEntries = leaderboard.topPlayers.map((player) => this.convertPlayerToEntry(player))

		// Combine above and below players around the current player
		const aroundPlayerEntries: LeaderboardEntry[] = []

		// Add above players if they exist
		if (leaderboard.abovePlayers && leaderboard.abovePlayers.length > 0) {
			aroundPlayerEntries.push(...leaderboard.abovePlayers.map((player) => this.convertPlayerToEntry(player)))
		}

		// Add current player if they exist in the leaderboard
		if (leaderboard.player) {
			aroundPlayerEntries.push(this.convertPlayerToEntry(leaderboard.player))
		}

		// Add below players if they exist
		if (leaderboard.belowPlayers && leaderboard.belowPlayers.length > 0) {
			aroundPlayerEntries.push(...leaderboard.belowPlayers.map((player) => this.convertPlayerToEntry(player)))
		}

		return {
			playerId: options.playerId,
			topEntries,
			aroundPlayerEntries,
		}
	}

	/**
	 * Converts a GamePush LeaderboardPlayer to our LeaderboardEntry format
	 */
	private convertPlayerToEntry(player: gamePush.LeaderboardPlayer): LeaderboardEntry {
		const timestamp = typeof player.date === 'number' ? player.date : Date.now()

		return {
			userId: player.id.toString(),
			timestamp: timestamp,
			rank: player.position,
			avatarUrl: player.avatar,
			username: player.name || player.id.toString(),
			score: typeof player.score === 'number' ? player.score : 0,
		}
	}

	private getVariant(tab: LeaderboardTab): string {
		switch (tab) {
			case 'weekly':
				return getWeekLeaderboardVariant()
			case 'monthly':
				return getMonthLeaderboardVariant()
			case 'all-time':
			default:
				return 'main'
		}
	}
}
