import { Config } from '../Config'
import { throttle } from 'es-toolkit/compat'
export class CoinsSpreadFX extends Phaser.Group {
	private coinsNum: number
	public background: Phaser.Image
	private coins: Phaser.Image[]
	public onCoinsCollectedSignal: Phaser.Signal
	private playCoinSoundThrottled: ReturnType<typeof throttle>

	constructor(_game: Phaser.Game, parent: Phaser.Group, coinsNum: number = 30) {
		super(_game, parent, 'video_coins_fx')

		this.coinsNum = coinsNum
		this.onCoinsCollectedSignal = new Phaser.Signal()
		this.playCoinSoundThrottled = throttle(this.playCoinSound.bind(this), 50, { trailing: true })

		this.addBackground()
		this.addCoins()

		this.visible = false
		this.exists = false
	}

	public setCoinTexture(key: string, frame?: string): void {
		this.coins.forEach((coin) => {
			coin.loadTexture(key, frame)
		})
	}

	private playCoinSound(): void {
		if (this.exists && this.game) {
			this.game.audio.playSound('coin', 0.33)
		}
	}

	private addBackground() {
		this.background = this.game.add.image(0, 0, 'interface', 'white_rect0000', this)
		this.background.alpha = 0.33
	}

	private addCoins() {
		this.coins = this.createMultiple(
			this.coinsNum,
			'interface',
			'CoinsCounter_Coin0000',
			true,
			(coin: Phaser.Image) => {
				coin.anchor.set(0.5, 0.5)
			}
		)
	}

	public show(dispatchPoint: Phaser.Point, collectPoint: Phaser.Point, delay: number = 0): void {
		this.revive()
		this.doReset()
		this.placeCoins()

		this.parent.bringToTop(this)

		this.showWhite()
		this.showCoins()
		this.collectCoins(1300, collectPoint)

		this.game.audio.playSound('coins_prize', 0.66)
	}

	private doReset() {
		this.game.tweens.removeFrom(this)

		this.coins.forEach((coin: Phaser.Image) => {
			this.game.tweens.removeFrom(coin.scale)

			coin.scale.set(1)
			coin.alpha = 1
		})
	}

	private placeCoins() {
		let offset: number = 40
		let bounds: Phaser.Rectangle = new Phaser.Rectangle(0, 0, 0, 0)
		bounds.copyFrom(Config.GAME_BOUNDS)
		bounds.inflate(-offset, -offset)

		this.coins.forEach((coin: Phaser.Image) => {
			this.placeCoinRandomly(coin, bounds)

			coin.angle = this.game.rnd.realInRange(-45, 45)
			coin.revive()
		})
	}

	private placeCoinRandomly(coin: Phaser.Image, bounds: Phaser.Rectangle) {
		coin.centerX = bounds.randomX
		coin.centerY = bounds.randomY
	}

	private showWhite() {
		this.background.alpha = 0

		this.game.add
			.tween(this.background)
			.to({ alpha: 0.77 }, 66, Phaser.Easing.Cubic.Out)
			.to({ alpha: 0 }, 1500, Phaser.Easing.Cubic.In)
			.start()
	}

	private showCoins() {
		let centerPoint: Phaser.Point = Config.GAME_CENTER

		this.coins.forEach((coin: Phaser.Image) => {
			let delay: number = 0
			let duration: number = 450
			let target: Phaser.Point = Phaser.Point.interpolate(centerPoint, coin.position, 0.8)

			this.game.add.tween(coin).from(
				{
					x: target.x,
					y: target.y,
				},
				duration,
				Phaser.Easing.Back.Out,
				true,
				delay
			)

			// this.game.add.tween(coin.scale).from({x: 0.5, y: 0.5}, 400, Phaser.Easing.Back.Out, true, delay);
			this.game.add.tween(coin).from({ alpha: 0 }, 200, Phaser.Easing.Cubic.Out, true, delay)
			this.game.add.tween(coin).from({ angle: '-30' }, 1800, Phaser.Easing.Cubic.Out, true, delay)
		})
	}

	private collectCoins(initialDelay: number, collectPoint: Phaser.Point) {
		this.game.time.events.add(
			initialDelay,
			() => {
				this.coins.forEach((coin, index) => {
					let delay: number = this.game.rnd.realInRange(0, 100)
					this.game.add
						.tween(coin)
						.to(
							{
								x: collectPoint.x,
								y: collectPoint.y,
								angle: 0,
							},
							800,
							Phaser.Easing.Back.In,
							true,
							delay
						)
						.onComplete.addOnce(this.onCoinCollected, this, 0, coin)
				})
			},
			this
		)
	}

	private onCoinCollected(coin: Phaser.Image): void {
		coin.visible = false

		this.playCoinSoundThrottled()

		if (this.coins.indexOf(coin) === this.coins.length - 1) {
			this.visible = false
			this.exists = false

			this.onCoinsCollectedSignal.dispatch()
		}
	}

	public resize(): void {
		this.background.width = Config.GAME_WIDTH * 1.2
		this.background.height = Config.GAME_HEIGHT * 1.2
		this.background.centerX = Config.HALF_GAME_WIDTH
		this.background.centerY = Config.HALF_GAME_HEIGHT
	}

	public destroy(): void {
		super.destroy(true, false)

		this.onCoinsCollectedSignal.dispose()
		this.onCoinsCollectedSignal = null
	}
}
