import { BoosterType } from '../boosters/BoosterType'
import { LevelStats } from './../LevelStats'
import { GridState } from './GridState'

export interface ISavedGameState {
	coins
	levelStats
	wasGameComplete: boolean
	gameOverState: IGameOverState
	freeBoosters: IFreeBoostersState
	gridState
	boosters
	seed
}

export interface IGameOverState {
	shuffleUsed: boolean
}

export type IFreeBoostersState = Record<BoosterType, boolean>

export class SavedGameState {
	private _coins: number
	public levelStats: LevelStats
	public wasGameComplete: boolean
	public gameOverState: IGameOverState
	public freeBoosters: IFreeBoostersState
	public gridState: GridState
	public boosters: Object
	private _seed: string

	constructor(
		coins: number,
		levelStats: LevelStats,
		wasGameComplete: boolean,
		gameOverState: IGameOverState,
		freeBoosters: IFreeBoostersState,
		gridState: GridState,
		boosters: Object,
		seed: string
	) {
		this._coins = coins
		this.levelStats = levelStats
		this.wasGameComplete = wasGameComplete
		this.gameOverState = gameOverState
		this.freeBoosters = freeBoosters
		this.gridState = gridState
		this.boosters = boosters
		this._seed = seed
	}

	public static fromString(data: string, _game: Phaser.Game): SavedGameState | null {
		let parsedData: ISavedGameState
		try {
			parsedData = JSON.parse(data)
		} catch (error) {
			console.warn("Can't parse SavedGameState data!", error)
			return null
		}

		let coins: number = parsedData.coins
		let levelStats: LevelStats = LevelStats.fromString(parsedData.levelStats, _game)
		let wasGameComplete: boolean = parsedData.wasGameComplete
		let gameOverState: IGameOverState = parsedData.gameOverState
		let freeBoosters: IFreeBoostersState = parsedData.freeBoosters ?? ({} as any)
		let gridState: GridState = GridState.fromString(parsedData.gridState)
		let boosters: Object = JSON.parse(parsedData.boosters)
		let seed: string = parsedData.seed

		return new SavedGameState(
			coins,
			levelStats,
			wasGameComplete,
			gameOverState,
			freeBoosters,
			gridState,
			boosters,
			seed
		)
	}

	public toString(): string {
		let data: ISavedGameState = {
			coins: this._coins,
			levelStats: this.levelStats.toString(),
			wasGameComplete: this.wasGameComplete,
			gameOverState: this.gameOverState,
			freeBoosters: this.freeBoosters,
			gridState: this.gridState.toString(),
			boosters: JSON.stringify(this.boosters),
			seed: this._seed,
		}

		return JSON.stringify(data)
	}

	public destroy(): void {
		this.levelStats = null
		this.gridState.destroy()
		this.gridState = null
		this.boosters = null
	}

	public get coins(): number {
		return this._coins
	}

	public get seed(): string {
		return this._seed
	}
}
