import { TypedEmitter } from 'tiny-typed-emitter'

interface Events {
	'hide-complete': () => void
}

export class FakeInterstitialScreen extends TypedEmitter<Events> {
	private dialog: HTMLElement
	private countdownValue: HTMLElement
	private closeButton: HTMLElement
	private countdownInterval: number

	constructor(private game: Phaser.Game) {
		super()

		const dialog = document.getElementById('interstitial-dialog')
		const countdownValue = document.getElementById('countdown-value')
		const closeButton = document.getElementById('interstitial-close')

		if (!dialog || !countdownValue || !closeButton) {
			throw new Error('Required interstitial elements not found in the DOM')
		}

		this.dialog = dialog
		this.countdownValue = countdownValue
		this.closeButton = closeButton

		this.closeButton.addEventListener('click', () => this.hide())
	}

	public show(data: { durationMs: number }) {
		const startedAt = Date.now()
		const durationMs = data.durationMs

		this.countdownValue.textContent = this.formatTime(durationMs)

		this.dialog.style.display = 'flex'

		this.countdownInterval = window.setInterval(() => {
			const msPassed = Date.now() - startedAt
			const msLeft = durationMs - msPassed
			this.countdownValue.textContent = this.formatTime(msLeft)

			if (msLeft <= 0) {
				this.hide()
			}
		}, 100)
	}

	private formatTime(ms: number): string {
		const seconds = Math.floor(ms / 1000)
		const minutes = Math.floor(seconds / 60)
		const remainingSeconds = seconds % 60
		return `${minutes.toString().padStart(2, '0')}:${remainingSeconds.toString().padStart(2, '0')}`
	}

	private hide() {
		clearInterval(this.countdownInterval)
		this.dialog.style.display = 'none'
		this.emit('hide-complete')
	}
}
