import { ListenerSignature, TypedEmitter } from 'tiny-typed-emitter'

export class TypedEventEmitter<TEvents extends ListenerSignature<TEvents> = {}> extends TypedEmitter<TEvents> {
	public once<Event extends keyof TEvents>(
		event: Event,
		listener: TEvents[Event],
		listenerCtx?: unknown,
		signal?: AbortSignal
	): this {
		if (signal?.aborted) {
			return this
		}

		const callback = listenerCtx ? listener.bind(listenerCtx) : listener

		if (signal) {
			const abortHandler = () => {
				this.off(event, callback)
				signal.removeEventListener('abort', abortHandler)
			}

			signal.addEventListener('abort', abortHandler)
		}

		return super.once(event, callback)
	}

	public on<Event extends keyof TEvents>(
		event: Event,
		listener: TEvents[Event],
		listenerCtx?: unknown,
		signal?: AbortSignal
	): this {
		if (signal?.aborted) {
			return this
		}

		const callback = listenerCtx ? listener.bind(listenerCtx) : listener

		if (signal) {
			const abortHandler = () => {
				this.off(event, callback)
				signal.removeEventListener('abort', abortHandler)
			}

			signal.addEventListener('abort', abortHandler)
		}

		return super.on(event, callback)
	}
}
