import { until } from '@open-draft/until'
import { Logger } from 'tslog'
import { getErrorLog } from '../robowhale/utils/error/utils'
import { BaseLeaderboardProvider } from './providers/BaseLeaderboardProvider'
import { LeaderboardData, LeaderboardEntry } from './providers/LeaderboardData'
import { LeaderboardTab, isLeaderboardTab, TABS } from './LeaderboardTab'

export interface LeaderboardScreenOptions {
	logger: Logger<{}>
	provider: BaseLeaderboardProvider
}

export interface LeaderboardScreenShowOptions {
	initialTab?: LeaderboardTab
	onClose?: () => void
}

export class LeaderboardScreen {
	private logger: Logger<{}>
	private provider: BaseLeaderboardProvider
	private leaderboardScreenElement: HTMLElement | null = null
	private titleElement: HTMLElement | null = null
	private closeButtonElement: HTMLElement | null = null
	private tabButtons: NodeListOf<HTMLButtonElement> | null = null
	private tabContents: { [key: string]: HTMLElement | null } = {}
	private entriesContainers: { [key: string]: HTMLElement | null } = {}
	private loadingElements: { [key: string]: HTMLElement | null } = {}
	private errorElements: { [key: string]: HTMLElement | null } = {}
	private currentTab: LeaderboardTab = 'all-time'
	private isLoading: boolean = false
	private onCloseCallback: (() => void) | null = null
	private leaderboardsData: { [key in LeaderboardTab]: LeaderboardData | null } = {
		'all-time': null,
		'weekly': null,
		'monthly': null,
	}

	constructor(private readonly options: LeaderboardScreenOptions) {
		this.logger = options.logger
		this.provider = options.provider
		this.initElements()
	}

	/**
	 * Initialize DOM elements
	 */
	private initElements(): void {
		this.leaderboardScreenElement = document.getElementById('leaderboard-screen')
		this.titleElement = this.leaderboardScreenElement?.querySelector('.leaderboard-screen__title')
		this.closeButtonElement = this.leaderboardScreenElement?.querySelector('.leaderboard-screen__close-button')
		this.tabButtons = this.leaderboardScreenElement?.querySelectorAll(
			'.leaderboard-screen__tab-button'
		) as NodeListOf<HTMLButtonElement>

		this.tabButtons?.forEach((button) => {
			const tabName = button.getAttribute('data-tab')
			if (!isLeaderboardTab(tabName)) {
				throw new Error(`invalid tab name: ${tabName}, should be one of: ${TABS.join(', ')}`)
			}

			button.addEventListener('click', () => this.switchTab(tabName))
		})

		// Initialize tab content elements
		this.tabContents['all-time'] = document.getElementById('all-time-tab')
		this.tabContents['monthly'] = document.getElementById('monthly-tab')
		this.tabContents['weekly'] = document.getElementById('weekly-tab')

		// Initialize entries containers
		this.entriesContainers['all-time'] = this.tabContents['all-time']?.querySelector(
			'.leaderboard-screen__entries'
		) as HTMLElement
		this.entriesContainers['monthly'] = this.tabContents['monthly']?.querySelector(
			'.leaderboard-screen__entries'
		) as HTMLElement
		this.entriesContainers['weekly'] = this.tabContents['weekly']?.querySelector(
			'.leaderboard-screen__entries'
		) as HTMLElement

		// Initialize loading elements
		this.loadingElements['all-time'] = this.tabContents['all-time']?.querySelector(
			'.leaderboard-screen__loading'
		) as HTMLElement
		this.loadingElements['monthly'] = this.tabContents['monthly']?.querySelector(
			'.leaderboard-screen__loading'
		) as HTMLElement
		this.loadingElements['weekly'] = this.tabContents['weekly']?.querySelector(
			'.leaderboard-screen__loading'
		) as HTMLElement

		// Initialize error elements
		this.errorElements['all-time'] = this.tabContents['all-time']?.querySelector(
			'.leaderboard-screen__error'
		) as HTMLElement
		this.errorElements['monthly'] = this.tabContents['monthly']?.querySelector(
			'.leaderboard-screen__error'
		) as HTMLElement
		this.errorElements['weekly'] = this.tabContents['weekly']?.querySelector(
			'.leaderboard-screen__error'
		) as HTMLElement

		// Add event listeners
		this.closeButtonElement?.addEventListener('click', () => this.hide())

		// Add backdrop click handler
		this.leaderboardScreenElement?.addEventListener('click', (event) => {
			// Only close if clicking the backdrop itself, not its children
			if (event.target === this.leaderboardScreenElement) {
				this.hide()
			}
		})

		// Add ESC key handler
		document.addEventListener('keydown', (event) => {
			if (event.key === 'Escape' && this.leaderboardScreenElement?.classList.contains('visible')) {
				this.hide()
			}
		})

		// Prevent context menu on the leaderboard screen (Yandex platform requirement 1.6.1.8 / 1.6.2.7)
		this.leaderboardScreenElement?.addEventListener('contextmenu', (event) => {
			event.preventDefault()
		})
	}

	/**
	 * Set the leaderboard data provider
	 * @param provider - The provider instance to use for fetching leaderboard data
	 */
	public setProvider(provider: BaseLeaderboardProvider): void {
		this.provider = provider
	}

	/**
	 * Show the leaderboard screen with custom options
	 * @param options - Configuration options for the leaderboard screen
	 */
	public show(options: LeaderboardScreenShowOptions = {}): void {
		if (!this.leaderboardScreenElement) {
			this.logger.error('cannot show leaderboard screen: DOM elements not initialized')
			return
		}

		if (!this.provider) {
			this.logger.error('cannot show leaderboard screen: provider not set')
			throw new Error('Leaderboard provider must be set before showing the screen')
		}

		// Set close callback
		this.onCloseCallback = options.onClose || null

		// Reset leaderboard data so it will be refetched
		this.leaderboardsData = {
			'all-time': null,
			'weekly': null,
			'monthly': null,
		}

		// Switch to initial tab if provided
		if (options.initialTab) {
			this.switchTab(options.initialTab, false)
		} else {
			this.switchTab(this.currentTab, false)
		}

		// Show the leaderboard screen
		this.leaderboardScreenElement.classList.add('visible')
	}

	/**
	 * Hide the leaderboard screen
	 */
	public hide(): void {
		if (this.leaderboardScreenElement) {
			this.leaderboardScreenElement.classList.remove('visible')

			// Call the close callback if provided
			if (this.onCloseCallback) {
				this.onCloseCallback()
				this.onCloseCallback = null
			}
		}
	}

	/**
	 * Switch between leaderboard tabs
	 * @param tabName - The name of the tab to switch to
	 * @param refetchData - Whether to fetch data for the tab
	 */
	public async switchTab(tabName: LeaderboardTab, refetchData = false) {
		if (!this.tabButtons || !this.tabContents[tabName]) {
			this.logger.error(`cannot switch to tab: ${tabName}`)
			return
		}

		if (!this.entriesContainers[tabName] || !this.loadingElements[tabName] || !this.errorElements[tabName]) {
			this.logger.error(`Cannot fetch data for tab: ${tabName}`)
			return null
		}

		// Prevent tab switching while loading
		if (this.isLoading) {
			return
		}

		// Update current tab
		this.currentTab = tabName as LeaderboardTab

		// Update tab buttons
		this.tabButtons.forEach((button) => {
			const buttonTabName = button.getAttribute('data-tab')
			if (buttonTabName === tabName) {
				button.classList.add('active')
			} else {
				button.classList.remove('active')
			}
		})

		// Update tab contents
		Object.keys(this.tabContents).forEach((key) => {
			if (key === tabName) {
				this.tabContents[key]?.classList.add('active')
			} else {
				this.tabContents[key]?.classList.remove('active')
			}
		})

		let data = this.leaderboardsData[tabName]
		if (refetchData || !data) {
			// Set loading state and disable tab buttons
			this.isLoading = true
			this.tabButtons.forEach((button) => (button.disabled = true))

			data = await this.fetchLeaderboardData(tabName)

			// Reset loading state and enable tab buttons
			this.isLoading = false
			this.tabButtons.forEach((button) => (button.disabled = false))
		}

		if (data) {
			this.leaderboardsData[tabName] = data
			this.renderLeaderboardData(tabName, data)
		}
	}

	/**
	 * Fetch leaderboard data for the specified tab
	 * @param tabName - The name of the tab to fetch data for
	 */
	private async fetchLeaderboardData(tabName: LeaderboardTab): Promise<LeaderboardData | null> {
		// Show loading state
		this.showLoading(tabName)

		const { error, data } = await until(() =>
			this.provider!.fetch({
				tab: tabName,
				playerId: this.provider!.getPlayerId(),
			})
		)

		if (error) {
			this.logger.error(`failed to fetch '${tabName}' data (${getErrorLog(error)})`)
			this.showError(tabName)
			return null
		}

		// Hide loading state
		this.hideLoading(tabName)

		return data
	}

	/**
	 * Render leaderboard entries for a specific tab
	 * @param tabName - The name of the tab to render entries for
	 * @param leaderboardData - The leaderboard data to render
	 */
	private renderLeaderboardData(tabName: string, leaderboardData: LeaderboardData): void {
		const entriesContainer = this.entriesContainers[tabName]
		if (!entriesContainer) {
			this.logger.error(`cannot render entries for tab: ${tabName}`)
			return
		}

		// Clear existing entries
		entriesContainer.innerHTML = ''

		// Get top entries and around player entries from the data
		const topEntries = leaderboardData.topEntries || []
		const aroundPlayerEntries = leaderboardData.aroundPlayerEntries || []
		const playerId = leaderboardData.playerId

		// Check if player is already in top entries
		const playerInTopEntries = topEntries.some((entry) => entry.userId === playerId)

		// Render top entries first
		if (topEntries.length > 0) {
			// Render each top entry
			topEntries.forEach((entry, index) => {
				const entryElement = this.createEntryElement(entry, playerId)

				// Add first entry class to the first entry
				if (index === 0) {
					entryElement.classList.add('leaderboard-screen__entry__first')
				}

				entriesContainer.appendChild(entryElement)
			})
		}

		// Only render around player entries if player is not already in top entries
		if (aroundPlayerEntries.length > 0 && !playerInTopEntries) {
			// Add a separator between top entries and around player entries if both exist
			if (topEntries.length > 0) {
				const separator = document.createElement('div')
				separator.className = 'leaderboard-screen__separator'
				separator.textContent = '...'
				entriesContainer.appendChild(separator)
			}

			// Render each around player entry
			aroundPlayerEntries.forEach((entry, index) => {
				const entryElement = this.createEntryElement(entry, playerId)

				// Add first entry class if this is the first entry after a separator
				if (index === 0 && topEntries.length > 0) {
					entryElement.classList.add('leaderboard-screen__entry__first')
				}

				entriesContainer.appendChild(entryElement)
			})
		}
	}

	/**
	 * Create an entry element for the leaderboard
	 * @param entry - The leaderboard entry data
	 * @param playerId - The ID of the current player
	 * @returns The created HTML element
	 */
	private createEntryElement(entry: LeaderboardEntry, playerId: string): HTMLElement {
		const entryElement = document.createElement('div')
		entryElement.className = 'leaderboard-screen__entry'

		// Add class if this is the current player
		if (entry.userId === playerId) {
			entryElement.classList.add('is-current-player')
		}

		// Format the timestamp
		const date = new Date(entry.timestamp)
		const formattedDate =
			date.toLocaleDateString('en-GB') +
			' ' +
			date.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })

		entryElement.innerHTML = `
			<div class="leaderboard-screen__rank">${entry.rank}</div>
			<div class="leaderboard-screen__username-container">
				<div class="leaderboard-screen__username">${entry.username}</div>
				<div class="leaderboard-screen__timestamp">${formattedDate}</div>
			</div>
			<div class="leaderboard-screen__score">${entry.score}</div>
		`

		return entryElement
	}

	/**
	 * Show loading state for a tab
	 * @param tabName - The name of the tab to show loading for
	 */
	private showLoading(tabName: string): void {
		if (this.entriesContainers[tabName]) {
			this.entriesContainers[tabName]!.style.display = 'none'
		}

		if (this.loadingElements[tabName]) {
			this.loadingElements[tabName]!.style.display = 'flex'
		}

		if (this.errorElements[tabName]) {
			this.errorElements[tabName]!.style.display = 'none'
		}
	}

	/**
	 * Hide loading state for a tab
	 * @param tabName - The name of the tab to hide loading for
	 */
	private hideLoading(tabName: string): void {
		if (this.entriesContainers[tabName]) {
			this.entriesContainers[tabName]!.style.display = 'block'
		}

		if (this.loadingElements[tabName]) {
			this.loadingElements[tabName]!.style.display = 'none'
		}
	}

	/**
	 * Show error state for a tab
	 * @param tabName - The name of the tab to show error for
	 * @param message - The error message to display
	 */
	private showError(tabName: string): void {
		if (this.entriesContainers[tabName]) {
			this.entriesContainers[tabName]!.style.display = 'none'
		}

		if (this.loadingElements[tabName]) {
			this.loadingElements[tabName]!.style.display = 'none'
		}

		if (this.errorElements[tabName]) {
			this.errorElements[tabName]!.style.display = 'flex'
		}
	}

	public setTexts(texts: texts.En): void {
		// Update title
		if (this.titleElement) {
			this.titleElement.textContent = texts.leaderboard.title
		}

		// Update tab buttons
		this.tabButtons?.forEach((button) => {
			const tabName = button.getAttribute('data-tab')
			if (tabName) {
				switch (tabName) {
					case 'all-time':
						button.textContent = texts.leaderboard.tabs.all_time
						break
					case 'monthly':
						button.textContent = texts.leaderboard.tabs.monthly
						break
					case 'weekly':
						button.textContent = texts.leaderboard.tabs.weekly
						break
				}
			}
		})

		// Update loading text for each tab
		Object.values(this.loadingElements).forEach((element) => {
			if (element) {
				element.textContent = texts.leaderboard.loading
			}
		})

		// Update error text for each tab
		Object.values(this.errorElements).forEach((element) => {
			if (element) {
				element.textContent = texts.leaderboard.error
			}
		})

		// If we have data, re-render entries to update any text
		Object.entries(this.leaderboardsData).forEach(([tabName, data]) => {
			if (data) {
				this.renderLeaderboardData(tabName as LeaderboardTab, data)
			}
		})
	}
}
