import { Config } from '../../../Config'
import { SimpleButton } from '../../../gui/buttons/SimpleButton'
import { CreditsContent } from './CreditsContent'
export class CreditsPopup extends Phaser.Group {
	private back: Phaser.Image
	public content: CreditsContent
	public closeButton: SimpleButton

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'settings_popup')

		this.addBack()
		this.addCloseButton()
		this.addCreditsContent()
	}

	private addBack(): void {
		this.back = this.game.add.image(0, 0, 'main_menu', 'Settings_GUI_Back0000', this)
		this.back.inputEnabled = true
		this.back.name = 'settings_popup'
	}

	private addCloseButton(): void {
		let offset: number = -6 * Config.ASSETS_SCALE

		this.closeButton = new SimpleButton(this.game, 0, 0, 'main_menu', 'Button_Close0000', this)
		this.closeButton.centerX = this.back.right + offset
		this.closeButton.centerY = this.back.top - offset
		this.closeButton.name = 'settings_close_button'
	}

	private addCreditsContent(): void {
		this.content = new CreditsContent(this.game, this)
	}

	public show(initialDelay: number): void {
		this.visible = true
		this.exists = true

		this.game.tweens.removeFrom(this)
		this.game.add.tween(this).from({ alpha: 0 }, 150, Phaser.Easing.Cubic.Out, true, initialDelay)
		this.game.add.tween(this).from({ y: '+50' }, 350, Phaser.Easing.Back.Out, true, initialDelay)

		this.showCloseButton(initialDelay + 200)
	}

	private showCloseButton(delay: number) {
		this.closeButton.alpha = 0
		this.closeButton.scale.set(0.77)

		this.game.tweens.removeFrom(this.closeButton)
		this.game.tweens.removeFrom(this.closeButton.scale)
		this.game.add.tween(this.closeButton).to({ alpha: 1 }, 150, Phaser.Easing.Cubic.Out, true, delay)
		this.game.add.tween(this.closeButton.scale).to({ x: 1, y: 1 }, 350, Phaser.Easing.Back.Out, true, delay)
	}

	public hide(): void {
		this.game.tweens.removeFrom(this)
		this.game.add
			.tween(this)
			.to({ alpha: 0, y: '+40' }, 160, Phaser.Easing.Cubic.In, true)
			.onComplete.addOnce(() => {
				this.visible = false
				this.exists = false
			})
	}

	public getWidth(): number {
		return this.back.width
	}

	public getHeight(): number {
		return this.back.height
	}

	public destroy(): void {
		super.destroy(true, false)
	}
}
