import { createAbortError } from '../error/create-abort-error'

type AnyFunction = (...args: any[]) => any

/**
 * Delays the execution of a function by the specified number of milliseconds.
 * Can be aborted using an optional AbortSignal.
 *
 * @param {number} ms - The number of milliseconds to delay execution.
 * @param {AbortSignal} [signal] - An optional AbortSignal object that can be used to abort the delay.
 * @returns {Promise<void>} - A promise that resolves after the specified delay.
 * @throws {DOMException} - If the delay is aborted using the provided AbortSignal.
 */
export function timeout(ms: number, signal?: AbortSignal): Promise<void> {
	return new Promise((resolve, reject) => {
		if (signal?.aborted) {
			return reject(createAbortError(signal.reason))
		}

		signal?.addEventListener(
			'abort',
			() => {
				clearTimeout(timeoutId)
				reject(createAbortError(signal.reason))
			},
			{ once: true }
		)

		const timeoutId = setTimeout(() => resolve(), ms)
	})
}

export function timeoutCb(
	ms: number,
	onComplete: AnyFunction,
	signal?: AbortSignal,
	onCancel?: (reason: string | undefined) => void
): void {
	if (signal?.aborted) {
		onCancel?.(signal?.reason)
		return
	}

	signal?.addEventListener(
		'abort',
		() => {
			clearTimeout(timeoutId)
			onCancel?.(signal?.reason)
		},
		{ once: true }
	)

	const timeoutId = setTimeout(() => onComplete(), ms)
}
