import { YaPlatform } from '../../platform/yandex/YaPlatform'
import { Result } from '../../robowhale/Result'
import { AdBasicResult, AdErrorCode } from '../AdsService'
import { IAdsProvider } from './IAdsProvider'

/**
 * @link https://yandex.com/dev/games/doc/en/sdk/sdk-adv
 */
export class YaAdsProvider implements IAdsProvider {
	readonly name = 'yandex'

	private platform: YaPlatform

	constructor(platform: YaPlatform) {
		this.platform = platform
	}

	public async showInterstitial(): Promise<AdBasicResult> {
		if (!this.platform.ready) {
			return Result.Error({
				code: AdErrorCode.GENERIC,
				message: 'YA platform is not ready',
			})
		}

		const shown = await this.platform.showInterstitialAd()
		if (shown.success === true) {
			return Result.Ok()
		}

		return Result.Error({
			code: this.getErrorCode(shown.error),
			message: shown.error || 'platform show error',
		})
	}

	public async showRewarded(): Promise<AdBasicResult> {
		if (!this.platform.ready) {
			return Result.Error({
				code: AdErrorCode.GENERIC,
				message: 'YA platform is not ready',
			})
		}

		const shown = await this.platform.showRewardedAd()
		if (shown.success === true) {
			return Result.Ok()
		}

		return Result.Error({
			code: this.getErrorCode(shown.error),
			message: shown.error || 'platform show error',
		})
	}

	public async loadRewarded(): Promise<AdBasicResult> {
		if (!this.platform.ready) {
			return Result.Error({
				code: AdErrorCode.GENERIC,
				message: 'YA platform is not ready',
			})
		}

		/**
		 * Для Яндекса нет такого метода, считаем, что по умолчанию, все загружено
		 * @link https://yandex.ru/dev/games/doc/ru/sdk/sdk-adv
		 */
		return Result.Ok()
	}

	private getErrorCode(error: string): AdErrorCode {
		// Error: Please, don't try to open advertising often than once per 60 s
		if (error.includes('open advertising often than once per')) {
			return AdErrorCode.CALL_LIMIT
		}

		if (error.includes('adblock')) {
			return AdErrorCode.ADBLOCKED
		}

		if (error.includes('closed by user')) {
			return AdErrorCode.SKIP
		}

		/**
		 * в документации https://yandex.ru/dev/games/doc/ru/sdk/sdk-adv
		 * не описано никаких типов ошибок при показе рекламы,
		 * поэтому все ошибки будем считать generic
		 */
		return AdErrorCode.GENERIC
	}
}
