import { Logger } from 'tslog'
import { TypedEventEmitter } from '../robowhale/TypedEventEmitter'
import { Platform } from '../startup/Platform'
import { SentryService } from '../sentry/SentryService'
import { Result } from 'neverthrow'
import { IVisibilityProvider } from '../visibility/IVisibilityProvider'


export interface BasePlatformOptions {
	game: Phaser.Game
	logger: Logger<{}>
	sentry: SentryService
}

export interface BasePlatformEvents {
	'player-logged-in': (id: string) => void
	'player-logged-out': () => void
}

export abstract class BasePlatform extends TypedEventEmitter<BasePlatformEvents> {
	public abstract readonly type: Platform

	protected readonly game: BasePlatformOptions['game']
	protected readonly _logger: Logger<{}>
	protected readonly _sentry: SentryService
	protected _ready = false

	constructor(protected readonly options: BasePlatformOptions) {
		super()

		this.game = options.game
		this._logger = options.logger
		this._sentry = options.sentry
	}

	abstract init(): Promise<void>

	/**
	 * @return two-letter language code
	 */
	abstract getLanguage(): Promise<string | undefined>

	abstract gameReady(): Promise<void>

	/**
	 * @return true, если adblock включен
	 */
	protected async hasAdblock(): Promise<boolean> {
		try {
			const res = await fetch('//ad.mail.ru/static/ads-async.js')
			// если рекламный скрипт загрузился = адблока нет
			return res.ok !== true
		} catch (error) {
			// рекламный скрипт не загрузился - адблок есть
			return true
		}
	}

	abstract loadRewardedAd(): Promise<any>

	abstract showRewardedAd(): Promise<any>

	abstract showInterstitialAd(): Promise<any>

	abstract isBannerAdSupported(): boolean
	abstract showBannerAd(): Promise<Result<void, string>>
	abstract hideBannerAd(): Promise<Result<void, string>>

	abstract isFullscreenSupported(): boolean
	abstract isFullscreen(): boolean
	abstract requestFullscreen(): Promise<void>
	abstract exitFullscreen(): Promise<void>

	/**
	 * Where platform is ready to use (initialized)
	 */
	public get ready(): boolean {
		return this._ready
	}

	public get logger(): Logger<{}> {
		return this._logger
	}

	public getVisibilityProvider(): IVisibilityProvider | undefined {
		return undefined
	}
}
