import { Logger } from 'tslog'
import { LeaderboardData } from './LeaderboardData'
import { LeaderboardTab } from '../LeaderboardTab'

export interface BaseLeaderboardProviderOptions {
	logger: Logger<{}>
}

export abstract class BaseLeaderboardProvider {
	protected logger: Logger<{}>

	constructor(protected readonly options: BaseLeaderboardProviderOptions) {
		this.logger = options.logger
	}

	abstract fetch(options: LeaderboardFetchOptions): Promise<LeaderboardData>

	abstract getPlayerId(): string
}

export interface LeaderboardFetchOptions {
	tab: LeaderboardTab
	playerId: string
	topEntriesCount?: number
	aroundPlayerCount?: number
}
