import { toReadableDateString } from './../robowhale/utils/date/readable-date-string'
import { prettyMs } from './../vendors/to-milliseconds'
import { BaseError } from './BaseError'

export class MultiTabError extends BaseError {
	public readonly isFatal = true

	constructor(currentSessionId: number, newerSessionId: number) {
		super('game was opened in a different tab or in a different browser on the same device')

		this.name = 'MultiTabError'

		this.sentryContext = {
			extra: {
				currentSessionId: toReadableDateString(currentSessionId, 'ms'),
				newerSessionId: toReadableDateString(newerSessionId, 'ms'),
				diff: prettyMs(newerSessionId - currentSessionId),
			},
		}
	}
}
