import type { VKBridge } from '@vkontakte/vk-bridge'
import { match } from 'ts-pattern'
import { IVisibilityProvider, VisibilityState } from './IVisibilityProvider'

export interface VkVisibilityProviderOptions {
	bridge: VKBridge
}

export class VkVisibilityProvider implements IVisibilityProvider {
	public readonly name = 'vk'
	private readonly _bridge: VKBridge
	private _state: VisibilityState
	private _listeners: (() => void)[] = []

	constructor(options: VkVisibilityProviderOptions) {
		this._bridge = options.bridge
		this._state = this.getInitialState()

		this._bridge.subscribe((event) => {
			const { type } = event.detail

			match(type)
				.with('VKWebAppViewHide', () => this.updateState('hidden'))
				.with('VKWebAppViewRestore', () => this.updateState('visible'))
				.otherwise(() => {})
		})
	}

	public getState(): VisibilityState {
		return this._state
	}

	public addChangeListener(listener: () => void): () => void {
		this._listeners.push(listener)
		return () => {
			this._listeners = this._listeners.filter((l) => l !== listener)
		}
	}

	private getInitialState(): VisibilityState {
		if (typeof document === 'undefined' || !document.visibilityState) {
			return 'visible'
		}

		return match(document.visibilityState as string)
			.with('visible', () => 'visible' as const)
			.otherwise(() => 'hidden' as const)
	}

	private updateState(newState: VisibilityState): void {
		if (this._state === newState) {
			return
		}

		this._state = newState
		this._listeners.forEach((listener) => listener())
	}
}
