export interface ErrorScreenOptions {
	title?: string
	message?: string
	buttonText?: string
	onButtonClick?: () => void
}

export class ErrorScreen {
	private static instance: ErrorScreen
	private errorScreenElement: HTMLElement | null = null
	private titleElement: HTMLElement | null = null
	private messageElement: HTMLElement | null = null
	private buttonElement: HTMLElement | null = null
	private defaultButtonText: string = 'Restart'
	private defaultOnButtonClick: () => void = () => {
		window.location.reload()
	}

	/**
	 * Get the singleton instance of ErrorScreen
	 */
	public static getInstance(): ErrorScreen {
		if (!ErrorScreen.instance) {
			ErrorScreen.instance = new ErrorScreen()
		}

		return ErrorScreen.instance
	}

	private constructor() {
		this.initElements()
	}

	/**
	 * Initialize DOM elements
	 */
	private initElements(): void {
		this.errorScreenElement = document.getElementById('error-screen')

		if (this.errorScreenElement) {
			this.titleElement = this.errorScreenElement.querySelector('.error-screen__title')
			this.messageElement = this.errorScreenElement.querySelector('.error-screen__message')
			this.buttonElement = this.errorScreenElement.querySelector('.error-screen__button')

			if (this.buttonElement) {
				this.buttonElement.addEventListener('click', () => {
					this.hide()
					this.defaultOnButtonClick()
				})
			}
		} else {
			console.error('Error screen element not found in the DOM')
		}
	}

	/**
	 * Show the error screen with custom options
	 * @param options - Configuration options for the error screen
	 */
	public show(options: ErrorScreenOptions = {}): void {
		if (!this.errorScreenElement) {
			console.error('Cannot show error screen: DOM elements not initialized')
			return
		}

		// Set title
		if (this.titleElement && options.title) {
			this.titleElement.textContent = options.title
		}

		// Set message
		if (this.messageElement && options.message) {
			this.messageElement.textContent = options.message
		}

		// Set button text
		if (this.buttonElement) {
			this.buttonElement.textContent = options.buttonText || this.defaultButtonText

			// Remove previous click listener
			const newButton = this.buttonElement.cloneNode(true)
			if (this.buttonElement.parentNode) {
				this.buttonElement.parentNode.replaceChild(newButton, this.buttonElement)
				this.buttonElement = newButton as HTMLElement
			}

			// Add new click listener
			const onButtonClick = options.onButtonClick || this.defaultOnButtonClick
			this.buttonElement.addEventListener('click', () => {
				this.hide()
				onButtonClick()
			})
		}

		// Show the error screen
		this.errorScreenElement.classList.add('visible')
	}

	/**
	 * Hide the error screen
	 */
	public hide(): void {
		if (this.errorScreenElement) {
			this.errorScreenElement.classList.remove('visible')
		}
	}
}
