import { SaveService } from './save/SaveService'

import SoundManager = Phaser.SoundManager

/**
 * Состояние аудио перед показом рекламы
 */
type AudioState = {
	muted: boolean
	contextState: string
}

export interface GameAudioOptions {
	save: SaveService
	game: Phaser.Game
}

export class GameAudio {
	get musicLoop(): Phaser.Sound {
		return this._musicLoop
	}

	private game: Phaser.Game
	private save: SaveService
	private _musicLoop: Phaser.Sound
	private musicVolume: number
	private savedSoundMute: boolean = false
	private savedMusicMute: boolean = false
	private firstTouchListener: EventListener
	private beforeAdShowState: AudioState | undefined

	constructor(private readonly options: GameAudioOptions) {
		this.game = options.game
		this.save = options.save

		this.fixIFrameSoundIssue()
	}

	private fixIFrameSoundIssue() {
		this.game.input.touch.touchEndCallback = () => {
			if (this.game.sound.context.state === 'suspended') {
				this.game.sound.context.resume()
			}
		}
	}

	public initMusicLoop(externalNode: boolean = false): void {
		this.musicVolume = 1
		this._musicLoop = this.game.sound.add('main_loop', this.musicVolume, true, !externalNode)
		this._musicLoop.mute = this.savedMusicMute

		if (externalNode) {
			this._musicLoop.gainNode = this.createMusicLoopNode()
		}
	}

	private createMusicLoopNode(): GainNode {
		const node = this.game.sound.context.createGain()
		node.gain.setTargetAtTime(0, node.context.currentTime, 0.1)
		node.connect(this.game.sound.context.destination)

		return node
	}

	public loadMute() {
		this.soundMute = this.save.getValue('sound_muted')
		this.musicMute = this.save.getValue('music_muted')
	}

	public playMusicLoop(): Phaser.Sound {
		if (this._musicLoop && this._musicLoop.isPlaying === false) {
			this._musicLoop.play()
		}

		return this._musicLoop
	}

	public playSound(key: string, volume: number = 1.0): Phaser.Sound {
		if (this.game.cache.checkSoundKey(key)) {
			return this.game.sound.play(key, volume)
		} else {
			// console.warn(`Audio :: sound ${key} not found in Cache.`);
		}

		return null
	}

	public stopSound(key: string) {
		this.game.sound._sounds.forEach((sound) => {
			if (sound.key === key) {
				sound.stop()
			}
		})
	}

	public playClickSound(volume: number = 1) {
		if (this.game.cache.checkSoundKey('click')) {
			this.game.sound.play('click', volume)
		}
	}

	public trackFocusChange() {
		if (this.game.device.desktop) {
			return
		}

		this.game.onBlur.add(this.onGameFocusLost, this)
		this.game.onFocus.add(this.onGameFocus, this)
	}

	public onGameFocusLost(event: Event) {
		this.game.sound.mute = true

		if (this._musicLoop) {
			this._musicLoop.mute = true
		}
	}

	public onGameFocus(event: Event) {
		this.game.sound.mute = this.savedSoundMute

		if (this._musicLoop) {
			this._musicLoop.mute = this.savedMusicMute
		}
	}

	public handleMusicOnStart() {
		if (this.game.sound.touchLocked) {
			const touchEventType: string = this.game.device.iOSVersion > 8 ? 'touchend' : 'touchstart'

			this.firstTouchListener = this.onFirstTouch.bind(this)
			this.game.canvas.addEventListener(touchEventType, this.firstTouchListener)
		} else {
			this.playMusicLoop()
		}
	}

	private onFirstTouch(event: TouchEvent): void {
		this.game.canvas.removeEventListener(event.type, this.firstTouchListener)
		this.playMusicLoopFirstTime(1500)
	}

	public playMusicLoopFirstTime(fadeDuration: number = 1000): void {
		if (this._musicLoop) {
			this._musicLoop.play(null, 0, 0, true)
			this._musicLoop.fadeTo(fadeDuration, this.musicVolume)
		}
	}

	public get soundMute(): boolean {
		return this.game.sound.mute
	}

	public set soundMute(value: boolean) {
		this.savedSoundMute = value
		this.game.sound.mute = value
		this.game.save.setValue('sound_muted', value, { origin: 'audio/sound_mute' })
	}

	public get musicMute(): boolean {
		/*if (this._musicLoop) {
            return this._musicLoop.mute;
        }*/

		return this.savedMusicMute
	}

	public set musicMute(value: boolean) {
		this.savedMusicMute = value
		this.game.save.setValue('music_muted', value, { origin: 'audio/music_mute' })

		if (this._musicLoop) {
			this._musicLoop.mute = value
		}
	}

	public recreateAudioContext() {
		if (this.game.device.iOS === false) {
			return
		}

		if (this.game.sound.usingWebAudio === false) {
			return
		}

		let hasAudioContext: boolean = typeof AudioContext !== 'undefined'
		if (hasAudioContext === false) {
			return
		}

		this.doRecreateAudioContext()
	}

	private doRecreateAudioContext() {
		let manager: SoundManager = this.game.sound
		let managerMute: boolean = this.game.save.getValue('sound_muted')
		let managerVolume: number = manager.volume

		manager.context?.close()
		manager.masterGain?.disconnect()
		manager.context = new AudioContext()
		manager.masterGain = manager.context.createGain()
		manager.masterGain.connect(manager.context.destination)
		manager.masterGain.gain.value = managerMute ? 0 : managerVolume

		manager._sounds.forEach((sound: Phaser.Sound) => {
			let volume: number = sound.volume
			let mute: boolean = sound.mute

			sound.context = manager.context
			sound.masterGainNode = manager.masterGain
			sound.gainNode = sound.context.createGain()
			if (sound.connect) {
				sound.gainNode.connect(sound.masterGainNode)
			}

			sound.volume = volume
			sound.mute = mute
		})
	}

	public beforeAdShow(): Promise<void> {
		this.beforeAdShowState = {
			muted: this.game.sound.mute,
			contextState: '',
		}

		this.game.sound.mute = true

		return this.suspendAudioContext()
	}

	private suspendAudioContext(): Promise<void> {
		const context = this.game.sound.context

		if (!context) {
			return Promise.resolve()
		}

		this.beforeAdShowState.contextState = context.state

		if (context.state === 'running') {
			return context.suspend()
		}

		return Promise.resolve()
	}

	public async afterAdShow() {
		await this.resumeAudioContext()

		this.game.sound.mute = this.beforeAdShowState?.muted ?? false

		this.beforeAdShowState = undefined
	}

	private async resumeAudioContext(): Promise<void> {
		const context = this.game.sound.context

		if (!context) {
			return Promise.resolve()
		}

		// if context was suspended before, we won't be able to resume it
		if (this.beforeAdShowState?.contextState === 'suspended') {
			return Promise.resolve()
		}

		if (context.state === 'suspended') {
			return context.resume()
		}

		return Promise.resolve()
	}
}
