import { maxBy } from 'es-toolkit/compat'
import { Item } from './items/Item'

export class LevelStats {
	protected game: Phaser.Game
	public coins: number = 0
	public moves: number = 0
	protected totalTime: number
	protected lastActiveTime: number
	protected _timeInSeconds: number
	protected _timeInMinutes: number
	protected bestItemTypeOnStart: number
	public currentBestItemType: number
	public bestItemTypeAtEnd: number
	protected _isHighscore: boolean = false

	constructor(_game: Phaser.Game) {
		this.game = _game

		this.bestItemTypeOnStart = this.game.save.getValue('best_item')
		this.totalTime = 0
		this.lastActiveTime = this.game.time.now
	}

	public updateTime(): void {
		let delta: number = this.game.time.now - this.lastActiveTime
		this.lastActiveTime = this.game.time.now
		this.totalTime += delta
	}

	public onLevelEnd(itemsOnGrid: Item[]): void {
		this.updateTime()
		this.calculateTime()

		this.bestItemTypeAtEnd = maxBy(itemsOnGrid, 'itemType').itemType
		if (this.bestItemTypeAtEnd > this.bestItemTypeOnStart) {
			this._isHighscore = true
		}
	}

	private calculateTime(): void {
		this._timeInSeconds = Math.round(this.totalTime / 1000)
		this._timeInMinutes = Math.round(this._timeInSeconds / 60)
	}

	public get timeInMinutes(): number {
		return this._timeInMinutes
	}

	public get timeInSeconds(): number {
		return this._timeInSeconds
	}

	public get isHighscore(): boolean {
		return this._isHighscore
	}

	public clone(): LevelStats {
		let ls: LevelStats = new LevelStats(this.game)
		ls.moves = this.moves
		ls.coins = this.coins
		ls.lastActiveTime = this.lastActiveTime
		ls.totalTime = this.totalTime

		return ls
	}

	public toString(): string {
		let data = {
			coins: this.coins,
			moves: this.moves,
			totalTime: this.totalTime,
			timeInSeconds: this.timeInSeconds,
			timeInMinutes: this.timeInMinutes,
			bestItemTypeOnStart: this.bestItemTypeOnStart,
			currentBestItemType: this.currentBestItemType,
			bestItemTypeAtEnd: this.bestItemTypeAtEnd,
			isHighscore: this._isHighscore,
		}

		return JSON.stringify(data)
	}

	public static fromString(data: string, _game: Phaser.Game): LevelStats {
		let parsedData: any
		try {
			parsedData = JSON.parse(data)
		} catch (error) {
			const parseError = error as Error
			console.warn("Can't parse saved LevelStats!", parseError.name, parseError.message)
			return null
		}

		let levelStats: LevelStats = new LevelStats(_game)
		levelStats.coins = parsedData.coins
		levelStats.moves = parsedData.moves
		levelStats.totalTime = parsedData.totalTime
		levelStats.lastActiveTime = _game.time.now
		levelStats._timeInSeconds = parsedData.timeInSeconds
		levelStats._timeInMinutes = parsedData.timeInMinutes
		levelStats.bestItemTypeOnStart = parsedData.bestItemTypeOnStart
		levelStats.currentBestItemType = parsedData.currentBestItemType
		levelStats.bestItemTypeAtEnd = parsedData.bestItemTypeAtEnd
		levelStats._isHighscore = parsedData.isHighscore

		return levelStats
	}
}
