import { Logger } from 'tslog'
import { padStart } from 'es-toolkit/compat'
import { NetUtil } from './robowhale/utils/NetUtil'
import { PLATFORMS } from './startup/Platform'
import { BoosterType } from './states/level/boosters/BoosterType'

import GA = gameanalytics.GameAnalytics
import EGAProgressionStatus = gameanalytics.EGAProgressionStatus
import EGAAdAction = gameanalytics.EGAAdAction
import EGAAdType = gameanalytics.EGAAdType
import EGAErrorSeverity = gameanalytics.EGAErrorSeverity

export enum RendererType {
	CANVAS = 'CANVAS',
	WEBGL = 'WEBGL',
}

export interface GameAnalyticsWrapperOptions {
	game: Phaser.Game
	logger: Logger<{}>
}

/**
 * @link https://docs.gameanalytics.com/integrations/sdk/javascript/event-tracking
 */
export class GameAnalyticsWrapper {
	private game: Phaser.Game
	private logger: Logger<{}>
	private isEnabled: boolean = false
	private loadingTimes: Record<string, number>

	constructor(private readonly options: GameAnalyticsWrapperOptions) {
		this.game = options.game
		this.logger = options.logger

		const config = window.game.config

		if (!config.analytics.enabled) {
			this.isEnabled = false
			this.logger.warn('disabled')
			return
		}

		this.isEnabled = true
		this.loadingTimes = {}
		this.setLog()
		this.setCustomDimensions()

		GA.configureBuild(config.build_version.toString())
		GA.initialize(config.analytics.gameKey, config.analytics.secret)
		GA.addDesignEvent('Startup')
	}

	private setLog() {
		let logLevel: number = NetUtil.getParamInt('analyticsLog')
		if (logLevel === 1) {
			this.logger.info('enabled info log')
			GA.setEnabledInfoLog(true)
		} else if (logLevel === 2) {
			this.logger.info('enabled verbose log')
			GA.setEnabledVerboseLog(true)
		}
	}

	private setCustomDimensions() {
		GA.configureAvailableCustomDimensions01(PLATFORMS as unknown as string[])
		GA.setCustomDimension01(window.game.config.platform)

		GA.configureAvailableCustomDimensions02([RendererType.CANVAS, RendererType.WEBGL])
		GA.setCustomDimension02(this.getRendererType())

		let browsers: string[] = [
			'chrome',
			'firefox',
			'ie',
			'mobileSafari',
			'opera',
			'safari',
			'silk',
			'trident',
			'other',
		]
		let currentBrowser: string = this.getCurrentBrowser(browsers)
		GA.configureAvailableCustomDimensions03(browsers)
		GA.setCustomDimension03(currentBrowser)
	}

	private getRendererType(): RendererType {
		if (this.game.renderer instanceof PIXI.CanvasRenderer) {
			return RendererType.CANVAS
		} else {
			return RendererType.WEBGL
		}
	}

	private getCurrentBrowser(browsers: string[]) {
		let currentBrowser: string = browsers.find((browser) => this.game.device[browser] === true)
		return currentBrowser ?? 'other'
	}

	public setUser(userId: string): void {
		if (this.isEnabled === false) {
			return
		}

		GA.configureUserId(userId)
	}

	public sendLevelStart(level: number): void {
		this.sendProgressionEvent(EGAProgressionStatus.Start, level)
	}

	public sendLevelComplete(level: number, starsNum: number): void {
		this.sendProgressionEvent(EGAProgressionStatus.Complete, level, starsNum)
	}

	public sendLevelFail(level: number): void {
		this.sendProgressionEvent(EGAProgressionStatus.Fail, level)
	}

	private sendProgressionEvent(type: EGAProgressionStatus, level: number, score?: number): void {
		if (this.isEnabled === false) {
			return
		}

		let levelKey: string = 'level_' + padStart(level.toString(), 3, '0')
		GA.addProgressionEvent(type, levelKey, '', '', score)
	}

	public sendBoosterUseEvent(level: number, type: BoosterType): void {
		if (this.isEnabled === false) {
			return
		}

		let levelKey: string = 'Level_' + padStart(level.toString(), 3, '0')
		GA.addDesignEvent(`${levelKey}:Booster:${type}`)
	}

	public sendAdEvent(action: EGAAdAction, type: EGAAdType, placement?: string, adProvider?: string): void {
		if (this.isEnabled === false) {
			return
		}

		GA.addAdEvent(action, type, adProvider, placement)
	}

	public sendRewardedAd(
		placement: 'second_chance' | 'free_booster',
		type: string,
		action: 'request' | 'fail' | 'receive'
	): void {
		if (this.isEnabled === false) {
			return
		}

		GA.addDesignEvent(`Rewarded_Ad:${placement}:${type}:${action}`)
	}

	public sendLoadingEvent(place: 'main' | 'levels_map' | 'gameplay', type: 'start' | 'complete'): void {
		if (this.isEnabled === false) {
			return
		}

		if (type === 'start') {
			this.loadingTimes[place] = Date.now()
			GA.addDesignEvent(`Loading:${place}:${type}`)
		}

		if (type === 'complete') {
			let durationMs: number = Date.now() - this.loadingTimes[place]
			let duration: number = Phaser.Math.roundTo(durationMs / 1000, -1)
			GA.addDesignEvent(`Loading:${place}:${type}`, duration)
		}
	}

	/**
	 * @link https://docs.gameanalytics.com/event-types/design-events
	 */
	public sendDesignEvent(event: string, value?: any) {
		if (this.isEnabled === false) {
			return
		}

		GA.addDesignEvent(event, value)
	}

	/**
	 * @link https://docs.gameanalytics.com/event-types/error-events
	 */
	public sendError(message: string, severity: EGAErrorSeverity = EGAErrorSeverity.Error) {
		if (this.isEnabled === false) {
			return
		}

		GA.addErrorEvent(severity, message)
	}

	public getRemoteConfigValue(key: string, defaultValue: string): string {
		if (this.isEnabled === false) {
			return defaultValue
		}

		return GA.getRemoteConfigsValueAsString(key, defaultValue)
	}
}
