import { Booster } from './Booster'
import { BoosterType } from './BoosterType'
import { BoosterTypeUtil } from './BoosterTypeUtil'

export class BoostersManager {
	private game: Phaser.Game
	public boosters: Booster[]

	constructor(_game: Phaser.Game) {
		this.game = _game
		this.createBoosters()

		this.game.texts.onLanguageChange.add(this.onLanguageChange, this)
	}

	private onLanguageChange(): void {
		this.boosters.forEach((booster) => booster.updateTexts())
	}

	private createBoosters() {
		this.boosters = BoosterTypeUtil.getAllTypes().map((boosterType: BoosterType) => {
			return new Booster(this.game, boosterType)
		})

		this.boosters.forEach((booster) => {
			booster.onChange.add(this.onBoosterChange, this)
		})
	}

	private onBoosterChange(booster: Booster, prevValue: number, newValue: number) {
		// console.log("Boosters :: changed", booster.type, prevValue, newValue);
	}

	public getBooster(type: BoosterType): Booster {
		return this.boosters.find((booster) => booster.type === type)
	}

	public createSave(): Object {
		let save: Object = {}

		this.boosters.forEach((booster: Booster) => {
			save[booster.type] = booster.num
		})

		return save
	}

	public loadFromSave(save: Object, ignoreUndo: boolean = true): void {
		Object.keys(save).forEach((key: string) => {
			let boosterType: BoosterType = BoosterTypeUtil.fromString(key)
			let booster: Booster = this.getBooster(boosterType)
			if (!booster) {
				return
			}

			if (boosterType === BoosterType.UNDO) {
				booster.num = ignoreUndo ? booster.num : save[key]
			} else {
				booster.num = save[key]
			}
		})
	}

	public canBuyAnyBooster(): boolean {
		let coins: number = this.game.save.getCoins()

		return this.boosters.some((booster: Booster) => {
			return coins >= booster.price
		})
	}
}
