import { getErrorLog } from './utils/error/utils'

type OkResult<TData> = {
	success: true
	data?: TData
	ok(): this is OkResult<TData>
}

function createOkResult<TData>(data?: TData): OkResult<TData> {
	return {
		success: true,
		data,
		ok(): this is OkResult<TData> {
			return true
		},
	}
}

type ErrorResult<TError> = {
	success: false
	error?: TError
	ok(): false
}

function createErrorResult<TError>(error?: TError): ErrorResult<TError> {
	return {
		success: false,
		error,
		ok(): false {
			return false
		},
	}
}

/**
 * Helper type for any action that can succeed of fail.
 *
 * ```typescript
 * // example with 'match()' from ts-pattern
 * const res = Result.Ok({ test: true });
 * match(res)
 * 	.with({ success: true }, ({ data }) => console.log(data.test))
 * 	.with({ success: false }, ({ error }) => console.log(error))
 * 	.exhaustive();
 * ```
 */
export type Result<TData = never, TError = string> = OkResult<TData> | ErrorResult<TError>

export const Result = {
	Ok: <TData>(data?: TData) => createOkResult(data),
	Error: <TError>(error?: TError) => createErrorResult(error),
}

export type AsyncResult<TError = string, TData = never> = Promise<Result<TData, TError>>

export const AsyncResult = {
	Ok: <TData>(data?: TData): AsyncResult<never, TData> => Promise.resolve(Result.Ok(data)),
	Error: <TError>(error?: TError): AsyncResult<TError, never> => Promise.resolve(Result.Error(error)),
	fromPromise: <TData, TErrorMapper extends (error: unknown) => any = typeof getErrorLog>(
		promise: Promise<TData>,
		mapError: TErrorMapper = getErrorLog as TErrorMapper
	): AsyncResult<ReturnType<TErrorMapper>, TData> => {
		return promise.then((data) => Result.Ok(data)).catch((error) => Result.Error(mapError(error)))
	},
}
