import { Cell } from '../grid/Cell'
import { Grid } from '../grid/Grid'
import { Item } from '../items/Item'
import { ItemsAligner } from '../ItemsAligner'
import { BoosterType } from './BoosterType'

export class BoosterMode {
	public onAddItem: Phaser.Signal
	public onBoosterComplete: Phaser.Signal
	public onSave: Phaser.Signal

	private game: Phaser.Game
	public active: boolean = false
	private boosterType: BoosterType
	private grid: Grid
	private itemsLayer: Phaser.Group
	private itemsAligner: ItemsAligner
	private preCallbacks: Object
	private callbacks: Object
	private activeItems: Item[]

	constructor(_game: Phaser.Game, grid: Grid, itemsLayer: Phaser.Group, itemsAligner: ItemsAligner) {
		this.game = _game
		this.grid = grid
		this.itemsLayer = itemsLayer
		this.itemsAligner = itemsAligner

		this.onAddItem = new Phaser.Signal()
		this.onBoosterComplete = new Phaser.Signal()
		this.onSave = new Phaser.Signal()

		this.initCallbacks()
	}

	private initCallbacks(): void {
		this.callbacks = {}
		this.callbacks[BoosterType.REMOVE] = this.applyRemoveItem
		this.callbacks[BoosterType.MAGNET] = this.applyMagnet
		this.callbacks[BoosterType.SORT] = this.applySort
		this.callbacks[BoosterType.UPGRADE] = this.applyUpgrade

		this.preCallbacks = {}
		this.preCallbacks[BoosterType.REMOVE] = this.dummyPrecallback
		this.preCallbacks[BoosterType.SORT] = this.dummyPrecallback
		this.preCallbacks[BoosterType.MAGNET] = this.canApplyMagnet
		this.preCallbacks[BoosterType.UPGRADE] = this.canApplyUpgrade
	}

	private dummyPrecallback(item: Item = null): boolean {
		return true
	}

	public activate(items: Item[], boosterType: BoosterType): void {
		console.assert(this.active === false)

		//trace("BoosterMode activated!", boosterType);

		this.active = true
		this.activeItems = items
		this.boosterType = boosterType

		this.game.input.onDown.add(this.onInputDown, this)
		this.startFloatItems()
	}

	private startFloatItems(): void {
		this.activeItems
			.sort(this.sortItemsUpBottom)
			.reverse()
			.forEach((item, index) => {
				let delay: number = Phaser.Math.wrap(index * 100, 0, 400)
				item.floatTween = this.game.add
					.tween(item)
					.to({ y: '-16' }, 550, Phaser.Easing.Sinusoidal.InOut, true, delay, -1, true)
			})
	}

	private sortItemsUpBottom(item1: Item, item2: Item): number {
		let cell1: Cell = item1.cell
		let cell2: Cell = item2.cell

		if (cell1.row === cell2.row) return cell2.column - cell1.column
		else return cell1.row - cell2.row
	}

	private stopFloatItems(): void {
		this.activeItems.forEach((item) => {
			if (item.floatTween) {
				item.floatTween.stop(false)
				item.floatTween = null
			}

			item.alignToCellCenterSmooth(200)
			// item.alignToCellCenterInstant();
		})
	}

	private onInputDown(pointer: Phaser.Pointer): void {
		if (this.active === false) {
			return
		}

		let cell: Cell = this.grid.getCellUnderPoint(pointer.x, pointer.y)
		if (cell && cell.item) {
			let preCallback = this.preCallbacks[this.boosterType]
			let performCallback: boolean = preCallback.call(this, cell.item)
			let callback: Function = this.callbacks[this.boosterType]
			if (callback && performCallback) {
				this.game.sentry.setContext('lastBooster', {
					type: this.boosterType,
					cell: `[column: ${cell.column}, row: ${cell.row}]`,
					item: cell.item.itemType,
				})

				this.game.sound.play('pop_2', 0.5)

				this.active = false
				this.stopFloatItems()
				this.beforeBoosterStart()
				callback.call(this, cell.item)
			}
		}
	}

	private beforeBoosterStart(): void {
		this.onSave.dispatch()
		this.game.boosters.getBooster(this.boosterType).num--
	}

	private applyRemoveItem(item: Item): void {
		item.parent.bringToTop(item)
		item.onRemoveBoosterComplete.addOnce(this.onRemoveItemComplete, this)
		item.applyRemoveBooster()
	}

	private onRemoveItemComplete(item: Item): void {
		this.removeItem(item)
		this.updateGridAfterBooster()
	}

	private canApplyMagnet(centralItem: Item): boolean {
		let filteredItems: Item[] = this.activeItems.filter((item) => {
			return item.itemType === centralItem.itemType
		})
		if (filteredItems.length < 3) {
			let message: string = this.game.boosters.getBooster(BoosterType.MAGNET).warning
			this.game.toast.show(message)

			filteredItems.forEach((item: Item, index: number) => {
				this.game.add.tween(item.scale).to(
					{
						x: 1.1,
						y: 1.1,
					},
					100,
					Phaser.Easing.Sinusoidal.InOut,
					true,
					0,
					6,
					true
				)
			})

			return false
		}

		return true
	}

	private applyMagnet(centralItem: Item): void {
		this.attractItems(centralItem)

		centralItem.parent.bringToTop(centralItem)
		centralItem.animateAsMagnet()
	}

	private attractItems(centralItem: Item): void {
		let delay: number = 100

		this.activeItems
			.filter((item) => item !== centralItem && item.itemType === centralItem.itemType)
			.forEach((item, index) => {
				item.parent.bringToTop(item)
				this.applyMagnetToItem(centralItem, item, delay)

				delay += 33
			})

		this.game.time.events.add(delay + 300, this.onMagnetComplete, this, centralItem)
	}

	private applyMagnetToItem(centralItem: Item, item: Item, delay: number): void {
		this.game.time.events.add(
			delay,
			() => {
				this.game.tweens.removeFrom(item)
				this.game.add
					.tween(item)
					.to({ x: centralItem.x, y: centralItem.y }, 350, Phaser.Easing.Back.In, true)
					.onComplete.addOnce(() => {
						this.removeItem(item)
					})
			},
			this
		)
	}

	private onMagnetComplete(centralItem: Item): void {
		this.game.audio.playSound('item_convert_2', 0.25)

		let newItemType: number = centralItem.itemType + 1
		let cell: Cell = centralItem.cell

		centralItem.stopMagnetAnimation()
		this.removeItem(centralItem)
		this.onAddItem.dispatch(cell, newItemType)
		this.game.time.events.add(600, this.updateGridAfterBooster, this)
	}

	private applySort(item: Item): void {
		this.game.audio.playSound('shuffle', 0.66)

		this.shakeGrid()
		this.sortItems()
	}

	private shakeGrid(): void {
		this.game.add.tween(this.itemsLayer).to({ x: '+10' }, 75, Phaser.Easing.Sinusoidal.InOut, true, 0, 5, true)
	}

	private sortItems(): void {
		this.activeItems.sort(this.sortItemsByType)
		this.activeItems.forEach((item) => {
			item.clearCell()
		})

		this.activeItems.forEach((item: Item, index) => {
			let cell: Cell = this.grid.cells[index]
			item.linkCell(cell)
			item.stopAlignTween()
			item.alignToCellCenterInstant()

			item.alpha = 0
			item.y -= 20

			let delay: number = index * 33 + 100
			let tween: Phaser.Tween = this.game.add.tween(item).to(
				{
					y: '+20',
					alpha: 1,
				},
				330,
				Phaser.Easing.Cubic.Out,
				true,
				delay
			)
			if (index === this.activeItems.length - 1) {
				tween.onComplete.addOnce(this.onBoosterCompleteCallback, this)
			}
		})
	}

	private sortItemsByType(item_1: Item, item_2: Item): number {
		return item_1.itemType - item_2.itemType
	}

	private removeItem(item: Item): void {
		item.clearCell()
		item.onAddToPool()

		const itemIndex = this.activeItems.indexOf(item)
		if (itemIndex !== -1) {
			this.activeItems.splice(itemIndex, 1)
		}
	}

	public updateGridAfterBooster(): void {
		this.itemsAligner.onAlignComplete.addOnce(this.onBoosterCompleteCallback, this)
		this.itemsAligner.alignAndRefill(this.activeItems)
	}

	private canApplyUpgrade(item: Item): boolean {
		if (item.itemType === 12) {
			let warning: string = this.game.boosters.getBooster(BoosterType.UPGRADE).warning
			this.game.toast.show(warning)
			console.warn('BoosterMode :: ', warning)

			this.game.add.tween(item).to({ x: '+6' }, 80, Phaser.Easing.Sinusoidal.InOut, true, 0, 3, true)

			return false
		}

		return true
	}

	private applyUpgrade(item: Item): void {
		this.game.sound.play('new_item', 0.5)

		let delay: number = 33
		let itemsToUpgrade: Item[] = this.activeItems
			.filter((candidate) => candidate.itemType === item.itemType)
			.sort(this.sortItemsByGridPosition.bind(this))

		itemsToUpgrade.forEach((item: Item, index: number) => {
			this.game.time.events.add(index * delay, item.upgrade, item)
		})

		let finalDelay: number = itemsToUpgrade.length * delay + 100
		this.game.time.events.add(finalDelay, this.onBoosterCompleteCallback, this)
	}

	private sortItemsByGridPosition(item_1: Item, item_2: Item): number {
		let z1: number = item_1.cell.row * this.grid.columns + item_1.cell.column
		let z2: number = item_2.cell.row * this.grid.columns + item_2.cell.column

		return z1 - z2
	}

	private onBoosterCompleteCallback(): void {
		this.active = false
		this.game.input.onDown.remove(this.onInputDown, this)
		this.itemsAligner.onAlignComplete.remove(this.onBoosterCompleteCallback, this)

		this.onBoosterComplete.dispatch(this.boosterType)
	}

	private dispatchNewItemEvent(cell: Cell, itemType: number): void {
		this.onAddItem.dispatch(cell, itemType)
	}

	public cancel(): void {
		this.active = false
		this.game.input.onDown.remove(this.onInputDown, this)
		this.stopFloatItems()
	}

	public destroy(): void {
		this.game.input.onDown.remove(this.onInputDown, this)
		this.itemsAligner.onAlignComplete.remove(this.onBoosterCompleteCallback, this)

		this.callbacks = null
		this.activeItems = null
		this.grid = null
		this.game = null
		this.itemsAligner = null

		this.disposeSignals()
	}

	private disposeSignals() {
		this.onAddItem.dispose()
		this.onAddItem = null
		this.onBoosterComplete.dispose()
		this.onBoosterComplete = null
		this.onSave.dispose()
		this.onSave = null
	}
}
