import { FontWeight, GameFonts } from '../../../GameFonts'
import PhaserTextStyle = Phaser.PhaserTextStyle
export class StatCircle extends Phaser.Group {
	protected circle: Phaser.Image
	public innerCircle: Phaser.Image
	private _text: Phaser.Text
	protected icon: Phaser.Image

	constructor(
		_game: Phaser.Game,
		parent: Phaser.Group,
		circleTextureKey: string,
		circleTextureFrame: string,
		textColor: number,
		textContent: string
	) {
		super(_game, parent, 'stat_circle')

		this.addCircle(circleTextureKey, circleTextureFrame)
		this.addText(textContent, textColor)
	}

	protected addInnerCircle(): void {
		this.innerCircle = this.game.add.image(0, 0, 'game_over', 'Circle_Inner0000', this)
		this.innerCircle.anchor.set(0.5, 0.5)
		this.innerCircle.alignIn(this.circle, Phaser.CENTER)
		this.innerCircle.sendToBack()
	}

	private addCircle(circleTextureKey: string, circleTextureFrame: string): void {
		this.circle = this.game.add.image(0, 0, circleTextureKey, circleTextureFrame, this)
		this.circle.anchor.set(0.5, 0.5)
	}

	private addText(textContent: string, textColor: number): void {
		let style: PhaserTextStyle = {
			font: GameFonts.NUNITO_CSS,
			fontSize: 44,
			fontWeight: FontWeight.BOLD,
			fill: '#' + textColor.toString(16),
			align: 'center',
		}

		this._text = this.game.add.text(0, 0, textContent, style, this)
		this._text.lineSpacing = -8
		this._text.anchor.set(0.5, 0.5)
		this._text.x = this.circle.centerX
		this._text.y = this.circle.centerY
	}

	public updateText(content: string): void {
		this._text.text = content
	}

	public addIcon(iconTextureKey: string, iconTextureFrame?: string): void {
		if (!this.icon) {
			this.icon = this.game.add.image(0, 0, iconTextureKey, iconTextureFrame, this)
			this.icon.anchor.set(0.5, 0.5)
			this.icon.centerX = this.circle.centerX
			this.icon.centerY = this.circle.top + 3
		}
	}

	public getCircleHeight(): number {
		return this.circle.height
	}

	public get text(): Phaser.Text {
		return this._text
	}

	public destroy(): void {
		super.destroy(true, false)
	}
}
