/// <reference path="./ITexts.ts" />

import { Logger } from 'tslog'
import { TypedEventEmitter } from '../robowhale/TypedEventEmitter'
import { NetUtil } from '../robowhale/utils/NetUtil'
import { GameTextsJson } from '../startup/load-game-texts'
import { LanguageUtil } from './LanguageUtil'

type Events = {
	'language-change': (language: string, prevLanguage: string | undefined) => void
}

export interface GameTextsOptions {
	game: Phaser.Game
	texts: GameTextsJson
	logger: Logger<{}>
	platformLanguage: string | undefined
}

export class GameTexts extends TypedEventEmitter<Events> {
	public get allLanguages(): string[] {
		return this._allLanguages
	}

	public get language(): string {
		return this._language
	}

	private logger: Logger<{}>
	private game: Phaser.Game
	private allTexts: object
	private _allLanguages: string[]
	private _language: string
	public texts: texts.En

	public onLanguageChange: Phaser.Signal

	constructor(options: GameTextsOptions) {
		super()

		this.logger = options.logger
		this.game = options.game
		this.allTexts = options.texts
		this._allLanguages = Object.keys(this.allTexts)
		this._language = this.detectLanguage(options.platformLanguage)
		this.texts = this.allTexts[this._language]
		this.onLanguageChange = new Phaser.Signal()

		this.logger.info(`language: ${this._language}`)

		// console.groupCollapsed('Texts')
		// console.log(this.texts)
		// console.groupEnd()
	}

	private detectLanguage(platformLanguage: string | undefined): string {
		return (
			this.getLanguageFromUrlParam() ||
			this.getSavedLanguage() ||
			this.getLanguageFromPlatform(platformLanguage) ||
			this.getLanguageFromBrowser() ||
			'en'
		)
	}

	private getLanguageFromUrlParam(): string | null {
		let language: string = NetUtil.getParam('lang') || NetUtil.getParam('language')
		if (language && this.isLanguageSupported(language)) {
			return language
		}

		return null
	}

	private getSavedLanguage(): string {
		return this.game.save.getValue('language')
	}

	private getLanguageFromPlatform(platformLanguage: string | undefined): string | null {
		if (!platformLanguage) {
			return null
		}

		if (platformLanguage && this.isLanguageSupported(platformLanguage)) {
			return platformLanguage
		}

		return null
	}

	private getLanguageFromBrowser(): string | null {
		let language = LanguageUtil.convertLanguageCodeToGameLanguage(navigator.language)
		if (language && this.isLanguageSupported(language)) {
			return language
		}

		if (typeof navigator.languages !== 'undefined') {
			let languages = navigator.languages.map((code) => LanguageUtil.convertLanguageCodeToGameLanguage(code))
			let supportedLanguage = languages.find((language) => this.isLanguageSupported(language))
			if (supportedLanguage) {
				return supportedLanguage
			}
		}

		return null
	}

	private isLanguageSupported(language: string): boolean {
		return this._allLanguages.includes(language)
	}

	public setLanguage(language: string) {
		const prevLanguage = this._language

		if (!this.isLanguageSupported(language)) {
			this.logger.warn(`language ${language} is not supported!`)
			return false
		}

		this._language = language
		this.texts = this.allTexts[language]
		this.onLanguageChange.dispatch(language)

		this.emit('language-change', language, prevLanguage)

		this.logger.info(`language changed: ${prevLanguage} -> ${this._language}`)

		return true
	}
}
