import { Result, err, ok } from 'neverthrow'
import { Logger } from 'tslog'
import { fromError } from 'zod-validation-error'
import { getObjectKeys } from '../collection/get-object-keys'
import { tryit } from '../functions/tryit'
import { TypedEventEmitter } from '../TypedEventEmitter'
import { getErrorLog } from '../utils/error/utils'
import { SCHEMA, type Schema } from './SafeLocalStorageSchema'

export type SafeLocalStorageKey = keyof Schema

type Value<K extends SafeLocalStorageKey> = Schema[K]

type LocalStorageError = {
	type: 'storage-not-avail' | 'parse-error'
	message: string
}

// TODO(minor) pass in schema as type argument
type SafeLocalStorageOptions = {
	logger: Logger<{}>
}

type Events = {
	[K in SafeLocalStorageKey]: (value: Value<K>) => void
}

/**
 * Wrapper over localStorage that provides a safe way to interact with it.
 * It will always return a Result, so you can handle errors gracefully.
 *
 * @note It **won't** emit change events if you will use `localStorage.setItem`, `localStorage.removeItem` or `localStorage.clear` directly.
 */
export class SafeLocalStorage extends TypedEventEmitter<Events> {
	private options: SafeLocalStorageOptions
	private logger: Logger<{}>
	private schema: typeof SCHEMA

	constructor(options: SafeLocalStorageOptions) {
		super()

		this.options = options
		this.logger = options.logger
		this.schema = SCHEMA
		this.listenToStorageEvent()
	}

	/**
	 * The 'storage' event is primarily used for communication between different tabs or windows.
	 * If you want to listen for changes made in one tab from another tab, the storage event is the right choice.
	 * However, if you are setting an item in the same tab, the event does not fire.
	 * @see https://developer.mozilla.org/en-US/docs/Web/API/Window/storage_event
	 * @see https://caniuse.com/mdn-api_window_storage_event
	 */
	private listenToStorageEvent(): void {
		window.addEventListener('storage', (event) => {
			this.logger.debug(`'storage' event`, {
				key: event.key,
				newValue: event.newValue,
				oldValue: event.oldValue,
			})

			const key = event.key
			if (!this.isStorageKey(key)) {
				return
			}

			const schema = this.schema.shape[key]
			const parsedValue = schema.safeParse(event.newValue)
			if (!parsedValue.success) {
				this.logger.warn(`invalid value for '${key}' (value: ${event.newValue})`)
				this.logger.warn('parse error', fromError(parsedValue.error).message)
				localStorage.removeItem(key)
				this.emit(key, null)
				return
			}

			this.emit(key, parsedValue.data)
		})
	}

	private isStorageKey(key: string): key is SafeLocalStorageKey {
		return key in SCHEMA.shape
	}

	public get<K extends SafeLocalStorageKey>(
		key: K,
		valueIfMissing: Value<K> = null
	): Result<Value<K>, LocalStorageError> {
		const [getItemError, value] = tryit(() => localStorage.getItem(key))

		if (getItemError) {
			return err({
				type: 'storage-not-avail',
				message: getErrorLog(getItemError),
			})
		}

		if (value === null) {
			return ok(valueIfMissing)
		}

		const parseResult = this.schema.shape[key].safeParse(value)

		if (!parseResult.success) {
			return err({
				type: 'parse-error',
				message: fromError(parseResult.error).message,
			})
		}

		return ok(parseResult.data as Value<K>)
	}

	public set<K extends SafeLocalStorageKey>(key: K, value: Value<K>): Result<{}, LocalStorageError> {
		const [error] = tryit(() => localStorage.setItem(key, JSON.stringify(value)))

		if (error) {
			return err({
				type: 'storage-not-avail',
				message: getErrorLog(error),
			})
		}

		// @ts-expect-error
		this.emit(key, value)

		return ok({})
	}

	public remove<K extends SafeLocalStorageKey>(key: K): Result<{}, LocalStorageError> {
		const [error] = tryit(() => localStorage.removeItem(key))

		if (error) {
			return err({
				type: 'storage-not-avail',
				message: getErrorLog(error),
			})
		}

		// @ts-expect-error
		this.emit(key, null)

		return ok({})
	}

	/**
	 * Notice that it won't clear the whole localStorage, **only the keys from the schema**.
	 */
	public clear(): Result<{}, LocalStorageError> {
		const results = getObjectKeys(this.schema.shape).map((key) => {
			return this.remove(key)
		})

		const allOk = results.every((result) => result.isOk())
		if (!allOk) {
			return err({
				type: 'storage-not-avail',
				message: 'failed to clear all keys',
			})
		}

		return ok({})
	}

	public getKeys(): SafeLocalStorageKey[] {
		return getObjectKeys(this.schema.shape)
	}

	public getContent(omitNulls = true) {
		return this.getKeys()
			.sort()
			.reduce<{ [K in SafeLocalStorageKey]: Value<K> }>(
				(acc, key) => {
					const value = this.get(key).unwrapOr(null)
					if (omitNulls && value === null) {
						return acc
					}

					// @ts-expect-error
					acc[key] = value

					return acc
				},
				{} as { [K in SafeLocalStorageKey]: Value<K> }
			)
	}

	public destroy(): void {
		window.removeEventListener('storage', this.listenToStorageEvent)
	}
}
