import { FontWeight, GameFonts } from '../../../GameFonts'
import { SimpleButton } from '../../../gui/buttons/SimpleButton'

export class CreditsContent extends Phaser.Group {
	private static readonly ROBOWHALE_URL: string = 'https://robowhale.com/?utm_source=get13_fbinstant'

	private back: Phaser.Image
	private title: Phaser.Text
	public backButton: SimpleButton
	private content: SimpleButton

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'credits')

		this.addBack()
		this.addTitle()
		this.addBackButton()
		this.addContent()
		this.alignContent()

		this.backButton.kill()
	}

	private addBack(): void {
		this.back = this.game.add.image(0, 0, 'main_menu', 'Settings_GUI_Back0000', this)
		this.back.alpha = 0
	}

	private addTitle(): void {
		let content: string = this.geTitleContent()
		let style: Phaser.PhaserTextStyle = {
			font: GameFonts.DEFAULT,
			fontWeight: FontWeight.BOLD,
			fontSize: 46,
			fill: '#F29000',
			align: 'center',
		}

		this.title = this.game.add.text(0, 0, content, style, this)
		this.title.anchor.set(0.5, 0.5)
		this.title.centerX = this.back.centerX
		this.title.centerY = this.back.top + 56
	}

	private geTitleContent(): string {
		return this.game.texts.texts.credits
	}

	private addBackButton(): void {
		this.backButton = new SimpleButton(this.game, 0, 0, 'main_menu', 'Button_Back0000', this)
		this.backButton.areTweensEnabled = false
		this.backButton.left = this.back.left
		this.backButton.centerY = this.title.centerY + 1
	}

	private addContent(): void {
		this.content = new SimpleButton(this.game, 0, 0, 'main_menu', 'credits_content0000', this)
		this.content.input.enabled = false
		// this.content.callback.add(this.onRobowhaleClick, this);
	}

	private alignContent() {
		let top: number = this.title.bottom
		let bottom: number = this.back.bottom
		let height: number = bottom - top

		this.content.centerX = this.back.centerX
		this.content.centerY = top + height / 2
	}

	private onRobowhaleClick(): void {
		window.open(CreditsContent.ROBOWHALE_URL)
	}

	public show(delay: number): void {
		this.visible = true
		this.exists = true

		this.backButton.enabled = true

		this.alpha = 0
		this.game.tweens.removeFrom(this)
		this.game.add.tween(this).to({ alpha: 1 }, 250, Phaser.Easing.Cubic.Out, true, delay)
	}

	public hide(): void {
		this.backButton.enabled = false

		this.game.tweens.removeFrom(this)
		this.game.add
			.tween(this)
			.to({ alpha: 0 }, 120, Phaser.Easing.Cubic.Out, true)
			.onComplete.addOnce(() => {
				this.exists = false
				this.visible = false
			})
	}

	public onLanguageChange() {
		this.title.text = this.geTitleContent()
	}

	public destroy(): void {
		super.destroy(true, false)
	}
}
