import { Config } from '../../../../Config'
import { BoosterType } from '../../boosters/BoosterType'
import { LevelGUI } from '../LevelGUI'
import { BoosterButton } from './BoosterButton'

export class BoostersPanel extends Phaser.Group {
	private back: Phaser.Image
	private gameOverBack: Phaser.Image
	private buttons: BoosterButton[]
	public onBoosterSelected: Phaser.Signal
	public onBoosterCanceled: Phaser.Signal

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'boosters_panel')

		this.onBoosterSelected = new Phaser.Signal()
		this.onBoosterCanceled = new Phaser.Signal()

		this.addBack()
		this.addGameOverBack()
		this.addBoostersButtons()
	}

	private addBack() {
		this.back = this.game.add.image(0, 0, 'interface', 'Panel_Back0000', this)
		this.back.tint = 0xf9b752
		this.back.name = 'simple_back'
	}

	private addGameOverBack() {
		this.gameOverBack = this.game.add.image(0, 0, 'interface', 'Panel_Back0000', this)
		this.gameOverBack.tint = LevelGUI.GAME_OVER_COLOR
		this.gameOverBack.visible = false
		this.gameOverBack.name = 'game_over_back'
	}

	private addBoostersButtons() {
		let boosterTypes: BoosterType[] = [
			BoosterType.MAGNET,
			BoosterType.UNDO,
			BoosterType.REMOVE,
			BoosterType.SORT,
			BoosterType.UPGRADE,
		]
		this.buttons = boosterTypes.map((type) => {
			return new BoosterButton(this.game, this, type)
		})
		this.buttons.forEach((button) => {
			button.onClick.add(this.onBoosterButtonClick, this)
			// button.onSelected.add(this.onBoosterButtonSelected, this);
		})
	}

	private onBoosterButtonClick(button: BoosterButton) {
		if (button.selected) {
			this.onBoosterCanceled.dispatch(button.boosterType)
		} else {
			this.game.audio.playSound('fancy_tap', 0.66)
			this.onBoosterSelected.dispatch(button.boosterType)
		}
	}

	private onBoosterButtonSelected(button: BoosterButton) {
		this.buttons.filter((candidate) => candidate !== button).forEach((button) => {
			button.deselect()
		})
	}

	public updateData(): void {
		this.buttons.forEach((button) => {
			button.updateData()
		})
	}

	public resize(height: number): void {
		this.back.width = Config.GAME_WIDTH
		this.back.height = height

		this.gameOverBack.width = this.back.width
		this.gameOverBack.height = this.back.height

		this.resizeButtons()
	}

	private resizeButtons() {
		let buttonWidth: number = this.back.width / this.buttons.length
		this.buttons.forEach((button, index: number) => {
			button.resize(buttonWidth, this.back.height)
			button.left = index * buttonWidth
			button.centerY = this.back.centerY
		})
	}

	public getButton(boosterType: BoosterType): BoosterButton {
		return this.buttons.find((button) => button.boosterType === boosterType)
	}

	public enableInput() {
		this.ignoreChildInput = false

		this.buttons.forEach((button: BoosterButton) => {
			button.ignoreChildInput = false
		})
	}

	public disableInput(): void {
		this.ignoreChildInput = true

		this.buttons.forEach((button: BoosterButton) => {
			button.ignoreChildInput = true
		})
	}

	public disableButtonsExcept(exception: BoosterButton) {
		this.buttons.forEach((button: BoosterButton) => {
			if (button !== exception) {
				button.ignoreChildInput = true
			}
		})
	}

	public deselectAllButtons() {
		this.buttons.forEach((button: BoosterButton) => {
			button.deselect()
		})
	}

	public setGameOverColors(): void {
		this.gameOverBack.visible = true
		this.gameOverBack.alpha = 0
		this.game.add.tween(this.gameOverBack).to({ alpha: 1 }, 450, Phaser.Easing.Cubic.Out, true)

		this.buttons.forEach((button) => {
			button.setGameOverColors()
		})
	}

	public setNormalColors(): void {
		this.game.add
			.tween(this.gameOverBack)
			.to({ alpha: 0 }, 150, Phaser.Easing.Cubic.Out, true)
			.onComplete.addOnce(() => {
				this.gameOverBack.visible = false
			})

		this.buttons.forEach((button) => {
			button.setNormalColors()
		})
	}

	public shakeButtons() {
		this.buttons.forEach((button) => {
			let boostersNum: number = this.game.boosters.getBooster(button.boosterType).num
			if (boostersNum > 0) {
				button.shake()
			}
		})
	}

	public destroy(): void {
		super.destroy(true, false)

		this.onBoosterSelected.dispose()
		this.onBoosterSelected = null
		this.onBoosterCanceled.dispose()
		this.onBoosterCanceled = null
	}
}
