import { BestItemCircle } from './../gameOver/circles/BestItemCircle'
import { StatCircle } from './../gameOver/circles/StatCircle'

export class MainMenuCircles extends Phaser.Group {
	private coinsCircle: StatCircle
	public bestItemCircle: BestItemCircle
	public gamesPlayedCircle: StatCircle
	private circles: StatCircle[]

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'circles')

		this.addCircles()

		this.bringToTop(this.bestItemCircle)
	}

	private addCircles(): void {
		let dx: number = 200
		let textColor: number = 0xf29000
		let circleTextureKey: string = 'main_menu'
		let circleTextureFrame: string = 'Circle0000'

		let coinsContent: string = this.game.save.getCoins().toString()
		this.coinsCircle = new StatCircle(
			this.game,
			this,
			circleTextureKey,
			circleTextureFrame,
			textColor,
			coinsContent
		)
		this.coinsCircle.addIcon('main_menu', 'Icon_Coin0000')
		this.coinsCircle.scale.set(0.9)
		this.coinsCircle.name = 'coins_circle'
		this.coinsCircle.centerX = -dx

		let bestItem: number = this.game.save.getValue('best_item') || 2
		this.bestItemCircle = new BestItemCircle(
			this.game,
			this,
			circleTextureKey,
			circleTextureFrame,
			textColor,
			bestItem.toString(),
			bestItem
		)
		this.bestItemCircle.innerCircle.loadTexture('main_menu', 'Circle_Inner0000')
		;(this.bestItemCircle.item.getAt(0) as Phaser.Image).loadTexture('main_menu', 'Item_Back0000')
		this.bestItemCircle.addIcon('main_menu', 'Icon_Crown0000')
		this.bestItemCircle.scale.set(1.13)
		this.bestItemCircle.name = 'best_item_circle'

		let gamesPlayerText = this.getGamesPlayedText()
		this.gamesPlayedCircle = new StatCircle(
			this.game,
			this,
			circleTextureKey,
			circleTextureFrame,
			textColor,
			gamesPlayerText
		)
		this.gamesPlayedCircle.addIcon('main_menu', 'Icon_Time0000')
		this.gamesPlayedCircle.text.scale.set(0.9)
		this.gamesPlayedCircle.text.y -= 5
		this.gamesPlayedCircle.scale.set(0.9)
		this.gamesPlayedCircle.centerX = dx

		this.circles = [this.coinsCircle, this.bestItemCircle, this.gamesPlayedCircle]
	}

	private getGamesPlayedText(): string {
		let gamesPlayedNum = this.game.save.getValue('games_played')
		let gamesPlayedTemplate = this.game.texts.texts.games
		let gamesPlayerText = gamesPlayedTemplate.replace('#', gamesPlayedNum + '\n')

		return gamesPlayerText
	}

	public show(initialDelay: number): void {
		this.visible = true

		this.circles.forEach((circle, index) => {
			let delay: number = initialDelay + 150 + index * 120
			this.game.add.tween(circle).from({ alpha: 0 }, 200, Phaser.Easing.Cubic.Out, true, delay)
			this.game.add.tween(circle).from({ y: '+22' }, 400, Phaser.Easing.Back.Out, true, delay)
			// .onComplete.addOnce(() => {
			// 	this.animateCircle(circle);
			// });
		})
	}

	private animateCircle(circle: StatCircle): void {
		this.game.add.tween(this).to({ y: '+16' }, 1000, Phaser.Easing.Sinusoidal.InOut, true, 0, -1, true)
	}

	public updateCoinsCircle(): void {
		let coins: number = this.game.save.getCoins()
		this.coinsCircle.updateText(coins.toString())
	}

	public onLanguageChange() {
		this.gamesPlayedCircle.updateText(this.getGamesPlayedText())
	}

	public destroy(): void {
		super.destroy(true, false)

		this.circles = null
	}
}
