import { attempt } from 'es-toolkit'
import { err, ok } from 'neverthrow'
import { until } from 'until-async'
import { getErrorLog } from '../robowhale/utils/error/utils'
import type { PlaygamaStorage, PlaygamaStorageType } from '../platform/playgama/PlaygamaPlatform'
import { BaseStorage, type BaseStorageOptions, type StorageLoadResult, type StorageSaveResult } from './BaseStorage'

const DEFAULT_STORAGE_KEY = 'state'
const DEFAULT_STORAGE_TYPE: PlaygamaStorageType = 'platform_internal'

export interface PlaygamaRemoteStorageOptions extends BaseStorageOptions {
	/** Playgama storage API instance. */
	storage: PlaygamaStorage
	/** Storage type to use. Defaults to "platform_internal". */
	storageType?: PlaygamaStorageType
	/** Storage key for serialized state. Defaults to "state". */
	key?: string
}

export class PlaygamaRemoteStorage extends BaseStorage {
	private readonly storage: PlaygamaStorage
	private readonly storageType: PlaygamaStorageType
	private readonly key: string

	constructor(options: PlaygamaRemoteStorageOptions) {
		super(options)

		this.storage = options.storage
		this.storageType = options.storageType ?? DEFAULT_STORAGE_TYPE
		this.key = options.key ?? DEFAULT_STORAGE_KEY
	}

	public async loadState(): Promise<StorageLoadResult> {
		const [error, data] = await until(() => Promise.resolve(this.storage.get(this.key, this.storageType)))
		if (error) {
			return err({ code: 'load_error', message: getErrorLog(error) })
		}

		if (data === null || data === undefined) {
			return ok({})
		}

		if (typeof data === 'string') {
			const [parseError, parsedValue] = attempt(() => JSON.parse(data))
			if (parseError) {
				return err({ code: 'invalid_state', message: getErrorLog(parseError) })
			}

			if (typeof parsedValue !== 'object' || parsedValue === null) {
				return err({ code: 'invalid_state', message: 'state is not an object' })
			}

			return ok(parsedValue as Record<string, unknown>)
		}

		const isObject = typeof data === 'object' && data !== null
		if (!isObject) {
			return err({ code: 'invalid_state', message: 'state is not an object' })
		}

		return ok(data as Record<string, unknown>)
	}

	public async saveState(state: Record<string, unknown>): Promise<StorageSaveResult> {
		if (!this._savesEnabled) {
			return err({ code: 'saves_disabled', message: 'saves are disabled' })
		}

		const [stringifyError, serialized] = attempt(() => JSON.stringify(state))
		if (stringifyError) {
			return err({ code: 'save_error', message: getErrorLog(stringifyError) })
		}

		const [error] = await until(() => Promise.resolve(this.storage.set(this.key, serialized, this.storageType)))
		if (error) {
			return err({ code: 'save_error', message: getErrorLog(error) })
		}

		return ok({})
	}

	public async clearState(): Promise<StorageSaveResult> {
		const [error] = await until(() => Promise.resolve(this.storage.delete(this.key, this.storageType)))
		if (error) {
			return err({ code: 'clear_error', message: getErrorLog(error) })
		}

		return ok({})
	}
}
