import { Cell } from './grid/Cell'
import { Grid } from './grid/Grid'
import { Item } from './items/Item'

export class DropStrategy {
	private game: Phaser.Game
	private grid: Grid
	private items: Item[]
	private dropDuration: number = 0
	public onDropComplete: Phaser.Signal

	constructor(_game: Phaser.Game, grid: Grid) {
		this.game = _game
		this.grid = grid
		this.onDropComplete = new Phaser.Signal()
	}

	public dropItems(items: Item[]): void {
		this.items = items
		this.dropDuration = 0
		this.doDrop()
	}

	private doDrop(): void {
		this.items.sort(this.sortItemsBottomUp)

		// calculate drop
		for (let i: number = 0; i < Grid.ROWS; i++) {
			this.items.forEach((item) => {
				let dropCell = this.findBottomFreeCell(item.cell)
				if (dropCell) {
					item.dropCell = dropCell
					item.linkCell(dropCell)
				}
			})
		}

		let itemsToDrop: Item[] = this.items.filter((item) => !!item.dropCell)
		let itemsToDropNum: number = itemsToDrop.length
		if (itemsToDropNum === 0) {
			this.onDropCompleteCallback()
			return
		}

		// do actual drop
		itemsToDrop.forEach((item) => {
			item.dropToCell(item.dropCell).onComplete.addOnce(() => {
				if (--itemsToDropNum === 0) {
					this.onDropCompleteCallback()
				}
			})
			item.dropCell = null
		})
	}

	private sortItemsBottomUp(item1: Item, item2: Item): number {
		let cell1: Cell = item1.cell
		let cell2: Cell = item2.cell

		if (cell1.row === cell2.row) return cell2.column - cell1.column
		else return cell2.row - cell1.row
	}

	private findBottomFreeCell(itemCell: Cell): Cell {
		let bottomCell: Cell = this.grid.getCellAt(itemCell.row + 1, itemCell.column)
		if (bottomCell && bottomCell.isFree()) {
			return bottomCell
		}

		return null
	}

	private findDropCell(itemCell: Cell): Cell {
		let bottomCell: Cell = this.grid.getCellAt(itemCell.row + 1, itemCell.column)
		if (bottomCell && bottomCell.isFree()) {
			return bottomCell
		}

		let rightCell: Cell = this.grid.getCellAt(itemCell.row, itemCell.column + 1)
		let bottomRightCell: Cell = this.grid.getCellAt(itemCell.row + 1, itemCell.column + 1)
		if (rightCell && rightCell.isFree() && bottomRightCell && bottomRightCell.isFree()) {
			return bottomRightCell
		}

		let leftCell: Cell = this.grid.getCellAt(itemCell.row, itemCell.column - 1)
		let bottomLeftCell: Cell = this.grid.getCellAt(itemCell.row + 1, itemCell.column - 1)
		if (leftCell && leftCell.isFree() && bottomLeftCell && bottomLeftCell.isFree()) {
			return bottomLeftCell
		}

		return null
	}

	private onDropCompleteCallback(): void {
		this.onDropComplete.dispatch()
	}

	public destroy(): void {
		this.game = null
		this.grid = null
		this.items = null

		this.onDropComplete.dispose()
		this.onDropComplete = null
	}
}
