import { GameFonts } from '../../../GameFonts'
import { Item } from './../../level/items/Item'
import { ShareButton } from './ShareButton'

export class ItemShareButton extends ShareButton {
	private itemType: number
	private darkColor: number
	private mainColor: number

	private itemBack: Phaser.Image
	private centralPart: Phaser.Image
	private titleText: Phaser.BitmapText
	private item: Phaser.Group
	private highscoreText: Phaser.BitmapText
	private delayedCall: Phaser.TimerEvent

	constructor(_game: Phaser.Game, parent: Phaser.Group, itemType: number) {
		super(_game, parent)

		this.itemType = itemType
		this.mainColor = Item.getBackColor(itemType)
		this.darkColor = Item.getTextColor(itemType)

		this.addItemBack()
		this.addGradient()
		this.addCentralPart()
		this.addTitle()
		this.addItem()
		this.addStars()
		this.addHashtag()

		this.hint.tint = this.mainColor
	}

	private addItemBack(): void {
		this.itemBack = this.game.add.image(0, 0, 'game_over', 'Item_Share_Back0000', this)
		this.itemBack.tint = this.darkColor
		this.itemBack.centerX = this.back.centerX
		this.itemBack.top = this.back.top
	}

	private addGradient(): void {
		let alpha: number = 0.2
		let scale: number = 1.32
		let gradientsNum: number = 4
		let deltaScale: number = (scale - 1) / gradientsNum

		for (let i: number = 0; i < gradientsNum; i++) {
			let gradient: Phaser.Image = this.game.add.image(0, 0, 'game_over', 'Item_Share_Back_Central0000', this)
			gradient.anchor.set(0.5, 0.5)
			gradient.scale.x = scale
			gradient.centerX = this.itemBack.centerX
			gradient.centerY = this.itemBack.centerY
			gradient.tint = this.mainColor
			gradient.alpha = alpha

			scale -= deltaScale
		}
	}

	private addCentralPart(): void {
		this.centralPart = this.game.add.image(0, 0, 'game_over', 'Item_Share_Back_Central0000', this)
		this.centralPart.tint = this.mainColor
		this.centralPart.anchor.set(0.5, 0.5)
		this.centralPart.centerX = this.itemBack.centerX
		this.centralPart.centerY = this.itemBack.centerY
	}

	private addTitle(): void {
		let content: string = 'BEAT THIS'

		this.titleText = this.game.add.bitmapText(0, 0, GameFonts.GAME_OVER_BARIOL_BOLD, content, 35, this)
		this.titleText.anchor.set(0.5, 0.5)
		this.titleText.centerX = this.itemBack.centerX
		this.titleText.centerY = this.itemBack.top + 40
	}

	private addItem(): void {
		let shadow: Phaser.Image = this.game.add.image(0, 6, 'game_over', 'White_Circle0000')
		shadow.anchor.set(0.5, 0.5)
		shadow.tint = this.darkColor
		shadow.alpha = 0.4

		let back: Phaser.Image = this.game.add.image(0, 0, 'game_over', 'White_Circle0000')
		back.anchor.set(0.5, 0.5)

		let text: Phaser.BitmapText = this.game.add.bitmapText(
			0,
			0,
			GameFonts.GAME_OVER_BARIOL_BOLD,
			this.itemType.toString(),
			46
		)
		text.tint = this.mainColor
		text.anchor.set(0.5, 0.5)

		this.item = this.game.add.group(this, 'item')
		this.item.addMultiple([shadow, back, text], true)
		this.alignItem()
	}

	private alignItem() {
		let top: number = this.titleText.bottom
		let bottom: number = this.itemBack.bottom
		let height: number = bottom - top

		this.item.centerX = this.itemBack.centerX
		this.item.centerY = top + height / 2
	}

	private addStars(): void {
		let stars: Phaser.Image = this.game.add.image(0, 0, 'game_over', 'Item_Share_Stars0000', this)
		stars.anchor.set(0.5, 0.5)
		stars.x = this.item.centerX
		stars.y = this.item.centerY - 6
	}

	public animate(delay: number): void {
		this.game.add
			.tween(this.scale)
			.to(
				{ x: this.scale.x * 1.1, y: this.scale.y * 1.1 },
				500,
				Phaser.Easing.Sinusoidal.InOut,
				true,
				delay,
				2,
				true
			)
			.onComplete.addOnce(() => {
				this.game.time.events.add(3000, this.animate, this)
			})
	}

	public showHighscore(): void {
		this.addHighscore()
		this.animateHighscore()

		this.hint.visible = false
	}

	private addHighscore(): void {
		let content: string = this.game.texts.texts['highscore']

		this.highscoreText = this.game.add.bitmapText(0, 0, GameFonts.GAME_OVER_BARIOL_BOLD, content, 30, this)
		this.highscoreText.anchor.set(0.5, 0.5)
		this.highscoreText.centerX = this.itemBack.centerX
		this.highscoreText.centerY = this.hint.y
		this.highscoreText.tint = this.mainColor
	}

	private animateHighscore(): void {
		this.highscoreText.alpha = 0
		this.highscoreText.visible = true

		let fadeDuration: number = 230

		this.game.add
			.tween(this.highscoreText)
			.to({ alpha: 1 }, fadeDuration, Phaser.Easing.Cubic.Out, true, 200)
			.onComplete.addOnce(() => {
				this.game.add
					.tween(this.highscoreText)
					.to({ alpha: 0.6 }, 360, Phaser.Easing.Sinusoidal.InOut, true, 0, 2, true)
					.onComplete.addOnce(() => {
						this.game.add
							.tween(this.highscoreText)
							.to({ alpha: 0 }, fadeDuration, Phaser.Easing.Cubic.Out, true)
							.onComplete.addOnce(() => {
								this.highscoreText.visible = false
								this.animateHint()
							})
					})
			})
	}

	private animateHint(): void {
		this.hint.alpha = 0
		this.hint.visible = true

		let fadeDuration: number = 230

		this.game.add
			.tween(this.hint)
			.to({ alpha: 1 }, fadeDuration, Phaser.Easing.Cubic.Out, true, 200)
			.onComplete.addOnce(() => {
				this.game.add
					.tween(this.hint)
					.to({ alpha: 0.6 }, 360, Phaser.Easing.Sinusoidal.InOut, true, 0, 2, true)
					.onComplete.addOnce(() => {
						this.game.add
							.tween(this.hint)
							.to({ alpha: 0 }, fadeDuration, Phaser.Easing.Cubic.Out, true)
							.onComplete.addOnce(() => {
								this.hint.visible = false
								this.animateHighscore()
							})
					})
			})
	}

	public destroy(): void {
		if (this.highscoreText) {
			this.game.tweens.removeFrom(this.highscoreText)
		}

		this.game.tweens.removeFrom(this.hint)
		this.game.tweens.removeFrom(this)

		super.destroy()
	}
}
