import { TypedEmitter } from 'tiny-typed-emitter'

type Events = {
	'hide-start': () => void
	'hide-complete': () => void
}

export interface WaitingScreenShowOptions {
	reason: string
	reasonExtra?: Record<string, unknown>
	showDelayMs?: number
	text?: string
}

export class WaitingScreen extends TypedEmitter<Events> {
	private container: HTMLDivElement
	private spinner: HTMLImageElement
	private textElement: HTMLDivElement
	private showTimeout: number | null = null
	private hideAnimationEndHandler: (() => void) | null = null

	constructor() {
		super()

		// Get existing elements
		this.container = document.getElementById('waiting-screen') as HTMLDivElement
		if (!this.container) throw new Error('Waiting screen container not found')

		this.spinner = this.container.querySelector('.waiting-screen__spinner') as HTMLImageElement
		if (!this.spinner) throw new Error('Waiting screen spinner not found')

		this.textElement = this.container.querySelector('.waiting-screen__text') as HTMLDivElement
		if (!this.textElement) throw new Error('Waiting screen text element not found')

		// Add animation end listener
		this.container.addEventListener('animationend', (e) => {
			if (e.animationName === 'fade-out' && this.hideAnimationEndHandler) {
				this.container.classList.remove('visible', 'hiding')
				this.hideAnimationEndHandler()
				this.hideAnimationEndHandler = null
				this.emit('hide-complete')
			}
		})
	}

	public show(options: WaitingScreenShowOptions) {
		// Clear any existing timeout
		if (this.showTimeout !== null) {
			window.clearTimeout(this.showTimeout)
			this.showTimeout = null
		}

		// Update text if provided
		if (options.text) {
			this.textElement.textContent = options.text
			this.textElement.style.display = 'block'
		} else {
			this.textElement.style.display = 'none'
		}

		// Show after delay
		if (options.showDelayMs) {
			this.showTimeout = window.setTimeout(() => {
				this.container.classList.add('visible')
				this.showTimeout = null
			}, options.showDelayMs)
		} else {
			this.container.classList.add('visible')
		}
	}

	public hide() {
		// Clear any pending show
		if (this.showTimeout !== null) {
			window.clearTimeout(this.showTimeout)
			this.showTimeout = null
		}

		this.emit('hide-start')

		// If not visible, complete immediately
		if (!this.container.classList.contains('visible')) {
			this.emit('hide-complete')
			return
		}

		// Start hide animation
		this.container.classList.add('hiding')
		this.hideAnimationEndHandler = () => {
			this.container.classList.remove('visible', 'hiding')
		}
	}

	public destroy() {
		if (this.showTimeout !== null) {
			window.clearTimeout(this.showTimeout)
		}
		this.container.removeEventListener('animationend', this.hideAnimationEndHandler as any)
		this.removeAllListeners()
	}
}
