import { TutorialTopPanel } from './TutorialTopPanel';
import { Finger } from './Finger';
import { Config } from '../../../Config'
import { BoosterType } from '../boosters/BoosterType'
import { Cell } from '../grid/Cell'
import { Grid } from '../grid/Grid'
import { Item } from '../items/Item'
import { Level } from '../Level'

export class Tutorial extends Phaser.Group {
	private topPanel: TutorialTopPanel
	private finger: Finger
	private level: Level
	public allowedItems: Item[]
	private clicks: number = 0
	public onComplete: Phaser.Signal
	public isComplete: boolean = false

	constructor(_game: Phaser.Game, parent: Phaser.Group, level: Level) {
		super(_game, parent, 'tutorial')

		this.onComplete = new Phaser.Signal()

		this.level = level
		this.prepareGrid()
		this.initAllowedItems()
		this.addFinger()
		this.addText()
	}

	private prepareGrid(): void {
		this.level.activeItems.forEach((item: Item) => {
			item.setItemType(2)
		})

		this.level.activeItems[0].setItemType(1)
		this.level.activeItems[this.level.activeItems.length - 1].setItemType(1)
	}

	public initAllowedItems(): void {
		var grid: Grid = this.level.grid

		this.allowedItems = [grid.getCellAt(3, 1).item, grid.getCellAt(2, 2).item, grid.getCellAt(1, 2).item]

		this.allowedItems.forEach((item: Item) => {
			item.setItemType(1)
		})
	}

	private addFinger(): void {
		this.finger = new Finger(this.game)
		this.add(this.finger)
	}

	private addText(): void {
		this.topPanel = new TutorialTopPanel(this.game, this)
		this.topPanel.x = (Config.GAME_WIDTH - this.topPanel.width) * 0.5
	}

	public show(): void {
		this.parent.bringToTop(this)

		this.game.sound.play('tutorial', 0.5)

		this.level.pointerEnabled = false
		this.level.gui.topPanel.hideForTutorial()

		this.topPanel.show()
		this.topPanel.hideSubtitle()
		this.level.onFirstComboComplete.addOnce(this.onFirstComboComplete, this)
		this.level.pointerEnabled = true

		this.game.time.events.add(100, () => {
			this.showCombineTutorial()
		})
	}

	private onInputDown(pointer: Phaser.Pointer): void {
		switch (this.clicks) {
			case 0:
				this.game.input.onDown.remove(this.onInputDown, this)
				this.topPanel.showNextLine()
				this.showUndoTutorial()
				this.level.gui.boostersPanel.onBoosterSelected.addOnce(this.onUndoComplete, this)
				break

			case 1:
				this.game.input.onDown.remove(this.onInputDown, this)
				this.topPanel.showNextLine()
				this.level.gui.boostersPanel.getButton(BoosterType.REMOVE).stopHighlightForTutorial()
				this.level.onFirstBoosterComplete.addOnce(this.onRemoveBoosterComplete, this)
				this.finger.stopAndHide()
				break

			default:
				if (this.topPanel.isLastLine) {
					this.game.input.onDown.remove(this.onInputDown, this)
					this.level.gui.topPanel.enableButtons()
					this.hide()
				} else {
					this.topPanel.showNextLine()
				}
				break
		}

		this.clicks++
	}

	private showCombineTutorial(): void {
		this.fadeOutItems()
		this.moveFingerAlongPath()
	}

	private fadeOutItems(): void {
		this.level.activeItems.forEach((item) => {
			if (this.allowedItems.indexOf(item) === -1) {
				item.alpha = 0.33
			}
		})
	}

	private moveFingerAlongPath(): void {
		var path: Phaser.Point[] = this.createPath()
		this.finger.followPath(path)
	}

	private createPath(): Phaser.Point[] {
		var grid: Grid = this.level.grid
		var cells: Cell[] = [grid.getCellAt(3, 1), grid.getCellAt(2, 2), grid.getCellAt(1, 2)]

		let path: Phaser.Point[] = cells.map((cell: Cell) => {
			let point: Phaser.Point = cell.parent.toGlobal(cell.position).toPhaser()
			point.add(Finger.OFFSET.x, Finger.OFFSET.y)

			return point
		})

		return path
	}

	private onFirstComboComplete(): void {
		this.fadeInAllItems()
		this.level.pointerEnabled = false
		this.finger.stopAndHide()
		this.topPanel.showNextLine()

		this.game.input.onDown.add(this.onInputDown, this)
	}

	private fadeInAllItems(): void {
		var l: number = this.level.activeItems.length
		for (var i: number = 0; i < l; i++) {
			this.level.activeItems[i].alpha = 1
		}
	}

	private showUndoTutorial(): void {
		var buttonWidth: number = Config.GAME_WIDTH / 5
		var undoButtonIndex: number = 2
		var fingerX: number = undoButtonIndex * buttonWidth - buttonWidth * 0.5 + 6
		var fingerY: number = Config.GAME_HEIGHT - 88

		this.finger.pointAt(fingerX, fingerY)

		this.game.boosters.boosters.forEach((booster) => {
			booster.num = 0
		})
		this.game.boosters.getBooster(BoosterType.UNDO).num = 1
		this.level.gui.boostersPanel.updateData()

		this.level.gui.boostersPanel.enableInput()
		this.level.gui.boostersPanel.getButton(BoosterType.UNDO).highlightForTutorial()
	}

	private onUndoComplete(): void {
		this.level.gui.boostersPanel.onBoosterSelected.remove(this.onUndoComplete, this)
		this.level.gui.boostersPanel.getButton(BoosterType.UNDO).stopHighlightForTutorial()
		this.allowedItems.length = 0
		this.finger.stopAndHide()
		this.level.pointerEnabled = false

		this.topPanel.showNextLine()
		this.showRemoveBoosterTutorial()
	}

	private showRemoveBoosterTutorial(): void {
		var buttonWidth: number = Config.GAME_WIDTH / 5
		var undoButtonIndex: number = 3
		var fingerX: number = undoButtonIndex * buttonWidth - buttonWidth * 0.5 + 6
		var fingerY: number = Config.GAME_HEIGHT - 88 * Config.ASSETS_SCALE

		this.game.boosters.getBooster(BoosterType.REMOVE).num = 1
		this.finger.pointAt(fingerX, fingerY)
		this.level.gui.boostersPanel.getButton(BoosterType.REMOVE).updateData()
		this.level.gui.boostersPanel.getButton(BoosterType.REMOVE).highlightForTutorial()

		this.game.input.onDown.add(this.onInputDown, this)
	}

	private onRemoveBoosterComplete(): void {
		this.level.onFirstBoosterComplete.remove(this.onRemoveBoosterComplete, this)
		this.level.pointerEnabled = false
		this.topPanel.showNextLine()

		this.level.gui.topPanel.disableInput()

		this.game.input.onDown.add(this.onInputDown, this)

		this.level.pointerEnabled = true
		this.isComplete = true
	}

	private hide(): void {
		this.level.gui.topPanel.showAfterTutorial()

		this.game.add
			.tween(this.topPanel)
			.to({ alpha: 0 }, 200, Phaser.Easing.Cubic.Out, true)
			.onComplete.addOnce(() => {
				this.onHideComplete()
			})
	}

	private onHideComplete(): void {
		this.visible = false
		this.onComplete.dispatch()
	}

	public resize(height: number): void {
		this.topPanel.resize(height)
	}

	public destroy(): void {
		super.destroy(true, false)

		this.level = null
		this.allowedItems = null

		this.onComplete.dispose()
		this.onComplete = null
	}
}
