import { FontWeight, GameFonts } from '../../../../GameFonts'
import { SimpleButton } from '../../../../gui/buttons/SimpleButton'
import { BoosterType } from '../../boosters/BoosterType'
import { Cell } from '../../grid/Cell'
import { Grid } from '../../grid/Grid'

export class BoosterHint extends Phaser.Group {
	private back: Phaser.Image
	private text: Phaser.Text
	private cancelButton: SimpleButton
	public onCancel: Phaser.Signal
	private wasResized: boolean = false

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'booster_hint')

		this.onCancel = new Phaser.Signal()

		this.addBack()
		this.addCancelButton()
		this.addHintText()
		this.alignText()

		this.game.time.events.add(
			50,
			() => {
				this.kill()
			},
			this
		)
	}

	private addBack(): void {
		this.back = this.game.add.image(0, 0, 'interface', 'Panel_Back0000', this)
		this.back.width = Cell.WIDTH * Grid.COLUMNS
		this.back.height = 100
		this.back.tint = 0xf8a122
	}

	private addCancelButton(): void {
		this.cancelButton = new SimpleButton(this.game, 0, 0, 'interface', 'Booster_Hint_Close0000', this)
		this.cancelButton.callback.add(this.onCancelButtonClick, this)
		this.cancelButton.centerX = this.back.left + this.back.width * 0.8
		this.cancelButton.centerY = this.back.centerY
	}

	private onCancelButtonClick(): void {
		this.onCancel.dispatch()
	}

	private addHintText(): void {
		let content = this.game.boosters.getBooster(BoosterType.MAGNET).hint
		let style = {
			font: GameFonts.DEFAULT,
			fontWeight: FontWeight.BOLD,
			fontSize: 30,
			fill: '#ffffff',
			align: 'center',
		}

		this.text = this.game.add.text(0, 0, content, style, this)
		this.text.anchor.set(0.5, 0.5)
		this.text.lineSpacing = -6
		this.text.align = 'center'
	}

	private alignText() {
		let left: number = this.back.left
		let right: number = this.cancelButton.left
		let width: number = right - left
		let maxWidth: number = width * 0.85
		let maxHeight: number = this.back.height * 0.85

		this.text.scale.set(1)
		this.text.wordWrap = true
		this.text.wordWrapWidth = maxWidth
		if (this.text.width > maxWidth || this.text.height > maxHeight) {
			let scaleX: number = maxWidth / this.text.width
			let scaleY: number = maxHeight / this.text.height
			let scale: number = Math.min(scaleX, scaleY)
			this.text.scale.set(scale)
		}

		this.text.centerX = left + width / 2
		this.text.centerY = this.back.centerY
	}

	public updateContent(content: string): void {
		this.text.setText(content)
		this.alignText()
	}

	public show(): void {
		this.game.tweens.removeFrom(this)

		this.visible = true
		this.exists = true

		this.alpha = 1
		this.game.add.tween(this).from({ alpha: 0 }, 150, Phaser.Easing.Cubic.Out, true)
		this.game.add.tween(this).from({ y: '-10' }, 250, Phaser.Easing.Cubic.Out, true)
	}

	public hide(): void {
		this.game.add
			.tween(this)
			.to({ alpha: 0 }, 150, Phaser.Easing.Cubic.Out, true)
			.onComplete.addOnce(() => {
				this.visible = false
				this.exists = false
			})
	}

	public hideInstant() {
		this.visible = false
		this.exists = false
	}

	public resize(width: number, height: number): void {
		this.back.width = width
		this.back.height = height

		this.cancelButton.right = this.back.right - 20
		this.cancelButton.centerY = this.back.centerY

		this.alignText()
	}

	public destroy(): void {
		super.destroy(true, false)

		this.onCancel.dispose()
		this.onCancel = null
	}
}
