import { Config } from '../Config'
import type { IGameController, ISceneNode } from './IGameController'

// Phaser CE extends PIXI.DisplayObject with a name property at runtime
type NamedDisplayObject = PIXI.DisplayObject & { name?: string }

export class GameController implements IGameController {
	constructor(public readonly game: Phaser.Game) {}

	getGameSize() {
		return { width: this.game.width, height: this.game.height }
	}

	getCanvasSize() {
		const canvas = this.game.canvas
		return { width: canvas.width, height: canvas.height }
	}

	getWorldScale() {
		return Config.WORLD_SCALE
	}

	getScaleMode() {
		return this.game.scaler?.scaleMode ?? 'unknown'
	}

	getRendererType(): 'webgl' | 'canvas' {
		return this.game.renderType === Phaser.WEBGL ? 'webgl' : 'canvas'
	}

	getRendererInfo() {
		return {
			type: this.getRendererType(),
			resolution: this.game.resolution,
		}
	}

	getFPS() {
		return this.game.time.fps
	}

	getDesiredFPS() {
		return this.game.time.desiredFps
	}

	getElapsedTime() {
		return this.game.time.totalElapsedSeconds()
	}

	getCurrentState() {
		return this.game.state.current
	}

	getPendingState(): string | null {
		// Phaser CE stores pending state internally
		const stateManager = this.game.state as any
		return stateManager._pendingState ?? null
	}

	getPlatformType() {
		return this.game.platform?.type ?? 'unknown'
	}

	isFullscreen() {
		return window.ysdk?.screen?.fullscreen?.status === 'on'
	}

	getDeviceType() {
		return this.game.device.desktop ? 'desktop' : 'mobile'
	}

	isSoundMuted() {
		return this.game.audio?.soundMute ?? false
	}

	isMusicMuted() {
		return this.game.audio?.musicMute ?? false
	}

	getSaveState(): Record<string, unknown> {
		if (!this.game.save) return {}
		// Access internal state via getValue for each known key
		// Since _state is private, we'll return a basic snapshot
		const save = this.game.save
		return {
			coins: save.getCoins(),
		}
	}

	getMemoryInfo(): { usedJSHeapSize?: number; totalJSHeapSize?: number } | null {
		const perf = performance as Performance & {
			memory?: { usedJSHeapSize: number; totalJSHeapSize: number }
		}
		if (!perf.memory) return null
		return {
			usedJSHeapSize: perf.memory.usedJSHeapSize,
			totalJSHeapSize: perf.memory.totalJSHeapSize,
		}
	}

	// Scene tree methods
	getSceneTree(depth = 3): ISceneNode {
		return this.serializeNode(this.game.world, 'world', depth)
	}

	getWorldChildren(): ISceneNode[] {
		return this.game.world.children.map((child, i) => {
			const named = child as NamedDisplayObject
			return this.serializeNode(child, `world/${named.name || i}`, 1)
		})
	}

	getObjectByName(name: string): ISceneNode | null {
		const obj = this.findByName(this.game.world, name)
		if (!obj) return null
		return this.serializeNode(obj.node, obj.path, 0)
	}

	getObjectAtPath(path: string): ISceneNode | null {
		const parts = path.split('/')
		let current: PIXI.DisplayObject = this.game.world

		for (let i = 1; i < parts.length; i++) {
			// skip 'world'
			const part = parts[i]
			const container = current as PIXI.DisplayObjectContainer
			if (!container.children) return null

			const child =
				container.children.find((c) => (c as NamedDisplayObject).name === part) ??
				container.children[parseInt(part)]
			if (!child) return null
			current = child
		}

		return this.serializeNode(current, path, 1)
	}

	private serializeNode(obj: PIXI.DisplayObject, path: string, depth: number): ISceneNode {
		const named = obj as NamedDisplayObject
		const container = obj as PIXI.DisplayObjectContainer
		const children = container.children ?? []

		return {
			name: named.name || '(unnamed)',
			type: obj.constructor.name,
			path,
			visible: obj.visible,
			alive: (obj as any).alive ?? true,
			position: { x: obj.x, y: obj.y },
			scale: { x: obj.scale.x, y: obj.scale.y },
			alpha: obj.alpha,
			childCount: children.length,
			children:
				depth > 0
					? children.map((c, i) => {
							const childNamed = c as NamedDisplayObject
							return this.serializeNode(c, `${path}/${childNamed.name || i}`, depth - 1)
						})
					: undefined,
		}
	}

	private findByName(
		root: PIXI.DisplayObject,
		name: string,
		path = 'world'
	): { node: PIXI.DisplayObject; path: string } | null {
		const named = root as NamedDisplayObject
		if (named.name === name) return { node: root, path }

		const container = root as PIXI.DisplayObjectContainer
		if (!container.children) return null

		for (let i = 0; i < container.children.length; i++) {
			const child = container.children[i]
			const childNamed = child as NamedDisplayObject
			const childPath = `${path}/${childNamed.name || i}`
			const found = this.findByName(child, name, childPath)
			if (found) return found
		}
		return null
	}
}
