import { Config } from '../../../Config'
import { GameFonts } from '../../../GameFonts'
import { Item } from '../../level/items/Item'
import { StatCircle } from './StatCircle'

export class BestItemCircle extends StatCircle {
	public item: Phaser.Group
	private digit: Phaser.BitmapText

	constructor(
		_game: Phaser.Game,
		parent: Phaser.Group,
		circleTextureKey: string,
		circleTextureFrame: string,
		textColor: number,
		textContent: string,
		itemType: number
	) {
		super(_game, parent, circleTextureKey, circleTextureFrame, textColor, textContent)

		this.text.visible = false
		this.addInnerCircle()
		this.addItem(itemType)
	}

	private addItem(itemType: number): void {
		let back: Phaser.Image = this.game.add.image(0, 0, 'game_over', 'Item_Back0000')
		back.anchor.set(0.5, 0.5)
		back.tint = Item.getBackColor(itemType)

		let text: Phaser.BitmapText = this.game.add.bitmapText(0, 0, GameFonts.BARIOL_BOLD_BMP, itemType.toString(), 42)
		text.anchor.set(0.5, 0.5)
		text.tint = Item.getTextColor(itemType)

		this.item = this.game.add.group(this, 'item')
		this.item.addMultiple([back, text], true)
		this.item.scale.set(1.2)
		this.item.x = this.circle.centerX
		this.item.y = this.circle.centerY
	}

	public setItemFont(font: string) {
		if (this.item && this.item.getAt(1) && this.item.getAt(1) instanceof Phaser.BitmapText) {
			;(this.item.getAt(1) as Phaser.BitmapText).font = font
		}
	}

	public animateIcon(): void {
		this.game.add.tween(this.icon).to({ y: '-10' }, 330, Phaser.Easing.Sinusoidal.InOut, true, 0, -1, true)
	}

	public animateItem(): void {
		this.game.add.tween(this.item.scale).to(
			{
				x: 1.33,
				y: 1.33,
			},
			900,
			Phaser.Easing.Sinusoidal.InOut,
			true,
			0,
			-1,
			true
		)
	}

	public addIcon(iconTextureKey: string, iconTextureFrame?: string): void {
		super.addIcon(iconTextureKey, iconTextureFrame)

		this.icon.y -= 10 * Config.ASSETS_SCALE
		this.bringToTop(this.item)
	}

	public destroy(): void {
		this.game.tweens.removeFrom(this.item.scale)

		if (this.icon) {
			this.game.tweens.removeFrom(this.icon)
		}

		super.destroy()
	}
}
