import { Config } from "../../Config"
import { GameFonts, FontWeight } from "../../GameFonts"

export class GameOverTopPanel extends Phaser.Group {
    private back: Phaser.Image
    private title: Phaser.Text
    private leftRhombs: Phaser.Image
    private rightRhombs: Phaser.Image

    constructor(_game: Phaser.Game, parent: Phaser.Group) {
        super(_game, parent, 'game_over_top')

        this.addBack()
        this.addTitle()
        this.addRhombuses()

        this.bringToTop(this.title)
    }

    private addBack(): void {
        this.back = this.game.add.image(0, 0, 'game_over', 'Top_Panel_Back0000', this)
    }

    private addTitle(): void {
        let content: string = this.game.texts.texts['game_over']
        let style: Phaser.PhaserTextStyle = {
            font: GameFonts.DEFAULT,
            fontWeight: FontWeight.BOLD,
            fontSize: 56,
            fill: '#ffffff',
            align: 'center',
        }

        this.title = this.game.add.text(0, 0, content, style, this)
        this.title.anchor.set(0.5, 0.5)
    }

    private addRhombuses(): void {
        let y: number = this.back.height * 0.5
        let dx: number = this.back.width * 0.34
        let titleMargin: number = 20

        this.leftRhombs = this.game.add.image(0, 0, 'game_over', 'Top_Panel_Rhombuses0000', this)
        this.leftRhombs.anchor.set(1, 0.5)
        this.leftRhombs.x = this.title.left - titleMargin
        this.leftRhombs.y = y

        this.rightRhombs = this.game.add.image(0, 0, 'game_over', 'Top_Panel_Rhombuses0000', this)
        this.rightRhombs.scale.x = -1
        this.rightRhombs.left = this.title.right + 20
        this.rightRhombs.x = Math.round(this.back.width * 0.5 + dx)
        this.rightRhombs.y = y

        if (this.title.width > 400) {
            this.rightRhombs.kill()
            this.leftRhombs.kill()
        }
    }

    public show(initialDelay: number): void {
        let offsetY: number = 60 * Config.ASSETS_SCALE

        this.alpha = 0
        this.y -= offsetY
        this.game.add.tween(this).to(
            {
                y: this.y + offsetY,
                alpha: 1,
            },
            400,
            Phaser.Easing.Cubic.Out,
            true,
            initialDelay
        )

        this.showRhombuses(initialDelay)
    }

    private showRhombuses(initialDelay: number): void {
        let offsetX: number = 66 * Config.ASSETS_SCALE
        let duration: number = 660
        let delay: number = initialDelay + 200

        this.game.add.tween(this.leftRhombs).from(
            {
                x: this.leftRhombs.x - offsetX,
                alpha: 0,
            },
            duration,
            Phaser.Easing.Cubic.Out,
            true,
            delay
        )

        this.game.add.tween(this.rightRhombs).from(
            {
                x: this.rightRhombs.x + offsetX,
                alpha: 0,
            },
            duration,
            Phaser.Easing.Cubic.Out,
            true,
            delay
        )
    }

    public resize(): void {
        this.back.width = Config.GAME_WIDTH

        this.title.centerX = this.back.centerX
        this.title.centerY = this.back.centerY + 2

        let titleMargin: number = 24
        this.leftRhombs.right = this.title.left - titleMargin
        this.leftRhombs.centerY = this.title.centerY

        this.rightRhombs.right = this.title.right + titleMargin
        this.rightRhombs.centerY = this.title.centerY
    }

    public destroy(): void {
        super.destroy(true, false)
    }
}
