export class PIXIExtensions {
    public static extend() {
        PIXI.Rectangle.prototype.toPhaser = function (): Phaser.Rectangle {
            return new Phaser.Rectangle(this.x, this.y, this.width, this.height)
        }

        PIXI.Point.prototype.toPhaser = function (): Phaser.Point {
            return new Phaser.Point(this.x, this.y)
        }

        PIXI.DisplayObjectContainer.prototype.bringToTop = function (child: PIXI.DisplayObject) {
            this.setChildIndex(child, this.children.length - 1)
        }

        Object.defineProperty(PIXI.DisplayObjectContainer.prototype, 'numChildren', {
            get: function () {
                return this.children.length
            },
        })
    }
}
