export class LanguageUtil {
    public static LANGUAGES_MAP = {
        ru: 'Русский',
        en: 'English',
        fr: 'Français',
        it: 'Italiano',
        de: 'Deutsch',
        es: 'Español',
        nl: 'Nederlands',
        no: 'Norsk',
        fi: 'Suomi',
        br: 'Brasileiro',
        pt: 'Português',
        jp: '日本語',
        ar: 'العربية',
        tr: 'Türkçe',
        se: 'Svenska',
        pl: 'Polski',
    }

    public static getLanguageTitle(shortCode: string): string {
        return this.LANGUAGES_MAP[shortCode]
    }

    public static convertLanguageCodeToGameLanguage(code: string): string {
        switch (code) {
            case 'pt-BR':
                return 'br'

            case 'ja':
                return 'jp'

            default:
                return code.split('-')[0].toLowerCase()
        }
    }
}
