import prettyMs from 'pretty-ms'
import { Logger } from 'tslog'
import { until } from 'until-async'
import { toReadableDateString } from '../../scripts/utils/readable-date-string'
import { SafeLocalStorage } from '../robowhale/storage/SafeLocalStorage'
import { toMs } from '../vendors/to-milliseconds'
import { VisibilityService } from '../visibility/VisibilityService'

type TimeServiceOptions = {
	/** server time in **milliseconds** */
	serverTimeGetter: () => Promise<number>

	visibility: VisibilityService

	logger: Logger<unknown>

	/** in seconds */
	startTime: { local: number; server: number }

	debugStorage: SafeLocalStorage
}

export class TimeService {
	private options: TimeServiceOptions
	private logger: Logger<unknown>
	private originalDateNow: () => number
	private _localTimeOffsetMs = 0
	private _serverTimeOffsetMs = 0
	/** таймстамп (серверное время, в миллисекундах) */
	private serverTime: number
	/** performance.now() at last successful sync (or initialization) */
	private lastServerSyncPerfNowMs: number
	/** server absolute time (ms) at the same sync moment */
	private serverTimeAtLastSyncMs: number

	constructor(options: TimeServiceOptions) {
		this.options = options
		this.logger = options.logger

		this.serverTime = options.startTime.server
		this.serverTimeAtLastSyncMs = this.serverTime
		this.lastServerSyncPerfNowMs = performance.now()

		this.logger.info(`local time on start ${toReadableDateString(this.options.startTime.local)}`)
		this.logger.info(`server time on start ${toReadableDateString(this.serverTime)}`)

		this.originalDateNow = Date.now

		const localTimeOffsetMinutes = this.options.debugStorage.get('localTimeOffsetMinutes').unwrapOr(0)
		if (Number.isInteger(localTimeOffsetMinutes)) {
			this.applyLocalTimeOffset(toMs({ minutes: localTimeOffsetMinutes }))
		}

		const serverTimeOffsetMinutes = this.options.debugStorage.get('serverTimeOffsetMinutes').unwrapOr(0)
		if (Number.isInteger(serverTimeOffsetMinutes)) {
			this.applyServerTimeOffset(toMs({ minutes: serverTimeOffsetMinutes }))
		}

		// options.clock.on('second-passed', this.adjustServerTime, this)

		options.visibility.on('page-visible', async () => {
			await this.updateServerTimeIfStale()

			if (this.options.debugStorage.get('logTimeOnPageVisible').unwrapOr(false)) {
				this.logger.info(`local  - ${toReadableDateString(this.local)}`)
				this.logger.info(`server - ${toReadableDateString(this.server)}`)
			}
		})
	}

	/**
	 *  Корректировка серверного времени относительно количества секунд, прошедших с момента последнего апдейта серверного времени.
	 *  @return текущее время на сервере (таймстамп в миллисекундах)
	 */
	public adjustServerTime() {
		const elapsedMs = performance.now() - this.lastServerSyncPerfNowMs
		this.serverTime = this.serverTimeAtLastSyncMs + elapsedMs
		return this.serverTime
	}

	/**
	 * Refreshes server time if the time since last sync is greater than or equal to the threshold.
	 * @param thresholdMs - threshold in milliseconds. If <= 0, forces update.
	 * @returns current server time (possibly refreshed) in milliseconds.
	 */
	public async updateServerTimeIfStale(thresholdMs = 5_000): Promise<number> {
		const elapsedMsSinceLastSync = performance.now() - this.lastServerSyncPerfNowMs

		if (thresholdMs <= 0 || elapsedMsSinceLastSync >= thresholdMs) {
			return await this.updateServerTime()
		}

		return this.adjustServerTime()
	}

	/**
	 * @return текущее время на сервере (таймстамп в миллисекундах)
	 */
	public async updateServerTime(): Promise<number> {
		const [error, data] = await until(() => this.options.serverTimeGetter())

		if (error) {
			throw error
		}

		this.serverTime = data
		this.serverTime += this._serverTimeOffsetMs
		this.serverTimeAtLastSyncMs = this.serverTime
		this.lastServerSyncPerfNowMs = performance.now()
		return this.serverTime
	}

	public applyLocalTimeOffset(offsetMs: number): void {
		if (offsetMs === 0) {
			Date.now = this.originalDateNow
			this._localTimeOffsetMs = 0
			this.logger.info(`offset was removed from LOCAL time`)
		} else {
			Date.now = () => this.originalDateNow() + offsetMs
			this._localTimeOffsetMs = offsetMs
			this.logger.warn(`${prettyMs(offsetMs)} offset was applied to LOCAL time`)
		}

		this.adjustServerTime()
	}

	public applyServerTimeOffset(offsetMs: number): void {
		this.adjustServerTime()

		const offsetDelta = offsetMs - this._serverTimeOffsetMs

		if (offsetMs === 0) {
			this._serverTimeOffsetMs = 0
			this.logger.info(`offset was removed from SERVER time`)
		} else {
			this._serverTimeOffsetMs = offsetMs
			this.logger.warn(`${prettyMs(offsetMs)} offset was applied to SERVER time`)
		}

		this.serverTimeAtLastSyncMs = this.serverTime + offsetDelta
		this.lastServerSyncPerfNowMs = performance.now()
		this.serverTime = this.serverTimeAtLastSyncMs
	}

	/**
	 * Возвращает серверное время **в миллисекундах**
	 */
	public get server(): number {
		return this.serverTime
	}

	/**
	 * Возвращает локальное время **в миллисекундах**
	 */
	public get local(): number {
		return Date.now()
	}
}
