import { Config } from '../Config'
import { DrawUtil } from '../robowhale/utils/DrawUtil'

export class StateTransition extends Phaser.Plugin {
	private overlay: Phaser.Image
	private overlayTween: Phaser.Tween
	public overlayDuration: number = 150

	constructor(_game: Phaser.Game) {
		super(_game, _game.plugins)

		let bmd: Phaser.BitmapData = DrawUtil.createRectTexture(this.game, 1, 1, '#FFF3E0', 'black_rect')
		this.overlay = new Phaser.Image(_game, 0, 0, bmd)
		this.overlay.visible = false
		this.game.stage.addChild(<PIXI.DisplayObject>this.overlay)
	}

	private fillStage(): void {
		this.overlay.width = Config.GAME_WIDTH
		this.overlay.height = Config.GAME_HEIGHT
	}

	public changeState(newState: string, arg?: any): void {
		this.fillStage()

		this.game.input.enabled = false

		this.showOverlay(newState, arg)
	}

	private showOverlay(newState: string, arg?: any): void {
		this.overlay.visible = true
		this.overlay.alpha = 0
		this.overlayTween = this.game.add
			.tween(this.overlay)
			.to({ alpha: 1 }, this.overlayDuration, Phaser.Easing.Cubic.Out, true)
		this.overlayTween.onComplete.addOnce(() => {
			this.doChangeState(newState, arg)
		}, this)
	}

	private doChangeState(newState: string, arg: any): void {
		this.game.input.enabled = true
		this.game.state.start(newState, true, false, arg)
		setTimeout(() => {
			this.hideOverlay()
		}, 100)
		setTimeout(() => {
			this.overlay.visible = false
		}, 100 + this.overlayDuration) // just in case
	}

	public hideOverlay(): void {
		this.overlayTween = this.game.add
			.tween(this.overlay)
			.to({ alpha: 0 }, this.overlayDuration, Phaser.Easing.Cubic.Out, true)
	}
}
