import { times } from 'es-toolkit/compat'
import { Grid } from '../grid/Grid'
import { IResetable } from './../IResetable'
import { Item } from './Item'

export class ItemsPool implements IResetable {
	private _game: Phaser.Game
	private itemsLayer: Phaser.Group
	public items: Item[]

	constructor(_game: Phaser.Game, objectsLayer: Phaser.Group) {
		this._game = _game
		this.itemsLayer = objectsLayer

		this.initItems()
	}

	private initItems(): void {
		let itemsNum: number = Grid.COLUMNS * Grid.ROWS
		this.items = times(itemsNum, () => {
			return new Item(this._game, this.itemsLayer)
		})

		this.itemsLayer.addMultiple(this.items, true)
	}

	public getItem(itemType: number): Item {
		let item: Item = this.items.find((candidate) => candidate.exists === false)
		if (!item) {
			console.warn(`Additional item allocated! [itemType = ${itemType}]`)

			item = new Item(this._game)
			this.items.push(item)
			this.itemsLayer.add(item)
		}

		item.setItemType(itemType)
		item.onRemoveFromPool()
		return item
	}

	public returnItem(item: Item): void {
		item.onAddToPool()
	}

	public doReset(): void {
		let l: number = this.items.length
		for (let i: number = 0; i < l; i++) {
			let item: Item = this.items[i]
			if (item.exists) this.returnItem(item)
		}
	}

	public destroy(): void {
		this._game = null
		this.itemsLayer = null
		this.items.length = 0
		this.items = null
	}
}
