import { ensureWebAwesomeRuntime } from '../devtools/webawesome/ensure-webawesome-runtime'
import {
	URL_PARAMS,
	URL_PARAM_GROUPS,
	type UrlParam,
	type UrlParamDefinition,
	type UrlParamGroup,
	UrlParams,
} from './UrlParams'

const VIEWER_STYLES_ID = 'url-params-viewer-styles'

