function escapeHtml(text: string): string {
	const div = document.createElement('div')
	div.textContent = text
	return div.innerHTML
}

function formatDescription(text: string): string {
	const parts: string[] = []
	let currentIndex = 0
	const backtickRegex = /`([^`]+)`/g
	let match: RegExpExecArray | null

	while ((match = backtickRegex.exec(text)) !== null) {
		if (match.index > currentIndex) {
			parts.push(escapeHtml(text.substring(currentIndex, match.index)))
		}

		parts.push(`<code>${escapeHtml(match[1])}</code>`)
		currentIndex = match.index + match[0].length
	}

	if (currentIndex < text.length) {
		parts.push(escapeHtml(text.substring(currentIndex)))
	}

	return parts.length > 0 ? parts.join('') : escapeHtml(text)
}

export class UrlParamsViewer {
	private drawer: HTMLElement | null = null

	public async toggle(): Promise<void> {
		if (this.drawer) {
			this.close()
			return
		}

		await this.show()
	}

	public async show(): Promise<void> {
		if (this.drawer) {
			return
		}

		await ensureWebAwesomeRuntime()
		ensureViewerStyles()
		this.open()
	}

	private open(): void {
		const drawer = document.createElement('wa-drawer')
		drawer.setAttribute('label', 'URL Parameters')
		drawer.setAttribute('placement', 'bottom')
		drawer.setAttribute('light-dismiss', 'true')
		drawer.style.setProperty('--size', '70vh')

		// Ensure components are discovered in the drawer after it's created but before it's opened
		ensureWebAwesomeRuntime()

		const searchButton = document.createElement('wa-button')
		searchButton.setAttribute('slot', 'header-actions')
		searchButton.setAttribute('variant', 'neutral')
		searchButton.setAttribute('appearance', 'plain')
		searchButton.setAttribute('data-url-params-search', 'true')
		const searchIcon = document.createElement('wa-icon')
		searchIcon.setAttribute('name', 'magnifying-glass')
		searchIcon.setAttribute('label', 'Search')
		searchButton.appendChild(searchIcon)

		const content = document.createElement('div')
		content.className = 'url-params-viewer'
		content.innerHTML = this.renderFilter() + this.renderSections()

		drawer.appendChild(searchButton)
		drawer.appendChild(content)

		this.attachInteractions(drawer)

		drawer.addEventListener('wa-after-hide', () => {
			if (this.drawer && this.drawer.parentElement) {
				this.drawer.parentElement.removeChild(this.drawer)
			}
			this.drawer = null
		})

		document.body.appendChild(drawer)
		requestAnimationFrame(() => {
			;(drawer as unknown as { open: boolean }).open = true
		})

		this.drawer = drawer
	}

	private close(): void {
		if (!this.drawer) return
		;(this.drawer as unknown as { open: boolean }).open = false
	}

	private attachInteractions(drawer: HTMLElement): void {
		const searchButton = drawer.querySelector<HTMLElement>('[data-url-params-search]')
		if (searchButton) {
			searchButton.addEventListener('click', () => this.toggleFilter(drawer, searchButton))
		}

		const input = drawer.querySelector('wa-input') as unknown as HTMLElement | null
		if (input) {
			const handleFilter = () => this.applyFilter(drawer)
			input.addEventListener('wa-input', handleFilter)
			input.addEventListener('input', handleFilter)
		}

		const nameElements = drawer.querySelectorAll<HTMLElement>('.url-params-name')
		nameElements.forEach((element) => {
			element.addEventListener('click', async () => {
				const paramName = element.dataset.param
				if (!paramName) return
				await this.copyToClipboard(paramName, element)
			})
		})

		const codeElements = drawer.querySelectorAll<HTMLElement>('.url-params-description code')
		codeElements.forEach((element) => {
			element.addEventListener('click', async () => {
				const text = element.textContent?.trim()
				if (!text) return
				await this.copyToClipboard(text, element)
			})
		})
	}

	private applyFilter(drawer: HTMLElement): void {
		const input = drawer.querySelector('wa-input') as unknown as HTMLInputElement | null
		const query = (input?.value ?? '').trim().toLowerCase()
		const rows = Array.from(drawer.querySelectorAll<HTMLTableRowElement>('tbody tr'))

		rows.forEach((row) => {
			const name = row.dataset.paramName ?? ''
			const description = row.dataset.paramDescription ?? ''
			const matches =
				query.length === 0 || name.toLowerCase().includes(query) || description.toLowerCase().includes(query)
			row.style.display = matches ? '' : 'none'
		})

		const sections = Array.from(drawer.querySelectorAll<HTMLElement>('.url-params-section'))
		sections.forEach((section) => {
			const visibleRows = section.querySelectorAll('tbody tr:not([style*="display: none"])').length
			section.style.display = visibleRows > 0 ? '' : 'none'
		})
	}

	private async copyToClipboard(text: string, element: HTMLElement): Promise<void> {
		if (!text) return

		const currentSearch = window.location?.search ?? ''
		const normalizedSearch = currentSearch.startsWith('?') ? currentSearch.slice(1) : currentSearch
		const textToCopy = normalizedSearch.trim().length === 0 ? `?${text}` : `&${text}`

		try {
			await navigator.clipboard.writeText(textToCopy)
		} catch {
			const textArea = document.createElement('textarea')
			textArea.value = textToCopy
			textArea.style.position = 'fixed'
			textArea.style.opacity = '0'
			document.body.appendChild(textArea)
			textArea.select()
			try {
				document.execCommand('copy')
			} finally {
				document.body.removeChild(textArea)
			}
		}

		element.classList.add('copied')
		setTimeout(() => element.classList.remove('copied'), 500)
	}

	private toggleFilter(drawer: HTMLElement, button?: HTMLElement): void {
		const content = drawer.querySelector('.url-params-viewer') as HTMLElement | null
		if (!content) {
			return
		}

		content.classList.toggle('filter-open')
		if (button) {
			button.classList.toggle('is-active', content.classList.contains('filter-open'))
		}
		const input = drawer.querySelector('wa-input') as unknown as HTMLInputElement | null
		if (content.classList.contains('filter-open')) {
			input?.focus()
		} else {
			if (input) {
				input.value = ''
			}
			this.applyFilter(drawer)
		}
	}

	private renderFilter(): string {
		return `
			<div class="url-params-filter-wrapper">
				<wa-input
					class="url-params-filter"
					placeholder="Filter params..."
					clearable
				></wa-input>
			</div>
		`
	}

	private renderSections(): string {
		const paramsByGroup = new Map<UrlParamGroup, UrlParamDefinition[]>()
		for (const param of URL_PARAMS) {
			const group = (param.group ?? 'general') as UrlParamGroup
			const existing = paramsByGroup.get(group) || []
			existing.push(param)
			paramsByGroup.set(group, existing)
		}

		const groups = Object.entries(URL_PARAM_GROUPS) as Array<[UrlParamGroup, string]>
		return groups
			.map(([groupId, label]) => {
				const params = paramsByGroup.get(groupId) || []
				if (params.length === 0) {
					return ''
				}

				const rows = params
					.slice()
					.sort((a, b) => a.name.localeCompare(b.name))
					.map((param) => {
						const isSet = UrlParams.has(param.name as UrlParam)
						const dot = isSet ? '<span class="url-params-dot" aria-hidden="true"></span>' : ''
						const description = param.description
							? formatDescription(param.description)
							: '<span class="url-params-empty">No description</span>'

						return `
							<tr data-param-name="${escapeHtml(param.name)}" data-param-description="${escapeHtml(param.description || '')}">
								<td>
									<span class="url-params-name-row">
										<span class="url-params-name" data-param="${escapeHtml(param.name)}">${escapeHtml(param.name)}</span>
										${dot}
									</span>
								</td>
								<td class="url-params-description">${description}</td>
							</tr>
						`
					})
					.join('')

				return `
					<section class="url-params-section">
						<div class="url-params-section-title">${escapeHtml(label)}</div>
						<table class="url-params-table">
							<thead>
								<tr>
									<th>Param</th>
									<th>Description</th>
								</tr>
							</thead>
							<tbody>
								${rows}
							</tbody>
						</table>
					</section>
				`
			})
			.join('')
	}
}
