import { Result } from 'neverthrow'
import { Logger } from 'tslog'
import { SentryService } from '../sentry/SentryService'
import { TypedEventEmitter } from './../robowhale/TypedEventEmitter'

export interface BaseStorageOptions {
	logger: Logger<unknown>
	sentry: SentryService
}

export type StorageLoadResult = Result<GenericState, StorageErrorData>

export type StorageErrorData = {
	code: string
	message: string
}

export type StorageSaveResult = Result<{}, StorageErrorData>

export type GenericState = Record<string, unknown>

export abstract class BaseStorage extends TypedEventEmitter {
	protected logger: Logger<unknown>
	protected sentry: SentryService
	protected changedKeysBatches: Set<string>[]
	protected _savesEnabled = true

	protected constructor(options: BaseStorageOptions) {
		super()

		this.logger = options.logger
		this.sentry = options.sentry
		this.changedKeysBatches = []
	}

	public abstract loadState(): Promise<StorageLoadResult>

	/**
	 * @returns A promise that resolves to the result of the save operation. The promise is NEVER rejected.
	 */
	public abstract saveState(state: GenericState): Promise<StorageSaveResult>

	/**
	 * Clears all persisted state. The promise is NEVER rejected.
	 */
	public abstract clearState(): Promise<StorageSaveResult>

	/**
	 * We keep track of changed keys so when we want to persist state, we skip saving if nothing has changed.
	 */
	public onStateChange(stateKey: string): void {
		const currentBatch = this.changedKeysBatches.at(-1)
		if (!currentBatch) {
			this.changedKeysBatches.push(new Set())
		}

		currentBatch.add(stateKey)
	}

	public getLogger() {
		return this.logger
	}

	protected get stateHasChanges(): boolean {
		const currentBatch = this.changedKeysBatches.at(-1)
		if (!currentBatch) {
			return false
		}

		return currentBatch.size > 0
	}

	public disableSaves(): void {
		if (!this._savesEnabled) {
			return
		}

		this._savesEnabled = false
		this.logger.info('saves are disabled')
	}
}
