import { GameFonts } from "../../GameFonts"

export class LeaderboardRankLabel extends Phaser.Group {
    private back: Phaser.Image
    private text: Phaser.BitmapText
    private wasDestroyed = false

    constructor(_game: Phaser.Game, parent: Phaser.Group) {
        super(_game, parent, 'rank_label')

        this.addBack()
        this.addText()
        this.alignText()
        // this.loadPlayerRank()
    }

    private addBack() {
        this.back = this.game.add.image(0, 0, 'game_over', 'Rank_Label0000', this)
        this.back.anchor.set(0.5, 0.5)
    }

    private addText() {
        let content: string = '# 1 000 000'
        this.text = this.game.add.bitmapText(0, 0, GameFonts.GAME_OVER_BARIOL_BOLD, content, 22, this)
        this.text.anchor.set(0.5, 0.5)
    }

    public updateRank(rank: number): void {
        this.text.setText('# ' + this.formatNumber(rank))
        this.alignText()
    }

    private formatNumber(num: number) {
        return num.toLocaleString().split(',').join(' ')
    }

    private alignText() {
        let maxWidth: number = this.back.width * 0.8
        this.text.scale.set(1)
        if (this.text.width > maxWidth) {
            this.text.scale.set(maxWidth / this.text.width)
        }

        this.text.centerX = this.back.centerX
        this.text.centerY = this.back.centerY
    }

    public async loadPlayerRank() {
        if (!this.game.leaderboards) {
            return
        }

        const playerDataResult = await this.game.leaderboards.getPlayerData()

        if (playerDataResult.isErr()) {
            return
        }

        if (this.wasDestroyed) {
            return
        }

        this.updateRank(playerDataResult.value.position)
        this.show()
    }

    public show(): void {
        this.revive()
        this.game.add.tween(this).from({ alpha: 0, y: '+8' }, 800, Phaser.Easing.Cubic.Out, true)
    }

    public destroy(): void {
        this.wasDestroyed = true
        super.destroy(true, false)
    }
}
