import type { VKBridge } from '@vkontakte/vk-bridge'
import { attempt } from 'es-toolkit'
import { err, ok, type Result } from 'neverthrow'
import { until } from 'until-async'
import { getErrorLog } from '../robowhale/utils/error/utils'
import {
	BaseStorage,
	type BaseStorageOptions,
	type StorageErrorData,
	type StorageLoadResult,
	type StorageSaveResult,
} from './BaseStorage'

export interface VkRemoteStorageOptions extends BaseStorageOptions {
	/** VK Bridge instance used to call storage events. */
	bridge?: VKBridge
	/** Storage key name used to persist serialized state. Defaults to "state". */
	key?: string
}

type WriteValuesOptions = {
	/** Key-value pairs to set/update in VK storage. */
	upserts: { recordKey: string; value: string }[]
	/** Record keys to delete (sent as empty values to VK storage). */
	deletions: string[]
}

/** Conservative per-entry value length to avoid VK trimming of stored strings. */
const MAX_SERIALIZED_VALUE_LENGTH = 2236

/** Base storage prefix (namespace) applied to all VK Storage keys. */
const DEFAULT_KEY_PREFIX = 'state'

/** Delimiter used by json-kv to keep VK keys charset-safe. */
const KEY_DELIMITER = '-'

/** Metadata prefix used by json-kv for markers like __t and __v. */
const META_PREFIX = '__'

/** Marker key (with prefix) indicating the storage format version. */
const FORMAT_MARKER_KEY = `${META_PREFIX}format`

/** Marker value identifying json-kv v1 format. */
const FORMAT_MARKER_VALUE = 'json-kv-v1'

/** VK key charset constraint applied to generated VK storage keys. */
const VK_KEY_PATTERN = /^[a-zA-Z0-9_-]+$/

/** Page size for VKWebAppStorageGetKeys pagination. */
const VK_STORAGE_KEYS_PAGE_SIZE = 100

/** Chunk size for VKWebAppStorageGet batch reads. */
const VK_STORAGE_GET_CHUNK_SIZE = 50

/**
 * Persists game state in VK Mini Apps Storage via VK Bridge.
 * VKWebAppStorageSet may drop entries whose values are empty strings (see https://dev.vk.com/ru/bridge/VKWebAppStorageSet), so empty string string-values are skipped on save to avoid partial json-kv records.
 */
export class VkRemoteStorage extends BaseStorage {
	private readonly bridge?: VKBridge
	private readonly prefix: string
	private readonly kv: JsonKV.JsonKV
	private lastSavedRecord: JsonKV.KvFlatRecord | null = null
	private readonly prefixWithDelimiter: string

	/**
	 * Creates a VK remote storage instance configured with a VK Bridge and json-kv flattening options.
	 * @param options dependencies and optional prefix/key override
	 */
	constructor(options: VkRemoteStorageOptions) {
		super(options)

		this.bridge = options.bridge
		this.prefix = options.key ?? DEFAULT_KEY_PREFIX
		this.kv = new JsonKV.JsonKV({
			delimiter: KEY_DELIMITER,
			metaPrefix: META_PREFIX,
		})
		this.prefixWithDelimiter = `${this.prefix}${KEY_DELIMITER}`
	}

	/**
	 * Loads serialized state from VK Storage using prefixed keys and json-kv unflattening.
	 * Returns an empty object when no data or missing format marker is present.
	 * @returns parsed state object or an error describing the failure
	 */
	public async loadState(): Promise<StorageLoadResult> {
		if (!this.bridge) {
			return err({ code: 'bridge_unavailable', message: 'VK Bridge is not available' })
		}

		const prefixedKeysResult = await this.listPrefixedKeys()
		if (prefixedKeysResult.isErr()) {
			return err(prefixedKeysResult.error)
		}

		if (prefixedKeysResult.value.length === 0) {
			return ok({})
		}

		const valuesResult = await this.getValues(prefixedKeysResult.value)
		if (valuesResult.isErr()) {
			return err(valuesResult.error)
		}

		const formatValue = valuesResult.value[this.formatKey()]
		if (formatValue !== FORMAT_MARKER_VALUE) {
			return ok({})
		}

		delete valuesResult.value[this.formatKey()]

		const recordResult = this.buildRecord(valuesResult.value)
		if (recordResult.isErr()) {
			return err(recordResult.error)
		}

		const missingStringValueKeys = this.findStringTypeKeysMissingValues(recordResult.value)
		if (missingStringValueKeys.length > 0) {
			this.logger.warn('missing string values in VK storage', { keys: missingStringValueKeys })
		}

		this.logger.debug('unflattened loaded state', recordResult.value)

		const [parseError, state] = attempt(() => this.kv.unflatten(recordResult.value))
		if (parseError) {
			return err({ code: 'parse_error', message: `Failed to unflatten state (${getErrorLog(parseError)})` })
		}

		if (typeof state !== 'object' || state === null) {
			return err({ code: 'invalid_state', message: 'state is not an object' })
		}

		this.lastSavedRecord = recordResult.value

		return ok(state as Record<string, unknown>)
	}

	/**
	 * Saves serialized state to VK Storage using per-entry json-kv flattening with diffed writes.
	 * @note VK limits: up to 1,000 keys and 1,000 calls per user per hour; serialized value is trimmed after 2,236 characters (raw string limit is 4,096).
	 * @param state state object to serialize and store
	 * @returns empty ok result or error describing the failure
	 */
	public async saveState(state: Record<string, unknown>): Promise<StorageSaveResult> {
		if (!this._savesEnabled) {
			return err({ code: 'saves_disabled', message: 'saves are disabled' })
		}

		if (!this.bridge) {
			return err({ code: 'bridge_unavailable', message: 'VK Bridge is not available' })
		}

		const [flattenError, flattened] = attempt(() => this.kv.flatten(state))
		if (flattenError) {
			return err({ code: 'invalid_state', message: `Failed to flatten state (${getErrorLog(flattenError)})` })
		}

		const { record: normalizedRecord, droppedValueKeys } = this.removeEmptyStringValues(flattened.record)

		if (droppedValueKeys.length > 0) {
			this.logger.debug('skipped empty string values for VK storage', { keys: droppedValueKeys })
		}

		const keyValidationError = this.validateRecordKeys(normalizedRecord)
		if (keyValidationError) {
			return err(keyValidationError)
		}

		const stringRecordResult = this.convertRecordToStrings(normalizedRecord)
		if (stringRecordResult.isErr()) {
			return err(stringRecordResult.error)
		}

		const { changedKeys, removedKeys } = this.computeDiff(normalizedRecord)
		const deletions = new Set(removedKeys)
		const writes = new Set<string>(changedKeys)

		if (this.lastSavedRecord === null) {
			writes.add(FORMAT_MARKER_KEY)

			const staleKeysResult = await this.listPrefixedKeys()
			if (staleKeysResult.isErr()) {
				return err({ code: 'save_error', message: staleKeysResult.error.message })
			}

			staleKeysResult.value.forEach((vkKey) => {
				const recordKey = this.stripPrefix(vkKey)
				if (!(recordKey in stringRecordResult.value) && recordKey !== FORMAT_MARKER_KEY) {
					deletions.add(recordKey)
				}
			})
		}

		if (writes.size === 0 && deletions.size === 0) {
			this.lastSavedRecord = normalizedRecord
			return ok({})
		}

		const saveError = await this.writeValues({
			upserts: Array.from(writes).map((recordKey) => ({
				recordKey,
				value: recordKey === FORMAT_MARKER_KEY ? FORMAT_MARKER_VALUE : stringRecordResult.value[recordKey],
			})),
			deletions: Array.from(deletions),
		})

		if (saveError) {
			return err(saveError)
		}

		this.lastSavedRecord = normalizedRecord

		return ok({})
	}

	public async clearState(): Promise<StorageSaveResult> {
		if (!this.bridge) {
			return err({ code: 'bridge_unavailable', message: 'VK Bridge is not available' })
		}

		const prefixedKeysResult = await this.listPrefixedKeys()
		if (prefixedKeysResult.isErr()) {
			return err({ code: 'clear_error', message: prefixedKeysResult.error.message })
		}

		if (prefixedKeysResult.value.length === 0) {
			this.lastSavedRecord = null
			return ok({})
		}

		const clearError = await this.runSetRequests(
			prefixedKeysResult.value.map((key) => ({ key, value: '' }))
		)

		if (clearError) {
			return err({ code: 'clear_error', message: clearError.message })
		}

		this.lastSavedRecord = null

		return ok({})
	}

	/**
	 * Applies VK storage mutations by upserting provided record entries and deleting obsolete ones.
	 * @param upserts key/value entries to write
	 * @param deletions record keys to delete (empty value writes)
	 * @returns null when successful or a structured error when any VK call fails
	 */
	private async writeValues({ upserts, deletions }: WriteValuesOptions): Promise<StorageErrorData | null> {
		const setError = await this.runSetRequests(
			upserts.map((entry) => ({ key: this.buildVkKey(entry.recordKey), value: entry.value }))
		)
		if (setError) {
			return setError
		}

		if (deletions.length === 0) {
			return null
		}

		const deleteError = await this.runSetRequests(
			deletions.map((recordKey) => ({
				key: this.buildVkKey(recordKey),
				value: '',
			}))
		)

		if (deleteError) {
			return deleteError
		}

		return null
	}

	/**
	 * Executes VKWebAppStorageSet calls in parallel for provided key/value pairs.
	 * Returns the first encountered error, or null when all succeed.
	 * @param entries VK key/value pairs to set
	 */
	private async runSetRequests(entries: { key: string; value: string }[]): Promise<StorageErrorData | null> {
		if (entries.length === 0) {
			return null
		}

		const results = await Promise.all(
			entries.map(async (entry) => {
				const [error] = await until(() =>
					this.bridge!.send('VKWebAppStorageSet', {
						key: entry.key,
						value: entry.value,
					})
				)

				return error ? error : null
			})
		)

		const firstError = results.find((error) => error !== null)
		if (firstError) {
			return { code: 'save_error', message: `VKWebAppStorageSet failed (${getErrorLog(firstError)})` }
		}

		return null
	}

	private removeEmptyStringValues(
		record: JsonKV.KvFlatRecord
	): { record: JsonKV.KvFlatRecord; droppedValueKeys: string[] } {
		const normalizedRecord: JsonKV.KvFlatRecord = { ...record }
		const droppedValueKeys: string[] = []

		for (const [recordKey, value] of Object.entries(record)) {
			if (!this.isValueKey(recordKey)) {
				continue
			}

			if (value !== '') {
				continue
			}

			const baseKey = this.getBaseKey(recordKey)
			if (baseKey === '') {
				continue
			}

			const typeKey = this.joinMetaKey(baseKey, `${META_PREFIX}t`)
			if (record[typeKey] !== 's') {
				continue
			}

			delete normalizedRecord[recordKey]
			delete normalizedRecord[typeKey]
			droppedValueKeys.push(baseKey)
		}

		return { record: normalizedRecord, droppedValueKeys }
	}

	private findStringTypeKeysMissingValues(record: JsonKV.KvFlatRecord): string[] {
		const missingKeys: string[] = []

		for (const [recordKey, marker] of Object.entries(record)) {
			if (!this.isTypeKey(recordKey)) {
				continue
			}

			if (marker !== 's') {
				continue
			}

			const baseKey = this.getTypeBaseKey(recordKey)
			const valueKey = this.joinMetaKey(baseKey, `${META_PREFIX}v`)

			if (valueKey in record) {
				continue
			}

			missingKeys.push(baseKey)
		}

		return missingKeys
	}

	/**
	 * Computes changed and removed record keys versus the last saved snapshot.
	 * @param record current flattened record
	 * @returns lists of changedKeys and removedKeys
	 */
	private computeDiff(record: JsonKV.KvFlatRecord): { changedKeys: string[]; removedKeys: string[] } {
		if (this.lastSavedRecord === null) {
			return {
				changedKeys: Object.keys(record),
				removedKeys: [],
			}
		}

		const changedKeys: string[] = []
		for (const key in record) {
			if (!Object.prototype.hasOwnProperty.call(record, key)) {
				continue
			}

			if (this.lastSavedRecord[key] !== record[key]) {
				changedKeys.push(key)
			}
		}

		const removedKeys: string[] = []
		for (const key in this.lastSavedRecord) {
			if (!Object.prototype.hasOwnProperty.call(this.lastSavedRecord, key)) {
				continue
			}

			if (!(key in record)) {
				removedKeys.push(key)
			}
		}

		return { changedKeys, removedKeys }
	}

	/**
	 * Converts flattened record values to strings enforcing VK value length limits.
	 * @param record flattened record with primitive values
	 * @returns ok(stringifiedRecord) or payload_too_large error
	 */
	private convertRecordToStrings(record: JsonKV.KvFlatRecord): Result<Record<string, string>, StorageErrorData> {
		const stringRecord: Record<string, string> = {}

		for (const [recordKey, value] of Object.entries(record)) {
			const stringValue = String(value)

			if (stringValue.length > MAX_SERIALIZED_VALUE_LENGTH) {
				return err({
					code: 'payload_too_large',
					message: `Value for key "${recordKey}" exceeds VK storage limit (${stringValue.length}/${MAX_SERIALIZED_VALUE_LENGTH})`,
				})
			}

			stringRecord[recordKey] = stringValue
		}

		return ok(stringRecord)
	}

	/**
	 * Ensures generated VK keys match VK charset/length constraints, returning an error descriptor on the first violation.
	 * @param record flattened record to validate
	 */
	private validateRecordKeys(record: JsonKV.KvFlatRecord): StorageErrorData | null {
		for (const recordKey of Object.keys(record)) {
			const vkKey = this.buildVkKey(recordKey)

			if (!VK_KEY_PATTERN.test(vkKey)) {
				return { code: 'key_invalid', message: `Key "${vkKey}" has invalid characters` }
			}

			if (vkKey.length > 100) {
				return { code: 'key_too_long', message: `Key "${vkKey}" exceeds VK key length limit (100)` }
			}
		}

		return null
	}

	/**
	 * Rebuilds a flattened record from VK key/value map, stripping prefixes and parsing primitives.
	 * @param values VK key/value map
	 * @returns ok(flatRecord) or structured invalid_state error
	 */
	private buildRecord(values: Record<string, string>): Result<JsonKV.KvFlatRecord, StorageErrorData> {
		const record: JsonKV.KvFlatRecord = {}

		for (const [vkKey, value] of Object.entries(values)) {
			const recordKey = this.stripPrefix(vkKey)
			record[recordKey] = value
		}

		for (const [recordKey, rawValue] of Object.entries(record)) {
			if (this.isValueKey(recordKey)) {
				const parsedValue = this.parseValue(recordKey, rawValue, record)
				if (parsedValue.isErr()) {
					return err(parsedValue.error)
				}

				record[recordKey] = parsedValue.value
			}

			if (this.isLengthKey(recordKey)) {
				const parsedLength = Number(rawValue)
				if (Number.isNaN(parsedLength) || !Number.isFinite(parsedLength)) {
					return err({
						code: 'invalid_state',
						message: `Invalid array length for key "${recordKey}"`,
					})
				}
				record[recordKey] = parsedLength
			}
		}

		return ok(record)
	}

	/**
	 * Parses a single json-kv value based on its type marker.
	 * @param recordKey key of the value (with meta suffix)
	 * @param rawValue raw string/primitive read from VK
	 * @param record full flat record to consult for type markers
	 * @returns parsed primitive or invalid_state error
	 */
	private parseValue(
		recordKey: string,
		rawValue: JsonKV.KvPrimitive,
		record: JsonKV.KvFlatRecord
	): Result<JsonKV.KvPrimitive, StorageErrorData> {
		const baseKey = this.getBaseKey(recordKey)
		const typeKey = this.joinMetaKey(baseKey, `${META_PREFIX}t`)
		const typeMarker = record[typeKey]

		if (typeof typeMarker !== 'string') {
			return err({
				code: 'invalid_state',
				message: `Missing type marker for key "${recordKey}"`,
			})
		}

		if (typeMarker === 'b') {
			if (rawValue !== 'true' && rawValue !== 'false') {
				return err({ code: 'invalid_state', message: `Invalid boolean for key "${recordKey}"` })
			}
			return ok(rawValue === 'true')
		}

		if (typeMarker === 'n') {
			const numberValue = Number(rawValue)
			if (Number.isNaN(numberValue) || !Number.isFinite(numberValue)) {
				return err({ code: 'invalid_state', message: `Invalid number for key "${recordKey}"` })
			}
			return ok(numberValue)
		}

		return ok(rawValue)
	}

	/**
	 * Checks whether a record key denotes a json-kv value slot (__v).
	 * @param recordKey flat record key
	 */
	private isValueKey(recordKey: string): boolean {
		return recordKey === `${META_PREFIX}v` || recordKey.endsWith(`${KEY_DELIMITER}${META_PREFIX}v`)
	}

	/**
	 * Checks whether a record key denotes a json-kv array length slot (__l).
	 * @param recordKey flat record key
	 */
	private isLengthKey(recordKey: string): boolean {
		return recordKey === `${META_PREFIX}l` || recordKey.endsWith(`${KEY_DELIMITER}${META_PREFIX}l`)
	}

	private isTypeKey(recordKey: string): boolean {
		return recordKey === `${META_PREFIX}t` || recordKey.endsWith(`${KEY_DELIMITER}${META_PREFIX}t`)
	}

	/**
	 * Removes the VK namespace prefix from a VK storage key.
	 * @param vkKey namespaced VK storage key
	 */
	private stripPrefix(vkKey: string): string {
		return vkKey.startsWith(this.prefixWithDelimiter) ? vkKey.slice(this.prefixWithDelimiter.length) : vkKey
	}

	/**
	 * Builds a VK storage key by adding the namespace prefix.
	 * @param recordKey flat record key without prefix
	 */
	private buildVkKey(recordKey: string): string {
		return `${this.prefixWithDelimiter}${recordKey}`
	}

	/**
	 * Returns the full VK storage key for the format marker.
	 */
	private formatKey(): string {
		return this.buildVkKey(FORMAT_MARKER_KEY)
	}

	/**
	 * Lists all VK storage keys under the configured prefix using paginated VKWebAppStorageGetKeys.
	 * @returns ok(array of keys) or load_error
	 */
	private async listPrefixedKeys(): Promise<Result<string[], StorageErrorData>> {
		const keys: string[] = []
		let offset = 0

		// eslint-disable-next-line no-constant-condition
		while (true) {
			const [error, data] = await until(() =>
				this.bridge!.send('VKWebAppStorageGetKeys', {
					count: VK_STORAGE_KEYS_PAGE_SIZE,
					offset,
				})
			)

			if (error) {
				return err({ code: 'load_error', message: `VKWebAppStorageGetKeys failed (${getErrorLog(error)})` })
			}

			const pageKeys = data.keys ?? []
			const prefixedKeys = pageKeys.filter((key: string) => key.startsWith(this.prefixWithDelimiter))

			if (prefixedKeys.length > 0) {
				keys.push(...prefixedKeys)
			}

			if (pageKeys.length < VK_STORAGE_KEYS_PAGE_SIZE) {
				break
			}

			offset += VK_STORAGE_KEYS_PAGE_SIZE
		}

		return ok(keys)
	}

	/**
	 * Fetches VK storage values for the provided keys in chunks.
	 * @param keys VK storage keys to fetch
	 * @returns ok(map of key->value) or load_error
	 */
	private async getValues(keys: string[]): Promise<Result<Record<string, string>, StorageErrorData>> {
		const values: Record<string, string> = {}

		for (let index = 0; index < keys.length; index += VK_STORAGE_GET_CHUNK_SIZE) {
			const chunk = keys.slice(index, index + VK_STORAGE_GET_CHUNK_SIZE)

			const [error, data] = await until(() => this.bridge!.send('VKWebAppStorageGet', { keys: chunk }))

			if (error) {
				return err({ code: 'load_error', message: `VKWebAppStorageGet failed (${getErrorLog(error)})` })
			}

			data.keys.forEach((item: { key: string; value: string }) => {
				values[item.key] = item.value
			})
		}

		return ok(values)
	}

	/**
	 * Derives the base record key without meta suffixes (__v/__l).
	 * @param recordKey flat record key
	 */
	private getBaseKey(recordKey: string): string {
		if (recordKey === `${META_PREFIX}v` || recordKey === `${META_PREFIX}l`) {
			return ''
		}

		if (recordKey.endsWith(`${KEY_DELIMITER}${META_PREFIX}v`)) {
			return recordKey.slice(0, -`${KEY_DELIMITER}${META_PREFIX}v`.length)
		}

		if (recordKey.endsWith(`${KEY_DELIMITER}${META_PREFIX}l`)) {
			return recordKey.slice(0, -`${KEY_DELIMITER}${META_PREFIX}l`.length)
		}

		return recordKey
	}

	private getTypeBaseKey(recordKey: string): string {
		if (recordKey === `${META_PREFIX}t`) {
			return ''
		}

		return recordKey.slice(0, -`${KEY_DELIMITER}${META_PREFIX}t`.length)
	}

	/**
	 * Joins a base key with a meta suffix using the configured delimiter.
	 * @param baseKey base record key
	 * @param metaKey meta part (e.g., __t, __v, __l)
	 */
	private joinMetaKey(baseKey: string, metaKey: string): string {
		return baseKey === '' ? metaKey : `${baseKey}${KEY_DELIMITER}${metaKey}`
	}
}
