import { Event, EventHint } from '@sentry/browser'

export type SentryErrorContext = Pick<Event, 'contexts' | 'tags' | 'extra' | 'level' | 'fingerprint' | 'message'>

export class BaseError extends Error {
	/**
	 * Фатальные ошибки полностью останавливают игру.
	 */
	public readonly isFatal: boolean = false

	/**
	 * Дополнительная информация, которая будет отправлена в Сентри вместе с этой ошибкой.
	 */
	public sentryContext?: SentryErrorContext | ((event: Event, hint: EventHint) => SentryErrorContext)

	constructor(message?: string, options?: ErrorOptions) {
		super(message, options)

		// TODO infer this.name from class name
	}
}


