export class PanelStars extends Phaser.Group {
    constructor(_game: Phaser.Game, parent: Phaser.Group, key: string, frame?: string) {
        super(_game, parent, 'panel_stars')

        let scales: number[] = [0.44, 0.66, 1]
        this.createMultiple(scales.length, key, frame, true)
        this.children.forEach((child: Phaser.Sprite, index: number) => {
            child.anchor.set(0.5, 0.5)
            child.scale.set(scales[index])
        })

        this.align(this.numChildren, 1, 40, 70, Phaser.CENTER)

        this.children[1].x -= 5
    }

    public show(initialDelay: number) {
        this.children.reverse().forEach((child, index) => {
            let delay: number = initialDelay + index * 100
            let duration: number = 330 + 120 * index
            this.game.add
                .tween(child)
                .from({ x: child.x - 66, alpha: 0, angle: -50 }, duration, Phaser.Easing.Cubic.Out, true, delay)
        })
    }

    public destroy(): void {
        super.destroy(true, false)
    }
}
