import { GameFonts } from '../../../GameFonts'

export class LevelCoinsLabel extends Phaser.Group {
	private back: Phaser.Image
	private icon: Phaser.Image
	private text: Phaser.BitmapText

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'coins_label')

		this.addBack()
		this.addIcon()
		this.addText()
	}

	private addBack() {
		this.back = this.game.add.image(0, 0, 'interface', 'CoinsCounter_Back0000', this)
	}

	private addIcon() {
		this.icon = this.game.add.image(0, 0, 'interface', 'CoinsCounter_Coin0000', this)
		this.icon.anchor.set(0.5, 0.5)
		this.icon.left = this.back.left + 20
		this.icon.centerY = this.back.centerY
	}

	private addText() {
		this.text = this.game.add.bitmapText(0, 0, GameFonts.BARIOL_BOLD_BMP, '0000', 42, this)
		this.text.anchor.set(1, 0.5)
		this.text.x = this.back.right - 20
		this.text.y = this.back.centerY
	}

	public updateContent(coins: number, instant: boolean = false): void {
		this.text.setText(coins)

		if (instant === false) {
			this.game.tweens.removeFrom(this.text)
			this.text.x = this.back.right - 20
			this.game.add.tween(this.text).to({ x: '-10' }, 200, Phaser.Easing.Sinusoidal.InOut, true, 0, 0, true)
		}
	}

	public resize(height: number) {
		this.back.height = height
		this.icon.centerY = this.back.centerY
		this.text.centerY = this.back.centerY + 2
	}
}
