import { SimpleButton } from './SimpleButton'

export enum ToggleButtonState {
	STATE_1 = 0,
	STATE_2 = 1,
}

export class ToggleButton extends SimpleButton {
	private spriteSheet: string
	private textureKey1: string
	private textureKey2: string
	private _buttonState: ToggleButtonState

	constructor(
		game: Phaser.Game,
		x: number,
		y: number,
		spritesheet: string,
		key1: string,
		key2: string,
		parent?: Phaser.Group
	) {
		super(game, x, y, spritesheet, key1, parent)

		this.spriteSheet = spritesheet
		this.textureKey1 = key1
		this.textureKey2 = key2
		this._buttonState = ToggleButtonState.STATE_1

		this.events.onInputDown.add(this.switchTextures, this)
	}

	public switchTextures(): void {
		this.buttonState =
			this._buttonState === ToggleButtonState.STATE_1 ? ToggleButtonState.STATE_2 : ToggleButtonState.STATE_1
	}

	public get buttonState(): ToggleButtonState {
		return this._buttonState
	}

	public set buttonState(value: ToggleButtonState) {
		this._buttonState = value

		this.frameName = this._buttonState === ToggleButtonState.STATE_1 ? this.textureKey1 : this.textureKey2
	}
}
