import { ComplexPopup } from './ComplexPopup'

export class HeadstartPopup extends ComplexPopup {
	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent)

		this.name = 'headstart_popup'
		this.backdrop.name = 'headstart_popup_back'

		let titleContent: string = this.game.texts.texts['headstart_popup_title']
		this.title.setText(titleContent)

		let mainTextContent: string = this.game.texts.texts.headstart_popup_message
		this.mainText.setText(mainTextContent)

		this.content.frameName = 'Headstart_Popup_Content0000'
		this.alignContent()

		this.yesButton.setCallbackOn('pointerup')
		this.yesButton.callback.addOnce(this.showRewardedVideo.bind(this, 'HeadstartPopup'))

		this.checkbox.checked = this.game.save.getValue('headstart_popup_disabled')
		this.checkbox.onChange.add(this.onCheckboxChanged, this)
	}

	private onCheckboxChanged() {
		this.game.save.setValue('headstart_popup_disabled', this.checkbox.checked, { origin: 'popup/headstart_checkbox' })
	}
}
