import { Config } from '../../../Config'
import { AlertPopup } from './AlertPopup'

export interface AlertOptions {
    title?: string
    message?: string
    onOk?: () => void
}

export class AlertScreen extends Phaser.Group {
    private backdrop: Phaser.Image
    public window: AlertPopup
    private onOkCallback: (() => void) | null = null

    constructor(_game: Phaser.Game, parent: Phaser.Group) {
        super(_game, parent, 'alert_screen')

        this.addBackdrop()
        this.addWindow()
    }

    private addBackdrop(): void {
        this.backdrop = this.game.add.image(0, 0, 'main_menu', 'white_rect0000', this)
        this.backdrop.tint = 0x1a237e
        this.backdrop.alpha = 0.66
        this.backdrop.inputEnabled = true
        this.backdrop.name = 'alert_background'
    }

    private addWindow(): void {
        this.window = new AlertPopup(this.game, this)
        this.window.okButton.callback.add(this.onOkButtonClick, this)
    }

    public show(options: AlertOptions = {}): void {
        this.parent.bringToTop(this)
        
        this.backdrop.events.onInputDown.add(this.onBackClick, this)

        this.revive()

        this.window.okButton.enabled = true
        this.window.updateContent(
            options.title || 'Alert', 
            options.message || 'Alert message'
        )
        
        this.onOkCallback = options.onOk || null

        this.alpha = 1

        this.showBackdrop()
        this.window.show(100)
    }

    private onOkButtonClick(): void {
        if (this.onOkCallback) {
            this.onOkCallback()
        }

        this.hide()
    }

    private onBackClick(back: Phaser.Image, pointer: Phaser.Pointer) {
        if (pointer.interactiveCandidates.length > 1) {
            return
        }

        this.hide()
    }

    private showBackdrop(): void {
        this.backdrop.alpha = 0
        this.game.add.tween(this.backdrop).to({ alpha: 0.66 }, 150, Phaser.Easing.Cubic.Out, true)
    }

    public hide(): void {
        this.backdrop.events.onInputDown.remove(this.onBackClick, this)

        this.window.okButton.enabled = false

        this.game.add
            .tween(this)
            .to({ alpha: 0 }, 200, Phaser.Easing.Cubic.Out, true)
            .onComplete.addOnce(() => {
                this.exists = false
                this.visible = false
            })
    }

    public resize(): void {
        this.resizeBackdrop()

        this.window.centerX = Config.HALF_GAME_WIDTH
        this.window.centerY = Config.HALF_GAME_HEIGHT
    }

    private resizeBackdrop() {
        this.backdrop.width = Config.GAME_WIDTH * 1.2
        this.backdrop.height = Config.GAME_HEIGHT * 1.2
        this.backdrop.centerX = Config.HALF_GAME_WIDTH
        this.backdrop.centerY = Config.HALF_GAME_HEIGHT
    }

    public destroy(): void {
        super.destroy(true, false)
    }
}