    private static extendTimer() {
        Phaser.Timer.prototype.removeBy = function (callback: Function, callbackContext?: any): void {
            this.events
                .filter((event) => event.callback === callback && event.callbackContext === callbackContext)
                .forEach((event) => {
                    this.remove(event)
                })
        }
    }
