    private static extendLoader() {
        Phaser.Loader.prototype.bitmapFontFromAtlas = function (
            key: string,
            atlasKey: string,
            atlasFrame: string,
            dataURL: string,
            xSpacing?: number,
            ySpacing?: number
        ): Phaser.Loader {
            this.xml(key + '_data', dataURL)

            this.onLoadComplete.addOnce(() => {
                this.game.cache.addBitmapFontFromAtlas(
                    key,
                    atlasKey,
                    atlasFrame,
                    key + '_data',
                    'xml',
                    xSpacing,
                    ySpacing
                )
            })

            return this
        }
    }

    private static extendBitmapText() {
        Phaser.BitmapText.prototype.setTextOld = Phaser.BitmapText.prototype.setText
        Phaser.BitmapText.prototype.setText = function (text: string | number): void {
            if (typeof text === 'number') {
                text = text.toString()
            }

            return this.setTextOld(text as string)
        }
    }

    private static extendText() {
        Phaser.Text.prototype.setTextOld = Phaser.Text.prototype.setText
        Phaser.Text.prototype.setText = function (text: string | number, immediate?: boolean): Phaser.Text {
            if (typeof text === 'number') {
                text = text.toString()
            }

            return this.setTextOld(text as string, immediate)
        }
    }

    private static addWiggleEasing(): void {
        Phaser.Easing.Wiggle = function wiggle(
            aProgress: number,
            aPeriod1: number = 6.5,
            aPeriod2: number = 6.5
        ): number {
            let current1: number = aProgress * Math.PI * 2 * aPeriod1
            let current2: number = aProgress * Math.PI * 2 * aPeriod2

            return Math.sin(current1) * Math.cos(current2)
        }
    }

    private static addLightBackEasing() {
        let mult: number = 1

        Phaser.Easing.LightBack = {
            In: function (k) {
                var s = 1.70158 * mult
                return k * k * ((s + 1) * k - s)
            },

            Out: function (k) {
                var s = 1.70158 * mult
                return --k * k * ((s + 1) * k + s) + 1
            },

            InOut: function (k) {
                var s = 1.70158 * 1.525 * mult
                if ((k *= 2) < 1) return 0.5 * (k * k * ((s + 1) * k - s))
                return 0.5 * ((k -= 2) * k * ((s + 1) * k + s) + 2)
            },
        }
    }

    private static extendCache() {
        Phaser.Cache.prototype.cloneBitmapFont = function (oldKey: string, newKey: string): Phaser.BitmapFont {
            if (this.checkBitmapFontKey(newKey)) {
                console.warn(`Cache :: bitmapFont with key ${newKey} already exists! Choose another key.`)
                return null
            }

            let oldFont: Phaser.BitmapFont = this.getBitmapFont(oldKey)

            let newFont: Phaser.BitmapFont = {
                url: null,
                data: cloneDeep(oldFont.data),
                font: cloneDeep(oldFont.font),
                base: oldFont.base,
            }

            this.game.cache._cache.bitmapFont[newKey] = newFont

            return newFont
        }
    }
