import { Cell } from "./grid/Cell"
import { Grid } from "./grid/Grid"
import { Item } from "./items/Item"

export class FindChainStrategy {
    private game: Phaser.Game
    private grid: Grid
    private stack: Item[] = []
    private foundChain: Item[] = []

    constructor(_game: Phaser.Game, grid: Grid) {
        this.game = _game
        this.grid = grid
    }

    public hasChains(items: Item[]): boolean {
        return this.getPossibleMove(items) !== null
    }

    public getPossibleMove(items: Item[]): Item[] {
        let l: number = items.length
        for (let i: number = 0; i < l; i++) {
            let item: Item = items[i]
            let chain: Item[] = this.getPossibleChain(item)
            if (chain && chain.length >= 3) {
                return chain
            }
        }

        return null
    }

    private getPossibleChain(item: Item): Item[] {
        this.stack.length = 0
        this.stack.push(item)

        this.foundChain.length = 0

        let type: number = item.itemType
        let iterations: number = 0
        while (this.stack.length > 0) {
            let testItem: Item = this.stack.pop()
            this.foundChain.push(testItem)
            if (this.foundChain.length > 2) {
                return this.foundChain
            }

            this.putInStack(testItem, type, -1, -1) // top-left
            this.putInStack(testItem, type, -1, 0) // top
            this.putInStack(testItem, type, -1, 1) // top-right
            this.putInStack(testItem, type, 0, 1) // right
            this.putInStack(testItem, type, 1, 1) // bottom-right
            this.putInStack(testItem, type, 1, 0) // bottom
            this.putInStack(testItem, type, 1, -1) // bottom-left
            this.putInStack(testItem, type, 0, -1) // left
        }

        return null
    }

    private putInStack(sourceItem: Item, type: number, rowOffset: number, columnOffset: number): void {
        let item: Item = this.getItem(sourceItem, rowOffset, columnOffset)
        if (item && this.itemGoodForChain(item, type)) {
            this.stack.push(item)
        }
    }

    private getItem(sourceItem: Item, rowOffset: number, columnOffset: number): Item {
        let cell: Cell = sourceItem.cell
        let row: number = cell.row + rowOffset
        let column: number = cell.column + columnOffset
        if (row >= 0 && row < this.grid.rows && column >= 0 && column < this.grid.columns) {
            return this.grid.getCellAt(row, column).item
        }
    }

    private itemGoodForChain(item: Item, type: number): boolean {
        return item.itemType === type && this.foundChain.indexOf(item) === -1
    }

    public destroy(): void {
        this.game = null
        this.grid = null
        this.stack = null
        this.foundChain = null
    }
}
