import { Main } from './Main'

export interface ShareData {
	text: string
	title: string
	url: string
}

export class WebShare {
	private game: Main
	private isEnabled: boolean = false
	private _share: (data?: ShareData) => Promise<void>

	constructor(_game: Main) {
		this.game = _game
		this.isEnabled = typeof navigator['share'] === 'function'

		if (this.isEnabled) {
			this._share = navigator.share.bind(navigator)
		}
	}

	public share(text: string, url?: string, title?: string): Promise<void> {
		if (this.isEnabled === false) {
			this.game.toast.showShareWarningMessage()
			return Promise.reject("WebShare API isn't available")
		}

		let _default = {
			url: location.href,
			title: window.game.config['game_title'],
		}

		return this._share({
			..._default,
			title,
			text,
			url,
		})
	}
}
