import { DeferredPromise } from '@open-draft/deferred-promise'
import pRetry from 'p-retry'
import { Logger } from 'tslog'
import { loadScript } from '../robowhale/net/load-script'
import { getErrorLog } from '../robowhale/utils/error/utils'
import { TypedEventEmitter } from './../robowhale/TypedEventEmitter'

type Events = {
	'multi-session': () => void
}

export type PlayerRole = 'admin' | 'user'

export interface GamePushServiceOptions {
	logger: Logger<{}>
	projectId: string
	publicToken: string
}

/**
 * @link https://gamepush.com/panel/projects/20712/public
 * @link https://docs.gamepush.com/docs/api/#overview
 */
export class GamePushService extends TypedEventEmitter<Events> {
	private readonly _logger: Logger<{}>
	private readonly _projectId: string
	private readonly _publicToken: string
	private _ready = false
	private _sdk: gamePush.SDK | undefined

	constructor(options: GamePushServiceOptions) {
		super()

		this._logger = options.logger
		this._projectId = options.projectId
		this._publicToken = options.publicToken
	}

	public async init(): Promise<void> {
		if (this._ready) {
			return
		}

		const complete = new DeferredPromise<void>()

		window.onGPInit = async (gp) => {
			this._sdk = gp
			this._logger.info('sdk ready')

			gp.on('event:connect', () => this.emit('multi-session'))

			await this._sdk.player.ready
			this._logger.info(`player ready (id: ${this._sdk.player.id}, role: ${this.playerRole})`)

			this._ready = true

			complete.resolve()
		}

		const projectId = this._projectId
		const publicToken = this._publicToken

		// we have to use `gs.eponesh.com` instead of `gamepush.com` because Yandex is blocking `gamepush.com`
		const url = `https://gs.eponesh.com/sdk/gamepush.js?projectId=${projectId}&publicToken=${publicToken}&callback=onGPInit`

		// load sdk script with retries
		this.loadSdkScript(url).catch((error) => complete.reject(error))

		return complete
	}

	private async loadSdkScript(url: string): Promise<void> {
		try {
			await pRetry(
				async (attempt) => {
					if (attempt > 1) {
						this._logger.warn(`retrying script load (attempt: ${attempt})`)
					}

					await loadScript(url)
				},
				{
					retries: 5,
					onFailedAttempt: (error) => {
						this._logger.error(
							`script failed to load (attempt: ${error.attemptNumber}, remaining: ${error.retriesLeft}) (${getErrorLog(error)})`
						)
					},
				}
			)
		} catch (error) {
			this._logger.error(`script failed to load (exhausted all retries) (${getErrorLog(error)})`)
			throw error
		}
	}

	public get ready(): boolean {
		return this._ready
	}

	public get sdk(): gamePush.SDK {
		return this._sdk
	}

	public get player(): gamePush.Player {
		return this._sdk.player
	}

	/**
	 * Returns the current player's role.
	 */
	public get playerRole(): PlayerRole {
		const role = this.player.get('role')
		if (!role) {
			return 'user'
		}

		if (role.toLowerCase() === 'admin') {
			return 'admin'
		}

		return 'user'
	}

	/**
	 * Current server time in milliseconds
	 */
	public get serverTime(): number {
		return new Date(this._sdk.serverTime).getTime()
	}
}

/**
 * Returns a string identifier for the current month's leaderboard.
 * Uses a one-based month index (01-12) combined with the year.
 * @param nowMs - Unix timestamp in milliseconds. Defaults to current time if not provided.
 * @returns The month identifier in YYYY-MM format
 * @example
 * // If called in March 2024
 * getMonthLeaderboardVariant() // returns "2024-03"
 */
export function getMonthLeaderboardVariant(nowMs = Date.now()): string {
	const now = new Date(nowMs)
	const month = now.getMonth() + 1
	const year = now.getFullYear()

	return `${year}-${month.toString().padStart(2, '0')}`
}

/**
 * Returns a string identifier for the current week's leaderboard.
 * Uses Monday as the start of the week and returns the date in YYYY-MM-DD format.
 * @param nowMs - Unix timestamp in milliseconds. Defaults to current time if not provided.
 * @returns The Monday date of the current week in YYYY-MM-DD format
 * @example
 * // If called on Wednesday March 20, 2024
 * getWeekLeaderboardVariant() // returns "2024-03-18"
 */
export function getWeekLeaderboardVariant(nowMs = Date.now()): string {
	// Create a date object from the timestamp
	const date = new Date(nowMs)

	// Create a new date object with the same year, month, and day
	// This ensures we're working with the local date without time zone issues
	const localDate = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate(), 0, 0, 0, 0))

	// Get the day of the week (0 = Sunday, 1 = Monday, etc.)
	const dayOfWeek = localDate.getUTCDay()

	// Calculate days to subtract to get to Monday
	// If Sunday (0), go back 6 days
	// If Monday (1), go back 0 days
	// If Tuesday (2), go back 1 day, etc.
	const daysToSubtract = dayOfWeek === 0 ? 6 : dayOfWeek - 1

	// Create a new date for Monday
	const monday = new Date(localDate)
	monday.setUTCDate(localDate.getUTCDate() - daysToSubtract)

	// Format as YYYY-MM-DD
	const year = monday.getUTCFullYear()
	const month = String(monday.getUTCMonth() + 1).padStart(2, '0')
	const day = String(monday.getUTCDate()).padStart(2, '0')

	return `${year}-${month}-${day}`
}
