import { FontWeight, GameFonts } from '../../../../GameFonts'
import { BoosterType } from '../../boosters/BoosterType'
import { IFreeBoostersState } from '../../undo/SaveGameState'
import { FreeBoostersButton } from './FreeBoostersButton'

export class FreeBoostersPopover extends Phaser.Group {
	private back: Phaser.Image
	private text: Phaser.Text
	public freeRemoveButton: FreeBoostersButton
	public freeUndoButton: FreeBoostersButton
	private buttons: FreeBoostersButton[]
	private buttonsGroup: Phaser.Group
	public onBoosterRewarded: Phaser.Signal

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'free_boosters_popover')

		this.onBoosterRewarded = new Phaser.Signal()

		this.addBack()
		this.addText()
		this.addButtons()
		this.alignButtons()
	}

	private addBack(): void {
		this.back = this.game.add.image(0, 0, 'interface', 'Free_Boosters_Back0000', this)
		this.back.anchor.set(0.5, 0)
	}

	private addText(): void {
		let content: string = this.game.texts.texts.watch_video

		let style: Phaser.PhaserTextStyle = {
			font: GameFonts.DEFAULT,
			fontWeight: FontWeight.BOLD,
			fontSize: 33,
			fill: '#ffffff',
			align: 'center',
		}

		let maxHeight = 100
		this.text = this.game.add.text(0, 0, content, style, this)
		this.text.anchor.set(0.5, 0.5)
		this.text.wordWrap = true
		this.text.wordWrapWidth = this.back.width * 0.9
		this.text.lineSpacing = -10
		this.text.scale.set(Math.min(1, maxHeight / this.text.height))
		this.text.centerX = this.back.centerX
		this.text.centerY = this.back.top + 86
	}

	private addButtons(): void {
		this.freeRemoveButton = new FreeBoostersButton(this.game, 'interface', 'Button_Free_Remove0000', this)
		this.freeRemoveButton.booster = BoosterType.REMOVE
		this.freeRemoveButton.boostersNum = 2

		this.freeUndoButton = new FreeBoostersButton(this.game, 'interface', 'Button_Free_Undo0000', this)
		this.freeUndoButton.booster = BoosterType.UNDO
		this.freeUndoButton.boostersNum = 3

		this.buttons = [this.freeRemoveButton, this.freeUndoButton]
		this.buttons.forEach((button) => {
			button.events.onInputUp.add(this.onButtonClick, this)
		})

		this.buttonsGroup = this.game.add.group(this, 'buttons')
		this.buttonsGroup.addMultiple(this.buttons, true)
		this.buttonsGroup.align(1, 2, this.freeUndoButton.width, this.freeUndoButton.height * 1.25, Phaser.CENTER)
	}

	private alignButtons() {
		let top: number = this.text.bottom
		let bottom: number = this.back.bottom
		let height: number = bottom - top

		this.buttonsGroup.centerX = this.back.centerX
		this.buttonsGroup.centerY = top + height / 2
	}

	private onButtonClick(button: FreeBoostersButton): void {
		this.game.ads.showRewarded(`Gameplay:FreeBoostersPopover:${button.booster}`).then((result) => {
			if (result.success === true) {
				button.disable()
				this.onRewardedAdComplete(button.booster, button.boostersNum)
			} else {
				// this.onRewardedAdFail()
			}
		})
	}

	private onRewardedAdComplete(boosterType: BoosterType, boostersNum: number): void {
		this.onBoosterRewarded.dispatch(boosterType, boostersNum)
	}

	private onRewardedAdFail(): void {
		this.game.toast.showRewardedVideoWarning()
	}

	public show(): void {
		this.revive()

		this.game.tweens.removeFrom(this)
		this.game.tweens.removeFrom(this.scale)

		this.alpha = 1
		this.scale.set(1)

		this.game.add.tween(this.scale).from({ x: 0.9, y: 0.9 }, 400, Phaser.Easing.Back.Out, true)
		this.game.add.tween(this).from({ alpha: 0, y: '-20' }, 200, Phaser.Easing.Cubic.Out, true)

		/*let offsetY:number = 50 * Config.ASSETS_SCALE;
        this.alpha = 0;
        this.y += offsetY;
        this.game.add.tween(this).to({alpha: 1, y: this.y - offsetY}, 300, Phaser.Easing.Cubic.Out, true);*/
	}

	public hide(): void {
		this.game.add
			.tween(this)
			.to({ alpha: 0, y: '+25' }, 150, Phaser.Easing.Cubic.Out, true)
			.onComplete.addOnce(() => {
				this.visible = false
				this.exists = false
			})
	}

	public getButtonByBoosterType(boosterType: BoosterType): FreeBoostersButton {
		return this.buttons.find((button) => button.booster === boosterType)
	}

	public getSaveState(): IFreeBoostersState {
		return this.buttons.reduce((acc, button) => {
			return { ...acc, [button.booster]: button.enabled === false }
		}, {}) as any
	}

	public loadState(freeBoosters: IFreeBoostersState) {
		Object.keys(freeBoosters).forEach((key: BoosterType) => {
			let wasUsed: boolean = freeBoosters[key]
			if (wasUsed === true) {
				this.getButtonByBoosterType(key).disable()
			}
		})
	}

	public destroy(): void {
		super.destroy(true, false)

		this.buttons = null

		this.onBoosterRewarded.dispose()
		this.onBoosterRewarded = null
	}
}
