import { TypedEmitter } from 'tiny-typed-emitter'
import { Logger } from 'tslog'
import { prettyMs } from '../vendors/to-milliseconds'
import { IVisibilityProvider } from './IVisibilityProvider'
import { WebVisibilityProvider } from './WebVisibilityProvider'

type Events = {
	'page-hidden': () => void
	'page-visible': (hiddenTimeMs: number, hideSignal: AbortSignal) => void
}

export interface VisibilityServiceOptions {
	logger: Logger<unknown>
	provider?: IVisibilityProvider
}

/**
 * Tracks page visibility and emits events when the page is hidden / visible.
 * Provides an AbortSignal that is aborted when the page becomes hidden.
 */
export class VisibilityService extends TypedEmitter<Events> {
	private _hiddenAt = 0
	private readonly _logger: Logger<unknown>
	private readonly _provider: IVisibilityProvider
	private _hideController: AbortController = new AbortController()

	public constructor(options: VisibilityServiceOptions) {
		super()

		this._logger = options.logger

		this._provider = options.provider ?? new WebVisibilityProvider()

		this._logger.info(`initialized (provider: ${this._provider.name}, initial state: ${this._provider.getState()})`)

		if (this._provider.getState() === 'hidden') {
			this._hiddenAt = Date.now()
			this._hideController.abort()
		}

		this._provider.addChangeListener(this.onVisibilityChange)
	}

	private onVisibilityChange = (): void => {
		if (this._provider.getState() === 'hidden') {
			this.onHidden()
			return
		}

		this.onVisible()
	}

	private onHidden(): void {
		this._hiddenAt = Date.now()
		this._hideController.abort()
		this._logger.info('page hidden')
		this.emit('page-hidden')
	}

	private onVisible(): void {
		// don't emit visible event if page wasn't hidden
		// it happens sometimes on iOS
		if (!this._hiddenAt) {
			return
		}

		const hiddenTimeMs = Date.now() - this._hiddenAt
		this._hiddenAt = 0
		this._hideController = new AbortController()
		this._logger.info(`page visible [was hidden for ${prettyMs(hiddenTimeMs)}]`)
		this.emit('page-visible', hiddenTimeMs, this._hideController.signal)
	}

	public get isPageVisible(): boolean {
		return this._provider.getState() === 'visible'
	}

	public get isPageHidden(): boolean {
		return this._provider.getState() === 'hidden'
	}

	/**
	 * Все операции с сетью и IndexedDb лучше выполнять когда вкладка с игрой активна, это уменьшает вероятность ошибок.
	 */
	public untilPageIsVisible(): Promise<{ hiddenTimeMs: number; hideSignal: AbortSignal }> {
		if (this.isPageVisible) {
			return Promise.resolve({ hiddenTimeMs: 0, hideSignal: this.hideSignal })
		}

		return new Promise((resolve) => {
			this.once('page-visible', (hiddenTimeMs, hideSignal) => resolve({ hiddenTimeMs, hideSignal }))
		})
	}

	public get hideSignal(): AbortSignal {
		return this._hideController.signal
	}
}
