import toMs from '@sindresorhus/to-milliseconds'
import { TypedEmitter } from 'tiny-typed-emitter'
import { Logger } from 'tslog'
import { Result } from '../robowhale/Result'
import { timeout } from '../robowhale/utils/async/timeout'
import { prettyMs } from '../vendors/to-milliseconds'
import { VisibilityService } from '../visibility/VisibilityService'
import { IAdsProvider } from './providers/IAdsProvider'
import { UrlParams } from '../url-params/UrlParams'
import { Deferred } from '../robowhale/utils/async/deferred'

export type AdBasicResult = Result<never, AdBasicError>

export type AdBasicError = {
	code: AdErrorCode
	message?: string
}

export type AdResult = Result<
	{
		adType: AdType
		placement: string
	},
	AdError
>

export type AdError = {
	adType: AdType
	placement: string
	code: AdErrorCode
	message?: string
}

export enum AdErrorCode {
	/** У игрока запущен adblock */
	ADBLOCKED,

	/** Достигнут лимит на количество вызывов (нужно дождаться завершения кулдауна) */
	CALL_LIMIT,

	/** Игрок пропустил рекламу (актуально для rewarded) */
	SKIP,

	/** Общая ошибка, не требующая отдельной обработки */
	GENERIC,

	/** Реклама для игрока не найдена */
	NO_FILL,
}

export type AdType = 'interstitial' | 'rewarded'

export type AdTimings = {
	requestedAt: number
	willRestoreAt: number
}

export interface AdsServiceOptions {
	game: Phaser.Game
	provider: IAdsProvider
	visibility: VisibilityService
	logger: Logger<unknown>
	cooldownMs: {
		interstitial: number
		rewarded: number
	}
}

/**
 * Время ожидания рекламы от платформы (ОК, ВК и тд).
 * По прошествии этого времени запрос считается зависшим и прерывается.
 */
export const AD_TIMEOUT = 45_000

type Events = {
	'before-ad-start': (timeoutAt: number, adType: AdType) => void
	'after-ad-finish': (adType: AdType, result: AdBasicResult) => void
	'rewarded-ad-avail-changed': (adsAreAvail: boolean) => void
}

export class AdsService extends TypedEmitter<Events> {
	private options: AdsServiceOptions
	public logger: Logger<unknown>
	public preloaderAdComplete: Deferred<void> | undefined
	public bannerAdComplete: Deferred<void> | undefined
	private adInProgress = false
	private _provider: IAdsProvider
	private _timings: { [adType in AdType]: AdTimings }
	private _isRewardedAdAvail = true
	private _rewardedAdPreloadEnabled = true

	constructor(options: AdsServiceOptions) {
		super()

		this.options = options

		this.logger = options.logger
		this.logger.info(`ad provider: ${options.provider.name}`)
		this.logger.info(`interstitials cooldown ${options.cooldownMs.interstitial} ms`)
		this.logger.info(`rewarded cooldown ${options.cooldownMs.rewarded} ms`)

		this._provider = options.provider

		this._timings = {
			interstitial: this.createAdTimings(),
			rewarded: this.createAdTimings(),
		}
	}

	private createAdTimings(): AdTimings {
		return {
			requestedAt: 0,
			willRestoreAt: Date.now(),
		}
	}

	public async preloadRewardedAd() {
		if (!this._rewardedAdPreloadEnabled || UrlParams.get('rewardedAds') === '0') {
			return
		}

		this._isRewardedAdAvail = false

		const preloadStartedAt = Date.now()

		this.logger.info(`rewarded ad preload - start`)

		const result = await this._provider.loadRewarded()

		const preloadDurationMs = Date.now() - preloadStartedAt

		if (result.success === true) {
			this.logger.info(`rewarded ad preload - complete [${preloadDurationMs} ms]`)
			this._isRewardedAdAvail = true
			this.emit('rewarded-ad-avail-changed', true)
			return
		}

		const msTillRetry = this.getMsBetweenRewardedAdPreloadAttempts()

		this.logger.info(
			`rewarded ad preload - failed (will retry in ${prettyMs(msTillRetry)}) [${preloadDurationMs} ms]`
		)

		timeout(msTillRetry)
			.then(() => this.options.visibility.untilPageIsVisible())
			.then(() => this.preloadRewardedAd())

		this._isRewardedAdAvail = false

		this.emit('rewarded-ad-avail-changed', false)
	}

	private getMsBetweenRewardedAdPreloadAttempts(): number {
		return toMs({ minutes: 1.5 })
	}

	public async showInterstitial(placement: string): Promise<AdResult> {
		if (UrlParams.get('interAds') === '0') {
			return Result.Error({
				adType: 'interstitial',
				placement,
				code: AdErrorCode.GENERIC,
				message: 'interstitials are disabled',
			})
		}

		if (this.adInProgress) {
			return Result.Error({
				adType: 'interstitial',
				placement,
				code: AdErrorCode.GENERIC,
				message: 'another ad is in progress',
			})
		}

		if (!this._provider) {
			return Result.Error({
				adType: 'interstitial',
				placement,
				code: AdErrorCode.GENERIC,
				message: 'ad provider is missing',
			})
		}

		if (this.isCooldownActive('interstitial')) {
			return Result.Error({
				adType: 'interstitial',
				placement,
				code: AdErrorCode.CALL_LIMIT,
				message: 'ad cooldown is active',
			})
		}

		await this.beforeAdStart('interstitial', placement)

		const result = await this._provider.showInterstitial()

		await this.afterAdFinish('interstitial', placement, result)

		return result.success === true
			? Result.Ok({ adType: 'interstitial', placement })
			: Result.Error({ adType: 'interstitial', placement, ...result.error })
	}

	public async showRewarded(placement: string): Promise<AdResult> {
		if (UrlParams.get('rewardedAds') === '0') {
			return Result.Error({
				adType: 'rewarded',
				placement,
				code: AdErrorCode.GENERIC,
				message: 'rewarded ads are disabled',
			})
		}

		if (this.adInProgress) {
			return Result.Error({
				adType: 'rewarded',
				placement,
				code: AdErrorCode.GENERIC,
				message: 'another ad is in progress',
			})
		}

		if (!this._provider) {
			return Result.Error({
				adType: 'rewarded',
				placement,
				code: AdErrorCode.GENERIC,
				message: 'ad provider is missing',
			})
		}

		if (this.isCooldownActive('rewarded')) {
			return Result.Error({
				adType: 'rewarded',
				placement,
				code: AdErrorCode.CALL_LIMIT,
				message: 'ad cooldown is active',
			})
		}

		await this.beforeAdStart('rewarded', placement)

		const result = await this._provider.showRewarded()

		await this.afterAdFinish('rewarded', placement, result)

		if (result.success === true) {
			// сразу пытаемся подгрузить новую рекламу
			this.preloadRewardedAd()

			return Result.Ok({ adType: 'rewarded', placement })
		} else {
			return Result.Error({ adType: 'rewarded', placement, ...result.error })
		}
	}

	private async beforeAdStart(adType: AdType, placement: string) {
		const now = Date.now()
		this.emit('before-ad-start', now + AD_TIMEOUT, adType)
		this._timings[adType].requestedAt = now
		this.adInProgress = true

		return this.options.game.audio.beforeAdShow()
	}

	private async afterAdFinish(adType: AdType, placement: string, result: AdBasicResult) {
		await this.options.game.audio.afterAdShow()

		if (result.success === true) {
			this.onAdComplete(adType, placement)
		} else {
			this.onAdFail(adType, placement, result.error)
		}

		this.adInProgress = false
		this.emit('after-ad-finish', adType, result)
	}

	private onAdComplete(adType: AdType, placement: string): void {
		const timing = this._timings[adType]
		const cooldownMs = this.options.cooldownMs[adType]
		timing.willRestoreAt = timing.requestedAt + cooldownMs

		this.logger.info(`${adType} ad complete`)
	}

	private onAdFail(adType: AdType, placement: string, error: AdBasicError): void {
		if (error.code === AdErrorCode.SKIP || error.code === AdErrorCode.CALL_LIMIT) {
			const timing = this._timings[adType]
			const cooldownMs = this.options.cooldownMs[adType]
			timing.willRestoreAt = timing.requestedAt + cooldownMs
		}

		this.logger.warn(`${adType} ad failed - ${error.message}`)
	}

	public get provider(): IAdsProvider {
		return this._provider
	}

	public isCooldownActive(adType: AdType): boolean {
		return this._timings[adType].willRestoreAt > Date.now()
	}

	public getCooldownCompleteTime(adType: AdType): number {
		return this._timings[adType].willRestoreAt
	}

	public setCooldownValue(adType: AdType, ms: number): void {
		this.options.cooldownMs[adType] = ms
	}

	public disableRewardedAdPreloading(): void {
		this._rewardedAdPreloadEnabled = false
		this.logger.info('rewarded ad preload - disabled')
	}

	public get isRewardedAdAvail(): boolean {
		return this._isRewardedAdAvail
	}
}
