export class DrawUtil {
    public static createRectTexture(
        _game: Phaser.Game,
        width: number,
        height: number,
        colorHex: string = '#000000',
        cacheKey?: string
    ): Phaser.BitmapData {
        let color: any = Phaser.Color.hexToColor(colorHex)
        let addToCache: boolean = !!cacheKey
        let texture: Phaser.BitmapData = _game.add.bitmapData(width, height, cacheKey, addToCache)
        texture.fill(color.r, color.g, color.b)

        return texture
    }

    public static createCircleTexture(
        _game: Phaser.Game,
        radius: number,
        colorHex: string = '#000000',
        cacheKey?: string
    ): Phaser.BitmapData {
        //let color:any = Phaser.Color.hexToColor(colorHex);
        let addToCache: boolean = !!cacheKey
        let texture: Phaser.BitmapData = _game.add.bitmapData(radius * 2, radius * 2, cacheKey, addToCache)
        texture.context.fillStyle = colorHex
        texture.circle(radius, radius, radius)

        return texture
    }
}
