import { Config } from '../../../../Config'
import { FontWeight, GameFonts } from '../../../../GameFonts'
import { IGameOverState } from '../../undo/SaveGameState'
import { BoosterHint } from '../boostersPanel/BoosterHint'
import { GameOverButton } from './GameOverButton'
import { GameOverVideoButton } from './GameOverVideoButton'
import PhaserTextStyle = Phaser.PhaserTextStyle
export class GameOverGUI extends Phaser.Group {
	private back: Phaser.Image
	private title: Phaser.Text
	public shuffleButton: GameOverVideoButton
	public endGameButton: GameOverButton
	private buttons: GameOverButton[]
	private buttonsGroup: Phaser.Group
	public onShuffle: Phaser.Signal
	public onUndo: Phaser.Signal
	public onEndGame: Phaser.Signal

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'game_over_gui')

		this.onShuffle = new Phaser.Signal()
		this.onUndo = new Phaser.Signal()
		this.onEndGame = new Phaser.Signal()

		this.addBack()
		this.addTitle()
		this.addButtons()

		this.bringToTop(this.title)
	}

	private addBack(): void {
		this.back = this.game.add.image(0, 0, 'interface', 'Game_Over_Top_Panel0000', this)
	}

	private addTitle(): void {
		let content: string = this.game.texts.texts['no_moves']

		let style: PhaserTextStyle = {
			font: GameFonts.NUNITO_CSS,
			fontSize: 48,
			fontWeight: FontWeight.BOLD,
			fill: '#ffffff',
			align: 'center',
		}

		this.title = this.game.add.text(0, 0, content, style, this)
		this.title.anchor.set(0.5, 0.5)
		this.title.centerX = this.back.centerX
		this.title.top = this.back.top + 20
	}

	private alignTitle(): void {
		let maxWidth: number = this.back.width * 0.8

		this.title.scale.set(1)
		if (this.title.width > maxWidth) {
			this.title.scale.set(maxWidth / this.title.width)
		}

		this.title.centerX = this.back.centerX
		this.title.centerY = this.back.top + (this.buttonsGroup.top - this.back.top) / 2 + 4
	}

	private addButtons(): void {
		let shuffleContent: string = this.game.texts.texts['video_shuffle']
		this.shuffleButton = new GameOverVideoButton(this.game, this, shuffleContent)
		this.shuffleButton.name = 'SHUFFLE'
		this.shuffleButton.userData.signal = this.onShuffle
		this.shuffleButton.setCallbackOn('pointerup')
		this.shuffleButton.callback.addOnce(this.onIncentiveButtonClick, this)

		let endGameContent: string = this.game.texts.texts['game_end']
		this.endGameButton = new GameOverButton(this.game, this, endGameContent)

		this.buttons = [this.shuffleButton, this.endGameButton]

		this.buttonsGroup = this.game.add.group(this, 'buttons')
		this.buttonsGroup.addMultiple(this.buttons, true)
		this.buttonsGroup.align(this.buttons.length, 1, 250, this.shuffleButton.height, Phaser.CENTER)
	}

	private onIncentiveButtonClick(button: GameOverVideoButton): void {
		this.game.ads.showRewarded('GameOver:ShuffleButton').then((result) => {
			if (result.success === true) {
				button.markAsUsed()
				button.userData.signal.dispatch()
			} else {
				// this.onRewardedAdFail()
			}
		})
	}

	public enableButtons(): void {
		this.buttons.forEach((button) => {
			if (button instanceof GameOverVideoButton) {
				if (button.wasUsed === false) {
					button.enable()
				}
			} else {
				button.enable()
			}
		})
	}

	private disableButtons(): void {
		this.buttons.forEach((button) => {
			button.disable()
		})
	}

	public show(): void {
		this.revive()

		this.alpha = 1
		this.game.add.tween(this).from({ alpha: 0, y: '-30' }, 300, Phaser.Easing.Cubic.Out, true)

		this.title.visible = true
		this.alignTitle()

		this.enableButtons()
		this.showButtons(150)
	}

	private showButtons(initialDelay: number = 0): void {
		this.buttons.forEach((button, index) => {
			button.visible = true
			// button.alpha = 1;
			button.scale.set(1)

			let delay: number = initialDelay + index * 100
			this.game.add.tween(button).from({ alpha: 0 }, 150, Phaser.Easing.Cubic.Out, true, delay)
			this.game.add.tween(button.scale).from({ x: 0.8, y: 0.8 }, 400, Phaser.Easing.Back.Out, true)
			// this.game.add.tween(button).from({y: "+10"}, 100, Phaser.Easing.Cubic.Out, true, delay);
		})
	}

	public hide(): void {
		this.disableButtons()

		this.game.add
			.tween(this)
			.to({ y: '-50', alpha: 0 }, 200, Phaser.Easing.Cubic.In, true)
			.onComplete.addOnce(() => {
				this.visible = false
				this.exists = false
			})
	}

	public shake(): void {
		this.shakeText()
		this.shakeButtons()
	}

	private shakeText() {
		this.game.tweens.removeFrom(this.title)
		this.title.x = this.back.centerX
		this.game.add.tween(this.title).to({ x: '-14' }, 50, Phaser.Easing.Sinusoidal.InOut, true, 0, 6, true)
	}

	private shakeButtons(): void {
		this.buttons.filter((button) => button.enabled === true && button.visible === true).forEach((button, index) => {
			let delay: number = index * 100
			this.game.tweens.removeFrom(button.scale)
			button.scale.set(1)
			this.game.add.tween(button.scale).to(
				{
					x: 1.15,
					y: 1.15,
				},
				200,
				Phaser.Easing.Sinusoidal.InOut,
				true,
				delay,
				0,
				true
			)
		})
	}

	public onBoosterSelected(boosterHint: BoosterHint): void {
		this.title.visible = false
		this.buttons.forEach((button) => {
			button.visible = false
		})

		this.y = -1 * (this.height - boosterHint.height) + 5 * Config.ASSETS_SCALE
	}

	public onBoosterCancelled(): void {
		this.title.visible = true
		this.buttons.forEach((button) => {
			button.visible = true
		})
		this.y = 0
	}

	public enableInput() {
		this.ignoreChildInput = false
		this.buttons.forEach((button) => {
			button.ignoreChildInput = false
		})
	}

	public disableInput() {
		this.ignoreChildInput = true
		this.buttons.forEach((button) => {
			button.ignoreChildInput = true
		})
	}

	public resize(width: number) {
		this.back.width = width

		this.alignButtons()
		this.alignTitle()
	}

	private alignButtons() {
		this.buttonsGroup.centerX = this.back.centerX
		this.buttonsGroup.centerY = 120
	}

	public getButtonGlobalPosition(button: GameOverButton): PIXI.Point {
		return button.parent.toGlobal(button.position)
	}

	public getSaveState(): IGameOverState {
		return {
			shuffleUsed: this.shuffleButton.wasUsed,
		}
	}

	public loadState(state: IGameOverState): void {
		if (state.shuffleUsed) {
			this.shuffleButton.markAsUsed()
		}
	}

	public destroy(): void {
		super.destroy(true, false)

		this.buttons = null
		this.disposeSignals()
	}

	private disposeSignals() {
		this.onShuffle.dispose()
		this.onShuffle = null
		this.onUndo.dispose()
		this.onUndo = null
		this.onEndGame.dispose()
		this.onEndGame = null
	}
}
