import { StatCircle } from './StatCircle'

export class CoinsCircle extends StatCircle {
	public coinsNum: number = 0
	public originalScale: Phaser.Point

	constructor(
		_game: Phaser.Game,
		parent: Phaser.Group,
		circleTextureKey: string,
		circleTextureFrame: string,
		textColor: number,
		textContent: string
	) {
		super(_game, parent, circleTextureKey, circleTextureFrame, textColor, textContent)
	}

	public setCoinsNum(coins: number): void {
		this.text.setText(coins)
		this.coinsNum = coins
	}

	public updateCoins(newNumber: number, delay: number = 0): void {
		let duration: number = 1300

		this.tweenCoins(newNumber, duration, delay)
		this.game.add.tween(this.scale).to({ x: 0.66, y: 0.66 }, duration, Phaser.Easing.Linear.None, true, delay)
	}

	private tweenCoins(newNumber: number, duration: number, delay: number) {
		let tween: Phaser.Tween = this.game.add
			.tween(this)
			.to({ coinsNum: newNumber }, duration, Phaser.Easing.Cubic.Out, true, delay)

		tween.onStart.addOnce(() => {
			this.game.audio.playSound('score_count_2', 0.5)
		})

		tween.onUpdateCallback(() => {
			this.coinsNum = Math.round(this.coinsNum)
			this.text.setText(this.coinsNum)
		})

		tween.onComplete.addOnce(() => {
			this.onCoinsTweenComplete()
		})
	}

	private onCoinsTweenComplete(): void {
		this.text.y = 0
		this.game.add.tween(this.scale).to(
			{
				x: this.originalScale.x,
				y: this.originalScale.y,
			},
			1000,
			Phaser.Easing.Elastic.Out,
			true
		)
	}

	public destroy(): void {
		this.game.tweens.removeFrom(this)
		this.game.tweens.removeFrom(this.scale)

		super.destroy()
	}
}
