import { ResizeSensor } from 'css-element-queries'
import { debounce } from 'es-toolkit/compat'
import { Config } from './Config'
import { UrlParams } from './url-params/UrlParams'

export interface GameScalerOptions {
	game: Phaser.Game
	scaleMode: ScaleMode
}

export type ScaleMode = 'desktop' | 'mobile'

export class GameScaler {
	private game: Phaser.Game
	private _scaleMode: ScaleMode = 'desktop'
	private resizeSensor: ResizeSensor | null = null
	private onViewportResize: (() => void) | null = null

	constructor(private readonly options: GameScalerOptions) {
		this.game = options.game

		this._scaleMode = UrlParams.has('mobileScale') ? 'mobile' : options.scaleMode

		if (this._scaleMode === 'desktop') {
			this.scaleForDesktop()
		} else {
			this.scaleForMobile()
		}
	}

	private scaleForDesktop(): void {
		const scale = this.game.scale

		scale.scaleMode = Phaser.ScaleManager.SHOW_ALL
		scale.fullScreenScaleMode = Phaser.ScaleManager.SHOW_ALL
		scale.aspectRatio = Config.SOURCE_GAME_WIDTH / Config.SOURCE_GAME_HEIGHT
		scale.compatibility.canExpandParent = false
		scale.pageAlignHorizontally = true
		scale.pageAlignVertically = true

		const maxWidth = UrlParams.getNumber('maxWidth')
		if (maxWidth && maxWidth > 0) {
			scale.maxWidth = maxWidth
			scale.maxHeight = maxWidth / scale.aspectRatio
		}

		document.addEventListener('fullscreenchange', () => {
			scale.compatibility.canExpandParent = !!document.fullscreenElement
		})
	}

	private scaleForMobile(): void {
		const scale = this.game.scale

		scale.scaleMode = Phaser.ScaleManager.EXACT_FIT

		// Phaser's reflowCanvas() calls resetCanvas() then updateScalingAndBounds().
		// resetCanvas() would overwrite canvas.style with internal game dimensions (e.g. 640x1286).
		// We replace it to instead fix scale.width/height to match the actual CSS display size,
		// so updateScalingAndBounds() computes the correct scaleFactor for input mapping.
		const scaleAny = scale as any
		scaleAny.resetCanvas = () => {
			const canvas = this.game.canvas
			const cssWidth = parseFloat(canvas.style.width) || canvas.width
			const cssHeight = parseFloat(canvas.style.height) || canvas.height
			scaleAny.width = cssWidth
			scaleAny.height = cssHeight
		}

		const canvasContainer = this.game.canvas.parentElement as HTMLDivElement | null
		if (!canvasContainer) {
			return
		}

		const resizeCallback = debounce(() => {
			this.onSizeChange(this.getViewportSize(canvasContainer))
		}, 150)

		// Keep a reference to avoid GC-related issues on some mobile browsers/WebViews.
		this.resizeSensor = new ResizeSensor(canvasContainer, resizeCallback)

		// Android browsers/WebViews often change the *visual* viewport height when the URL bar collapses/expands.
		// `visualViewport` tracks the actually-visible area better than `innerHeight`/DOM bounds.
		this.onViewportResize = resizeCallback
		window.addEventListener('resize', resizeCallback)
		window.visualViewport?.addEventListener('resize', resizeCallback)
		window.visualViewport?.addEventListener('scroll', resizeCallback)

		// Yandex (and other platforms) trigger fullscreen via the Fullscreen API.
		// Resize on fullscreen change to adapt canvas to the new viewport size.
		document.addEventListener('fullscreenchange', () => resizeCallback())

		resizeCallback()
	}

	private getViewportSize(container: HTMLElement): { width: number; height: number } {
		const vv = window.visualViewport
		if (vv) {
			return { width: vv.width, height: vv.height }
		}

		const bounds = container.getBoundingClientRect()
		const width = bounds.width || window.innerWidth
		const height = bounds.height || window.innerHeight
		return { width, height }
	}

	/**
	 * @param size Size of canvas container
	 */
	private onSizeChange(size: { width: number; height: number }): void {
		if (size.width > size.height) {
			this.showRotateOverlay()
			return
		}

		this.scaleGame(size.width, size.height)
		this.game.state.resize(Config.GAME_WIDTH, Config.GAME_HEIGHT)
		this.game.globalScene?.resize(Config.GAME_WIDTH, Config.GAME_HEIGHT)
		this.hideRotateOverlay()
	}

	private scaleGame(width?: number, height?: number): void {
		const newGameWidth = width ?? window.innerWidth
		const newGameHeight = height ?? window.innerHeight
		const originalWidth = Config.SOURCE_GAME_WIDTH
		const originalHeight = Config.SOURCE_GAME_HEIGHT
		const worldScale = Config.IS_PORTRAIT ? newGameWidth / originalWidth : newGameHeight / originalHeight

		this.game.scale.setGameSize(Math.ceil(newGameWidth / worldScale), Math.ceil(newGameHeight / worldScale))

		// setGameSize() sets scale.width/height to the internal game dimensions (e.g. 640x1286)
		// and scaleFactor to 1. For mobile scaling, we stretch the canvas to fit the viewport,
		// so we need to tell Phaser about the actual CSS display size for correct input mapping.
		if (this._scaleMode === 'mobile') {
			const canvas = this.game.canvas
			canvas.style.width = `${newGameWidth}px`
			canvas.style.height = `${newGameHeight}px`

			// Update Phaser's internal dimensions to match the CSS display size
			// so scaleFactor = game.width / displayWidth (e.g. 640/430 ≈ 1.49)
			const scaleAny = this.game.scale as any
			scaleAny.width = newGameWidth
			scaleAny.height = newGameHeight
			scaleAny.updateScalingAndBounds()
		}

		Config.WORLD_SCALE = worldScale
		Config.GAME_WIDTH = this.game.width
		Config.GAME_HEIGHT = this.game.height
		Config.HALF_GAME_WIDTH = Config.GAME_WIDTH * 0.5
		Config.HALF_GAME_HEIGHT = Config.GAME_HEIGHT * 0.5
		Config.ASPECT_RATIO = Config.GAME_WIDTH / Config.GAME_HEIGHT
		Config.GAME_BOUNDS.setTo(0, 0, Config.GAME_WIDTH, Config.GAME_HEIGHT)
		Config.GAME_CENTER.set(Config.HALF_GAME_WIDTH, Config.HALF_GAME_HEIGHT)
	}

	private showRotateOverlay(): void {
		const el = document.getElementById('rotate')
		if (el) el.style.display = 'flex'
	}

	private hideRotateOverlay(): void {
		const el = document.getElementById('rotate')
		if (el) el.style.display = 'none'
	}

	public get scaleMode(): ScaleMode {
		return this._scaleMode
	}
}
