import { err, ok } from 'neverthrow'
import { until } from 'until-async'
import type { Player } from 'ysdk'
import { getErrorLog } from '../robowhale/utils/error/utils'
import { BaseStorage, BaseStorageOptions, StorageLoadResult, StorageSaveResult } from './BaseStorage'

export interface YandexRemoteStorageOptions extends BaseStorageOptions {
	/** Player API used to load and save remote data. */
	player: Player
}

/**
 * @link https://yandex.ru/dev/games/doc/ru/sdk/sdk-player
 */
export class YandexRemoteStorage extends BaseStorage {
	private readonly options: YandexRemoteStorageOptions
	private readonly api: Player

	constructor(options: YandexRemoteStorageOptions) {
		super(options)

		this.options = options
		this.api = options.player
	}

	/**
	 * Loads state from Yandex player storage.
	 * @note Rate-limited to 100 requests per 5 minutes.
	 * @link https://yandex.ru/dev/games/doc/ru/sdk/sdk-player#limits
	 */
	public async loadState(): Promise<StorageLoadResult> {
		const [error, data] = await until(() => this.api.getData())

		if (error) {
			return err({ code: 'load_error', message: getErrorLog(error) })
		}

		const isObject = typeof data === 'object' && data !== null

		if (!isObject) {
			return err({ code: 'invalid_state', message: 'state is not an object' })
		}

		return ok(data)
	}

	/**
	 * Saves state to Yandex player storage.
	 * @note Rate-limited to 100 requests per 5 minutes.
	 * @param flush immediately sends data when true; when false (default) the request is queued by the SDK
	 * @link https://yandex.ru/dev/games/doc/ru/sdk/sdk-player#limits
	 */
	public async saveState(state: Record<string, unknown>, flush = true): Promise<StorageSaveResult> {
		if (!this._savesEnabled) {
			return err({ code: 'saves_disabled', message: 'saves are disabled' })
		}

		const [error] = await until(() => this.api.setData(state, flush))

		if (error) {
			return err({ code: 'save_error', message: getErrorLog(error) })
		}

		return ok({})
	}

	public async clearState(): Promise<StorageSaveResult> {
		const [error] = await until(() => this.api.setData({}, true))

		if (error) {
			return err({ code: 'clear_error', message: getErrorLog(error) })
		}

		return ok({})
	}
}
