import { Main } from '../../Main'

export class GameLogo extends Phaser.Group {
	private readonly starsNum: number = 3
	private scales: number[] = [0.44, 0.66, 1]
	private logo: Phaser.Image
	private leftStars: Phaser.Group
	private rightStars: Phaser.Group
	public originalY: number

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'game_logo')

		this.addLogo()
		this.addLeftStars()
		this.addRightStars()
	}

	private addLogo() {
		this.logo = this.game.add.image(0, 0, 'main_menu', 'Item_130000', this)
		this.logo.anchor.set(0.5, 0.5)
		this.logo.inputEnabled = true
		this.logo.data.clicks = 0
		this.logo.events.onInputDown.add(this.onClick, this)
		this.logo.name = 'game_logo'

		if (Main.development) {
			this.logo.input.useHandCursor = true
		}
	}

	private async onClick() {
		if (++this.logo.data.clicks !== 5) {
			return
		}

		this.logo.data.clicks = 0

		let clearSaveData = typeof window.confirm !== 'undefined' && window.confirm('Clear all saved data?') === true
		if (!clearSaveData) {
			return
		}

		await this.game.save.reset()
	}

	private addLeftStars() {
		this.leftStars = this.createStars()
		this.leftStars.name = 'left_stars'
		this.leftStars.right = this.logo.left - 20
		this.leftStars.centerY = this.logo.centerY
	}

	private addRightStars() {
		this.rightStars = this.createStars()
		this.rightStars.name = 'right_stars'
		this.rightStars.scale.x = -1
		this.rightStars.left = this.logo.right + 20
		this.rightStars.centerY = this.leftStars.centerY
	}

	private createStars(): Phaser.Group {
		let stars: Phaser.Group = this.game.add.group(this)
		stars.createMultiple(this.starsNum, 'main_menu', 'Title_Star0000', true)
		stars.children.forEach((child: Phaser.Sprite, index: number) => {
			child.anchor.set(0.5, 0.5)
			child.scale.set(this.scales[index])
		})
		stars.align(this.starsNum, 1, 52, 70, Phaser.CENTER)

		stars.children[1].x -= 9

		return stars
	}

	public show(initialDelay: number): void {
		this.showItem(initialDelay)
		this.showStars(initialDelay)
	}

	private showItem(initialDelay: number): void {
		this.game.add.tween(this.logo).from({ alpha: 0 }, 200, Phaser.Easing.Cubic.Out, true, initialDelay)

		this.game.add.tween(this.logo.scale).from(
			{
				x: 0.66,
				y: 0.66,
			},
			400,
			Phaser.Easing.Back.Out,
			true,
			initialDelay
		)

		// this.game.add.tween(this.logo).from({ angle: -15 }, 400, Phaser.Easing.Back.Out, true, initialDelay)

		this.centerY = this.originalY - 100
		this.game.add.tween(this).to({ y: this.originalY }, 500, Phaser.Easing.Back.Out, true, initialDelay)
	}

	private showStars(initialDelay: number): void {
		let delay: number = initialDelay + 200

		this.doShowStars(this.leftStars, delay)
		this.doShowStars(this.rightStars, delay)
	}

	private doShowStars(stars: Phaser.Group, initialDelay: number) {
		stars.children.reverse().forEach((star, index) => {
			let duration: number = 330 + 120 * index
			let delay: number = initialDelay + index * 100

			this.game.add.tween(star).from(
				{
					x: '-66',
					alpha: 0,
					angle: 30,
				},
				duration,
				Phaser.Easing.Cubic.Out,
				true,
				delay
			)
		})
	}

	public destroy(): void {
		super.destroy(true, false)
	}
}
