import { SentryErrorContext, BaseError } from './BaseError';

export type CreateErrorOptions = {
	errorOptions?: ErrorOptions

	/**
	 * Фатальные ошибки полностью останавливают игру.
	 * @default false
	 */
	isFatal?: boolean

	/**
	 * Контекст ошибки для отправки в Сентри.
	 */
	sentryContext?: SentryErrorContext
}

export function createError(name: string, message?: string, options?: CreateErrorOptions) {
	// Create a custom error class that extends BaseError
	class CustomError extends BaseError {
		public readonly isFatal: boolean = options?.isFatal ?? false;
	}

	const error = new CustomError(message, options?.errorOptions);
	error.name = name;

	if (options?.sentryContext !== undefined) {
		error.sentryContext = options.sentryContext;
	}

	return error;
}
