import { GameFonts } from '../../GameFonts'
import { Toast } from '../../gui/Toast'
import { LogsManager } from '../../logs/LogsManager'
import { NetUtil } from '../../robowhale/utils/NetUtil'
import { GameTexts } from '../../texts/GameTexts'
import { UrlParams } from '../../url-params/UrlParams'
import { GlobalScene } from '../global/GlobalScene'
import { BoostersManager } from '../level/boosters/BoostersManager'
import { BoosterType } from '../level/boosters/BoosterType'
import { FakeLevelStats } from '../level/FakeLevelStats'
import { SavedGameState } from './../level/undo/SaveGameState'

export class BasePreloader extends Phaser.State {
	private get logs(): LogsManager {
		return this.game.logs
	}

	private hasGameReadySent = false

	private fadeOutLoadingSpinner() {
		const loadingSpinner = this.getLoadingSpinner()
		if (loadingSpinner) {
			loadingSpinner.classList.add('spinner-fadeout')
		}
	}

	private removeLoadingSpinner(): void {
		const loadingSpinner = this.getLoadingSpinner()
		if (loadingSpinner) {
			loadingSpinner.remove()
		}
	}

	private getLoadingSpinner() {
		return document.getElementById('loading-spinner-container')
	}

	public preload() {
		this.game.analytics.sendLoadingEvent('main', 'start')
		// this.game.platform.sdk.gameLoadingStart()

		this.load.maxParallelDownloads = this.game.device.android ? 6 : 32
		this.load.onFileComplete.add(this.onLoadProgress, this)

		this.loadOtherAssets()
		this.loadFonts()
		this.loadAudio()
		this.loadGraphics()
	}

	public onLoadProgress() {}

	private loadOtherAssets(): void {
		this.load.json('boosters', 'assets/configs/boosters.json')
	}

	private loadFonts() {
		this.load.bitmapFontFromAtlas(
			GameFonts.BOOSTERS_SHOP_BARIOL_BOLD,
			'boosters_shop',
			'bariol_bold0000',
			'assets/fonts/bitmap/bariol_bold.fnt'
		)
		this.load.bitmapFontFromAtlas(
			GameFonts.BARIOL_BOLD_BMP,
			'interface',
			'bariol_bold0000',
			'assets/fonts/bitmap/bariol_bold.fnt'
		)
		this.load.bitmapFontFromAtlas(
			GameFonts.BARIOL_REGULAR_BMP,
			'interface',
			'bariol_regular0000',
			'assets/fonts/bitmap/bariol_regular.fnt'
		)
		this.load.bitmapFontFromAtlas(
			GameFonts.GAME_OVER_BARIOL_BOLD,
			'game_over',
			'bariol_bold0000',
			'assets/fonts/bitmap/bariol_bold.fnt'
		)
	}

	private loadAudio(): void {}

	private loadGraphics(): void {
		this.load.atlasJSONHash('leaderboard', 'assets/graphics/leaderboard.png', 'assets/graphics/leaderboard.json')
		this.load.atlasJSONHash('main_menu', 'assets/graphics/main_menu.png', 'assets/graphics/main_menu.json')
		this.load.atlasJSONHash(
			'language_button',
			'assets/graphics/button_language.png',
			'assets/graphics/button_language.json'
		)
		this.load.atlasJSONHash(
			'boosters_shop',
			'assets/graphics/boosters_shop.png',
			'assets/graphics/boosters_shop.json'
		)
		this.load.atlasJSONHash('interface', 'assets/graphics/interface.png', 'assets/graphics/interface.json')
		this.load.atlasJSONHash('game_over', 'assets/graphics/game_over.png', 'assets/graphics/game_over.json')
	}

	public async create() {
		this.addGlobalScene()
		this.addToast()
		await this.initTexts()
		this.initBoosters()
		this.addCheatResources()
		this.loadAudioDelayed()

		this.game.analytics.sendLoadingEvent('main', 'complete')

		this.startGame()
	}

	private addGlobalScene(): void {
		this.game.globalScene = new GlobalScene(this.game, this.game.world)
		this.game.stage.addChild(this.game.globalScene)
	}

	private addToast() {
		this.game.toast = new Toast(this.game, this.stage)
		this.game.toast.kill()
	}

	private async initTexts() {
		const platformLanguage = await this.game.platform.getLanguage()
		this.game.texts = new GameTexts({
			game: this.game,
			texts: window.game.texts,
			logger: this.logs.getOrCreate('l10n'),
			platformLanguage: platformLanguage,
		})

		const updateTextsCallback = () => {
			const texts = this.game.texts.texts
			this.game.errorsHandler.setTexts(texts)
			this.game.leaderboards?.setTexts(texts)
		}

		updateTextsCallback()

		this.game.texts.on('language-change', updateTextsCallback)

		this.game.analytics.sendDesignEvent(`Language:browser:${navigator.language}`)
		this.game.analytics.sendDesignEvent(`Language:game:${this.game.texts.language}`)
	}

	private initBoosters(): void {
		this.game.boosters = new BoostersManager(this.game)

		const addBoosters = NetUtil.getParamBool('boosters')
		if (addBoosters) {
			this.game.boosters.getBooster(BoosterType.MAGNET).num = 9
			this.game.boosters.getBooster(BoosterType.REMOVE).num = 9
			this.game.boosters.getBooster(BoosterType.UPGRADE).num = 3
			this.game.boosters.getBooster(BoosterType.SORT).num = 9
			this.game.boosters.getBooster(BoosterType.UNDO).num = 9
		}
	}

	private loadAudioDelayed() {
		const basePath = 'assets/audio/'
		const audioLoader = new Phaser.Loader(this.game)

		audioLoader.audio('tap', basePath + 'tap.mp3')
		audioLoader.audio('fancy_tap', basePath + 'fancy_tap.mp3')
		audioLoader.audio('coins_prize', basePath + 'coins_prize.mp3')
		audioLoader.audio('score_count_2', basePath + 'score_count_2.mp3')
		audioLoader.audio('pop_1', basePath + 'Pop_A.mp3')
		audioLoader.audio('pop_2', basePath + 'Pop_B.mp3')
		audioLoader.audio('pop_4', basePath + 'Pop_D.mp3')
		audioLoader.audio('item_convert', basePath + 'item_convert.mp3')
		audioLoader.audio('item_convert_2', basePath + 'item_convert_2.mp3')
		audioLoader.audio('toast_1', basePath + 'toast_1.mp3')
		audioLoader.audio('muted_error', basePath + 'muted_error.mp3')
		audioLoader.audio('new_item', basePath + 'new_item.mp3')
		audioLoader.audio('purchase', basePath + 'purchase.mp3')
		audioLoader.audio('game_complete_1', basePath + 'game_complete_1.mp3')
		audioLoader.audio('game_complete_2', basePath + 'game_complete_2.mp3')
		audioLoader.audio('coins_2', basePath + 'coins_2.mp3')
		audioLoader.audio('coins_3', basePath + 'coins_3.mp3')
		audioLoader.audio('no_moves_1', basePath + 'no_moves_1.mp3')
		audioLoader.audio('no_moves_2', basePath + 'no_moves_2.mp3')
		audioLoader.audio('whoosh', basePath + 'whoosh_up.mp3')
		audioLoader.audio('popup', basePath + 'popup.mp3')
		audioLoader.audio('shuffle', basePath + 'shake.mp3')
		audioLoader.audio('restart_1', basePath + 'restart_1.mp3')
		audioLoader.audio('booster_selected', basePath + 'booster_selected.mp3')
		audioLoader.audio('fforward', basePath + 'fforward.mp3')
		audioLoader.audio('tutorial', basePath + 'tutorial.mp3')

		audioLoader.resetLocked = true // prevent reset on state change
		audioLoader.onLoadComplete.addOnce(this.onAudioLoadComplete, this, 0, audioLoader)
		audioLoader.start()
	}

	private onAudioLoadComplete(loader: Phaser.Loader): void {
		console.groupCollapsed('Audio [delayed load]')

		loader._fileList.forEach((file) => {
			console.log(file.key, file.url, file.loaded)
		})

		console.groupEnd()
	}

	private addCheatResources() {
		if (UrlParams.has('coins')) {
			this.game.save.setValue('Coins', UrlParams.getNumber('coins'), { origin: 'preloader/cheat_resources' })
		}

		if (UrlParams.has('magnet')) {
			this.game.boosters.getBooster(BoosterType.MAGNET).num = UrlParams.getNumber('magnet')
		}

		if (UrlParams.has('undo')) {
			this.game.boosters.getBooster(BoosterType.UNDO).num = UrlParams.getNumber('undo')
		}

		if (UrlParams.has('remove')) {
			this.game.boosters.getBooster(BoosterType.REMOVE).num = UrlParams.getNumber('remove')
		}

		if (UrlParams.has('sort')) {
			this.game.boosters.getBooster(BoosterType.SORT).num = UrlParams.getNumber('sort')
		}

		if (UrlParams.has('upgrade')) {
			this.game.boosters.getBooster(BoosterType.UPGRADE).num = UrlParams.getNumber('upgrade')
		}
	}

	public async startGame() {
		if (this.game.ads.preloaderAdComplete) {
			await this.game.ads.preloaderAdComplete
		}

		if (this.game.ads.bannerAdComplete) {
			await this.game.ads.bannerAdComplete
		}

		if (this.tryStartFromUrl()) {
			return
		}

		const isPreview = window.game.config.build_type === 'dev'
		if (isPreview) {
			this.startGameDev()
		} else {
			this.startGameDist()
		}
	}

	private startGameDev() {
		this.game.changeState('MainMenu')
		// this.game.changeState("BoostersShop")
		// this.game.changeState("Level")
		// this.game.changeState("GameOver", { levelStats: new FakeLevelStats(this.game), skipStartAnimaition: false })
		// this.game.changeState("Test")
	}

	private startGameDist() {
		const isFirstTime = this.game.save.getValue('Tutorial') === false
		if (isFirstTime) {
			this.game.ads.showInterstitial('Preloader:ToGame').finally(() => {
				this.game.changeState('Level')
			})

			return
		}

		const savedGame = this.getSavedGameplayData()
		if (savedGame) {
			this.game.ads.showInterstitial('Preloader:ToGame').finally(() => {
				this.game.changeState('Level', savedGame)
			})

			return
		}

		this.game.changeState('MainMenu')
		// this.game.changeState("BoostersShop");
		// this.game.changeState("Level");
		// this.game.changeState("GameOver", new FakeLevelStats(this.game))
		// this.game.changeState("Test");
	}

	private getSavedGameplayData(): SavedGameState | null {
		const savedGame = this.game.save.getValue('saved_game_state')
		if (!savedGame) {
			return null
		}

		return SavedGameState.fromString(savedGame, this.game)
	}

	private tryStartFromUrl(): boolean {
		const startValue = UrlParams.get('start')
		if (!startValue) {
			return false
		}

		switch (startValue.trim().toLowerCase()) {
			case 'boostersshop':
			case 'boosters':
				this.game.changeState('BoostersShop')
				return true
			case 'level':
			case 'game':
			case 'main':
				this.game.changeState('Level')
				return true
			case 'gameover':
				this.game.changeState('GameOver', {
					levelStats: new FakeLevelStats(this.game),
					skipStartAnimation: false,
				})
				return true
			default:
				this.logs.info(`unknown start state: ${startValue}`)
				return false
		}
	}

	public shutdown(game: Phaser.Game): void {
		this.sendGameReadyOnce()
		this.fadeOutLoadingSpinner()

		setTimeout(() => {
			this.removeLoadingSpinner()
		}, 200)
	}

	private sendGameReadyOnce(): void {
		if (this.hasGameReadySent) {
			return
		}

		this.hasGameReadySent = true
		void this.game.platform.gameReady()
	}
}
