export class ScrollbarHandle extends Phaser.Image {
    private _minY: number = 0
    private _maxY: number = 0
    private delta: number = 0

    constructor(_game: Phaser.Game, key: string, frame: string) {
        super(_game, 0, 0, key, frame)

        this.anchor.set(0.5, 0.5)
    }

    public setLimits(min: number, max: number): void {
        this._minY = min
        this._maxY = max
        this.delta = max - min
    }

    public setPosition(percent: number): void {
        percent = Phaser.Math.clamp(percent, 0, 1)
        this.y = this._minY + this.delta * percent
    }

    public show(): void {
        this.game.time.events.removeBy(this.doHide, this)

        this.game.tweens.removeFrom(this)
        this.game.add.tween(this).to({ alpha: 1 }, 100, Phaser.Easing.Cubic.Out, true)
    }

    public hide(delay: number = 660): void {
        this.game.time.events.removeBy(this.doHide, this)
        this.game.time.events.add(delay, this.doHide, this)
    }

    private doHide() {
        this.game.add.tween(this).to({ alpha: 0 }, 150, Phaser.Easing.Cubic.Out, true)
    }

    public get minY(): number {
        return this._minY
    }

    public get maxY(): number {
        return this._maxY
    }
}
