import { Logger } from 'tslog'
import { merge } from 'es-toolkit/compat'
import { SafeLocalStorage } from '../robowhale/storage/SafeLocalStorage'
import { SentryService } from '../sentry/SentryService'
import { BaseStorage, StorageLoadResult } from '../storage/BaseStorage'
import { DEFAULT_STATE, GameState } from './GameState'

export interface StateServiceOptions {
	logger: Logger<{}>
	debugStorage: SafeLocalStorage
	remoteStorage: BaseStorage
	localStorage: BaseStorage
	sentry: SentryService
}

export type GenericState = Record<string, unknown>

export class StateService {
	private options: StateServiceOptions
	private logger: Logger<{}>

	constructor(options: StateServiceOptions) {
		this.options = options
		this.logger = options.logger
	}

	public async init(): Promise<GameState> {
		const pendingProfileClear = this.options.debugStorage.get('pendingProfileClear').unwrapOr(false)
		if (pendingProfileClear) {
			const clearFlagResult = this.options.debugStorage.remove('pendingProfileClear')
			if (clearFlagResult.isErr()) {
				this.logger.warn(`failed to clear pendingProfileClear flag (${clearFlagResult.error.message})`)
			}

			this.logger.info('pendingProfileClear detected, clearing local+remote storages')

			const localClearResult = await this.options.localStorage.clearState()
			if (localClearResult.isErr()) {
				this.logger.warn(`local clear failed (${localClearResult.error.message})`)
			}

			const remoteClearResult = await this.options.remoteStorage.clearState()
			if (remoteClearResult.isErr()) {
				this.logger.warn(`remote clear failed (${remoteClearResult.error.message})`)
				return DEFAULT_STATE
			}

			if (localClearResult.isErr()) {
				return DEFAULT_STATE
			}
		}

		const localStateResult = await this.options.localStorage.loadState()

		const remoteStateResult = await this.options.remoteStorage.loadState()

		const loadedState = this.pickLoadedState(localStateResult, remoteStateResult)

		const finalState = merge({}, DEFAULT_STATE, loadedState) as GameState

		return finalState
	}

	private pickLoadedState(localState: StorageLoadResult, remoteState: StorageLoadResult): GenericState | null {
		if (localState.isOk() && remoteState.isOk()) {
			const result = this.doPickLoadedState(localState.value, remoteState.value)
			this.logger.info(`picked ${result.type} state`)
			return result.state
		}

		if (localState.isOk() && remoteState.isErr()) {
			this.logger.info(`picked local state, remote state is not available (${remoteState.error.message})`)
			return localState.unwrapOr(null)
		}

		if (localState.isErr() && remoteState.isOk()) {
			this.logger.info(`picked remote state, local state is not available (${localState.error.message})`)
			return remoteState.unwrapOr(null)
		}

		this.logger.warn(`both local and remote states are not available`)

		return null
	}

	// TODO save: use StatesComparator
	private doPickLoadedState<T extends Partial<GameState>>(
		localState: T,
		remoteState: T
	): { type: 'local' | 'remote'; state: T } {
		const localSavedAt = localState.savedAt || 0
		const remoteSavedAt = remoteState.savedAt || 0

		if (localSavedAt > remoteSavedAt) {
			return { type: 'local', state: localState }
		}

		return { type: 'remote', state: remoteState }
	}
}
