import type * as Sentry from '@sentry/browser'
import { Logger } from 'tslog'
import { Main } from './Main'
import { MultiSessionError } from './errors/MultiSessionError'
import { MultiTabError } from './errors/MultiTabError'
import { ErrorScreen } from './states/global/errorScreen/ErrorScreen'
import { BaseError } from './errors/BaseError'

export interface ErrorsHandlerServiceOptions {
	logger: Logger<{}>
	game: Main
	texts: texts.En
}

export class ErrorsHandlerService {
	private logger: Logger<{}>
	private game: Main
	private texts: texts.En
	private _isGameBroken = false

	constructor(options: ErrorsHandlerServiceOptions) {
		this.logger = options.logger
		this.game = options.game
		this.texts = options.texts
	}

	public handle(error: Sentry.Event, hint: Sentry.EventHint): void {
		if (this._isGameBroken) {
			return
		}

		if (!this.shouldStopGame(error, hint)) {
			return
		}

		this._isGameBroken = true

		// TODO stop the game (audio, saves, etc.)

		const exception = hint.originalException
		if (!exception) {
			this.showGenericErrorScreen()
			return
		}

		if (exception instanceof MultiTabError || exception instanceof MultiSessionError) {
			this.showMultiSessionErrorScreen()
			return
		}

		this.showGenericErrorScreen()
	}

	private shouldStopGame(error: Sentry.Event, hint: Sentry.EventHint): boolean {
		const exc = hint.originalException
		
		if (exc instanceof BaseError && exc.isFatal === false) {
			return false
		}

		return false
	}

	private showGenericErrorScreen(): void {
		ErrorScreen.getInstance().show({
			title: this.texts.error_generic_title,
			message: this.texts.error_generic_text,
			buttonText: this.texts.error_generic_button,
		})
	}

	private showMultiSessionErrorScreen(): void {
		ErrorScreen.getInstance().show({
			title: this.texts.multiSessionTitle,
			message: this.texts.multiSessionMessage,
			buttonText: this.texts.multiSessionBtnAction,
		})
	}

	public setTexts(texts: texts.En): void {
		this.texts = texts
	}
}
