import { GameFonts } from './../../../GameFonts'
export class BoosterCountLabel extends Phaser.Group {
	private back: Phaser.Image
	private text: Phaser.BitmapText

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'booster_num_label')

		this.addBack()
		this.addText()
	}

	private addBack(): void {
		this.back = this.game.add.image(0, 0, 'boosters_shop', 'Booster_Count_Label_Back0000', this)
		this.back.anchor.set(0.5, 0.5)
	}

	private addText(): void {
		this.text = this.game.add.bitmapText(0, 0, GameFonts.BOOSTERS_SHOP_BARIOL_BOLD, 'x0', 40, this)
		this.text.anchor.set(0.5, 0.5)
	}

	public updateContent(value: number, tween: boolean = true): void {
		this.text.setText('x' + value.toString())

		if (tween) {
			this.text.y = 0
			this.game.tweens.removeFrom(this.text)
			this.game.add.tween(this.text).to({ y: '-6' }, 200, Phaser.Easing.Sinusoidal.InOut, true, 0, 0, true)

			this.back.scale.x = 1
			this.game.tweens.removeFrom(this.back.scale)
			this.game.add.tween(this.back.scale).to({ x: 1.4 }, 200, Phaser.Easing.Sinusoidal.InOut, true, 0, 0, true)
		}
	}

	public setBackgroundColor(color: number): void {
		this.back.tint = color
	}

	public destroy(): void {
		super.destroy(true, false)
	}
}
