export class Polyfills {
    public static extend() {
        let extendMethods: string[] = Object.keys(Polyfills)
        extendMethods.forEach((method: string) => {
            if (method !== 'extend') {
                Polyfills[method]()
            }
        })
    }

    public static numberIsFinite(): void {
        Number.isFinite =
            Number.isFinite ||
            function (value) {
                return typeof value === 'number' && isFinite(value)
            }
    }

    public static numberIsInteger(): void {
        Number.isInteger =
            Number.isInteger ||
            function (value) {
                return typeof value === 'number' && Number.isFinite(value) && !(value % 1)
            }
    }

    public static nodeRemove(): void {
        let arr = [Element, CharacterData, DocumentType]
        let args = []

        arr.forEach(function (item) {
            if (item) {
                args.push(item.prototype)
            }
        })

        // from:https://github.com/jserz/js_piece/blob/master/DOM/ChildNode/remove()/remove().md
        ;(function (arr) {
            arr.forEach(function (item) {
                if (item.hasOwnProperty('remove')) {
                    return
                }
                Object.defineProperty(item, 'remove', {
                    configurable: true,
                    enumerable: true,
                    writable: true,
                    value: function remove() {
                        this.parentNode.removeChild(this)
                    },
                })
            })
        })(args)
    }
}
