import { VkPlatform } from '../../platform/vk/VkPlatform'
import { Result } from '../../robowhale/Result'
import { AdBasicResult, AdErrorCode } from '../AdsService'
import { IAdsProvider } from './IAdsProvider'

/**
 * @link https://dev.vk.com/ru/games/bridge
 */
export class VkAdsProvider implements IAdsProvider {
	readonly name = 'vk'

        private platform: VkPlatform

        constructor(platform: VkPlatform) {
                this.platform = platform
        }

        public async loadRewarded(): Promise<AdBasicResult> {
                if (!this.platform.ready) {
                        return Result.Error({
                                code: AdErrorCode.GENERIC,
                                message: 'VK platform is not ready',
                        })
                }

                const availability = await this.platform.checkNativeAds('reward')

                if (availability.isOk()) {
                        return Result.Ok()
                }

                return Result.Error({
                        code: this.getErrorCode(availability.error),
                        message: availability.error,
                })
        }

        public async showRewarded(): Promise<AdBasicResult> {
                if (!this.platform.ready) {
                        return Result.Error({
                                code: AdErrorCode.GENERIC,
                                message: 'VK platform is not ready',
                        })
                }

                const shown = await this.platform.showRewardedAd()
                if (shown.success === true) {
                        return Result.Ok()
                }

                return Result.Error({
                        code: this.getErrorCode(shown.error),
                        message: shown.error,
                })
        }

        public async showInterstitial(): Promise<AdBasicResult> {
                if (!this.platform.ready) {
                        return Result.Error({
                                code: AdErrorCode.GENERIC,
                                message: 'VK platform is not ready',
                        })
                }

                const shown = await this.platform.showInterstitialAd()
                if (shown.success === true) {
                        return Result.Ok()
                }

                return Result.Error({
                        code: this.getErrorCode(shown.error),
                        message: shown.error,
                })
        }

        private getErrorCode(error?: string): AdErrorCode {
                const errorMessage = (error ?? '').toLowerCase()

                if (errorMessage.includes('no inventory') || errorMessage.includes('not available')) {
                        return AdErrorCode.NO_FILL
                }

                if (errorMessage.includes('limit') || errorMessage.includes('often')) {
                        return AdErrorCode.CALL_LIMIT
                }

                if (errorMessage.includes('block')) {
                        return AdErrorCode.ADBLOCKED
                }

                if (errorMessage.includes('skip') || errorMessage.includes('close')) {
                        return AdErrorCode.SKIP
                }

                return AdErrorCode.GENERIC
        }
}
