import { Config } from '../../../Config'
import { FontWeight, GameFonts } from '../../../GameFonts'
import { toReadableDateString } from '../../../robowhale/utils/date/readable-date-string'
import { SettingsPopup } from './SettingsPopup'

export class SettingsScreen extends Phaser.Group {
	private backdrop: Phaser.Image
	public window: SettingsPopup
	private buildInfo: Phaser.BitmapText

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'settings_screen')

		this.addBackdrop()
		this.addWindow()
		this.addBuildInfo()
	}

	private addBackdrop(): void {
		this.backdrop = this.game.add.image(0, 0, 'main_menu', 'white_rect0000', this)
		this.backdrop.tint = 0x1a237e
		this.backdrop.alpha = 0.66
		this.backdrop.inputEnabled = true
		this.backdrop.name = 'settings_background'
	}

	private addWindow(): void {
		this.window = new SettingsPopup(this.game, this)
		this.window.closeButton.callback.add(this.hide, this)
	}

	private addBuildInfo() {
		const config = window.game.config
		const buildVersion = config.build_version.toString()

		let commitHash = config.git_commit_hash || ''
		if (commitHash === '{{ GIT_COMMIT_HASH }}' || !commitHash) {
			commitHash = 'dev'
		} else {
			commitHash = commitHash.substring(0, 7).toLowerCase()
		}

		const buildDate = toReadableDateString(config.build_time)
		const content = `Build #${buildVersion} (${commitHash})\n${buildDate}`

		let style: Phaser.PhaserTextStyle = {
			font: GameFonts.NUNITO_CSS,
			fontWeight: FontWeight.NORMAL,
			fontSize: 30,
			fill: '#ffffff',
			align: 'center',
		}

		this.buildInfo = this.game.add.bitmapText(0, 0, GameFonts.BARIOL_REGULAR_BMP, content, 30, this)
		this.buildInfo.align = 'center'
		this.buildInfo.anchor.set(0.5, 1)
		this.buildInfo.alpha = 0.7
	}

	public show(): void {
		this.parent.bringToTop(this)

		this.backdrop.events.onInputDown.add(this.onBackClick, this)

		this.visible = true
		this.exists = true

		this.window.closeButton.enabled = true

		this.alpha = 1

		this.showBackdrop()
		this.window.show(100)
	}

	private onBackClick(back: Phaser.Image, pointer: Phaser.Pointer) {
		if (pointer.interactiveCandidates.length > 1) {
			return
		}

		this.hide()
	}

	private showBackdrop(): void {
		this.backdrop.alpha = 0
		this.game.add.tween(this.backdrop).to({ alpha: 0.66 }, 150, Phaser.Easing.Cubic.Out, true)
	}

	public hide(): void {
		this.backdrop.events.onInputDown.remove(this.onBackClick, this)

		this.window.closeButton.enabled = false

		this.game.add
			.tween(this)
			.to({ alpha: 0 }, 200, Phaser.Easing.Cubic.Out, true)
			.onComplete.addOnce(() => {
				this.exists = false
				this.visible = false
			})
	}

	public resize(): void {
		this.resizeBackdrop()

		this.window.closeButton.visible = false
		this.window.centerX = Config.HALF_GAME_WIDTH
		this.window.centerY = Config.HALF_GAME_HEIGHT
		this.window.closeButton.visible = true

		this.buildInfo.x = Config.HALF_GAME_WIDTH
		this.buildInfo.bottom = Config.GAME_HEIGHT - 20
	}

	private resizeBackdrop() {
		this.backdrop.width = Config.GAME_WIDTH * 1.2
		this.backdrop.height = Config.GAME_HEIGHT * 1.2
		this.backdrop.centerX = Config.HALF_GAME_WIDTH
		this.backdrop.centerY = Config.HALF_GAME_HEIGHT
	}

	public destroy(): void {
		super.destroy(true, false)
	}
}
