import { Logger } from 'tslog'
import { until } from 'until-async'
import { BrowserSyncService } from '../../browserSync/BrowserSyncService'
import { Main } from '../../Main'
import { getErrorLog } from '../../robowhale/utils/error/utils'
import { BaseStorage } from '../../storage/BaseStorage'
import { UrlParams } from '../../url-params/UrlParams'
import { AlertScreen } from './alertScreen/AlertScreen'
import { WaitingScreen, WaitingScreenShowOptions } from './WaitingScreen'

type UrlParamsViewer = import('../../url-params/UrlParamsViewer').UrlParamsViewer

export class GlobalScene extends Phaser.Group {
	public waitingScreen: WaitingScreen
	public alertScreen: AlertScreen
	private readonly screenshotLogger: Logger<{}>
	private urlParamsViewer: UrlParamsViewer | null = null
	private urlParamsViewerLoading: Promise<UrlParamsViewer> | null = null

	constructor(game: Phaser.Game, parent: Phaser.Group) {
		super(game, parent, 'global_scene')

		this.screenshotLogger = this.game.logs.getOrCreate('screenshots')

		this.patchKeyboardInput(game)
		this.addWaitingScreen(game)
		this.addAlertScreen(game)

		if (Main.development) {
			this.addScreenshotCallback()
			this.maybeOpenUrlParamsViewer()
		}
	}

	private addWaitingScreen(game: Phaser.Game) {
		this.waitingScreen = new WaitingScreen()
	}

	private addAlertScreen(game: Phaser.Game) {
		this.alertScreen = new AlertScreen(game, this)
		this.alertScreen.resize()
		this.alertScreen.kill()
		this.add(this.alertScreen)
	}

	/**
	 * Отображаем экран ожидания (спиннер + опциональный текст + опциональный прогресс-бар) на время выполнения асинхронной операции.
	 * Экран перекрывает всю площадь игры и блокирует инпут, то есть под ним ничего не прокликивается.
	 */
	public async waitFor<T>(
		fnOrPromise: ((...args: any[]) => PromiseLike<T>) | PromiseLike<T>,
		waitingScreenOptions: WaitingScreenShowOptions
	) {
		this.waitingScreen.show(waitingScreenOptions)
		const promise = typeof fnOrPromise === 'function' ? fnOrPromise() : fnOrPromise
		const result = await promise
		this.waitingScreen.hide()
		return result
	}

	public resize(width: number, height: number): void {
		this.alertScreen?.resize()
	}

	/** Prevent Phaser from processing keyboard events when an HTML input is focused */
	private patchKeyboardInput(game: Phaser.Game): void {
		const keyboard = game.input.keyboard
		const originalProcessKeyDown = keyboard.processKeyDown
		const originalProcessKeyUp = keyboard.processKeyUp

		keyboard.processKeyDown = (event: KeyboardEvent) => {
			if (this.isTypingInInput(event)) {
				return
			}
			originalProcessKeyDown.call(keyboard, event)
		}

		keyboard.processKeyUp = (event: KeyboardEvent) => {
			if (this.isTypingInInput(event)) {
				return
			}
			originalProcessKeyUp.call(keyboard, event)
		}
	}

	private addScreenshotCallback(): void {
		this.game.input.keyboard.addCallbacks(this, this.onKeyboardDown)
	}

	private onKeyboardDown(event: KeyboardEvent): void {
		const typingInInput = this.isTypingInInput(event)

		if (event.key === '/' && !typingInInput) {
			event.preventDefault()
			void this.toggleUrlParamsViewer()
			return
		}

		if (event.keyCode !== Phaser.Keyboard.S || typingInInput) {
			return
		}

		event.preventDefault()

		if (!event.shiftKey) {
			void this.logStorageStates()
			return
		}

		void this.makeScreenshot()
	}

	private async logStorageStates(): Promise<void> {
		if (!Main.development) {
			return
		}

		const saveService = this.game.save
		if (!saveService) {
			return
		}

		await Promise.all([
			this.logStorageState({
				label: 'local',
				storage: saveService.localStorage,
			}),
			this.logStorageState({
				label: 'remote',
				storage: saveService.remoteStorage,
			}),
		])
	}

	private async logStorageState(options: StorageStateLogOptions): Promise<void> {
		const { label, storage } = options
		if (!storage) {
			return
		}

		const logger = storage.getLogger()
		const [loadError, loadResult] = await until(() => storage.loadState())

		if (loadError) {
			logger.error(`${label} storage load rejected (${getErrorLog(loadError)})`)
			return
		}

		if (loadResult.isErr()) {
			const { code, message } = loadResult.error
			logger.warn(`${label} storage load failed (${code}: ${message})`)
			return
		}

		logger.info(`${label} storage state (saved at ${loadResult.value.savedAtStr})`, loadResult.value)
	}

	private async makeScreenshot(): Promise<void> {
		if (BrowserSyncService.isAvailable() === false) {
			return
		}

		try {
			const blob = await this.getCanvasSnapshot()
			const state = this.game.state?.current
			const language = this.game.texts?.language
			const { filename } = await BrowserSyncService.saveScreenshot(blob, state, language)
			const { width, height } = this.game.canvas
			this.screenshotLogger.info(`screenshot saved as ${filename} [${width}x${height}]`)
			this.game.toast?.show('Screenshot saved')
		} catch (error) {
			this.screenshotLogger.error("Can't save screenshot!", error)
		}
	}

	private isTypingInInput(event: KeyboardEvent): boolean {
		for (const el of event.composedPath()) {
			if (!(el instanceof HTMLElement)) {
				continue
			}

			const tagName = el.tagName
			if (tagName === 'INPUT' || tagName === 'TEXTAREA' || tagName === 'SELECT') {
				return true
			}

			if (el.isContentEditable) {
				return true
			}
		}

		return false
	}

	private async toggleUrlParamsViewer(): Promise<void> {
		if (!Main.development) {
			return
		}

		const viewer = await this.getUrlParamsViewer()
		await viewer.toggle()
	}

	private maybeOpenUrlParamsViewer(): void {
		if (!UrlParams.getBool('urlParamsViewer')) {
			return
		}

		requestAnimationFrame(() => {
			void this.getUrlParamsViewer().then((viewer) => viewer.show())
		})
	}

	private async getUrlParamsViewer(): Promise<UrlParamsViewer> {
		if (this.urlParamsViewer) {
			return this.urlParamsViewer
		}

		if (!this.urlParamsViewerLoading) {
			this.urlParamsViewerLoading = import('../../url-params/UrlParamsViewer')
				.then((module) => {
					this.urlParamsViewer = new module.UrlParamsViewer()
					return this.urlParamsViewer
				})
				.finally(() => {
					this.urlParamsViewerLoading = null
				})
		}

		return this.urlParamsViewerLoading
	}

	private getCanvasSnapshot(): Promise<Blob> {
		const canvas = this.game.canvas
		if (!canvas) {
			return Promise.reject(new Error('Game canvas is not available'))
		}

		return new Promise((resolve, reject) => {
			if (canvas.toBlob) {
				canvas.toBlob((blob) => {
					if (!blob) {
						reject(new Error('Failed to create screenshot blob'))
						return
					}
					resolve(blob)
				}, 'image/png')
				return
			}

			try {
				const dataUrl = canvas.toDataURL('image/png')
				fetch(dataUrl)
					.then((response) => response.blob())
					.then(resolve)
					.catch(reject)
			} catch (error) {
				reject(error)
			}
		})
	}

	public destroy(): void {
		super.destroy(true, false)
	}
}

interface StorageStateLogOptions {
	label: string
	storage: BaseStorage | null | undefined
}
