import { FontWeight, GameFonts } from '../../../GameFonts'
import { ComplexButton } from '../../../gui/buttons/ComplexButton'

export class FreeCoinsButton extends ComplexButton {
	private white: Phaser.Image

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'boosters_shop', 'Button_Free_Coins0000')

		this.addCustomText()
		this.addWhite()
	}

	private addCustomText() {
		let template: string = this.game.texts.texts.coins_1000
		let coinsNum: number = 1000
		let content: string = template.replace('#', coinsNum.toString())

		let style: Phaser.PhaserTextStyle = {
			font: GameFonts.DEFAULT,
			fontWeight: FontWeight.BOLD,
			fontSize: 31,
			fill: '#ffffff',
			align: 'center',
		}

		this.addText(content, style)
		this.text.x += 56
		this.text.y -= 5
		this.text.lineSpacing = -10
	}

	private addWhite(): void {
		this.white = this.game.add.image(0, 0, 'boosters_shop', 'Button_Highlight0000', this)
		this.white.centerX = this.back.centerX
		this.white.top = this.back.top
		this.white.visible = false
	}

	public highlight(): void {
		this.animateWhite()

		this.scale.set(1)
		this.game.tweens.removeFrom(this.scale)
		this.game.add.tween(this.scale).to(
			{
				x: 1.15,
				y: 1.15,
			},
			330,
			Phaser.Easing.Sinusoidal.InOut,
			true,
			0,
			0,
			true
		)
	}

	private animateWhite() {
		this.white.visible = true
		this.white.alpha = 0

		this.game.tweens.removeFrom(this.white)
		this.game.add
			.tween(this.white)
			.to({ alpha: 0.66 }, 330, Phaser.Easing.Sinusoidal.InOut, true, 0, 0, true)
			.onComplete.addOnce(() => {
				this.white.visible = false
			})
	}

	public disable(): void {
		this.alpha = 0.33
		this.enabled = false
	}
}
