import { err, Result as NeverthrowResult, ok } from 'neverthrow'
import { match } from 'ts-pattern'
import { until } from 'until-async'
import { Result } from '../../robowhale/Result'
import { getErrorLog } from '../../robowhale/utils/error/utils'
import { Platform } from '../../startup/Platform'
import { BasePlatform, BasePlatformOptions } from '../BasePlatform'

type PlaygamaRewardedState = 'loading' | 'opened' | 'rewarded' | 'closed' | 'failed'
type PlaygamaInterstitialState = 'loading' | 'opened' | 'closed' | 'failed'
type PlaygamaBannerState = 'loading' | 'shown' | 'hidden' | 'failed'
type PlaygamaAdState = PlaygamaRewardedState | PlaygamaInterstitialState | PlaygamaBannerState

type PlaygamaBannerPosition = 'top' | 'bottom'

type PlaygamaAdvertisement = {
	/** Indicates if interstitial ads are supported on this platform. */
	isInterstitialSupported?: boolean
	/** Indicates if rewarded ads are supported on this platform. */
	isRewardedSupported?: boolean
	/** Indicates if banner ads are supported on this platform. */
	isBannerSupported?: boolean
	/** Shows an interstitial ad (optional placement). */
	showInterstitial: (placement?: string) => Promise<void> | void
	/** Shows a rewarded ad (optional placement). */
	showRewarded: (placement?: string) => Promise<void> | void
	/** Shows a banner ad in a position (optional placement). */
	showBanner: (position: PlaygamaBannerPosition, placement?: string) => Promise<void> | void
	/** Hides the banner ad if it is visible. */
	hideBanner: () => Promise<void> | void
	/** Subscribes to advertisement state changes. */
	on?: (event: string, handler: (state: PlaygamaAdState) => void) => void
	/** Unsubscribes from advertisement state changes. */
	off?: (event: string, handler: (state: PlaygamaAdState) => void) => void
}

type PlaygamaBridgeEventName = {
	/** Event emitted when interstitial state changes. */
	INTERSTITIAL_STATE_CHANGED?: string
	/** Event emitted when rewarded state changes. */
	REWARDED_STATE_CHANGED?: string
	/** Event emitted when banner state changes. */
	BANNER_STATE_CHANGED?: string
}

type PlaygamaEnvironment = {
	/** Language code provided by the bridge, when available. */
	language?: string
}

type PlaygamaPlatformApi = {
	/** Returns the current server time in milliseconds. */
	getServerTime?: () => Promise<number> | number
	/** Sends a predefined message to the platform. */
	sendMessage?: (message: string) => Promise<void> | void
}

export type PlaygamaStorageType = 'local_storage' | 'platform_internal'

export type PlaygamaStorage = {
	/** Loads a value (or values) by key(s) from storage. */
	get: (key: string | string[], type?: PlaygamaStorageType) => Promise<unknown> | unknown
	/** Persists a value under a key into storage. */
	set: (key: string, value: unknown, type?: PlaygamaStorageType) => Promise<void> | void
	/** Deletes a key (or keys) from storage. */
	delete: (key: string | string[], type?: PlaygamaStorageType) => Promise<void> | void
	/** Returns whether a storage type is supported on the platform. */
	isSupported?: (type: PlaygamaStorageType) => boolean
	/** Returns whether a storage type is currently available for use. */
	isAvailable?: (type: PlaygamaStorageType) => Promise<boolean> | boolean
	/** Default storage type used when type argument is omitted. */
	defaultType?: PlaygamaStorageType
}

type PlaygamaBridge = {
	/** Playgama advertising API surface. */
	advertisement?: PlaygamaAdvertisement
	/** Playgama platform API surface. */
	platform?: PlaygamaPlatformApi
	/** User data storage API surface. */
	storage?: PlaygamaStorage
	/** Event name bag exposed by the bridge. */
	EVENT_NAME?: PlaygamaBridgeEventName
	/** Optional hook to notify the SDK that the game is ready. */
	gameReady?: () => Promise<void> | void
	/** Language code provided by the bridge, when available. */
	language?: string
	/** Environment metadata from the bridge, if present. */
	environment?: PlaygamaEnvironment
}

type AdStateTrackerOptions = {
	/** Advertising API used to subscribe to events. */
	advertisement: PlaygamaAdvertisement
	/** Event name to subscribe to. */
	eventName?: string
	/** States that finish the ad flow. */
	terminalStates: PlaygamaAdState[]
	/** Maps a terminal state into a Result. */
	resultForState: (state: PlaygamaAdState) => Result
	/** Result to use when no event channel is available. */
	defaultResult: Result
}

type AdStateTracker = {
	/** Resolves when a terminal ad state is reached. */
	promise: Promise<Result>
	/** Unsubscribes the listener if needed. */
	cleanup: () => void
}

type ShowAdWithStateOptions = {
	/** Advertising API instance. */
	advertisement: PlaygamaAdvertisement
	/** Event name to listen for ad states. */
	eventName?: string
	/** Callback that triggers the ad. */
	start: () => Promise<void> | void
	/** States that terminate the ad flow. */
	terminalStates: PlaygamaAdState[]
	/** Maps a terminal state into a Result. */
	resultForState: (state: PlaygamaAdState) => Result
	/** Result to use when event tracking is unavailable. */
	defaultResult: Result
}

export class PlaygamaPlatform extends BasePlatform {
	public readonly type: Platform = 'playgama'

	private _bridge: PlaygamaBridge | undefined

	constructor(options: BasePlatformOptions) {
		super(options)
	}

	public async init(): Promise<void> {
		const preloader = window.preloader.platform

		if (!preloader || preloader.type !== this.type) {
			throw new Error('Platform preloader is not initialized')
		}

		const bridge = (await preloader.loadAndInit()) as PlaygamaBridge | undefined
		if (!bridge) {
			throw new Error('Playgama bridge is not available')
		}

		this._bridge = bridge
		this._ready = true

		this._logger.info('ready')
	}

	public async getLanguage(): Promise<string | undefined> {
		const bridge = this._bridge
		if (!bridge) {
			return undefined
		}

		if (bridge.language) {
			return bridge.language
		}

		return bridge.environment?.language
	}

	public async getServerTime(): Promise<number> {
		const bridge = this._bridge
		if (!bridge?.platform?.getServerTime) {
			return Date.now()
		}

		const [error, serverTime] = await until(() => Promise.resolve(bridge.platform.getServerTime!()))
		if (error) {
			this._logger.warn(`server time request failed (${getErrorLog(error)})`)
			return Date.now()
		}

		return serverTime
	}

	public async gameReady(): Promise<void> {
		const bridge = this._bridge
		if (!bridge) {
			this._logger.warn(`'game_ready' skipped (bridge is unavailable)`)
			return
		}

		if (!bridge.platform || !bridge.platform.sendMessage || typeof bridge.platform.sendMessage !== 'function') {
			this._logger.warn(`'game_ready' skipped ('sendMessage' platform API is unavailable)`)
			return
		}

		const [error] = await until(() => Promise.resolve(bridge.platform.sendMessage('game_ready')))
		if (error) {
			this._logger.warn(`'game_ready' message send failed (${getErrorLog(error)})`)
		}
	}

	public async getStorageForType(type: PlaygamaStorageType): Promise<PlaygamaStorage | undefined> {
		const storage = this._bridge?.storage
		if (!storage) {
			return undefined
		}

		if (storage.isSupported && !storage.isSupported(type)) {
			return undefined
		}

		if (!storage.isAvailable) {
			return storage
		}

		const [error, isAvailable] = await until(() => Promise.resolve(storage.isAvailable!(type)))
		if (error) {
			this._logger.warn(`storage availability check failed (${getErrorLog(error)})`)
			return undefined
		}

		if (!isAvailable) {
			return undefined
		}

		return storage
	}

	public async loadRewardedAd(): Promise<Result> {
		const advertisement = this.getAdvertisement()
		if (!advertisement) {
			return Result.Error('Playgama bridge is not initialized')
		}

		if (advertisement.isRewardedSupported === false) {
			return Result.Error('rewarded ads are not supported')
		}

		return Result.Ok()
	}

	public async showRewardedAd(): Promise<Result> {
		const advertisement = this.getAdvertisement()
		if (!advertisement) {
			return Result.Error('Playgama bridge is not initialized')
		}

		if (advertisement.isRewardedSupported === false) {
			return Result.Error('rewarded ads are not supported')
		}

		const eventName = this.getEventName('REWARDED_STATE_CHANGED')

		return this.showAdWithState({
			advertisement,
			eventName,
			start: () => advertisement.showRewarded(),
			terminalStates: ['rewarded', 'closed', 'failed'],
			resultForState: (state) => this.getRewardedResultFromState(state),
			defaultResult: Result.Error('rewarded ad result is unavailable'),
		})
	}

	public async showInterstitialAd(): Promise<Result> {
		const advertisement = this.getAdvertisement()
		if (!advertisement) {
			return Result.Error('Playgama bridge is not initialized')
		}

		if (advertisement.isInterstitialSupported === false) {
			return Result.Error('interstitial ads are not supported')
		}

		const eventName = this.getEventName('INTERSTITIAL_STATE_CHANGED')

		return this.showAdWithState({
			advertisement,
			eventName,
			start: () => advertisement.showInterstitial(),
			terminalStates: ['closed', 'failed'],
			resultForState: (state) => this.getInterstitialResultFromState(state),
			defaultResult: Result.Ok(),
		})
	}

	public isBannerAdSupported(): boolean {
		const advertisement = this.getAdvertisement()
		if (!advertisement) {
			return false
		}

		return advertisement.isBannerSupported !== false
	}

	public async showBannerAd(): Promise<NeverthrowResult<void, string>> {
		const advertisement = this.getAdvertisement()
		if (!advertisement) {
			return err('Playgama bridge is not initialized')
		}

		if (advertisement.isBannerSupported === false) {
			return err('banner ad is not supported')
		}

		const [error] = await until(() => Promise.resolve(advertisement.showBanner('bottom')))
		if (error) {
			const errorLog = getErrorLog(error)
			this._logger.warn(`banner ad show failed (${errorLog})`)
			return err(errorLog)
		}

		return ok()
	}

	public async hideBannerAd(): Promise<NeverthrowResult<void, string>> {
		const advertisement = this.getAdvertisement()
		if (!advertisement) {
			return err('Playgama bridge is not initialized')
		}

		const [error] = await until(() => Promise.resolve(advertisement.hideBanner()))
		if (error) {
			const errorLog = getErrorLog(error)
			this._logger.warn(`banner ad hide failed (${errorLog})`)
			return err(errorLog)
		}

		return ok()
	}

	private getRewardedResultFromState(state: PlaygamaAdState): Result {
		return match(state)
			.returnType<Result>()
			.with('rewarded', () => Result.Ok())
			.with('closed', () => Result.Error('ad-closed'))
			.with('failed', () => Result.Error('ad-failed'))
			.otherwise(() => Result.Error(`ad-${state}`))
	}

	private getInterstitialResultFromState(state: PlaygamaAdState): Result {
		return match(state)
			.returnType<Result>()
			.with('closed', () => Result.Ok())
			.with('failed', () => Result.Error('ad-failed'))
			.otherwise(() => Result.Error(`ad-${state}`))
	}

	private async showAdWithState(options: ShowAdWithStateOptions): Promise<Result> {
		const tracker = this.createAdStateTracker({
			advertisement: options.advertisement,
			eventName: options.eventName,
			terminalStates: options.terminalStates,
			resultForState: options.resultForState,
			defaultResult: options.defaultResult,
		})

		const [error] = await until(() => Promise.resolve(options.start()))
		if (error) {
			tracker.cleanup()
			return Result.Error(getErrorLog(error))
		}

		return tracker.promise
	}

	private createAdStateTracker(options: AdStateTrackerOptions): AdStateTracker {
		if (!options.eventName || !options.advertisement.on) {
			return { promise: Promise.resolve(options.defaultResult), cleanup: () => undefined }
		}

		let isResolved = false
		let handler: ((state: PlaygamaAdState) => void) | undefined

		const promise = new Promise<Result>((resolve) => {
			handler = (state: PlaygamaAdState) => {
				if (!options.terminalStates.includes(state)) {
					return
				}

				isResolved = true
				options.advertisement.off?.(options.eventName!, handler!)
				resolve(options.resultForState(state))
			}

			options.advertisement.on?.(options.eventName, handler)
		})

		const cleanup = () => {
			if (isResolved || !handler) {
				return
			}

			options.advertisement.off?.(options.eventName!, handler)
		}

		return { promise, cleanup }
	}

	private getAdvertisement(): PlaygamaAdvertisement | undefined {
		return this._bridge?.advertisement
	}

	private getEventName(eventName: keyof PlaygamaBridgeEventName): string | undefined {
		return this._bridge?.EVENT_NAME?.[eventName]
	}

	public isFullscreenSupported(): boolean {
		return false
	}

	public isFullscreen(): boolean {
		return false
	}

	public async requestFullscreen(): Promise<void> {
		return Promise.resolve()
	}

	public async exitFullscreen(): Promise<void> {
		return Promise.resolve()
	}
}
