export class SimpleButton extends Phaser.Image {
    public get enabled(): boolean {
        return this._enabled
    }

    public set enabled(value: boolean) {
        this._enabled = value
        this.input.enabled = this._enabled
    }

    private _callback: Phaser.Signal
    private _callbackOn: 'pointerdown' | 'pointerup' = 'pointerdown'
    private callbackDelay: number = 0
    private _enabled: boolean = true
    public disableInput: boolean = false
    public userData: any = null
    public soundKey: string = 'tap'
    public areTweensEnabled: boolean = true

    constructor(game: Phaser.Game, x: number, y: number, key: string, frame: string, parent?: Phaser.Group) {
        super(game, x, y, key, frame)

        parent = parent ?? this.game.world
        parent.add(this)

        this._callback = new Phaser.Signal()
        this.anchor.set(0.5, 0.5)
        this.inputEnabled = true
        this.events.onInputDown.add(this.onInputDown, this)
        this.events.onInputUp.add(this.onInputUp, this)
        this.userData = {}
        this.name = frame

        if (this.game.device.desktop) {
            this.input.useHandCursor = true
        }
    }

    private onInputDown() {
        if (this.disableInput) {
            return
        }

        if (this._callbackOn === 'pointerdown') {
            this.executeCallback()
        }

        if (this.game.cache.checkSoundKey(this.soundKey)) {
            this.game.sound.play(this.soundKey)
        }

        if (this.areTweensEnabled) {
            this.game.add.tween(this.scale).to({ x: 0.9, y: 0.9 }, 50, Phaser.Easing.Cubic.Out, true)
        }
    }

    private onInputUp(): void {
        if (this.disableInput) {
            return
        }

        if (this._callbackOn === 'pointerup') {
            this.executeCallback()
        }

        if (this.areTweensEnabled) {
            this.game.tweens.removeFrom(this.scale)
            this.game.add.tween(this.scale).to({ x: 1, y: 1 }, 150, Phaser.Easing.Cubic.Out, true)
        }
    }

    private executeCallback(): void {
        if (this.callbackDelay > 0) {
            this.game.time.events.add(this.callbackDelay, this._callback.dispatch, this._callback, this)
        } else {
            this._callback.dispatch(this)
        }
    }

    public setCallbackOn(callbackOn: 'pointerdown' | 'pointerup'): void {
        this._callbackOn = callbackOn
    }

    public setCallbackDelay(delay: number): void {
        this.callbackDelay = delay
    }

    public destroy(): void {
        super.destroy()

        this._callback.dispose()
        this._callback = null
    }

    public get callback(): Phaser.Signal {
        return this._callback
    }
}
