import { LevelStats } from './LevelStats'

export class FakeLevelStats extends LevelStats {
    constructor(_game: Phaser.Game) {
        super(_game)

        this.coins = this.game.rnd.integerInRange(0, 1999)
        this.moves = this.game.rnd.integerInRange(1, 1000)
        this._timeInSeconds = this.game.rnd.integerInRange(30, 4000)
        this._timeInMinutes = this.game.rnd.integerInRange(0, 100)
        this.bestItemTypeAtEnd = this.game.rnd.integerInRange(2, 200)
        // this._isHighscore = this.game.rnd.sign() === 1;
        this._isHighscore = true
    }
}
