import { BoosterType } from './BoosterType'

export class BoosterTypeUtil {
	public static getAllTypes(): BoosterType[] {
		return Object.keys(BoosterType).map((key: string) => {
			return BoosterType[key]
		})
	}

	public static fromString(str: string): BoosterType {
		let entry = Object.entries(BoosterType).find(([, value]) => {
			return value === str
		})
		if (entry) {
			return BoosterType[entry[0]]
		}

		return null
	}
}
