import { until } from '@open-draft/until'
import { err, ok, Result } from 'neverthrow'
import { Logger } from 'tslog'
import { createError } from '../errors/create-error'
import { Main } from '../Main'
import { getErrorLog } from '../robowhale/utils/error/utils'
import { SaveService } from '../save/SaveService'
import { TimeService } from '../time/TimeService'
import { GamePushService, getMonthLeaderboardVariant, getWeekLeaderboardVariant } from './../gamePush/GamePushService'
import { LeaderboardScreen } from './LeaderboardScreen'
import { LeaderboardTab } from './LeaderboardTab'
import { FakeLeaderboardProvider } from './providers/FakeLeaderboardProvider'
import { GamepushLeaderboardProvider } from './providers/GamepushLeaderboardProvider'
export interface LeaderboardsServiceOptions {
	game: Main
	save: SaveService
	logger: Logger<{}>

	time: TimeService

	gamePush: GamePushService

	/**
	 * GamePush Leaderboard ID
	 */
	leaderboardId: number

	/**
	 * Score threshold to submit to leaderboards.
	 * If score is below this threshold, it will not be submitted.
	 * Only scores **equal or greater** than this threshold will be submitted.
	 */
	submitScoreThreshold: number
}

export class LeaderboardsService {
	private logger: Logger<{}>
	private game: Main
	private gamePush: GamePushService
	private time: TimeService
	private save: SaveService
	private screen: LeaderboardScreen

	constructor(private readonly options: LeaderboardsServiceOptions) {
		this.logger = options.logger
		this.game = options.game
		this.gamePush = options.gamePush
		this.time = options.time
		this.save = options.save
		this.screen = this.createLeaderboardScreen()
	}

	private createLeaderboardScreen(): LeaderboardScreen {
		const fakeProvider = new FakeLeaderboardProvider({
			logger: this.logger,
			fetchOptions: {
				'all-time': {
					playerRank: 50,
					topEntriesCount: 10,
					aroundPlayerCount: 5,
				},
				'monthly': {
					playerRank: 30,
					topPlayersScores: { min: 2000, max: 20000 },
					aroundPlayerPosition: 'end',
				},
				'weekly': {
					playerRank: 11,
					topEntriesCount: 10,
					aroundPlayerPosition: 'middle',
				},
			},
		})

		const gamepushProvider = new GamepushLeaderboardProvider({
			logger: this.logger,
			gamepush: this.gamePush,
			leaderboardId: this.options.leaderboardId,
		})

		return new LeaderboardScreen({
			logger: this.logger,
			// provider: fakeProvider,
			provider: gamepushProvider,
		})
	}

	/**
	 * Publishes the score to all leaderboards (all-time, monthly, and weekly).
	 *
	 * @remarks
	 * - Only publishes if the score is equal to or greater than the `submitScoreThreshold`.
	 * - Only publishes if the score is higher than the previously submitted best score.
	 *
	 * @param score - The score to publish.
	 * @returns A result indicating success or an error message.
	 */
	public async publishScore(score: number): Promise<Result<void, string>> {
		if (!this.isPlayerLoggedIn()) {
			return err('player not logged in')
		}

		if (score < this.options.submitScoreThreshold) {
			return err(`score '${score}' below submit threshold '${this.options.submitScoreThreshold}'`)
		}

		const prevBestScore = this.game.save.getValue('best_submitted_item')
		if (prevBestScore >= score) {
			return err(`higher score '${prevBestScore}' was submitted earlier`)
		}

		const wasPublished = await this.game.globalScene.waitFor(() => this.publishToAllLeaderboards(score), {
			reason: 'leaderboards-update',
			showDelayMs: 500,
		})

		return wasPublished ? ok() : err('failed to publish score')
	}

	private async publishToAllLeaderboards(score: number) {
		const dateMs = this.time.server

		const results = await Promise.all([
			this.publishToLeaderboard('main', score, dateMs), // all-time
			this.publishToLeaderboard(getMonthLeaderboardVariant(), score, dateMs),
			this.publishToLeaderboard(getWeekLeaderboardVariant(), score, dateMs),
		])

		const wasPublished = results.every((result) => result.isOk())
		if (wasPublished) {
			this.game.save.setValue('best_submitted_item', score, { origin: 'level/updateLeaderboards-update' })
		}

		return wasPublished
	}

	private async publishToLeaderboard(leaderboardVariant: string, score: number, dateMs: number) {
		const logger = this.game.logs.getOrCreate('leaderboards')

		const { error, data } = await until(() =>
			this.game.gamePush.sdk.leaderboard.publishRecord({
				id: this.options.leaderboardId,
				variant: leaderboardVariant,
				record: { score, date: dateMs },
			})
		)

		// await timeout(5000)

		if (error) {
			const errorLog = getErrorLog(error)
			logger.error(`failed on publishing score '${score}' to '${leaderboardVariant}' leaderboard (${errorLog})`)
			this.game.sentry.sendError(
				createError('LeaderboardPublishError', errorLog, {
					sentryContext: {
						extra: {
							leaderboardVariant,
							score,
							date: dateMs,
						},
					},
				})
			)

			return err(errorLog)
		}

		logger.debug(`score '${score}' published to '${leaderboardVariant}' leaderboard`)

		return ok(data)
	}

	public async getPlayerData(tab: LeaderboardTab = 'weekly'): Promise<Result<gamePush.LeaderboardPlayer, string>> {
		if (!this.isPlayerLoggedIn()) {
			return err('player not logged in')
		}

		const { error, data } = await until(() =>
			this.gamePush.sdk.leaderboard.fetchPlayerRatingScoped({
				id: this.options.leaderboardId,
				variant: this.tabToVariant(tab),
				includeFields: ['score', 'date'],
				showNearest: 0,
			})
		)

		if (error) {
			return err(getErrorLog(error))
		}

		return ok(data.player)
	}

	private tabToVariant(tab: LeaderboardTab): string {
		switch (tab) {
			case 'all-time':
				return 'main'
			case 'monthly':
				return getMonthLeaderboardVariant()
			case 'weekly':
				return getWeekLeaderboardVariant()
		}
	}

	/**
	 * Shows the leaderboard screen.
	 *
	 * @remarks
	 * Side effect: attempts to publish the current score before showing the screen.
	 *
	 * @param tab - The initial tab to display.
	 */
	public async show(tab: LeaderboardTab = 'weekly') {
		const isLoggedIn = await this.ensurePlayerLoggedIn()
		if (!isLoggedIn) {
			return
		}

		const score = this.save.getValue('best_item')
		await this.publishScore(score)

		this.screen.show({ initialTab: tab })
	}

	private async ensurePlayerLoggedIn(): Promise<boolean> {
		if (this.isPlayerLoggedIn()) {
			return true
		}

		const { error, data } = await until(() => this.gamePush.player.login())

		if (error) {
			this.logger.warn(`failed to login (${getErrorLog(error)})`)
		}

		if (!data) {
			this.logger.warn(`failed to login (player cancelled login)`)
		}

		return this.isPlayerLoggedIn()
	}

	private isPlayerLoggedIn(): boolean {
		return this.gamePush.player.isLoggedIn
	}

	public setTexts(texts: texts.En) {
		this.screen.setTexts(texts)
	}
}
