import { match } from 'ts-pattern'
import { AdBasicResult, AdErrorCode } from '../AdsService'
import { Result } from './../../robowhale/Result'
import { FakeInterstitialScreen } from './FakeInterstitialScreen'
import { FakeRewardedScreen } from './FakeRewardedScreen'
import { IAdsProvider } from './IAdsProvider'

export class FakeAdsProvider implements IAdsProvider {
	readonly name = 'fake'

	private _interstitialAd: FakeInterstitialScreen
	private _rewardedAd: FakeRewardedScreen

	constructor(private game: Phaser.Game) {
		this._interstitialAd = new FakeInterstitialScreen(this.game)
		this._rewardedAd = new FakeRewardedScreen(this.game)
	}

	public showInterstitial(): Promise<AdBasicResult> {
		return new Promise((resolve) => {
			this._interstitialAd.once('hide-complete', () => resolve(Result.Ok()))
			this._interstitialAd.show({ durationMs: 5_000 })
		})
	}

	public showRewarded(): Promise<AdBasicResult> {
		return new Promise((resolve) => {
			this._rewardedAd.once('complete', ({ state }) => {
				const result = match(state)
					.returnType<AdBasicResult>()
					.with('watched', () => Result.Ok())
					.with('closed', () =>
						Result.Error({
							code: AdErrorCode.SKIP,
							message: 'ad was closed by user',
						})
					)
					.exhaustive()

				resolve(result)
			})

			this._rewardedAd.show({ durationMs: 10_000 })
		})
	}

	public loadRewarded(): Promise<AdBasicResult> {
		return Promise.resolve(Result.Ok())
	}
}
