import { AdBasicResult } from '../AdsService'
import { Result } from './../../robowhale/Result'
import { IAdsProvider } from './IAdsProvider'

export class NoopAdsProvider implements IAdsProvider {
	readonly name = 'noop'

	public showInterstitial(): Promise<AdBasicResult> {
		return Promise.resolve(Result.Ok())
	}

	public showRewarded(): Promise<AdBasicResult> {
		return Promise.resolve(Result.Ok())
	}

	public loadRewarded(): Promise<AdBasicResult> {
		return Promise.resolve(Result.Ok())
	}
}
