import { FreeCoinsButton } from './FreeCoinsButton';
import { Config } from '../../../Config'
import { SimpleButton } from '../../../gui/buttons/SimpleButton'

export class BoostersShopBottomPanel extends Phaser.Group {
	private back: Phaser.Image
	public freeCoinsButton: FreeCoinsButton
	public playButton: SimpleButton

	constructor(_game: Phaser.Game, parent: Phaser.Group) {
		super(_game, parent, 'bottom_panel')

		this.addBack()
		this.addFreeCoinsButton()
		this.addPlayButton()
	}

	private addBack() {
		this.back = this.game.add.image(0, 0, 'boosters_shop', 'Bottom_Panel_Back0000', this)
		this.back.inputEnabled = true
	}

	private addFreeCoinsButton() {
		this.freeCoinsButton = new FreeCoinsButton(this.game, this)
		this.freeCoinsButton.name = '1000_coins_button'
	}

	private addPlayButton() {
		this.playButton = new SimpleButton(this.game, 0, 0, 'boosters_shop', 'Button_Play0000', this)
	}

	public resize(width: number): void {
		this.back.width = width

		this.alignButtons()
	}

	private alignButtons() {
		let buttonsY: number = this.back.centerY + 2

		this.playButton.centerX = this.back.centerX
		this.playButton.centerY = buttonsY
	}

	public show(initialDelay: number): void {
		this.game.add.tween(this).from({ y: '+60', alpha: 0 }, 400, Phaser.Easing.Cubic.Out, true, initialDelay)
	}

	public getHeight(): number {
		return this.back.height
	}

	public destroy(): void {
		super.destroy(true, false)
	}
}
